    def _helpresume_preview_summary(self) -> str:
        """Return one tiny truthful preview for plain ``helpresume``.

        ``helpresume`` already knows whether one dormant session-local docs
        target is ready, active already, missing, or absent. Its exact
        command-bar row should not flatten that state back to generic command
        metadata right before execution.
        """

        try:
            model = self.help_navigation_model()
        except Exception:
            model = {}
        if bool(model.get('help_resume_available')):
            target = str(model.get('help_resume_target', '') or '').strip()
            pos = str(model.get('help_resume_position', '') or '').strip()
            info = f'resume {target}' if target else 'resume help target'
            if pos:
                info += f' @ {pos}'
            return info
        warning = str(model.get('help_resume_warning', '') or '').strip()
        if warning:
            prefix = 'helpresume:'
            return warning[len(prefix):].strip() if warning.startswith(prefix) else warning
        if bool(model.get('help_navigation_active')):
            target = str(model.get('help_topic', '') or '').strip()
            pos = str(model.get('help_position', '') or '').strip()
            info = f'already active: {target}' if target else 'already active'
            if pos:
                info += f' @ {pos}'
            return info
        return 'no session help target'

    def _prompt_helpresume_command_row(self, insert: str) -> list[str]:
        """Return one tiny truthful row for plain ``helpresume``.

        The local docs session trail already knows whether one dormant target is
        ready to reopen (or why resume is blocked), so the no-arg command-bar
        row should not hide that state behind generic command metadata right
        before execution.
        """

        row = self._prompt_command_row(insert)
        if len(row) < 4:
            row = list(row) + [''] * (4 - len(row))
        row[3] = self._helpresume_preview_summary()
        return [str(x) for x in row[:4]]

    def _helpprune_preview_summary(self) -> str:
        """Return one tiny truthful preview for plain ``helpprune``.

        ``helpprune`` already knows whether the local docs trail has any stale
        missing targets worth clearing. Its exact command-bar row should keep
        that cleanup truth visible before Enter instead of hiding it behind
        generic command metadata.
        """

        try:
            session_count, back_count, forward_count, total = self._help_prune_counts()
        except Exception:
            session_count = back_count = forward_count = total = 0
        if total <= 0:
            return 'nothing to prune'
        parts: list[str] = []
        if session_count > 0:
            parts.append(f'session {session_count}')
        if back_count > 0:
            parts.append(f'back {back_count}')
        if forward_count > 0:
            parts.append(f'forward {forward_count}')
        detail = '; '.join(parts)
        info = f'prune {total} missing help target(s)'
        if detail:
            info += f' ({detail})'
        return info

    def _help_history_inventory_entry_summary(self, row: list[object]) -> str:
        """Return one tiny inventory fragment for ``helphistory`` previews.

        Keep the prompt/runtime summary dialect identical so future UIs and
        humans do not have to learn two different ways of reading the same
        local docs trail.
        """

        lane = str(row[0]) if row else ''
        try:
            depth = int(row[1]) if len(row) >= 2 else 0
        except Exception:
            depth = 0
        topic = str(row[2]) if len(row) >= 3 else ''
        position = str(row[4]) if len(row) >= 5 else ''
        state = str(row[5]) if len(row) >= 6 else ''
        tag = lane or 'help'
        if lane == 'current':
            tag = 'here'
        elif lane == 'dormant':
            tag = 'dormant'
        elif depth > 0:
            tag = f'{lane} {depth}'
        if state == 'missing':
            tag = f'{tag} missing'
        msg = f'[{tag}] {topic or "?"}'
        if position:
            msg += f' @ {position}'
        return msg

    def help_history_inventory_summary(self) -> str:
        """Return one tiny count-aware summary for plain ``helphistory``.

        ``helphistory`` already exists to expose the local docs trail after
        Enter, and the exact command-bar row should tell that same truth before
        Enter instead of falling back to generic command metadata.
        """

        try:
            rows = self.help_history_rows()
        except Exception:
            rows = []
        parts = [self._help_history_inventory_entry_summary(list(r)) for r in rows]
        total = len(rows)
        head = f'helphistory: {total} help target(s)'
        return head if not parts else head + ', ' + '; '.join(parts)

