    def _hook_inventory_preview_summary(self, query: str = "") -> str:
        """Return one tiny truthful hook-inventory summary.

        Both plain ``showhooks`` and the narrower root ``showhook`` inspector
        should keep the same live hook namespace truth visible before or after
        Enter. Reuse one tiny summary string so those adjacent entry points do
        not drift into different dialects when the underlying hook register is
        already inspectable.
        """

        rows = self.hook_summary_rows(query)
        total = len(rows)
        summary = self._count_label(total, 'hook')
        nonempty = 0
        first_row: list[object] | None = list(rows[0]) if rows else None
        sample_row: list[object] | None = None
        for item in rows:
            candidate = list(item)
            try:
                handler_count = int(candidate[1]) if len(candidate) >= 2 else 0
            except Exception:
                handler_count = 0
            if handler_count > 0:
                nonempty += 1
                if sample_row is None:
                    sample_row = candidate
        if sample_row is None:
            sample_row = first_row
        summary += f" · {nonempty} with handlers"
        if sample_row is not None:
            name = str(sample_row[0]) if len(sample_row) >= 1 else ''
            try:
                handler_count = int(sample_row[1]) if len(sample_row) >= 2 else 0
            except Exception:
                handler_count = 0
            sample_handler = str(sample_row[2]) if len(sample_row) >= 3 and sample_row[2] not in (0, '') else ''
            sample = self._count_label(handler_count, 'handler')
            if name:
                sample = f"{name}: {sample}"
            if sample_handler:
                sample += f" (e.g. {sample_handler})"
            if sample:
                summary += f" · {sample}"
        return str(summary)

