    def _plugin_inventory_preview_state(self) -> dict[str, object]:
        """Return one tiny shared snapshot for broad plugin inventory previews.

        The broad plugin entry points (`showplugins`, `plugin list`, `plugin
        info`, `plugin reload`, `plugin errors`) should distinguish an
        unavailable plugin manager from a real empty inventory. Reuse one tiny
        availability-aware snapshot so those command-bar rows stay truthful in
        safe startup or headless test harnesses.
        """

        available = getattr(self, 'plugin_manager', None) is not None
        inventory = [list(item) for item in self.plugin_inventory_rows()] if available else []
        error_rows = [item for item in inventory if str(item[1] if len(item) >= 2 else '') == 'error']
        loaded_rows = [item for item in inventory if str(item[1] if len(item) >= 2 else '') == 'loaded']
        available_rows = [item for item in inventory if str(item[1] if len(item) >= 2 else '') == 'available']
        return {
            'available': bool(available),
            'inventory': inventory,
            'error_rows': error_rows,
            'loaded_rows': loaded_rows,
            'available_rows': available_rows,
        }

    def _prompt_showplugins_command_row(self, insert: str) -> list[str]:
        """Return one tiny truthful row for plain ``showplugins``.

        ``showplugins [QUERY]`` already reuses grouped section-summary rows once
        a plugin manager is live, but its exact no-arg command row should not
        pretend an unavailable manager is the same thing as an empty inventory.
        """

        row = self._prompt_command_row(insert)
        state = self._plugin_inventory_preview_state()
        if not bool(state.get('available')):
            if len(row) < 4:
                row = list(row) + [''] * (4 - len(row))
            row[3] = 'plugin manager not available'
            return [str(x) for x in row[:4]]
        return self._prompt_section_summary_command_row(insert, cmd='showplugins', noun='plugin')

    def _prompt_showplugin_command_row(self, insert: str) -> list[str]:
        """Return one tiny truthful row for plain ``showplugin``.

        Exact ``showplugin NAME`` completion already reuses precise per-plugin
        state, and neighboring broad plugin entry points now preview live
        plugin availability too. Keep the no-arg ``showplugin`` row aligned
        with that broader plugin family so humans can see whether exact plugin
        inspection currently has anything to inspect before Enter.
        """

        row = self._prompt_command_row(insert)
        summary = self._prompt_plugin_command_row(insert, subcommand='info')[3]
        if len(row) < 4:
            row = list(row) + [''] * (4 - len(row))
        row[3] = str(summary)
        return [str(x) for x in row[:4]]

