    def _prompt_binding_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
    ) -> list[str]:
        raw = str(insert)
        key = raw[:-1] if raw.endswith(" ") else raw
        row = self.binding_detail_row(key)
        if row in (0, None):
            if strict_missing and key.strip():
                return [str(insert), "binding", "missing binding", "no such binding"]
            return [str(insert), "binding", "", str(fallback_info or "")]
        mode = str(row[0]) if len(row) >= 1 else "global"
        action = str(row[2]) if len(row) >= 3 else ""
        desc = str(row[3]) if len(row) >= 4 and row[3] not in (0, None, "") else ""
        group = str(row[4]) if len(row) >= 5 and row[4] not in (0, None, "") else ""
        menu = f"@{mode or 'global'} {action}".rstrip()
        if group:
            menu += f" [group {group}]"
        info = desc or str(fallback_info or "")
        return [str(insert), "binding", menu, info]

    def _prompt_buffer_row(self, insert: str) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        eb = self.buffers.get(name)
        if eb is None:
            return [str(insert), "buffer", "", ""]
        menu = "active" if (self.active == name) else "buffer"
        path = getattr(eb.buf, "path", None) or ""
        nlines = len(getattr(eb.buf, "lines", []) or [])
        info_parts: list[str] = []
        if path:
            info_parts.append(str(path))
        if nlines:
            info_parts.append(f"{nlines} lines")
        info = " | ".join(info_parts)
        return [str(insert), "buffer", str(menu), str(info)]

    def _buffer_inventory_preview_summary(self) -> str:
        """Return one tiny live buffer-inventory witness.

        Plain ``showbuffer`` is still a usage-shaped exact inspector, but its
        root entry point should not collapse back to generic command metadata
        when Micromax already knows the current buffer set. Keep the preview
        compact and prefer an active/dirty non-scratch buffer when present so
        the summary highlights the buffer state most likely to matter next.
        """

        rows = [list(row) for row in self.buffer_inventory_rows()]
        summary = self._count_label(len(rows), 'buffer')
        if not rows:
            return summary

        def _score(row: list[object]) -> tuple[int, int, int, int, str]:
            name = str(row[0]) if len(row) >= 1 else ''
            scratch = 1 if name == '*scratch*' else 0
            try:
                active = int(row[2]) if len(row) >= 3 else 0
            except Exception:
                active = 0
            try:
                dirty = int(row[3]) if len(row) >= 4 else 0
            except Exception:
                dirty = 0
            try:
                readonly = int(row[4]) if len(row) >= 5 else 0
            except Exception:
                readonly = 0
            return (
                0 if active and not scratch else 1,
                0 if dirty and not scratch else 1,
                scratch,
                0 if readonly else 1,
                name,
            )

        target = min(rows, key=_score)
        name = str(target[0]) if len(target) >= 1 else ''
        detail = self.buffer_detail_row(name) if name else None
        if detail is None:
            return summary
        position = str(detail[1]) if len(detail) >= 2 else ''
        try:
            active = int(detail[2]) if len(detail) >= 3 else 0
        except Exception:
            active = 0
        try:
            dirty = int(detail[3]) if len(detail) >= 4 else 0
        except Exception:
            dirty = 0
        try:
            readonly = int(detail[4]) if len(detail) >= 5 else 0
        except Exception:
            readonly = 0
        path = str(detail[6]) if len(detail) >= 7 else ''
        try:
            line_count = int(detail[7]) if len(detail) >= 8 else 0
        except Exception:
            line_count = 0
        if not name:
            return summary
        brief = name
        flags: list[str] = []
        if active:
            flags.append('active')
        if dirty:
            flags.append('dirty')
        if readonly:
            flags.append('readonly')
        if flags:
            brief += ' [' + ', '.join(flags) + ']'
        if position:
            brief += f' @ {position}'
        extras: list[str] = []
        if path:
            extras.append(self._display_path(path))
        if line_count > 0:
            extras.append(self._count_label(line_count, 'line'))
        if extras:
            brief += ' — ' + ' | '.join(extras)
        return f"{summary} · {brief}"

