    def _prompt_exact_buffer_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
    ) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        row = self.buffer_detail_row(name)
        if row is None:
            if strict_missing and name.strip():
                return [str(insert), "buffer", "missing buffer", "no such buffer"]
            return [str(insert), "buffer", "", str(fallback_info or "")]
        position = str(row[1]) if len(row) >= 2 else ""
        try:
            active = int(row[2]) if len(row) >= 3 else 0
        except Exception:
            active = 0
        try:
            dirty = int(row[3]) if len(row) >= 4 else 0
        except Exception:
            dirty = 0
        try:
            readonly = int(row[4]) if len(row) >= 5 else 0
        except Exception:
            readonly = 0
        section = str(row[5]) if len(row) >= 6 else ""
        path = str(row[6]) if len(row) >= 7 else ""
        try:
            line_count = int(row[7]) if len(row) >= 8 else 0
        except Exception:
            line_count = 0
        menu = section or ("active" if active else "buffer")
        flags: list[str] = []
        if active:
            flags.append("active")
        if dirty:
            flags.append("dirty")
        if readonly:
            flags.append("readonly")
        if flags:
            menu += " [" + ", ".join(flags) + "]"
        if position:
            menu += f" @ {position}"
        info_parts: list[str] = []
        if path:
            info_parts.append(path)
        if line_count > 0:
            info_parts.append(self._count_label(line_count, "line"))
        info = " | ".join(info_parts)
        return [str(insert), "buffer", menu, info or str(fallback_info or "")]

    def _prompt_exact_recent_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
        empty_info: str = "",
    ) -> list[str]:
        """Return one richer exact-recent completion row for one visible path.

        ``showrecent PATH`` already exposes the trusted exact recent-file row.
        Reusing that same tiny location/disk/action truth for adjacent commands
        keeps filtered recent-pick entry points from going blind again on their
        first argument.
        """

        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        row = self.recent_detail_row_by_index(name)
        if row is None:
            row = self.recent_detail_row(name)
        if row is None:
            if strict_missing or self.parse_recent_slot_token(name) is not None:
                return [str(insert), "recent", "", "no such recent file"]
            if empty_info:
                return [str(insert), "recent", "", str(empty_info)]
            return [str(insert), "recent", "", str(fallback_info or "inspect exact recent file")]

        try:
            index = int(row[2]) if len(row) >= 3 else 0
        except Exception:
            index = 0
        actual = str(row[1]) if len(row) >= 2 else name
        section = str(row[8]) if len(row) >= 9 else ""
        detail = str(row[9]) if len(row) >= 10 else ""
        disk_truth = str(row[10]) if len(row) >= 11 else ""
        action_truth = str(row[11]) if len(row) >= 12 else ""
        menu = f"#{index}" if index > 0 else "recent"
        if section:
            menu += f" {section}"
        try:
            basename = str(Path(actual).name or "")
        except Exception:
            basename = ""
        info = " | ".join(self._recent_location_parts(section, detail, basename=basename))
        info = self._trim_leading_location_echo(info, f"section={section}", section)
        info = self._append_palette_action_cue(info, disk_truth)
        info = self._append_palette_action_cue(info, action_truth)
        info = info or str(fallback_info or "inspect exact recent file")
        return [str(insert), "recent", menu, info]

    def _prompt_recent_command_row(
        self,
        insert: str,
        *,
        row: list[object] | None = None,
        fallback_info: str = "",
    ) -> list[str]:
        """Return one richer completion row for ``recent N|clear``.

        The plain ``recent`` command already exposes the trusted MRU inventory
        row surface. Completion should reuse that same tiny open/disk/action
        truth instead of making humans or future UIs guess what one number will
        open.
        """

        raw = str(insert)
        token = raw[:-1] if raw.endswith(" ") else raw
        if token == "clear":
            total = len(self.visible_recent_files())
            noun = self._count_label(total, "recent file")
            info = f"forget {noun}" if noun else "forget remembered recent files"
            return [str(insert), "recent", "clear history", info]

        index = self.parse_recent_slot_token(token)
        if index is None:
            return [str(insert), "recent", "", str(fallback_info or "open recent file")]

        data = list(row or [])
        if not data:
            for item in self.recent_inventory_rows(limit=max(0, int(index))):
                try:
                    if int(item[0]) == int(index):
                        data = list(item)
                        break
                except Exception:
                    continue
        if not data:
            return [str(insert), "recent", "", "no such recent file"]

        path = str(data[1]) if len(data) >= 2 else ""
        position = str(data[2]) if len(data) >= 3 else ""
        try:
            active = int(data[3]) if len(data) >= 4 else 0
        except Exception:
            active = 0
        try:
            open_flag = int(data[4]) if len(data) >= 5 else 0
        except Exception:
            open_flag = 0
        try:
            dirty = int(data[5]) if len(data) >= 6 else 0
        except Exception:
            dirty = 0
        try:
            readonly = int(data[6]) if len(data) >= 7 else 0
        except Exception:
            readonly = 0
        disk_truth = str(data[7]) if len(data) >= 8 else ""
        action_truth = str(data[8]) if len(data) >= 9 else ""

        menu = f"*{path}" if active else path
        flags: list[str] = []
        if open_flag and not active:
            flags.append("open")
        if dirty:
            flags.append("dirty")
        if readonly:
            flags.append("readonly")
        if flags:
            menu += " [" + ", ".join(flags) + "]"
        if position:
            menu += f" @ {position}"

        info = ""
        info = self._append_palette_action_cue(info, disk_truth)
        info = self._append_palette_action_cue(info, action_truth)
        return [str(insert), "recent", menu or f"recent #{index}", info or str(fallback_info or "open recent file")]

    def _prompt_mark_row(self, insert: str) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        if name not in self.marks or not self._mark_read_allowed(name):
            return [str(insert), "mark", "", ""]
        buf_name, cur = self.marks[name]
        menu = f"{buf_name}:{int(cur.line)+1}:{int(cur.col)+1}"
        info = ""
        eb = self.buffers.get(buf_name)
        if eb is not None:
            line_i = int(cur.line)
            if 0 <= line_i < len(eb.buf.lines):
                s = eb.buf.lines[line_i].rstrip("\n")
                s = s.strip()
                if len(s) > 80:
                    s = s[:77] + "..."
                info = s
        return [str(insert), "mark", str(menu), str(info)]

