    def _prompt_exact_jump_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
    ) -> list[str]:
        """Return one richer exact-jump completion row for one visible slot.

        Exact jumplist inspection already has one tiny trusted row behind
        ``showjump N|#N``. Reusing that same lane/depth/position/preview truth
        for adjacent command-bar entry points keeps direct slot-based jump
        workflows inspectable before execution instead of dropping back to a
        bare token.
        """

        raw = str(insert)
        token = raw[:-1] if raw.endswith(" ") else raw
        row = self.jump_detail_row(token)
        if row is None:
            if strict_missing and token.strip():
                return [str(insert), "jump", "missing jump", "no such jump"]
            return [str(insert), "jump", "", str(fallback_info or "inspect exact jump")]
        lane = str(row[2]) if len(row) >= 3 else ""
        try:
            depth = int(row[3]) if len(row) >= 4 else 0
        except Exception:
            depth = 0
        buffer_name = str(row[4]) if len(row) >= 5 else ""
        position = str(row[5]) if len(row) >= 6 else ""
        preview = str(row[6]) if len(row) >= 7 else ""
        menu = lane or "jump"
        if depth > 0:
            menu += f" {depth}"
        if buffer_name:
            menu += f" {buffer_name}"
        if position:
            menu += f" @ {position}"
        info = preview or str(fallback_info or "inspect exact jump")
        return [str(insert), "jump", menu, info]

    def _prompt_exact_macro_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
    ) -> list[str]:
        """Return one tiny truthful row for ``showmacro NAME``.

        Exact macro inspection should stay honest about whether a slot is saved,
        actively recording, or currently replaying. Reuse one shared macro
        detail row so command-bar previews and post-Enter inspection stay on the
        same tiny automation dialect.
        """

        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        row = self.macro_detail_row(name)
        if row is None:
            if strict_missing and name.strip():
                return [str(insert), "macro", "missing macro", "no such macro"]
            return [str(insert), "macro", "", str(fallback_info or "inspect exact macro")]
        state = str(row[2]) if len(row) >= 3 else "saved"
        try:
            steps = int(row[3]) if len(row) >= 4 else 0
        except Exception:
            steps = 0
        try:
            default = int(row[4] if len(row) >= 5 else 0)
        except Exception:
            default = 0
        try:
            shadow_steps = int(row[5] if len(row) >= 6 else 0)
        except Exception:
            shadow_steps = 0

        step_word = "step" if steps == 1 else "steps"
        count_label = f"{steps} {'live ' if state == 'recording' else ''}{step_word}"
        flags: list[str] = []
        if state == 'recording':
            flags.append('recording')
        elif state == 'playing':
            flags.append('playing')
        if default:
            flags.append('default')
        if flags:
            count_label += " [" + ", ".join(flags) + "]"

        info = str(fallback_info or "inspect exact macro")
        if state == 'recording':
            parts = ['stop to save, cancel to discard']
            if shadow_steps > 0:
                shadow_word = 'step' if shadow_steps == 1 else 'steps'
                parts.append(f"saved={shadow_steps} {shadow_word}")
            info = ' · '.join(parts)
        elif state == 'playing':
            info = 'wait for playback'
        elif default:
            info = 'default replay slot'
        return [str(insert), 'macro', count_label, info]

    def _prompt_hook_row(self, insert: str, *, strict_missing: bool = False) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        if name.strip() == "":
            return [str(insert), "hook", "", "inspect hook"]
        row = self.hook_detail_row(name)
        if row is None:
            if strict_missing:
                return [str(insert), "hook", "missing hook", "not a hook"]
            return [str(insert), "hook", "", "inspect hook"]
        handler_count = int(row[2]) if len(row) >= 3 else 0
        sample_name = row[3] if len(row) >= 4 else 0
        sample_detail = row[4] if len(row) >= 5 else 0
        menu = f"{handler_count} handler" + ("" if handler_count == 1 else "s")
        if sample_name:
            menu += f" (e.g. {sample_name})"
        info = str(sample_detail) if sample_detail else "inspect exact hook"
        return [str(insert), "hook", menu, info]

    def _prompt_hook_summary_row(self, insert: str) -> list[str]:
        """Return the tiny shared broad-hook summary row behind ``showhooks``."""

        raw = str(insert)
        query = raw[:-1] if raw.endswith(" ") else raw
        query = str(query).strip()
        rows = self.hook_summary_rows(query)
        target: list[object] | None = None
        folded = query.casefold()
        for row in rows:
            name = str(row[0] if row else "").strip()
            if name and name.casefold() == folded:
                target = list(row)
                break
        if target is None and folded:
            for row in self.hook_summary_rows(""):
                name = str(row[0] if row else "").strip()
                if name and name.casefold() == folded:
                    target = list(row)
                    break
        if target is None and rows:
            target = list(rows[0])
        if target is None:
            return [str(insert), "hook", "", "filter hook summary"]
        try:
            handler_count = int(target[1]) if len(target) >= 2 else 0
        except Exception:
            handler_count = 0
        sample_name = target[2] if len(target) >= 3 else 0
        src = target[3] if len(target) >= 4 else 0
        menu = f"{handler_count} handler" + ("" if handler_count == 1 else "s")
        if sample_name not in (0, None, ""):
            menu += f" (e.g. {sample_name})"
        info = "filter hook summary"
        if isinstance(src, list) and len(src) >= 3:
            info = f"defined at {src[0]}:{src[1]}:{src[2]}"
        return [str(insert), "hook", menu, info]

    def workspace_trust_model(self) -> dict[str, Any]:
        """Return the current startup trust model.

        The model is intentionally about automatic code loading.  It does not
        claim OS isolation and does not authorize any capability on its own.
        """

        return workspace_trust_policy(getattr(self, "workspace_trust", DEFAULT_TRUST_STATE)).model()

    def _plugin_state_snapshot(self, name: str) -> dict[str, object]:
        """Return one shared best-effort plugin state snapshot.

        This keeps plain plugin inventory, exact plugin detail, prompt metadata,
        and future host/UIs on one tiny substrate instead of rediscovering the
        same state/version/dependency/error-description joins independently.
        """

        plugin_name = str(name)
        pm = getattr(self, "plugin_manager", None)
        loaded = False
        version = ""
        reqs: list[str] = []
        errs: list[str] = []
        desc = ""
        if pm is not None:
            try:
                loaded = bool(plugin_name in getattr(pm, "plugins", {}))
                cand = getattr(pm, "candidates", {}).get(plugin_name) if hasattr(pm, "candidates") else None
                if cand is not None:
                    version = str(cand.meta.version or "")
                    reqs = [str(x) for x in list(cand.meta.requires or []) if str(x).strip() != ""]
                    desc = str(cand.meta.description or "")
                elif loaded:
                    plug = getattr(pm, "plugins", {}).get(plugin_name)
                    meta = getattr(plug, "meta", {}) if plug is not None else {}
                    if isinstance(meta, dict):
                        version = str(meta.get("version") or "")
                        reqs = [str(x) for x in list(meta.get("requires") or []) if str(x).strip() != ""]
                        desc = str(meta.get("description") or "")
            except Exception:
                pass
            try:
                errs = [str(e) for (n, e) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
            except Exception:
                errs = []
        state = "error" if errs else ("loaded" if loaded else "available")
        detail = errs[-1] if errs else desc
        return {
            "name": plugin_name,
            "state": state,
            "version": version,
            "deps": ",".join(reqs),
            "error_count": len(errs),
            "detail": detail,
        }

    def _plugin_inventory_row(self, name: str) -> list[object]:
        """Return one tiny inspectable plugin inventory row.

        The shared plugin inventory surface intentionally stays smaller than the
        full plugin detail path: enough to render the same plain `plugin list`
        register and let scripts/future UIs count state honestly, without
        turning broad inventory into a second copy of `plugin info`.
        """

        snap = self._plugin_state_snapshot(name)
        return [
            str(snap.get("name") or ""),
            str(snap.get("state") or "available"),
            str(snap.get("version") or ""),
            str(snap.get("deps") or ""),
            int(snap.get("error_count") or 0),
        ]

    def plugin_inventory_rows(self) -> list[list[object]]:
        """Return the tiny shared plugin inventory register.

        Rows are `[name state version deps error_count]` and intentionally match
        the ordinary `plugin list` summary rather than the richer plugin picker
        or detail views.
        """

        return [self._plugin_inventory_row(name) for name in self.plugin_names()]

    def plugin_detail_row(self, name: str, *, strict_denial: bool = False) -> list[object] | None:
        """Return one tiny exact plugin row for a known visible plugin.

        Script-origin callers can inspect the currently executing loaded plugin
        generation, but trusted/user, other-plugin, candidate-only, and broken
        plugin rows require ``cap.plugin-read``.  ``strict_denial`` raises on a
        protected exact hit so hostcalls can preserve the queried plugin name on
        the VM stack.
        """

        raw_query = str(name or "")
        plugin_name = raw_query.strip()
        if plugin_name == "":
            return None
        if plugin_name not in self._all_plugin_names():
            return None
        denial = self._plugin_read_denial(plugin_name, action="read")
        if denial:
            if strict_denial:
                raise PermissionError(denial)
            return None
        snap = self._plugin_state_snapshot(plugin_name)
        return [
            raw_query,
            str(snap.get("name") or plugin_name),
            str(snap.get("state") or "available"),
            str(snap.get("version") or ""),
            str(snap.get("deps") or ""),
            int(snap.get("error_count") or 0),
            str(snap.get("detail") or ""),
        ]

    def _plugin_inventory_entry_from_row(self, row: list[object]) -> str:
        name = str(row[0] if len(row) > 0 else "")
        state = str(row[1] if len(row) > 1 else "") or "available"
        version = str(row[2] if len(row) > 2 else "")
        deps = str(row[3] if len(row) > 3 else "")
        flags: list[str] = [state]
        if version:
            flags.append(f"v{version}")
        if deps:
            flags.append("deps:" + deps)
        return f"{name} [{', '.join(flags)}]" if name and flags else name

    def plugin_inventory_entry(self, name: str) -> str:
        return self._plugin_inventory_entry_from_row(self._plugin_inventory_row(name))

    def _workspace_trust_state(self) -> str:
        return str(getattr(self, "workspace_trust", DEFAULT_TRUST_STATE) or DEFAULT_TRUST_STATE)

    def _workspace_restricted(self) -> bool:
        return self._workspace_trust_state() == "restricted"

    def _plugin_grant_entry_from_row(self, row: list[object]) -> str:
        name = str(row[0] if len(row) > 0 else "")
        state = str(row[1] if len(row) > 1 else "") or "active"
        duration = str(row[2] if len(row) > 2 else "")
        issuer = str(row[3] if len(row) > 3 else "")
        flags = [state]
        if duration:
            flags.append(duration)
        if issuer:
            flags.append(f"issuer:{issuer}")
        return f"{name} [{', '.join(flags)}]" if name else ""

    def plugin_load_grant_rows(self) -> list[list[object]]:
        pm = getattr(self, "plugin_manager", None)
        if pm is None or not hasattr(pm, "load_grant_rows"):
            return []
        if self.in_script_context() and not self._script_plugin_read_capability_enabled():
            return []
        return [list(row) for row in pm.load_grant_rows()]

    def plugin_cleanup_failure_rows(self, name: str = "") -> list[list[object]]:
        """Return visible retained cleanup/retag failure rows.

        Rows are ``[plugin action group target_group surface operation detail]``.
        User-facing commands use this narrow view so report diagnostics are
        available without granting scripts a broad plugin-read side channel.
        """

        if self.in_script_context() and not self._script_plugin_read_capability_enabled():
            return []
        flt = str(name or "").strip()
        rows: list[list[object]] = []
        pm = getattr(self, "plugin_manager", None)
        if pm is not None and hasattr(pm, "runtime_group_failure_rows"):
            rows.extend(
                row
                for row in [list(row) for row in pm.runtime_group_failure_rows(flt)]
                if row and self._plugin_read_allowed(str(row[0]))
            )
        rows.extend(self.plugin_cleanup_log_rows(flt))
        deduped: list[list[object]] = []
        seen: set[tuple[str, ...]] = set()
        for row in rows:
            key = tuple(str(x) for x in list(row)[:7])
            if key in seen:
                continue
            seen.add(key)
            deduped.append(list(row))
        return deduped

    def plugin_load_with_feedback(self, name: str) -> bool:
        """Explicitly approve and load one available plugin candidate.

        Restricted startup intentionally scans plugin metadata without running
        source.  This method is the deliberate post-startup transition: it
        creates a session grant bound to the candidate root/entry, then evaluates
        only that candidate.  Trusted mode also accepts the command as a clearer
        alias for loading an available-but-unloaded plugin.
        """

        pm = getattr(self, "plugin_manager", None)
        if pm is None:
            self.message("plugin load: no plugin manager")
            return False
        plugin_name = str(name)
        loaded_before = bool(plugin_name in getattr(pm, "plugins", {}))
        cand_before = getattr(pm, "candidates", {}).get(plugin_name) if hasattr(pm, "candidates") else None
        try:
            errs_before = [str(e) for (n, e) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
        except Exception:
            errs_before = []
        if loaded_before:
            grant_note = ""
            if self._workspace_restricted():
                try:
                    pm.grant_load(
                        plugin_name,
                        issuer="user",
                        duration="session",
                        provenance=f"command:plugin load {plugin_name}",
                    )
                    grant_note = " · session grant"
                except Exception as e:
                    self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}")
                    self.message(f"  grant error: {e}")
                    return False
            self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}{grant_note}")
            return True
        if cand_before is None:
            if not errs_before:
                self.message(f"plugin load: no such plugin: {plugin_name}")
                return False
            self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}")
            summary = self._plugin_exact_error_info(errs_before[-1] if errs_before else '', len(errs_before))
            self.message(f"  load: {summary} · not loaded")
            return False
        grant = None
        grant_note = ""
        if self._workspace_restricted():
            try:
                grant = pm.grant_load(
                    plugin_name,
                    issuer="user",
                    duration="session",
                    provenance=f"command:plugin load {plugin_name}",
                )
                grant_note = " · session grant"
            except Exception as e:
                self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}")
                self.message(f"  grant error: {e}")
                return False
        try:
            pm.load_available(plugin_name, grant=grant)
        except Exception as e:
            try:
                errs_after = [str(err) for (n, err) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
            except Exception:
                errs_after = []
            self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}")
            detail = str(errs_after[-1] if errs_after else e)
            count = len(errs_after) if errs_after else 1
            summary = self._plugin_exact_error_info(detail, count)
            self.message(f"  load: {summary} · not loaded")
            return False
        self.message(f"plugin load: {self.plugin_inventory_entry(plugin_name)}{grant_note}")
        return True

    def _plugin_cleanup_failure_hint(self, name: str) -> str:
        """Return a compact pointer when retained cleanup diagnostics exist."""

        try:
            rows = self.plugin_cleanup_failure_rows(str(name))
        except Exception:
            rows = []
        return f" · see plugin cleanup {str(name)}" if rows else ""

    def plugin_unload_with_feedback(self, name: str) -> bool:
        """Unload one live plugin and report the resulting recovery state.

        Restricted trust needs a user-facing escape hatch after an explicit load:
        revocation stops future package-local source reads, but it does not tear
        down already registered commands, bindings, timers, or hooks.  This path
        commits the existing plugin-manager cleanup transaction and revokes the
        matching session grant so reactivation remains explicit.
        """

        pm = getattr(self, "plugin_manager", None)
        if pm is None:
            self.message("plugin unload: no plugin manager")
            return False
        plugin_name = str(name)
        loaded_before = bool(plugin_name in getattr(pm, "plugins", {}))
        cand_before = getattr(pm, "candidates", {}).get(plugin_name) if hasattr(pm, "candidates") else None
        try:
            errs_before = [str(e) for (n, e) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
        except Exception:
            errs_before = []
        if not loaded_before:
            if cand_before is None and not errs_before:
                self.message(f"plugin unload: no such plugin: {plugin_name}")
                return False
            self.message(f"plugin unload: {self.plugin_inventory_entry(plugin_name)}")
            self.message("  unload: not loaded")
            return False
        try:
            pm.unload(plugin_name)
        except Exception as e:
            self.message(f"plugin unload: {self.plugin_inventory_entry(plugin_name)}")
            self.message(f"  unload: {e} · still loaded{self._plugin_cleanup_failure_hint(plugin_name)}")
            return False
        if self._workspace_restricted() and hasattr(pm, "revoke_load_grant"):
            try:
                pm.revoke_load_grant(plugin_name)
            except Exception:
                pass
        self.message(f"plugin unload: {plugin_name} [unloaded]")
        return True

    def plugin_reload_with_feedback(self, name: str) -> bool:
        """Reload a plugin and report the resulting state in the current plugin dialect.

        The command-bar `plugin reload NAME` path became much more explicit over
        several tiny trust-first passes. The live scripting hostcall path should
        not drift back to older generic error messages, so this method centralizes
        the user-visible feedback shape for both command and hostcall reloads.
        """

        pm = getattr(self, "plugin_manager", None)
        if pm is None:
            self.message("plugin reload: no plugin manager")
            return False
        plugin_name = str(name)
        loaded_before = bool(plugin_name in getattr(pm, "plugins", {}))
        cand_before = getattr(pm, "candidates", {}).get(plugin_name) if hasattr(pm, "candidates") else None
        try:
            errs_before = [str(e) for (n, e) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
        except Exception:
            errs_before = []
        if self._workspace_restricted():
            if not loaded_before and cand_before is not None:
                self.message(f"plugin reload: {self.plugin_inventory_entry(plugin_name)}")
                self.message(f"  restricted workspace: use plugin load {plugin_name} to approve and load")
                return False
            if loaded_before and hasattr(pm, "active_load_grant") and pm.active_load_grant(plugin_name, refresh=True) is None:
                self.message(f"plugin reload: {self.plugin_inventory_entry(plugin_name)}")
                self.message(f"  restricted workspace: no active load grant; use plugin load {plugin_name} to approve reloads")
                return False
        if not loaded_before and cand_before is None:
            if not errs_before:
                self.message(f"plugin reload: no such plugin: {plugin_name}")
                return False
            self.message(f"plugin reload: {self.plugin_inventory_entry(plugin_name)}")
            summary = self._plugin_exact_error_info(errs_before[-1] if errs_before else '', len(errs_before))
            self.message(f"  reload: {summary} · not loaded")
            if len(errs_before) > 1:
                for err in errs_before[-50:]:
                    self.message(f"    - {err}")
            return False
        try:
            pm.reload(plugin_name)
        except Exception as e:
            try:
                errs_after = [str(err) for (n, err) in getattr(pm, "load_errors", []) if str(n) == plugin_name]
            except Exception:
                errs_after = []
            cand_after = getattr(pm, "candidates", {}).get(plugin_name) if hasattr(pm, "candidates") else None
            loaded_after = bool(plugin_name in getattr(pm, "plugins", {}))
            if loaded_after or cand_after is not None or errs_after:
                self.message(f"plugin reload: {self.plugin_inventory_entry(plugin_name)}")
                if errs_after:
                    summary = self._plugin_exact_error_info(errs_after[-1] if errs_after else '', len(errs_after))
                    suffix = ' · previous version still loaded' if loaded_after else ' · not loaded'
                    self.message(f"  reload: {summary}{suffix}{self._plugin_cleanup_failure_hint(plugin_name)}")
                    if len(errs_after) > 1:
                        for err in errs_after[-50:]:
                            self.message(f"    - {err}")
                else:
                    self.message(f"  reload error: {e}{self._plugin_cleanup_failure_hint(plugin_name)}")
                return False
            self.message(f"plugin reload: no such plugin: {plugin_name}")
            return False
        self.message(f"plugin reload: {self.plugin_inventory_entry(plugin_name)}")
        return True

    def _plugin_exact_state_info_fallback(self, state: str) -> str:
        raw = str(state or '').strip().lower()
        if raw == 'loaded':
            return 'loaded plugin'
        if raw == 'available':
            return 'available plugin'
        return ''

    def _plugin_exact_error_info(self, detail: str, error_count: int) -> str:
        detail_text = str(detail or '').strip()
        count = int(error_count or 0)
        if count <= 0:
            return ''
        if not detail_text:
            return self._count_label(count, 'load error')
        if count == 1:
            return detail_text
        return self._count_label(count, 'load error') + f' · last: {detail_text}'

    def _plugin_zero_error_info(self, state: str) -> str:
        """Return a tiny exact-plugin zero-error summary without hiding state.

        Exact ``plugin errors NAME`` rows should still say whether one known
        plugin is loaded or merely available on disk. Keep the zero-error path
        concrete instead of flattening back to a bare ``0 load errors`` when
        Micromax already knows the calmer loaded/available state.
        """

        info = '0 load errors'
        raw = str(state or '').strip().lower()
        state_info = self._plugin_exact_state_info_fallback(raw)
        if raw == 'available' and state_info:
            return f'{info} · {state_info} · not loaded'
        if raw == 'loaded' and state_info:
            return f'{info} · {state_info}'
        return info

    def _prompt_plugin_row(
        self,
        insert: str,
        *,
        strict_missing: bool = False,
        include_error_count_in_menu: bool = False,
        prefer_state_info_when_blank: bool = False,
    ) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        if name.strip() == "":
            return [str(insert), "plugin", "", ""]
        if getattr(self, 'plugin_manager', None) is None:
            return [str(insert), 'plugin', 'plugin manager', 'not available']
        row = self.plugin_detail_row(name)
        if row is None:
            if strict_missing:
                return [str(insert), 'plugin', 'missing plugin', 'no such plugin']
            return [str(insert), "plugin", "", ""]
        query = str(row[0]) if len(row) >= 1 else name
        canonical = str(row[1]) if len(row) >= 2 else query
        state = str(row[2]) if len(row) >= 3 else "available"
        error_count = int(row[5]) if len(row) >= 6 else 0
        detail = str(row[6]) if len(row) >= 7 else ""
        summary = self.plugin_inventory_entry(canonical)
        menu = summary[len(canonical):].strip() if summary.startswith(canonical) else summary
        if include_error_count_in_menu and error_count:
            menu += f" errors={error_count}"
        info = detail
        if error_count:
            info = self._plugin_exact_error_info(detail, error_count)
        if prefer_state_info_when_blank and not info:
            info = self._plugin_exact_state_info_fallback(state)
            if info and str(state or '').strip().lower() == 'available':
                info += ' · not loaded'
        if state == "available" and not info:
            info = "inspect exact plugin"
        return [str(insert), "plugin", str(menu), str(info)]

    def _prompt_plugin_target_row(self, insert: str, *, subcommand: str) -> list[str]:
        """Return one tiny truthful row for exact plugin-name arguments.

        ``plugin load NAME`` / ``plugin unload NAME`` / ``plugin reload NAME`` / ``plugin info NAME`` / ``plugin errors NAME``
        already have precise command semantics after Enter. Their exact target
        rows should preserve the typed token long enough to say whether that
        name is loaded, known-but-not-loaded, erroring, clean, or missing
        instead of disappearing back into a blank plugin row.
        """

        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        raw_sub = str(subcommand or "").strip().lower()
        if name.strip() == "":
            return [str(insert), "plugin", "", ""]
        if getattr(self, 'plugin_manager', None) is None:
            return [str(insert), 'plugin', 'plugin manager', 'not available']
        row = self.plugin_detail_row(name)
        if row is None:
            return [str(insert), 'plugin', 'missing plugin', 'no such plugin']
        query = str(row[0]) if len(row) >= 1 else name
        canonical = str(row[1]) if len(row) >= 2 else query
        state = str(row[2]) if len(row) >= 3 else "available"
        error_count = int(row[5]) if len(row) >= 6 else 0
        detail = str(row[6]) if len(row) >= 7 else ""
        summary = self.plugin_inventory_entry(canonical)
        menu = summary[len(canonical):].strip() if summary.startswith(canonical) else summary
        if raw_sub == 'load':
            if state == 'loaded':
                info = 'approve loaded plugin reloads' if self._workspace_restricted() else 'already loaded'
            elif error_count:
                info = self._plugin_exact_error_info(detail, error_count)
                info += ' · not loaded'
            else:
                info = 'approve and load plugin' if self._workspace_restricted() else 'load available plugin'
            return [str(insert), 'plugin', str(menu), str(info)]
        if raw_sub == 'unload':
            if state == 'loaded':
                info = 'unload loaded plugin'
                if self._workspace_restricted():
                    info += ' and revoke grant'
            elif error_count:
                info = self._plugin_exact_error_info(detail, error_count)
                info += ' · not loaded'
            else:
                state_info = self._plugin_exact_state_info_fallback(state)
                info = f'{state_info} · not loaded' if state_info else 'plugin not loaded'
            return [str(insert), 'plugin', str(menu), str(info)]
        if raw_sub == 'reload':
            if self._workspace_restricted() and state != 'loaded':
                info = 'use plugin load NAME first'
            elif self._workspace_restricted() and state == 'loaded':
                info = 'reload loaded plugin with active grant'
            elif state == 'loaded':
                info = 'reload loaded plugin'
            elif error_count:
                info = self._plugin_exact_error_info(detail, error_count)
                info += ' · not loaded'
            else:
                state_info = self._plugin_exact_state_info_fallback(state)
                info = f'{state_info} · not loaded' if state_info else 'plugin not loaded'
            return [str(insert), 'plugin', str(menu), str(info)]
        if raw_sub == 'errors':
            info = self._plugin_exact_error_info(detail, error_count)
            if not error_count:
                info = self._plugin_zero_error_info(state)
            return [str(insert), 'plugin', str(menu), str(info)]
        if raw_sub == 'cleanup':
            failure_rows = self.plugin_cleanup_failure_rows(canonical)
            count = len(failure_rows)
            info = self._count_label(count, 'cleanup failure')
            if count:
                last = failure_rows[-1]
                surface = str(last[4] if len(last) > 4 else '')
                detail = str(last[6] if len(last) > 6 else '')
                if surface or detail:
                    info += f" · last: {surface}" if surface else ""
                    if detail:
                        info += f" · {detail}"
            return [str(insert), 'plugin', str(menu), str(info)]
        info = detail
        if error_count:
            info = self._plugin_exact_error_info(detail, error_count)
        if raw_sub == 'info' and not info:
            info = self._plugin_exact_state_info_fallback(state)
            if info and state == 'available':
                info += ' · not loaded'
        if state == 'available' and not info:
            info = 'inspect exact plugin'
        return [str(insert), 'plugin', str(menu), str(info)]

    def _prompt_plugin_command_row(self, insert: str, *, subcommand: str) -> list[str]:
        """Return one tiny truthful row for exact plugin subcommands.

        Plain ``plugin list`` / ``plugin load`` / ``plugin unload`` / ``plugin reload`` / ``plugin info`` /
        ``plugin errors`` already all depend on the same live plugin inventory.
        Their exact subcommand rows should reuse that tiny shared register before
        Enter instead of collapsing back to a generic ``plugin action``
        placeholder.
        """

        raw_sub = str(subcommand or "").strip().lower()
        state = self._plugin_inventory_preview_state()
        inventory = [list(item) for item in list(state.get('inventory', []) or [])]
        error_rows = [list(item) for item in list(state.get('error_rows', []) or [])]
        loaded_rows = [list(item) for item in list(state.get('loaded_rows', []) or [])]
        available_rows = [list(item) for item in list(state.get('available_rows', []) or [])]
        manager_available = bool(state.get('available'))

        if raw_sub == 'list':
            row = [str(insert), 'subcommand', 'plugin list - show live plugin inventory', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(inventory), 'plugin')
            shape: list[str] = []
            if error_rows:
                shape.append(self._count_label(len(error_rows), 'error'))
            if loaded_rows:
                shape.append(f"{len(loaded_rows)} loaded")
            if available_rows:
                shape.append(f"{len(available_rows)} available")
            if shape:
                summary += f" ({', '.join(shape)})"
            sample = next(iter(error_rows or inventory), None)
            if sample is not None:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(sample)}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'load':
            row = [str(insert), 'subcommand', 'plugin load NAME - approve and load one plugin', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(available_rows), 'available plugin')
            if self._workspace_restricted():
                summary += ' · restricted approval required'
            if available_rows:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(available_rows[0])}"
            elif loaded_rows:
                summary += f" · {len(loaded_rows)} loaded"
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(loaded_rows[0])}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'unload':
            row = [str(insert), 'subcommand', 'plugin unload NAME - unload one loaded plugin', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(loaded_rows), 'loaded plugin')
            if self._workspace_restricted():
                summary += ' · revokes session grant'
            if loaded_rows:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(loaded_rows[0])}"
            elif inventory:
                summary += f" · {self._count_label(len(inventory), 'plugin')} total"
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(inventory[0])}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'reload':
            row = [str(insert), 'subcommand', 'plugin reload NAME - reload one loaded plugin', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(loaded_rows), 'loaded plugin')
            if self._workspace_restricted():
                summary += ' · active grant required'
            if loaded_rows:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(loaded_rows[0])}"
            elif inventory:
                summary += f" · {self._count_label(len(inventory), 'plugin')} total"
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(inventory[0])}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'grants':
            row = [str(insert), 'subcommand', 'plugin grants - show plugin load grants', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            grant_rows = self.plugin_load_grant_rows()
            summary = self._count_label(len(grant_rows), 'grant')
            if grant_rows:
                summary += f" · e.g. {self._plugin_grant_entry_from_row(grant_rows[0])}"
            row[3] = summary
            return [str(x) for x in row[:4]]

        if raw_sub == 'revoke':
            row = [str(insert), 'subcommand', 'plugin revoke NAME - revoke a plugin load grant', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            grant_rows = self.plugin_load_grant_rows()
            summary = self._count_label(len(grant_rows), 'grant')
            if grant_rows:
                summary += f" · e.g. {self._plugin_grant_entry_from_row(grant_rows[0])}"
            row[3] = summary
            return [str(x) for x in row[:4]]

        if raw_sub == 'info':
            row = [str(insert), 'subcommand', 'plugin info NAME - show exact plugin state', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(inventory), 'plugin')
            sample = next(iter(error_rows or inventory), None)
            if sample is not None:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(sample)}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'errors':
            row = [str(insert), 'subcommand', 'plugin errors NAME - show plugin load errors', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            summary = self._count_label(len(error_rows), 'plugin with errors', 'plugins with errors')
            if error_rows:
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(error_rows[0])}"
            elif inventory:
                summary += f" · {self._count_label(len(inventory), 'plugin')} total"
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(inventory[0])}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if raw_sub == 'cleanup':
            row = [str(insert), 'subcommand', 'plugin cleanup NAME - show retained cleanup failures', '']
            if not manager_available:
                row[3] = 'plugin manager not available'
                return [str(x) for x in row[:4]]
            cleanup_rows = self.plugin_cleanup_failure_rows()
            summary = self._count_label(len(cleanup_rows), 'cleanup failure')
            if cleanup_rows:
                sample = cleanup_rows[-1]
                plugin_name = str(sample[0] if sample else '')
                surface = str(sample[4] if len(sample) > 4 else '')
                if plugin_name:
                    summary += f" · e.g. {plugin_name}"
                if surface:
                    summary += f" {surface}"
            elif inventory:
                summary += f" · {self._count_label(len(inventory), 'plugin')} total"
                summary += f" · e.g. {self._plugin_inventory_entry_from_row(inventory[0])}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        return [str(insert), 'subcommand', 'plugin action', '']

    def _macro_inventory_entry_from_row(self, row: list[object]) -> str:
        name = str(row[0] if len(row) > 0 else "")
        try:
            steps = int(row[1] if len(row) > 1 else 0)
        except Exception:
            steps = 0
        step_word = "step" if steps == 1 else "steps"
        return f"{name} ({steps} {step_word})" if name else ""

    def _macro_badge_default_entry(self, entry: str, *, name: str) -> str:
        """Return ``entry`` with the shared ``[default]`` badge when needed.

        A lot of tiny macro surfaces now surface ``last`` explicitly as the
        editor's default replay/record slot. Centralize the badge formatting so
        preview rows, exact slot rows, and runtime list/status strings do not
        drift apart again through tiny copy-pasted string tweaks.
        """

        if str(entry) and str(name) == 'last' and not str(entry).endswith(' [default]'):
            return f"{entry} [default]"
        return str(entry)

    def _macro_empty_default_slot_entry(self) -> str:
        """Return the tiny exact label for an empty default replay slot.

        Exact macro inspection already keeps an empty ``last`` slot visible as
        ``0 steps [default]`` instead of pretending the default replay slot is
        missing. Reuse that same label for exact play/count rows so a fresh
        ``macro play last`` path stays inspectable too.
        """

        return '0 steps [default]'

    def _macro_inventory_preview_entry_from_row(self, row: list[object]) -> str:
        """Return one tiny prompt-facing macro inventory entry.

        Prompt summaries should keep the default replay slot visibly marked when
        it appears as an inventory sample, so preview rows stay aligned with the
        human-facing list/status messages.
        """

        entry = self._macro_inventory_entry_from_row(row)
        return self._macro_badge_default_entry(entry, name=str(row[0] if row else ''))

    def _macro_inventory_preview_sample(
        self,
        inventory: list[list[object]] | None = None,
        *,
        skip_names: set[str] | None = None,
    ) -> str:
        """Return one prompt-facing macro inventory sample.

        Macro root, status, and exact-inspection previews all want the same
        tiny sample-picking policy: prefer the first saved macro that is not in
        a small skip set, and keep the default-slot badge policy from the
        prompt-facing inventory entry formatter. Centralize that choice so
        sample dedupe and default-slot preview wording cannot drift again.
        """

        rows = [list(item) for item in (inventory if inventory is not None else self.macro_inventory_rows())]
        skipped = {str(name).strip() for name in (skip_names or set()) if str(name).strip()}
        for item in rows:
            if str(item[0] if item else '').strip() in skipped:
                continue
            sample = self._macro_inventory_preview_entry_from_row(item)
            if sample:
                return sample
        return ''

    def _macro_broad_inventory_preview_summary(self) -> str:
        """Return one tiny broad macro status+inventory summary."""

        inventory = [list(item) for item in self.macro_inventory_rows()]
        status_rows = [list(item) for item in self.macro_status_rows()]
        status = status_rows[0] if status_rows else ['status', 'idle', '', 0, 0]
        state = str(status[1] if len(status) > 1 else 'idle').strip() or 'idle'
        name = str(status[2] if len(status) > 2 else '').strip()
        try:
            steps = int(status[3] if len(status) > 3 else 0)
        except Exception:
            steps = 0
        sample = self._macro_inventory_preview_sample(inventory, skip_names={name})

        parts: list[str] = [state]
        if name:
            step_word = 'step' if steps == 1 else 'steps'
            parts.append(f"{name} ({steps} {step_word})")
        parts.append(self._count_label(len(inventory), 'macro'))
        if sample:
            parts.append(f"e.g. {sample}")
        return ' · '.join(str(part) for part in parts if str(part))

    def _macro_root_preview_summary(self) -> str:
        """Return one tiny truthful summary for plain ``macro``.

        The umbrella macro entry point is still usage-shaped, but nearby macro
        subcommands already preview live status and saved inventory before
        Enter. Reuse one compact combined witness here too so the root command
        stops collapsing back to generic command metadata and bare syntax.
        """

        summary = self._macro_broad_inventory_preview_summary()
        status_rows = [list(item) for item in self.macro_status_rows()]
        status = status_rows[0] if status_rows else ['status', 'idle', '', 0, 0]
        state = str(status[1] if len(status) > 1 else 'idle').strip() or 'idle'
        name = str(status[2] if len(status) > 2 else '').strip()
        if state == 'idle' and not name:
            return self._macro_idle_default_slot_summary(fallback_summary=summary)

        action_detail = ''
        if state == 'recording':
            action_detail = 'stop to save, cancel to discard'
        elif state == 'playing':
            action_detail = 'wait for playback'
        if not action_detail:
            return summary

        try:
            steps = int(status[3] if len(status) > 3 else 0)
        except Exception:
            steps = 0
        inventory = [list(item) for item in self.macro_inventory_rows()]
        sample = self._macro_inventory_preview_sample(inventory, skip_names={name})
        step_word = 'step' if steps == 1 else 'steps'
        parts: list[str] = [state]
        if name:
            parts.append(f"{name} ({steps} {step_word})")
        parts.append(action_detail)
        parts.append(self._count_label(len(inventory), 'macro'))
        if sample:
            parts.append(f'e.g. {sample}')
        return ' · '.join(str(part) for part in parts if str(part))

    def _macro_default_slot_steps(self) -> int:
        """Return the current recorded step count for the default ``last`` slot.

        A lot of tiny macro summaries now talk about the default slot explicitly.
        Centralize the step-count fetch so step-aware summary helpers do not each
        grow their own ``macro_detail_row('last')`` parsing branch.
        """

        row = self.macro_detail_row('last')
        if row is None:
            return 0
        try:
            return int(row[3] if len(row) >= 4 else 0)
        except Exception:
            return 0

    def _macro_default_slot_steps_label(self) -> str:
        """Return one tiny ``default=last`` label with the current step count."""

        steps = self._macro_default_slot_steps()
        step_word = 'step' if steps == 1 else 'steps'
        return f'default=last ({steps} {step_word})'

    def _macro_idle_default_slot_summary(self, fallback_summary: str | None = None, *, action_detail: str = '') -> str:
        """Return one tiny idle summary centered on the default ``last`` slot.

        Macro inspection and playback both treat ``last`` as the editor's
        default replay slot, so their idle entry points should keep that exact
        slot visible instead of collapsing back to a purely broad inventory
        witness. Callers may optionally splice in one tiny action witness when
        Enter would immediately use the default slot.
        """

        summary = str(fallback_summary or self._macro_broad_inventory_preview_summary())
        row = self.macro_detail_row('last')
        if row is None:
            return summary
        state = str(row[2] if len(row) >= 3 else 'saved')
        if state != 'saved':
            return summary

        inventory = [list(item) for item in self.macro_inventory_rows()]
        sample = self._macro_inventory_preview_sample(inventory, skip_names={'last'})

        parts: list[str] = ['idle', self._macro_default_slot_steps_label()]
        if str(action_detail):
            parts.append(str(action_detail))
        parts.append(self._count_label(len(inventory), 'macro'))
        if sample:
            parts.append(f'e.g. {sample}')
        return ' · '.join(str(part) for part in parts if str(part))

    def _macro_default_slot_play_detail(self, *, count: int | None = None) -> str:
        """Return one tiny playback detail for the default ``last`` slot.

        Exact slot rows, count rows, and bare play/run roots all need the same
        default-slot playback wording. Centralize that tiny choice once so the
        default-slot action dialect cannot drift between those surfaces.
        """

        steps = self._macro_default_slot_steps()
        if steps <= 0:
            return 'default slot empty'
        if count is not None:
            return f'play default slot {int(count)}x'
        return 'play default slot'

    def _macro_default_slot_record_detail(self) -> str:
        """Return one tiny record-detail string for the default slot.

        Bare record roots and exact `macro record last` rows should use the
        same wording for starting a fresh default-slot recording versus opening
        one that will overwrite the saved default slot on save.
        """

        return 'overwrite default slot on save' if self._macro_default_slot_steps() > 0 else 'record default slot'

    def _macro_idle_default_play_summary(self) -> str:
        """Return one tiny idle play/run summary centered on ``last``.

        Bare ``macro play`` / ``macro run`` immediately target the default slot
        on Enter, so their root action rows should preview whether that means
        replaying `last` or stopping on an empty default slot.
        """

        return self._macro_idle_default_slot_summary(action_detail=self._macro_default_slot_play_detail())

    def _macro_idle_default_record_summary(self) -> str:
        """Return one tiny idle record summary centered on ``last``.

        Bare ``macro record`` / ``macro rec`` / ``macro start`` also target
        the default slot on Enter, so their root action rows should preview
        whether that means starting a fresh default-slot recording or opening a
        recording that will overwrite the saved default slot on save.
        """

        return self._macro_idle_default_slot_summary(action_detail=self._macro_default_slot_record_detail())

    def _showmacro_root_preview_summary(self) -> str:
        """Return one tiny truthful summary for plain ``showmacro``.

        ``showmacro NAME`` is an exact-inspection lane rather than the broader
        umbrella macro surface, so its no-arg entry point should keep the
        special default slot visible whenever the editor is idle and exact slot
        choice matters more than a purely broad inventory summary. During live
        recording or playback, though, it should still reuse the same truthful
        runtime witness the umbrella macro root already speaks.
        """

        return self._macro_root_preview_summary()

    def _prompt_macro_root_command_row(self, insert: str) -> list[str]:
        """Return one tiny truthful row for plain ``macro``.

        Plain ``macro`` is still a usage-shaped umbrella command, but Micromax
        already knows the live macro runtime state and saved inventory behind
        that entry point. Keep one compact status+inventory witness visible
        before Enter instead of falling back to generic command metadata.
        """

        row = self._prompt_command_row(insert)
        if len(row) < 4:
            row = list(row) + [''] * (4 - len(row))
        row[3] = self._macro_root_preview_summary()
        return [str(x) for x in row[:4]]

    def _prompt_macro_command_row(self, insert: str, *, subcommand: str) -> list[str]:
        """Return one tiny truthful row for exact macro subcommands.

        Micromax already has tiny shared macro inventory/status registers behind
        both the broad inventory/status commands and the first-step automation
        verbs. Their exact subcommand rows should reuse the same live state
        before Enter instead of collapsing back to a generic ``macro action``
        placeholder.
        """

        raw_sub = str(subcommand or "").strip().lower()
        inventory = [list(item) for item in self.macro_inventory_rows()]
        status_rows = [list(item) for item in self.macro_status_rows()]
        status = status_rows[0] if status_rows else ['status', 'idle', '', 0, 0]
        state = str(status[1] if len(status) > 1 else 'idle')
        name = str(status[2] if len(status) > 2 else '')
        try:
            steps = int(status[3] if len(status) > 3 else 0)
        except Exception:
            steps = 0
        try:
            saved_count = int(status[4] if len(status) > 4 else 0)
        except Exception:
            saved_count = 0
        sample = self._macro_inventory_preview_sample(inventory, skip_names={name})

        def _state_parts(*, include_saved: bool = False, include_default: bool = False) -> list[str]:
            parts: list[str] = [state]
            if name:
                step_word = 'step' if steps == 1 else 'steps'
                parts.append(f"{name} ({steps} {step_word})")
            if include_default:
                parts.append(self._macro_default_slot_steps_label())
            if include_saved:
                parts.append(self._count_label(saved_count, 'macro'))
                if sample:
                    parts.append(f"e.g. {sample}")
            return [str(part) for part in parts if str(part)]

        canonical = {
            'rec': 'record',
            'start': 'record',
            'run': 'play',
            'ls': 'list',
            'st': 'status',
            'end': 'stop',
            'abort': 'cancel',
        }.get(raw_sub, raw_sub)

        if canonical == 'list':
            menu = {
                'list': 'macro list - show saved macro inventory',
                'ls': 'macro ls - show saved macro inventory',
            }.get(raw_sub, 'macro list - show saved macro inventory')
            row = [str(insert), 'subcommand', str(menu), '']
            summary = self._count_label(len(inventory), 'macro')
            if inventory:
                summary += f" · e.g. {sample}"
            row[3] = str(summary)
            return [str(x) for x in row[:4]]

        if canonical == 'status':
            menu = {
                'status': 'macro status - show live macro state',
                'st': 'macro st - show live macro state',
            }.get(raw_sub, 'macro status - show live macro state')
            row = [str(insert), 'subcommand', str(menu), '']
            row[3] = ' · '.join(_state_parts(include_saved=True, include_default=(state == 'idle')))
            return [str(x) for x in row[:4]]

        if canonical == 'play':
            menu = {
                'play': 'macro play [NAME] [COUNT] - play saved macro',
                'run': 'macro run [NAME] [COUNT] - play saved macro',
            }.get(raw_sub, 'macro play [NAME] [COUNT] - play saved macro')
            row = [str(insert), 'subcommand', str(menu), '']
            if state == 'idle':
                row[3] = self._macro_idle_default_play_summary()
            elif state == 'playing':
                row[3] = ' · '.join(_state_parts()) + ' · wait for playback'
            elif state == 'recording':
                row[3] = ' · '.join(_state_parts()) + ' · stop or cancel first'
            else:
                row[3] = ' · '.join(_state_parts(include_saved=True))
            return [str(x) for x in row[:4]]

        if canonical == 'record':
            menu = {
                'record': 'macro record [NAME] - start recording macro',
                'rec': 'macro rec [NAME] - start recording macro',
                'start': 'macro start [NAME] - start recording macro',
            }.get(raw_sub, 'macro record [NAME] - start recording macro')
            row = [str(insert), 'subcommand', str(menu), '']
            if state == 'recording':
                row[3] = ' · '.join(_state_parts()) + ' · stop or cancel first'
            elif state == 'playing':
                row[3] = ' · '.join(_state_parts()) + ' · wait for playback'
            else:
                row[3] = self._macro_idle_default_record_summary()
            return [str(x) for x in row[:4]]

        if canonical == 'stop':
            menu = {
                'stop': 'macro stop - stop recording and save',
                'end': 'macro end - stop recording and save',
            }.get(raw_sub, 'macro stop - stop recording and save')
            row = [str(insert), 'subcommand', str(menu), '']
            if state == 'recording':
                row[3] = ' · '.join(_state_parts()) + ' · save macro'
            elif state == 'playing':
                row[3] = ' · '.join(_state_parts()) + ' · wait for playback'
            else:
                row[3] = ' · '.join(_state_parts()) + ' · not recording'
            return [str(x) for x in row[:4]]

        if canonical == 'cancel':
            menu = {
                'cancel': 'macro cancel - stop recording and discard',
                'abort': 'macro abort - stop recording and discard',
            }.get(raw_sub, 'macro cancel - stop recording and discard')
            row = [str(insert), 'subcommand', str(menu), '']
            if state == 'recording':
                row[3] = ' · '.join(_state_parts()) + ' · discard macro'
            elif state == 'playing':
                row[3] = ' · '.join(_state_parts()) + ' · wait for playback'
            else:
                row[3] = ' · '.join(_state_parts()) + ' · not recording'
            return [str(x) for x in row[:4]]

        if raw_sub:
            return [str(insert), 'subcommand', 'missing subcommand', f'no such subcommand: {raw_sub}']
        return [str(insert), 'subcommand', 'macro action', '']

    def _prompt_macro_slot_row(self, insert: str, *, subcommand: str) -> list[str]:
        """Return one tiny truthful row for exact macro-slot arguments.

        ``macro play NAME`` and ``macro record NAME`` already depend on the same
        saved-slot inventory. Their exact slot rows should show known step counts
        and whether Enter would play or overwrite that slot instead of falling
        back to a generic ``macro slot`` placeholder.

        When live macro state already blocks the typed slot command, reuse the
        same tiny blocker witness the parent subcommand row already shows so the
        exact target stops looking more runnable than the command root.
        """

        raw = str(insert)
        name = raw[:-1] if raw.endswith(' ') else raw
        raw_sub = str(subcommand or '').strip().lower()
        row = [str(insert), 'macro', '', '']
        inventory = {
            str(item[0]): list(item)
            for item in self.macro_inventory_rows()
            if item and str(item[0])
        }
        slot = inventory.get(str(name))
        status_rows = [list(item) for item in self.macro_status_rows()]
        status = status_rows[0] if status_rows else ['status', 'idle', '', 0, 0]
        state = str(status[1] if len(status) > 1 else 'idle').strip() or 'idle'
        canonical = {
            'run': 'play',
            'record': 'record',
            'rec': 'record',
            'start': 'record',
        }.get(raw_sub, raw_sub)
        if slot is not None:
            row[2] = self._macro_inventory_entry_from_row(slot)
            if canonical in {'play', 'record'} and str(row[2]):
                row[2] = self._macro_badge_default_entry(str(row[2]), name=str(name))
        elif canonical == 'record' and str(name) == 'last':
            row[2] = 'last [default]'
        elif canonical == 'record':
            row[2] = 'new macro slot'
        elif str(name) == 'last':
            row[2] = self._macro_empty_default_slot_entry()
        else:
            row[2] = 'missing macro'

        if canonical == 'play':
            if state in {'recording', 'playing'}:
                blocker = self._prompt_macro_command_row(f'{raw_sub} ', subcommand=raw_sub)
                row[3] = str(blocker[3] if len(blocker) > 3 else ('stop or cancel first' if state == 'recording' else 'wait for playback'))
            else:
                if str(name) == 'last':
                    row[3] = self._macro_default_slot_play_detail()
                else:
                    row[3] = 'play macro' if slot is not None else 'no such macro'
        elif canonical == 'record':
            if state in {'recording', 'playing'}:
                blocker = self._prompt_macro_command_row(f'{raw_sub} ', subcommand=raw_sub)
                row[3] = str(blocker[3] if len(blocker) > 3 else '')
            elif slot is not None:
                if str(name) == 'last':
                    row[3] = self._macro_default_slot_record_detail()
                else:
                    row[3] = 'overwrite on save'
            elif str(name) == 'last':
                row[3] = self._macro_default_slot_record_detail()
            else:
                row[3] = 'record new macro'
        return [str(x) for x in row[:4]]


    def _prompt_macro_count_row(self, insert: str, *, subcommand: str, slot_name: str) -> list[str]:
        """Return one tiny truthful row for exact macro playback counts.

        ``macro play NAME COUNT`` and ``macro run NAME COUNT`` already depend on
        the same saved-slot inventory and runtime blockers as the earlier macro
        tokens. The exact count row should preview whether Enter would replay,
        reject a missing slot, or reject a malformed/non-positive count instead
        of going blank until runtime.
        """

        raw = str(insert)
        token = raw[:-1] if raw.endswith(' ') else raw
        raw_sub = str(subcommand or '').strip().lower()
        name = str(slot_name or '').strip()
        row = [str(insert), 'count', '', '']
        slot = None
        for item in self.macro_inventory_rows():
            if item and str(item[0]) == name:
                slot = list(item)
                break
        if slot is not None:
            row[2] = self._macro_inventory_entry_from_row(slot)
            if str(row[2]):
                row[2] = self._macro_badge_default_entry(str(row[2]), name=str(name))
        elif str(name) == 'last':
            row[2] = self._macro_empty_default_slot_entry()
        else:
            row[2] = 'missing macro'

        if getattr(self, 'macro_recording', False) or getattr(self, '_macro_playing', False):
            blocker = self._prompt_macro_command_row(f'{raw_sub} ', subcommand=raw_sub)
            row[3] = str(blocker[3] if len(blocker) > 3 else ('stop or cancel first' if getattr(self, 'macro_recording', False) else 'wait for playback'))
            return [str(x) for x in row[:4]]

        try:
            count = int(str(token), 10)
        except Exception:
            row[3] = 'count must be an int'
            return [str(x) for x in row[:4]]
        if count <= 0:
            row[3] = 'count must be > 0'
            return [str(x) for x in row[:4]]

        if slot is None:
            row[3] = self._macro_default_slot_play_detail() if str(name) == 'last' else 'no such macro'
            return [str(x) for x in row[:4]]
        if str(name) == 'last':
            row[3] = self._macro_default_slot_play_detail(count=count)
        else:
            row[3] = f'play {count}x'
        return [str(x) for x in row[:4]]

    def _prompt_macro_arity_row(self, insert: str, *, subcommand: str) -> list[str]:
        """Return one tiny truthful row for over-arity macro paths.

        Macro completion already knows the exact subcommand and when the typed
        path has spilled past the supported arity. Keep that tiny contract
        visible before Enter too so stray tail tokens do not look harmless when
        runtime would reject them.
        """

        raw_sub = str(subcommand or '').strip().lower()
        if raw_sub in ('stop', 'end', 'cancel', 'abort', 'list', 'ls', 'status', 'st'):
            label = {
                'stop': 'macro stop',
                'end': 'macro end',
                'cancel': 'macro cancel',
                'abort': 'macro abort',
                'list': 'macro list',
                'ls': 'macro ls',
                'status': 'macro status',
                'st': 'macro st',
            }.get(raw_sub, f'macro {raw_sub}')
            return [str(insert), 'arg', str(label), 'takes no args']
        if raw_sub in ('record', 'rec', 'start'):
            label = {
                'record': 'macro record [NAME]',
                'rec': 'macro rec [NAME]',
                'start': 'macro start [NAME]',
            }.get(raw_sub, 'macro record [NAME]')
            return [str(insert), 'arg', str(label), 'takes at most 1 arg']
        if raw_sub in ('play', 'run'):
            label = {
                'play': 'macro play [NAME] [COUNT]',
                'run': 'macro run [NAME] [COUNT]',
            }.get(raw_sub, 'macro play [NAME] [COUNT]')
            return [str(insert), 'arg', str(label), 'takes at most 2 args']
        return [str(insert), 'arg', f'macro {raw_sub}'.strip() or 'macro', 'unexpected arg']


    def _prompt_option_value_candidates(
        self,
        name: str,
        prefix: str,
        *,
        at_eol: bool,
    ) -> tuple[list[str], bool]:
        spec = self.options.spec(str(name))
        if spec is None:
            return ([], False)
        if spec.kind == "bool":
            return self._completion_candidates_for_prefix(["true", "false"], prefix, at_eol=at_eol)
        if spec.kind == "enum" and spec.enum:
            return self._completion_candidates_for_prefix(list(spec.enum), prefix, at_eol=at_eol)
        return ([], False)


    def _prompt_display_value(self, value: object) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        if value is None:
            return "0"
        return str(value)

    def _option_kind_label(self, spec: object) -> str:
        kind = str(getattr(spec, "kind", "") or "")
        enum = getattr(spec, "enum", None)
        if kind == "enum" and enum:
            kind = kind + "[" + "|".join(str(x) for x in enum) + "]"
        return kind

    def option_inventory_rows(self, *, names: list[str] | None = None) -> list[list[object]]:
        local_options = self.cur().local_options if (self.active is not None and self.active in self.buffers) else None
        rows: list[list[object]] = []
        specs: list[object] = []
        if names is None:
            specs = list(self.options.list_specs())
        else:
            seen: set[str] = set()
            for name in names:
                spec = self.options.canonical_spec(str(name))
                if spec is None:
                    continue
                canonical = str(spec.name)
                if canonical in seen:
                    continue
                seen.add(canonical)
                specs.append(spec)
        for spec in specs:
            name = str(getattr(spec, "name", "") or "")
            value = self.options.get(name, local=local_options)
            default = getattr(spec, "default", None)
            local_override = 1 if (local_options is not None and name in local_options) else 0
            rows.append(
                [
                    name,
                    self._display_option_value(name, value),
                    self._display_option_value(name, default),
                    self._option_kind_label(spec),
                    int(local_override),
                ]
            )
        return rows

    def option_detail_row(self, name: str) -> list[object] | None:
        """Return one tiny shared exact option-detail row.

        The row keeps single-option config inspection just as inspectable as the
        broader canonical ``show`` inventory: callers can ask one narrow
        question - what does this exact option name mean right now? - without
        scraping command text or rejoining alias/default/local/doc metadata by
        hand.

        Returns ``[query canonical value default kind local_override doc]`` and
        preserves the queried spelling so alias-driven inspection remains
        explicit too. Returns ``None`` when ``name`` is not a known option.
        """

        raw = str(name or "").strip()
        if not raw:
            return None
        query_spec = self.options.spec(raw)
        canonical_spec = self.options.canonical_spec(raw)
        if query_spec is None or canonical_spec is None:
            return None
        local_options = self.cur().local_options if (self.active is not None and self.active in self.buffers) else None
        canonical = str(canonical_spec.name)
        value = self.options.get(raw, local=local_options)
        default = getattr(canonical_spec, "default", None)
        local_override = 1 if (local_options is not None and canonical in local_options) else 0
        doc = str(getattr(query_spec, "doc", "") or getattr(canonical_spec, "doc", "") or "")
        return [
            raw,
            canonical,
            self._display_option_value(canonical, value),
            self._display_option_value(canonical, default),
            self._option_kind_label(canonical_spec),
            int(local_override),
            doc,
        ]

    def _option_section_label_for_name(self, name: str) -> str:
        raw = str(name or "").strip()
        if "." not in raw:
            return "Editor"
        head = raw.split(".", 1)[0]
        labels = {
            "cap": "Capabilities",
            "help": "Help",
            "history": "History",
            "jumplist": "Jumplist",
            "open-url": "Open URL",
            "page": "Paging",
            "prompt": "Prompt",
            "recent": "Recent",
            "savecursor": "Save Cursor",
            "softwrap": "Soft Wrap",
            "tui": "TUI",
            "viewport": "Viewport",
        }
        if head in labels:
            return str(labels[head])
        return head.replace("-", " ").replace("_", " ").title() or "Editor"

    def _option_section_label(self, row: list[str]) -> str:
        return self._option_section_label_for_name(str(row[0] if row else ""))

    def _option_section_label_rank(self, label: str) -> tuple[int, str]:
        lbl = str(label or "")
        if lbl == "Editor":
            return (0, lbl.casefold())
        return (1, lbl.casefold())

    def _option_section_sort_key(self, row: list[str]) -> tuple[int, str, str]:
        label = self._option_section_label(row)
        rank, folded = self._option_section_label_rank(label)
        name = str(row[0] if row else "")
        return (int(rank), str(folded), name.casefold())

    def option_prompt_rows(self) -> list[list[str]]:
        """Return canonical option prompt rows for browse/search/summary use."""

        rows: list[list[str]] = []
        for name, value, default, kind, local_override in self.option_inventory_rows():
            canonical = str(name)
            spec = self.options.canonical_spec(canonical)
            doc = str(getattr(spec, "doc", "") or "")
            menu = f"{kind} value={value} default={default}"
            if int(local_override):
                menu += " (local)"
            rows.append([canonical, "option", menu, doc])
        rows.sort(key=self._option_section_sort_key)
        return rows

    def _option_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        return prompt_picker_row_sort_key(row, query)

    def option_apropos_rows(self, query: str = "", *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.option_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._option_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1]))
        out = [row for _key, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def option_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group canonical options by visible config-family label."""

        rows = self.option_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._option_section_label,
            label_sort_key=self._option_section_label_rank,
        )

    def option_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware option-family summaries.

        Each row is ``[label count sample_name sample_detail]`` and reuses the
        first visible option row from each family section. This keeps broad
        config discovery inspectable without forcing scripts or future UIs to
        walk the full canonical option inventory just to answer what families of
        knobs exist right now.
        """

        return self._section_summary_rows(self.option_section_rows(query, limit=limit))


    def _option_inventory_preview_summary(self) -> str:
        """Return one tiny live option-inventory witness.

        Plain ``showoption`` is still a usage-shaped exact inspector, but its
        root entry point should not collapse back to generic command metadata
        when Micromax already knows the active option inventory. Keep the
        preview compact and favor one local override when present so the calm
        current-buffer config state stays visible before Enter and after it.
        """

        inventory = self.option_inventory_rows()
        count = len(inventory)
        summary = self._count_label(count, 'option')
        if not inventory:
            return summary
        target = next(
            (
                list(row)
                for row in inventory
                if len(row) >= 5 and int(row[4]) != 0 and len(row) >= 3 and str(row[1]) != str(row[2])
            ),
            next((list(row) for row in inventory if len(row) >= 5 and int(row[4]) != 0), list(inventory[0])),
        )
        name = str(target[0]) if len(target) >= 1 else ''
        value = str(target[1]) if len(target) >= 2 else ''
        local_override = 0
        try:
            local_override = int(target[4]) if len(target) >= 5 else 0
        except Exception:
            local_override = 0
        if not name:
            return summary
        detail = f"{name}={value}"
        if local_override:
            detail += " (local)"
        return f"{summary} · {detail}"

    def _prompt_exact_option_row(
        self,
        insert: str,
        *,
        fallback_info: str = "",
        strict_missing: bool = False,
    ) -> list[str]:
        raw = str(insert)
        name = raw[:-1] if raw.endswith(" ") else raw
        row = self.option_detail_row(name)
        if row is None:
            if strict_missing and name.strip():
                return [str(insert), "option", "missing option", "no such option"]
            return [str(insert), "option", "", str(fallback_info or "")]
        query = str(row[0]) if len(row) >= 1 else name
        canonical = str(row[1]) if len(row) >= 2 else query
        value = str(row[2]) if len(row) >= 3 else ""
        kind = str(row[4]) if len(row) >= 5 else "option"
        local_override = int(row[5]) if len(row) >= 6 else 0
        doc = str(row[6]) if len(row) >= 7 else ""
        menu = f"{kind} value={value}"
        if local_override:
            menu += " (local)"
        if canonical and canonical != query:
            menu += f" alias for {canonical}"
        return [str(insert), "option", menu, doc or str(fallback_info or "inspect exact option")]

    def _prompt_showoption_command_row(self, insert: str) -> list[str]:
        """Return one tiny truthful row for plain ``showoption``.

        ``showoption NAME`` is an exact inspector, but the root entry point
        should keep one compact live option-inventory witness visible before it
        asks for one exact option name.
        """

        row = self._prompt_command_row(insert)
        if len(row) < 4:
            row = list(row) + [''] * (4 - len(row))
        row[3] = self._option_inventory_preview_summary()
        return [str(x) for x in row[:4]]

    def _prompt_option_row(self, name: str, *, local: bool) -> list[str]:
        spec = self.options.spec(str(name))
        if spec is None:
            return [str(name), "option", "", ""]

        scope = "local" if local else "global"
        kind = self._option_kind_label(spec)

        cur_local = self.cur().local_options if local else None
        cur = self.options.get(spec.name, local=cur_local)
        menu = f"{kind} {scope} current={self._prompt_display_value(cur)} default={self._prompt_display_value(spec.default)}"
        return [spec.name + " ", "option", menu, str(spec.doc or "")]

    def _prompt_path_row(self, insert: str) -> list[str]:
        import os

        raw = str(insert)
        body = raw[:-1] if raw.endswith(" ") else raw
        if body.startswith(("'", '"')):
            body = body[1:]
        if body.endswith(("'", '"')):
            body = body[:-1]
        kind = "dir" if body.endswith(os.sep) else "file"
        menu = "directory" if kind == "dir" else "file"
        return [str(insert), kind, menu, body]

    def _help_topic_meta_text(self, row: list[object]) -> str:
        parts: list[str] = []
        if len(row) >= 3 and row[2] not in (None, 0, ""):
            parts.append(str(row[2]))
        if len(row) >= 4 and row[3] not in (None, 0, ""):
            parts.append(str(row[3]))
        return " ".join(parts).strip()

    def _search_terms(self, query: str) -> list[str]:
        return prompt_search_terms(query)

    def _multi_term_field_key(
        self,
        fields: list[tuple[int, str]],
        query: str,
        *,
        fallback_rank: int,
        tie_name: str,
    ) -> RowSortKey | None:
        return prompt_multi_term_field_key(
            fields,
            query,
            fallback_rank=fallback_rank,
            tie_name=tie_name,
        )

    def _apropos_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        q = str(query or "").strip()
        if q == "":
            return (0, 0, 0, 0, 0, 0, 0, 0, 0, "")

        name = str(row[0]) if row else ""
        kind = str(row[1]) if len(row) >= 2 else ""
        name_key = self._completion_fuzzy_sort_key(name, q)
        if name_key is not None:
            return (0, *name_key, name.casefold())

        meta = self._help_topic_meta_text(row)
        meta_contains_rank = 1 if kind != "doc" else 3
        meta_fuzzy_rank = 2 if kind != "doc" else 4
        multi_term_rank = 3 if kind != "doc" else 5
        if meta:
            folded_meta = meta.casefold()
            folded_q = q.casefold()
            if folded_q and folded_q in folded_meta:
                pos = folded_meta.find(folded_q)
                return (meta_contains_rank, pos, pos, 0, 0, 0, 0, len(meta), len(name), name.casefold())

            meta_key = self._completion_fuzzy_sort_key(meta, q)
            if meta_key is not None:
                return (meta_fuzzy_rank, *meta_key, name.casefold())

        multi_key = self._multi_term_field_key([(0, name), (1, meta)], q, fallback_rank=multi_term_rank, tie_name=name)
        if multi_key is not None:
            return multi_key
        return None

    def _command_palette_row_key(self, row: list[object]) -> tuple[str, str]:
        name = str(row[0]) if row else ""
        kind = str(row[1]) if len(row) >= 2 else ""
        return (kind, name)

    def _normalize_palette_recent_authority(self) -> None:
        """Keep command-palette MRU provenance aligned with visible rows."""

        missing = len(self._palette_recent) - len(self._palette_recent_authority)
        if missing > 0:
            self._palette_recent_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del self._palette_recent_authority[len(self._palette_recent):]

    def _snapshot_palette_recent_authority(self) -> tuple[RuntimeRegistrationAuthority, ...]:
        self._normalize_palette_recent_authority()
        return tuple(self._clone_mark_authority(auth) for auth in self._palette_recent_authority)

    def _restore_palette_recent_authority(
        self,
        snapshot: tuple[RuntimeRegistrationAuthority, ...] | list[RuntimeRegistrationAuthority] | None,
    ) -> None:
        self._palette_recent_authority[:] = [
            self._clone_mark_authority(auth) for auth in list(snapshot or [])
        ]
        self._normalize_palette_recent_authority()

    def _guard_palette_recent_entry_mutation(self, index: int, action: str) -> None:
        """Raise if current lower-authority code may not reorder/erase a palette MRU row."""

        self._normalize_palette_recent_authority()
        if not (0 <= int(index) < len(self._palette_recent_authority)):
            return
        kind, name = self._palette_recent[int(index)]
        self._guard_runtime_registration_mutation(
            kind="command-palette MRU",
            target=f"{int(index) + 1}:{kind}:{name}:{action}",
            authority=self._clone_mark_authority(self._palette_recent_authority[int(index)]),
            current_kind="editor",
        )

    def _palette_recent_entry_visible(self, index: int) -> bool:
        """Return whether the current caller may inspect one palette MRU row."""

        self._normalize_palette_recent_authority()
        if not self.in_script_context():
            return True
        if not (0 <= int(index) < len(self._palette_recent_authority)):
            return False
        current = self._current_runtime_authority(kind="editor")
        target = self._clone_mark_authority(self._palette_recent_authority[int(index)])
        return bool(script_runtime_mutation_policy(current, target).allowed)

    def _visible_palette_recent_entries(self) -> list[tuple[str, str]]:
        self._normalize_palette_recent_authority()
        out: list[tuple[str, str]] = []
        for idx, (kind, name) in enumerate(list(self._palette_recent)):
            if self._palette_recent_entry_visible(idx):
                out.append((str(kind), str(name)))
        return out

    def _record_palette_recent(self, kind: str, name: str) -> bool:
        k = str(kind or "").strip()
        nm = str(name or "").strip()
        if k not in ("command", "action") or not nm:
            return False
        entry = (k, nm)
        self._normalize_palette_recent_authority()
        original_rows = list(self._palette_recent)
        original_authority = self._snapshot_palette_recent_authority()

        existing_index: int | None = None
        for idx, old in enumerate(list(self._palette_recent)):
            if old == entry:
                existing_index = int(idx)
                break

        try:
            if existing_index is not None:
                self._guard_palette_recent_entry_mutation(existing_index, "reorder")
        except PermissionError:
            self._palette_recent[:] = original_rows
            self._restore_palette_recent_authority(original_authority)
            return False

        if existing_index is not None:
            del self._palette_recent[existing_index]
            del self._palette_recent_authority[existing_index]
        self._palette_recent.insert(0, entry)
        self._palette_recent_authority.insert(0, self._current_runtime_authority(kind="editor"))

        limit = max(1, int(self._palette_recent_limit))
        while len(self._palette_recent) > limit:
            dropped = False
            for idx in range(len(self._palette_recent) - 1, -1, -1):
                try:
                    self._guard_palette_recent_entry_mutation(idx, "drop-oldest")
                except PermissionError:
                    continue
                del self._palette_recent[idx]
                del self._palette_recent_authority[idx]
                dropped = True
                break
            if not dropped:
                self._palette_recent[:] = original_rows
                self._restore_palette_recent_authority(original_authority)
                return False
        return bool(self._palette_recent and self._palette_recent[0] == entry)

    def _remove_palette_recent_rows_for_authority(
        self,
        predicate: Callable[[RuntimeRegistrationAuthority], bool],
    ) -> int:
        """Remove command-palette MRU rows matching an authority predicate."""

        self._normalize_palette_recent_authority()
        kept_rows: list[tuple[str, str]] = []
        kept_authority: list[RuntimeRegistrationAuthority] = []
        removed = 0
        for row, authority in zip(list(self._palette_recent), list(self._palette_recent_authority)):
            auth = self._clone_mark_authority(authority)
            if predicate(auth):
                removed += 1
                continue
            kept_rows.append((str(row[0]), str(row[1])))
            kept_authority.append(auth)
        if removed:
            self._palette_recent[:] = kept_rows
            self._palette_recent_authority[:] = kept_authority
        self._normalize_palette_recent_authority()
        return int(removed)

    def remove_palette_recent_group(self, group: object) -> int:
        """Remove command-palette MRU rows owned by one runtime group."""

        raw = str(group or "")
        if not raw:
            return 0
        return self._remove_palette_recent_rows_for_authority(
            lambda authority: self._authority_group_matches(authority, raw)
        )

    def retag_palette_recent_group(self, old: object, new: object) -> int:
        """Retag staged command-palette MRU rows after successful plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        self._normalize_palette_recent_authority()
        changed = 0
        for idx, authority in enumerate(list(self._palette_recent_authority)):
            auth = self._clone_mark_authority(authority)
            if not self._authority_group_matches(auth, old_s):
                continue
            self._palette_recent_authority[idx] = self._authority_with_group(auth, new_s)
            changed += 1
        self._normalize_palette_recent_authority()
        return int(changed)

    def remove_plugin_palette_recent_generation(
        self,
        plugin_load_root: object,
        plugin_generation: object,
    ) -> int:
        """Remove command-palette MRU rows owned by one plugin generation."""

        return self._remove_palette_recent_rows_for_authority(
            lambda authority: self._authority_matches_plugin_generation(
                authority,
                plugin_load_root=plugin_load_root,
                plugin_generation=plugin_generation,
            )
        )

    def _command_palette_recent_rank(self, row: list[object]) -> int:
        entry = self._command_palette_row_key(row)
        visible = self._visible_palette_recent_entries()
        try:
            return visible.index(entry)
        except ValueError:
            return max(1000, len(visible) + 100)

    def command_palette_recent_rows(self, *, limit: int | None = None) -> list[list[str]]:
        rows: list[list[str]] = []
        for kind, name in self._visible_palette_recent_entries():
            if kind == "command":
                c = self.command_dispatcher.get(name)
                if c is None:
                    continue
                info = f"group={c.group}" if c.group else ""
                rows.append([str(name), "command", str(c.doc or ""), info])
                continue
            if kind == "action":
                a = self.actions.get(name)
                if a is None or not self._action_read_allowed(a):
                    continue
                rows.append([str(name), "action", str(a.doc or ""), ""])
        return rows[:limit] if limit is not None else rows

    def _command_palette_recent_file_row(self, path: str) -> list[str]:
        """Return one command-palette recent-file row with exact MRU metadata.

        The palette already treats recent files as a first-class execution path,
        so when one visible row is also one exact recent entry Micromax should
        keep the same recency/state/detail cues exposed through
        ``recent_detail_row(PATH)`` instead of flattening back to basename +
        parent only.
        """

        stored = str(path or "")
        try:
            fallback_path = Path(stored)
            fallback_menu = str(fallback_path.name) if fallback_path.name else "file"
            fallback_info = str(fallback_path.parent) if str(fallback_path.parent) not in (".", "") else ""
        except Exception:
            fallback_menu, fallback_info = "file", ""

        row = self.recent_detail_row(stored)
        if row is None:
            return [stored, "recentfile", fallback_menu, fallback_info]

        actual = str(row[1]) if len(row) >= 2 else stored
        index = int(row[2]) if len(row) >= 3 else 0
        position = str(row[3]) if len(row) >= 4 else ""
        active = int(row[4]) if len(row) >= 5 else 0
        open_flag = int(row[5]) if len(row) >= 6 else 0
        dirty = int(row[6]) if len(row) >= 7 else 0
        readonly = int(row[7]) if len(row) >= 8 else 0
        section = str(row[8]) if len(row) >= 9 else ""
        detail = str(row[9]) if len(row) >= 10 else ""
        disk_truth = str(row[10]) if len(row) >= 11 else ""
        action_truth = str(row[11]) if len(row) >= 12 else ""

        try:
            pp = Path(actual)
            menu = str(pp.name) if pp.name else fallback_menu
        except Exception:
            menu = fallback_menu
        if index > 0:
            menu += f" #{index}"
        flags: list[str] = []
        if active:
            flags.append("active")
        elif open_flag:
            flags.append("open")
        if dirty:
            flags.append("dirty")
        if readonly:
            flags.append("readonly")
        if flags:
            menu += " [" + ", ".join(flags) + "]"
        if position and open_flag:
            menu += f" @ {position}"

        # The menu already carries the file identity (`name #N [flags] @ line:col`).
        # Keep the info slot focused on landing context so saved/missing recent rows
        # answer "where is this target?" instead of repeating the basename or the
        # same section directory twice.
        basename = ""
        try:
            basename = str(Path(actual).name)
        except Exception:
            basename = ""
        info = " | ".join(self._recent_location_parts(section, detail, basename=basename)) or fallback_info

        info = self._append_palette_action_cue(info, disk_truth)
        info = self._append_palette_action_cue(info, action_truth)

        return [actual, "recentfile", menu, info]

    def _recent_file_truth_cues(self, path: str) -> tuple[str, str]:
        """Return tiny disk/action truth cues for one remembered recent file."""

        raw = str(path or "")
        disk_truth = ""
        missing_file = False
        if bool(self.options.get("cap.fs-list")):
            try:
                resolved = fs_resolve_path(self, raw)
                if fs_path_allowed(self, resolved):
                    if resolved.exists() and not resolved.is_dir():
                        disk_truth = "existing file"
                    elif not resolved.exists():
                        missing_file = True
                        disk_truth = "new file"
            except Exception:
                pass
        action_truth = self._command_palette_file_action_cue(raw)
        if missing_file and not action_truth:
            action_truth = "empty buffer @ 1:0"
        return disk_truth, action_truth

    def _command_palette_dir_info(self, path: str, *, fallback_info: str = "") -> str:
        """Return tiny directory context for one visible palette path."""

        raw = str(path or "")
        info = str(fallback_info or "")
        row = self.recent_dir_detail_row(raw) or self.recent_dir_detail_row(raw.rstrip("/\\"))
        if row is None:
            return info

        try:
            count = int(row[2]) if len(row) >= 3 else 0
        except Exception:
            count = 0
        try:
            active_count = int(row[3]) if len(row) >= 4 else 0
        except Exception:
            active_count = 0
        try:
            open_count = int(row[4]) if len(row) >= 5 else 0
        except Exception:
            open_count = 0
        try:
            dirty_count = int(row[5]) if len(row) >= 6 else 0
        except Exception:
            dirty_count = 0
        try:
            readonly_count = int(row[6]) if len(row) >= 7 else 0
        except Exception:
            readonly_count = 0
        label = f"recent dir: {count} file" + ("" if count == 1 else "s")
        flags: list[str] = []
        if active_count == 1:
            flags.append("active")
        elif active_count > 1:
            flags.append(f"active={active_count}")
        if open_count > 0:
            flags.append(f"open={open_count}")
        if dirty_count > 0:
            flags.append(f"dirty={dirty_count}")
        if readonly_count > 0:
            flags.append(f"readonly={readonly_count}")
        if flags:
            label += " [" + ", ".join(flags) + "]"
        return label or info

    def _command_palette_file_info(self, path: str, *, fallback_info: str = "") -> str:
        """Return tiny file context for one visible palette path."""

        raw = str(path or "")
        info = str(fallback_info or "")
        row = self.recent_detail_row(raw)
        if row is not None:
            try:
                index = int(row[2]) if len(row) >= 3 else 0
            except Exception:
                index = 0
            position = str(row[3]) if len(row) >= 4 else ""
            try:
                active = int(row[4]) if len(row) >= 5 else 0
            except Exception:
                active = 0
            try:
                open_flag = int(row[5]) if len(row) >= 6 else 0
            except Exception:
                open_flag = 0
            try:
                dirty = int(row[6]) if len(row) >= 7 else 0
            except Exception:
                dirty = 0
            try:
                readonly = int(row[7]) if len(row) >= 8 else 0
            except Exception:
                readonly = 0
            section = str(row[8]) if len(row) >= 9 else ""
            detail = str(row[9]) if len(row) >= 10 else ""
            disk_truth = str(row[10]) if len(row) >= 11 else ""
            if raw and str(Path(raw).name) != str(raw):
                detail = raw
            elif disk_truth == "new file" and section:
                # For one bare filename that already maps to an open unsaved buffer,
                # the query/menu already shows the basename. Keep the landing
                # directory visible so humans/LLMs can still see where reopen/save
                # will land instead of repeating the filename again.
                detail = section
            label = f"recent #{index}" if index > 0 else "recent"
            flags: list[str] = []
            if active:
                flags.append("active")
            elif open_flag:
                flags.append("open")
            if dirty:
                flags.append("dirty")
            if readonly:
                flags.append("readonly")
            if flags:
                label += " [" + ", ".join(flags) + "]"
            if position and open_flag:
                label += f" @ {position}"
            extras = [part for part in (label, detail) if str(part or "")]
            return " | ".join(extras) or info

        eb = self._buffer_for_path(raw)
        if eb is None:
            return info
        brow = self.buffer_detail_row(str(getattr(eb, "name", "") or raw))
        if brow is None:
            return info

        position = str(brow[1]) if len(brow) >= 2 else ""
        try:
            active = int(brow[2]) if len(brow) >= 3 else 0
        except Exception:
            active = 0
        try:
            dirty = int(brow[3]) if len(brow) >= 4 else 0
        except Exception:
            dirty = 0
        try:
            readonly = int(brow[4]) if len(brow) >= 5 else 0
        except Exception:
            readonly = 0
        label = "active" if active else "open"
        flags: list[str] = []
        if dirty:
            flags.append("dirty")
        if readonly:
            flags.append("readonly")
        if flags:
            label += " [" + ", ".join(flags) + "]"
        if position:
            label += f" @ {position}"
        return label or info

    def _append_palette_action_cue(self, info: str, cue: str) -> str:
        """Append one tiny non-duplicated action cue to picker detail text."""

        base = str(info or "").strip()
        extra = str(cue or "").strip()
        if not extra:
            return base
        parts = [part.strip() for part in base.split("|") if part.strip()]
        folded = {part.casefold() for part in parts}
        if extra.casefold() not in folded:
            parts.append(extra)
        return " | ".join(parts)

    def _trim_leading_location_echo(self, info: str, *echoes: str) -> str:
        """Return picker/detail text with one repeated leading cue removed.

        Some exact inspection surfaces already name the directory, section, or
        sample file in their visible label, then reuse a richer row whose first
        detail slot repeats that same cue. Dropping one echoed prefix keeps the
        row truthful without spending its first slot on information the caller
        can already see.
        """

        base = str(info or "").strip()
        wants = [str(item or "").strip() for item in echoes if str(item or "").strip()]
        if not base or not wants:
            return base
        parts = [part.strip() for part in base.split("|") if part.strip()]
        if parts and parts[0] in wants:
            parts = parts[1:]
        return " | ".join(parts)

    def _recent_location_parts(self, section: str, detail: str, *, basename: str = "") -> list[str]:
        """Return non-redundant recent-file location parts for visible row text.

        Recent-file surfaces often want both the broad visible section root and
        one more specific landing cue. When the file already lives directly
        under that visible section, repeating the same directory twice wastes
        space without adding trust.
        """

        section_text = str(section or "").strip()
        detail_text = str(detail or "").strip()
        basename_text = str(basename or "").strip()

        parts: list[str] = []
        if section_text:
            parts.append(f"section={section_text}")

        location = detail_text
        if location and basename_text and location == basename_text and section_text:
            location = section_text
        if location and section_text and location == section_text:
            location = ""
        if location:
            parts.append(location)
        return parts

    def _command_palette_file_action_cue(self, path: str) -> str:
        """Return one tiny action cue for an already-open file target."""

        eb = self._buffer_for_path(str(path or ""))
        if eb is None:
            return ""
        current = None
        try:
            current = self.cur()
        except Exception:
            current = None
        return "current buffer" if current is eb else "switch buffer"

    def _format_linecol(self, cur: Cursor | None) -> str:
        """Return tiny 1-based ``line:col`` text for one cursor."""

        if cur is None:
            return ""
        return f"{int(cur.line) + 1}:{int(cur.col)}"

    def _command_palette_open_cursor_cue(self, path: str, cur: Cursor | None) -> str:
        """Return one tiny exact goto cue for an already-open parsecursor target."""

        if cur is None:
            return ""
        eb = self._buffer_for_path(str(path or ""))
        if eb is None:
            return ""
        target = eb.buf.clamp(Cursor(int(cur.line), int(cur.col)))
        pos = self._format_linecol(target)
        if not pos:
            return ""
        return f"goto {pos}"

    def _command_palette_open_cursor_request_cue(self, cur: Cursor | None) -> str:
        """Return one tiny requested cursor cue for non-open parsecursor file targets."""

        if cur is None:
            return ""
        pos = self._format_linecol(cur)
        if not pos:
            return ""
        return f"cursor {pos}"

    def _command_palette_new_file_landing_cue(self, cur: Cursor | None) -> str:
        """Return one tiny exact landing cue for a new-file parsecursor target."""

        if cur is None:
            return ""
        return "empty buffer @ 1:0"

    def _command_palette_open_path_row(self, path: str, menu: str, *, fallback_info: str = "") -> list[str]:
        """Return one command-palette filesystem row with best-effort context.

        Path-completion rows should stay lightweight, but when a visible file is
        already known as one exact recent/open target Micromax should keep that
        tiny state visible instead of rendering every filesystem hit as the same
        blank generic file row.

        Directory rows should also keep one small behavioral cue: pressing
        Enter on them drills further into that folder instead of opening a file.
        """

        raw = str(path or "")
        menu_text = str(menu or "open")
        info = str(fallback_info or "")
        can_stat = bool(self.options.get("cap.fs-list"))
        raw_target = raw
        initial_cursor: Cursor | None = None
        try:
            raw_target, initial_cursor = self._parse_open_target(raw)
        except Exception:
            raw_target = raw
            initial_cursor = None

        if menu_text == "open":

            dir_info = self._command_palette_dir_info(raw_target)
            if dir_info:
                detail = self._append_palette_action_cue(dir_info + " | directory", "drill down")
                return [raw, "openpath", menu_text, detail]

            file_info = self._command_palette_file_info(raw_target)
            if file_info:
                existing_file = False
                missing_file = False
                if can_stat:
                    try:
                        resolved = fs_resolve_path(self, raw_target)
                        if fs_path_allowed(self, resolved):
                            if resolved.exists() and resolved.is_file():
                                existing_file = True
                                file_info = self._append_palette_action_cue(file_info, "existing file")
                            elif not resolved.exists():
                                missing_file = True
                                file_info = self._append_palette_action_cue(file_info, "new file")
                    except Exception:
                        pass
                file_info = self._append_palette_action_cue(file_info, self._command_palette_file_action_cue(raw_target))
                exact_cursor_cue = self._command_palette_open_cursor_cue(raw_target, initial_cursor)
                file_info = self._append_palette_action_cue(file_info, exact_cursor_cue)
                if not exact_cursor_cue and existing_file:
                    file_info = self._append_palette_action_cue(file_info, self._command_palette_open_cursor_request_cue(initial_cursor))
                if not exact_cursor_cue and missing_file:
                    file_info = self._append_palette_action_cue(file_info, self._command_palette_new_file_landing_cue(initial_cursor))
                return [raw, "openpath", menu_text, file_info]

            if can_stat:
                existing_file = False
                missing_file = False
                try:
                    resolved = fs_resolve_path(self, raw_target)
                    if fs_path_allowed(self, resolved):
                        if resolved.exists() and resolved.is_dir():
                            info = self._append_palette_action_cue("directory", "drill down")
                        elif resolved.exists() and resolved.is_file():
                            existing_file = True
                            parent = str(resolved.parent)
                            extras = ["existing file"]
                            if parent not in ("", "."):
                                extras.append(parent)
                            info = " | ".join(extras)
                        else:
                            missing_file = True
                            parent = str(resolved.parent)
                            extras = ["new file"]
                            if parent not in ("", "."):
                                extras.append(parent)
                            info = " | ".join(extras)
                except Exception:
                    pass
                if existing_file:
                    info = self._append_palette_action_cue(info, self._command_palette_open_cursor_request_cue(initial_cursor))
                if missing_file:
                    info = self._append_palette_action_cue(info, self._command_palette_new_file_landing_cue(initial_cursor))
            return [raw, "openpath", menu_text, info]

        if menu_text == "dir":
            info = self._append_palette_action_cue(self._command_palette_dir_info(raw_target, fallback_info=info), "drill down")
        elif menu_text == "file":
            info = self._command_palette_file_info(raw_target, fallback_info=info)
            missing_file = False
            if can_stat:
                try:
                    resolved = fs_resolve_path(self, raw_target)
                    if fs_path_allowed(self, resolved) and not resolved.exists():
                        missing_file = True
                        info = self._append_palette_action_cue(info, "new file")
                except Exception:
                    pass
            info = self._append_palette_action_cue(info, self._command_palette_file_action_cue(raw_target))
            exact_cursor_cue = self._command_palette_open_cursor_cue(raw_target, initial_cursor)
            info = self._append_palette_action_cue(info, exact_cursor_cue)
            if not exact_cursor_cue:
                if missing_file:
                    info = self._append_palette_action_cue(info, self._command_palette_new_file_landing_cue(initial_cursor))
                else:
                    info = self._append_palette_action_cue(info, self._command_palette_open_cursor_request_cue(initial_cursor))

        return [raw, "openpath", menu_text, info]

    def command_palette_recent_file_rows(self, *, limit: int | None = None) -> list[list[str]]:
        """Rows for recent files shown inside the command palette."""
        rows = [self._command_palette_recent_file_row(str(raw)) for raw in self.visible_recent_files()]
        return rows[:limit] if limit is not None else rows

    def _command_palette_nonrecent_rows(self) -> list[list[str]]:
        recent = {self._command_palette_row_key(row) for row in self.command_palette_recent_rows()}
        out: list[list[str]] = []
        for row in self.command_palette_rows():
            if self._command_palette_row_key(row) in recent:
                continue
            out.append([str(x) for x in row[:4]])
        return out

    def _command_palette_section_label(self, row: list[object]) -> str:
        kind = str(row[1]) if len(row) >= 2 else ""
        if kind == 'openpath':
            menu = str(row[2]) if len(row) >= 3 else ""
            if menu == 'dir':
                return 'Directories'
            if menu == 'file' or menu == 'other':
                return 'Files'
            return 'Open'
        if kind == 'recentfile':
            return 'Recent Files'
        if self._command_palette_recent_rank(row) < max(1000, len(self._palette_recent) + 100):
            return 'Recent'
        if kind == 'action':
            return 'Actions'
        return 'Commands'

    def _parse_path_completion_query(self, raw: str) -> tuple[str, str]:
        """Return ``(query_path, cursor_suffix)`` for one palette path query."""

        s = str(raw or "").strip()
        if not s:
            return "", ""
        query_path = s
        cursor_suffix = ""
        try:
            parsed_path, initial_cursor = self._parse_open_target(s)
            if initial_cursor is not None:
                query_path = str(parsed_path or "")
                if s.startswith(query_path):
                    cursor_suffix = s[len(query_path) :]
        except Exception:
            query_path = s
            cursor_suffix = ""
        return query_path, cursor_suffix

    def _path_completion_base_prefix(self, query_path: str) -> tuple[Path, str, bool]:
        """Return ``(base_dir, prefix, ends_sep)`` for one path-completion query."""

        expanded = fs_resolve_path(self, query_path)
        ends_sep = str(query_path or "").endswith(("/", "\\"))
        try:
            if not ends_sep and expanded.exists() and expanded.is_dir():
                return expanded, "", ends_sep
            if ends_sep:
                return expanded, "", ends_sep
            return expanded.parent, expanded.name, ends_sep
        except Exception:
            return expanded.parent, expanded.name, ends_sep

    def _known_path_completion_candidates(self, base: Path, prefix: str) -> list[tuple[str, str]]:
        """Return tiny non-filesystem path completion candidates from editor state.

        These candidates reuse already-known buffer/MRU state, so the command
        palette can keep partial path queries visible even when the matching
        target is an unsaved open buffer or a recently visited path that no
        longer exists on disk.
        """

        want = str(prefix or "").casefold()
        want_base = self._normalize_path(str(base)) or str(base)
        out: list[tuple[str, str]] = []
        seen: set[tuple[str, str]] = set()

        def _add(raw: str) -> None:
            target = str(raw or "").strip()
            if target == "":
                return
            try:
                resolved = fs_resolve_path(self, target)
            except Exception:
                return
            if not fs_path_allowed(self, resolved):
                return
            try:
                parent = resolved.parent
            except Exception:
                return
            if (self._normalize_path(str(parent)) or str(parent)) != want_base:
                return
            name = str(resolved.name or "")
            if name == "":
                return
            if want and not name.casefold().startswith(want):
                return
            menu = "file"
            try:
                if resolved.exists() and resolved.is_dir():
                    menu = "dir"
                elif resolved.exists() and resolved.is_file():
                    menu = "file"
                elif target.endswith(("/", "\\")):
                    menu = "dir"
            except Exception:
                if target.endswith(("/", "\\")):
                    menu = "dir"
            disp = name + ("/" if menu == "dir" and not name.endswith("/") else "")
            key = (disp.casefold(), menu)
            if key in seen:
                return
            seen.add(key)
            out.append((disp, menu))

        for raw in self.visible_recent_files():
            _add(str(raw))
        for name in self.buffer_names():
            eb = self.buffers.get(str(name))
            if eb is None:
                continue
            target = str(getattr(eb.buf, "path", "") or getattr(eb, "name", "") or "")
            _add(target)

        out.sort(key=lambda item: (0 if item[1] == "dir" else 1, item[0].casefold()))
        return out

    def _looks_like_path_query(self, q: str) -> bool:
        """Heuristic: does a palette query look like a filesystem path?"""

        def _looks_pathlike_text(raw: str) -> bool:
            s = str(raw or "").strip()
            if not s:
                return False
            if any(ch in s for ch in ("/", "\\")):
                return True
            if s.startswith(("./", "../", "~", "/")):
                return True
            if s.endswith((".md", ".mx", ".py", ".json", ".toml", ".yaml", ".yml")):
                return True
            return False

        s = str(q or "").strip()
        if _looks_pathlike_text(s):
            return True
        try:
            parsed_path, initial_cursor = self._parse_open_target(s)
        except Exception:
            return False
        if initial_cursor is None:
            return False
        parsed_text = str(parsed_path or "")
        if _looks_pathlike_text(parsed_text):
            return True
        if self._buffer_for_path(parsed_text) is not None:
            return True
        if self.recent_detail_row(parsed_text):
            return True
        if self.recent_dir_detail_row(parsed_text):
            return True
        if not bool(self.options.get("cap.fs-list")):
            return False
        try:
            resolved = fs_resolve_path(self, parsed_text)
            if not fs_path_allowed(self, resolved):
                return False
            if resolved.exists():
                return True
            query_path, _cursor_suffix = self._parse_path_completion_query(s)
            if not query_path:
                return False
            base, prefix, _ends_sep = self._path_completion_base_prefix(query_path)
            if not fs_path_allowed(self, base):
                return False
            if not base.exists() or not base.is_dir():
                return False
            want = prefix.casefold()
            for child in base.iterdir():
                name = child.name
                if want and not name.casefold().startswith(want):
                    continue
                return True
            return bool(self._known_path_completion_candidates(base, prefix))
        except Exception:
            return False

    def command_palette_rows(self) -> list[list[str]]:
        rows: list[list[str]] = []
        for name in self.command_names():
            c = self.command_dispatcher.get(name)
            if c is None:
                continue
            info = f"group={c.group}" if c.group else ""
            rows.append([str(name), "command", str(c.doc or ""), info])
        for name in self.action_names():
            a = self.actions.get(name)
            if a is None:
                continue
            rows.append([str(name), "action", str(a.doc or ""), ""])

        def _kind_rank(kind: str) -> int:
            return {"recentfile": 0, "command": 1, "action": 2}.get(str(kind), 3)

        rows.sort(key=lambda row: (str(row[0]).casefold(), _kind_rank(str(row[1])), str(row[1]).casefold()))
        return rows

    def command_palette_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        file_rows = self.command_palette_recent_file_rows()

        def _path_completion_rows(raw: str, *, limit: int = 60) -> list[list[str]]:
            """Best-effort filesystem path completion rows for the palette.

            This is capability-gated (cap.fs-list) because it exposes host filesystem
            information to scripts/UI surfaces.

            Rows are: [path kind menu info] with kind=openpath and menu=dir|file.
            Directory rows include a trailing '/' so pressing Enter can drill down.
            Parsecursor-shaped queries reuse the parsed target for completion so the
            visible row list stays aligned with the submit/open path.
            """

            if not bool(self.options.get("cap.fs-list")):
                return []
            s = str(raw or "").strip()
            if not s:
                return []

            query_path, cursor_suffix = self._parse_path_completion_query(s)
            if not query_path:
                return []

            base, prefix, ends_sep = self._path_completion_base_prefix(query_path)

            # Optional filesystem sandbox: when cap.fs-root is set, refuse
            # to list outside it (including via symlink escapes).
            if not fs_path_allowed(self, base):
                return []

            try:
                if not base.exists() or not base.is_dir():
                    return []
            except Exception:
                return []

            try:
                items = list(base.iterdir())
            except Exception:
                items = []

            want = prefix.casefold()
            rows2: list[list[str]] = []

            # Preserve the user's typed directory prefix (./, ../, ~/, /abs/, etc.)
            # so completion candidates actually match the query string.
            typed_dir = ""
            if ends_sep:
                typed_dir = query_path
            else:
                try:
                    expanded = fs_resolve_path(self, query_path)
                    if expanded.exists() and expanded.is_dir() and not prefix:
                        typed_dir = query_path
                except Exception:
                    typed_dir = ""
            if typed_dir and not typed_dir.endswith(("/", "\\")):
                typed_dir = typed_dir + "/"
            if not typed_dir:
                slash = max(query_path.rfind("/"), query_path.rfind("\\"))
                typed_dir = query_path[: slash + 1] if slash >= 0 else ""
            typed_dir = typed_dir.replace("\\", "/")

            seen_candidates: set[tuple[str, str]] = set()

            for child in items:
                name = child.name
                if want and not name.casefold().startswith(want):
                    continue
                is_dir = False
                is_file = False
                try:
                    is_dir = child.is_dir()
                    is_file = child.is_file()
                except Exception:
                    pass
                menu = "dir" if is_dir else "file" if is_file else "other"
                disp = typed_dir + name
                if is_dir and not disp.endswith("/"):
                    disp = disp + "/"
                if cursor_suffix and (is_file or is_dir):
                    disp = disp + cursor_suffix
                key_name = name + ("/" if is_dir and not name.endswith("/") else "")
                seen_candidates.add((key_name.casefold(), menu))
                rows2.append(self._command_palette_open_path_row(disp, menu, fallback_info=str(base)))

            for name, menu in self._known_path_completion_candidates(base, prefix):
                key = (str(name).casefold(), str(menu))
                if key in seen_candidates:
                    continue
                disp = typed_dir + str(name)
                if cursor_suffix and menu in ("file", "dir"):
                    disp = disp + cursor_suffix
                seen_candidates.add(key)
                rows2.append(self._command_palette_open_path_row(disp, menu, fallback_info=str(base)))

            def _rank(row: list[str]) -> tuple[int, str]:
                menu = str(row[2])
                return (0 if menu == "dir" else 1, str(row[0]).casefold())

            rows2.sort(key=_rank)
            return rows2[: max(0, int(limit))]

        open_rows: list[list[str]] = []
        if q and self._looks_like_path_query(q):
            open_rows = [self._command_palette_open_path_row(q, "open", fallback_info="path-like query")]
            open_rows = _path_completion_rows(q, limit=max(0, min(80, int(limit or 60)))) + open_rows
        rows = self.command_palette_rows() + file_rows + open_rows
        if q == "":
            out = file_rows + self.command_palette_recent_rows() + self._command_palette_nonrecent_rows()
            return out[:limit] if limit is not None else out

        scored: list[tuple[RowSortKey, int, int, int, list[str]]] = []

        def _kind_rank(kind: str) -> int:
            return {"openpath": 0, "recentfile": 1, "command": 2, "action": 3}.get(str(kind), 4)

        for idx, row in enumerate(rows):
            key = self._apropos_row_sort_key(row, q)
            if key is None:
                continue
            recent_rank = self._command_palette_recent_rank(row)
            scored.append((key, recent_rank, _kind_rank(str(row[1])), idx, [str(x) for x in row]))

        scored.sort(
            key=lambda item: (
                item[0][:-2],
                item[1],
                item[0][-2],
                item[0][-1],
                item[2],
                item[3],
            )
        )
        out = [row for _key, _recent, _rank, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def command_palette_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        q = str(query or "").strip()
        section_order = ["Directories", "Files", "Open", "Recent Files", "Recent", "Commands", "Actions"]

        if q == "":
            buckets: dict[str, list[list[str]]] = {label: [] for label in section_order}
            for row in self.command_palette_recent_file_rows():
                vals = [str(x) for x in list(row[:4])]
                while len(vals) < 4:
                    vals.append("")
                buckets["Recent Files"].append(vals)
            for row in self.command_palette_recent_rows():
                vals = [str(x) for x in list(row[:4])]
                while len(vals) < 4:
                    vals.append("")
                buckets["Recent"].append(vals)
            for row in self._command_palette_nonrecent_rows():
                vals = [str(x) for x in list(row[:4])]
                while len(vals) < 4:
                    vals.append("")
                label = self._command_palette_section_label(vals)
                buckets.setdefault(label, [])
                buckets[label].append(vals)
            sections = [[label, buckets[label]] for label in section_order if buckets.get(label)]
            extras = [label for label in buckets.keys() if label not in section_order and buckets.get(label)]
            sections.extend([[label, buckets[label]] for label in extras])
            return self._limit_grouped_prompt_sections(sections, limit=limit, browse_budget=True)

        rows = self.command_palette_apropos_rows(q, limit=None)
        buckets: dict[str, list[list[str]]] = {label: [] for label in section_order}
        for row in rows:
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            label = self._command_palette_section_label(vals)
            buckets.setdefault(label, [])
            buckets[label].append(vals)
        sections: list[list[object]] = []
        for label in section_order:
            items = buckets.get(label, [])
            if items:
                sections.append([label, items])
        extras = [label for label in buckets.keys() if label not in section_order and buckets.get(label)]
        sections.extend([[label, buckets[label]] for label in extras])
        return self._limit_grouped_prompt_sections(sections, limit=limit, browse_budget=False)

    def command_palette_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return one tiny shared broad command-palette summary register.

        Rows are ``[label count sample_name sample_detail]`` so scripts and
        future UIs can inspect what command-palette buckets are visible right
        now without opening the live palette or walking every grouped picker
        row from ``ed.command-palette-section-rows``.
        """

        return self._section_summary_rows(self.command_palette_section_rows(query, limit=limit))

    def help_topic_rows(self) -> list[list[str]]:
        rows = self.command_palette_rows()
        for name in self._prompt_vm_word_names():
            row = self._prompt_vm_word_row(name)
            rows.append([str(name), str(row[1]), str(row[2]), str(row[3])])
        for row in self.doc_prompt_rows():
            rows.append([str(x) for x in row[:4]])
        return rows

    def _topic_section_names(self, kind: str) -> tuple[str, str]:
        k = str(kind or "").strip().casefold()
        if k == "command":
            return ("Command", "Commands")
        if k == "action":
            return ("Action", "Actions")
        if k == "buffer":
            return ("Buffer", "Buffers")
        if k == "mark":
            return ("Mark", "Marks")
        if k == "jump":
            return ("Jump", "Jumps")
        if k == "doc":
            return ("Doc", "Docs")
        if k == "link":
            return ("Link", "Links")
        if k in ("recent", "recentfile"):
            return ("Recent file", "Recent files")
        return ("Word", "Words")

    def _group_topic_rows(self, rows: list[list[str]]) -> list[list[object]]:
        section_order = ["Commands", "Actions", "Words"]
        buckets: dict[str, list[list[str]]] = {label: [] for label in section_order}
        extra_labels: list[str] = []
        for row in rows:
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            _single, plural = self._topic_section_names(vals[1])
            if plural not in buckets:
                buckets[plural] = []
                extra_labels.append(plural)
            buckets[plural].append(vals)
        out: list[list[object]] = []
        for label in section_order + extra_labels:
            items = buckets.get(label, [])
            if items:
                out.append([label, items])
        return out

    def help_topic_section_rows(self) -> list[list[object]]:
        return self._group_topic_rows(self.help_topic_rows())

    def _section_summary_prompt_row_detail(self, row: list[str]) -> str:
        """Return one tiny summary-detail string from a prompt-style row."""

        return section_summary_prompt_row_detail(row)

    def _section_summary_rows(
        self,
        sections: list[list[object]],
        *,
        sample_detail_fn=None,
    ) -> list[list[object]]:
        """Return tiny count-aware section summaries."""

        return prompt_section_summary_rows(
            sections,
            sample_detail_fn=sample_detail_fn,
        )

    def help_topic_section_summary_rows(self) -> list[list[object]]:
        return self._section_summary_rows(
            self.help_topic_section_rows(),
            sample_detail_fn=self._section_summary_prompt_row_detail,
        )

    def filter_section_summary_rows(
        self,
        rows: list[list[object]],
        query: str,
        *,
        limit: int | None = None,
    ) -> list[list[object]]:
        """Filter tiny ``[label count sample_name sample_detail]`` rows by query."""

        return prompt_filter_section_summary_rows(rows, query, limit=limit)

    def help_topic_section_summary_rows_query(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        return self.filter_section_summary_rows(self.help_topic_section_summary_rows(), query, limit=limit)

    def apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.help_topic_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, int, list[str]]] = []

        def _kind_rank(kind: str) -> int:
            return {"recentfile": 0, "command": 1, "action": 2, "word": 3, "doc": 4}.get(str(kind), 5)

        for idx, row in enumerate(rows):
            key = self._apropos_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, _kind_rank(str(row[1])), idx, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1], item[2]))
        out = [row for _key, _rank, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def apropos_section_rows(self, query: str, *, limit: int | None = None) -> list[list[object]]:
        return self._group_topic_rows(self.apropos_rows(query, limit=limit))

    def apropos_section_summary_rows(self, query: str, *, limit: int | None = None) -> list[list[object]]:
        return self._section_summary_rows(
            self.apropos_section_rows(query, limit=limit),
            sample_detail_fn=self._section_summary_prompt_row_detail,
        )

    def _binding_row_mode(self, row: list[str]) -> str:
        """Best-effort binding mode name encoded in a binding prompt row."""
        try:
            menu = str(row[2] if len(row) > 2 else "")
            m = re.match(r"@([^\s]+)", menu)
            if m is not None:
                return str(m.group(1) or "global")
        except Exception:
            pass
        return "global"

    def _binding_section_label_for_mode(self, mode: str) -> str:
        raw = str(mode or "global")
        if raw == "global":
            return "Global"
        if raw == "prompt":
            return "Prompt"
        return raw

    def _binding_section_label(self, row: list[str]) -> str:
        """Best-effort visible section label for binding picker rows."""
        return self._binding_section_label_for_mode(self._binding_row_mode(row))

    def _binding_section_label_rank(self, label: str) -> tuple[int, str]:
        lbl = str(label or "")
        active_labels: list[str] = []
        try:
            active_labels = [
                self._binding_section_label_for_mode(str(m))
                for m in self.active_key_modes()
                if str(m) not in ("", "global", "prompt")
            ]
        except Exception:
            active_labels = []
        if lbl == "Prompt":
            return (0, lbl.casefold())
        if lbl in active_labels:
            return (1 + active_labels.index(lbl), lbl.casefold())
        if lbl == "Global":
            return (10, lbl.casefold())
        return (20, lbl.casefold())

    def _binding_section_sort_key(self, row: list[str]) -> tuple[int, str, str, str]:
        label = self._binding_section_label(row)
        rank, folded = self._binding_section_label_rank(label)
        key = str(row[0] if row else "")
        menu = str(row[2] if len(row) > 2 else "")
        return (int(rank), str(folded), key.casefold(), menu.casefold())

    def binding_prompt_rows(self) -> list[list[str]]:
        rows: list[list[str]] = []
        for mode, key, action, desc, _group, _span in self.available_binding_info_rows():
            mode_s = str(mode or "global")
            menu = f"@{mode_s} {action}"
            info = str(desc or "")
            rows.append([str(key), "binding", menu, info])
        rows.sort(key=self._binding_section_sort_key)
        return rows

    def binding_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group current-binding rows by visible winning-mode label."""
        rows = self.binding_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._binding_section_label,
            label_sort_key=self._binding_section_label_rank,
        )

    def binding_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware winning-mode binding summaries.

        Each row is ``[label count sample_name sample_detail]`` and reuses the
        first visible binding row from each winning-mode section. This keeps the
        broad reachable-binding surface inspectable without forcing scripts or
        future UIs to walk grouped prompt rows just to answer what binding
        buckets exist right now.
        """

        return self._section_summary_rows(self.binding_section_rows(query, limit=limit))


    def _buffer_section_label(self, row: list[str]) -> str:
        """Best-effort section label for buffer picker rows.

        Used by the TUI to render section headers (and by the prompt row sorter so
        buffers appear grouped rather than interleaved).
        """
        try:
            name = str(row[0] if row else "")
            if name.startswith("help:"):
                return "Help"
            if name.startswith("*"):
                return "Scratch"
            info = str(row[3] if len(row) > 3 else "")
            path = info.split("|", 1)[0].strip() if info else ""
            if path:
                try:
                    root = self._project_root_for_path(path)
                except Exception:
                    root = None
                if root:
                    return str(root)
                return self._path_parent_section_label(path, fallback="Buffers")
        except Exception:
            pass
        return "Buffers"

    def _path_parent_section_label(self, path: str, *, fallback: str) -> str:
        """Return a visible parent-directory section label for one path.

        Picker/status surfaces should stay human and category-aware when a path
        has no useful parent directory (for example a relative ``notes.txt`` row
        whose filesystem parent would otherwise render as raw ``.``).
        """

        raw = str(path or "").strip()
        if raw == "":
            return str(fallback)
        try:
            parent = str(Path(raw).parent)
        except Exception:
            return str(fallback)
        if parent in ("", "."):
            return str(fallback)
        return parent

    def _buffer_section_label_rank(self, label: str) -> tuple[int, str]:
        lbl = str(label or "")
        rank = 2
        if lbl == "Help":
            rank = 0
        elif lbl in ("Scratch", "Buffers"):
            rank = 1
        return (int(rank), lbl.casefold())

    def _buffer_section_sort_key(self, row: list[str]) -> tuple[int, str, str]:
        label = self._buffer_section_label(row)
        rank, folded = self._buffer_section_label_rank(label)
        name = str(row[0] if row else "")
        return (int(rank), str(folded), name.casefold())


    def buffer_prompt_rows(self) -> list[list[str]]:
        rows: list[list[str]] = []
        for name in self.visible_buffer_names():
            insert = str(name)
            row = self._prompt_buffer_row(insert)
            # _prompt_buffer_row expects an 'insert' string; ensure 4 cols
            vals = list(row[:4])
            while len(vals) < 4:
                vals.append("")
            rows.append([str(vals[0]), str(vals[1]), str(vals[2]), str(vals[3])])
        rows.sort(key=self._buffer_section_sort_key)
        return rows

    def _group_prompt_rows_by_section(
        self,
        rows: list[list[str]],
        *,
        label_fn,
        label_sort_key=None,
    ) -> list[list[object]]:
        """Return grouped prompt rows as ``[[label, rows] ...]``."""

        return group_prompt_rows_by_section(
            rows,
            label_fn=label_fn,
            label_sort_key=label_sort_key,
        )

    def _limit_grouped_prompt_sections(
        self,
        sections: list[list[object]],
        *,
        limit: int | None = None,
        browse_budget: bool = False,
    ) -> list[list[object]]:
        """Limit grouped prompt rows while keeping section boundaries intact."""

        return limit_grouped_prompt_sections(
            sections,
            limit=limit,
            browse_budget=browse_budget,
        )

    def _flatten_grouped_prompt_sections(
        self,
        sections: list[list[object]],
        *,
        limit: int | None = None,
        browse_budget: bool = False,
    ) -> list[list[str]]:
        """Flatten grouped prompt rows using the same section-limit policy."""

        return flatten_grouped_prompt_sections(
            sections,
            limit=limit,
            browse_budget=browse_budget,
        )

    def buffer_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group buffer picker rows by their visible picker section label."""
        rows = self.buffer_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._buffer_section_label,
            label_sort_key=self._buffer_section_label_rank,
        )

    def buffer_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware broad buffer-section rows.

        Buffer discovery was already strong at flat plain inventory (`buffers`)
        and full grouped browse state (`bufferpick` / `ed.buffer-section-rows`),
        but future humans/LLMs/scripts often ask one smaller question first:
        what broad buffer buckets are visible right now? These summary rows keep
        that answer inspectable without opening the live picker or walking every
        grouped row.
        """

        return self._section_summary_rows(self.buffer_section_rows(query, limit=limit))

    # ----- plugin-register read policy -----
    def _script_plugin_read_capability_enabled(self) -> bool:
        """Return true when scripts may inspect protected plugin state."""

        if not self.in_script_context():
            return False
        try:
            return bool(self.options.get("cap.plugin-read"))
        except Exception:
            return False

    def _all_plugin_names(self) -> list[str]:
        """Return every known plugin/candidate/error name without read filtering."""

        pm = getattr(self, "plugin_manager", None)
        names: set[str] = set()
        if pm is not None:
            try:
                names.update(str(n) for n in getattr(pm, "plugins", {}).keys())
            except Exception:
                pass
            try:
                names.update(str(n) for n in getattr(pm, "candidates", {}).keys())
            except Exception:
                pass
            try:
                names.update(str(n) for (n, _e) in getattr(pm, "load_errors", []))
            except Exception:
                pass
        return sorted({str(n) for n in names if str(n).strip() != ""}, key=lambda s: s.casefold())

    def _plugin_registration_authority(self, name: str) -> RuntimeRegistrationAuthority:
        """Return the runtime authority associated with one plugin row."""

        plugin_name = str(name)
        pm = getattr(self, "plugin_manager", None)
        plugin = None
        if pm is not None:
            try:
                plugin = getattr(pm, "plugins", {}).get(plugin_name)
            except Exception:
                plugin = None
        if plugin is None:
            # Candidate-only, broken, missing-dependency, and unloaded rows are
            # host/plugin-manager state, not owned by a running script origin.
            return RuntimeRegistrationAuthority(script_context=False)
        generation = getattr(plugin, "generation", None)
        return RuntimeRegistrationAuthority(
            script_context=True,
            plugin_load_root=(str(getattr(plugin, "root", "") or "") or None),
            plugin_generation=(
                int(generation) if generation not in (None, "") else None
            ),
            group=(str(getattr(plugin, "group", "") or "") or None),
        )

    def _plugin_read_denial(self, name: str, *, action: str = "read") -> str:
        """Return a denial string when the current script cannot inspect a plugin."""

        current = self._current_runtime_authority(kind="editor")
        if not bool(getattr(current, "script_context", False)):
            return ""
        decision = plugin_access_policy(
            current,
            self._plugin_registration_authority(str(name)),
            capability_enabled=self._script_plugin_read_capability_enabled(),
        )
        if decision.allowed:
            return ""
        reason = str(decision.reason or "not owned by current script")
        return f"script context cannot {str(action or 'read')} plugin: {str(name)} ({reason}; cap.plugin-read)"

    def _plugin_read_allowed(self, name: str) -> bool:
        return not bool(self._plugin_read_denial(str(name), action="read"))

    def _guard_plugin_read(self, name: str, *, action: str = "read") -> None:
        denial = self._plugin_read_denial(str(name), action=action)
        if denial:
            raise PermissionError(denial)

    def plugin_names(self) -> list[str]:
        """Return plugin names visible to the current runtime authority."""

        return [name for name in self._all_plugin_names() if self._plugin_read_allowed(str(name))]


    def _plugin_section_label(self, row: list[str]) -> str:
        """Best-effort section label for plugin picker rows."""
        try:
            menu = str(row[2] if len(row) > 2 else "")
            low = menu.casefold()
            if "error" in low:
                return "Errors"
            if "loaded" in low:
                return "Loaded"
            if "available" in low:
                return "Available"
            return "Available"
        except Exception:
            return "Plugins"

    def _plugin_section_display_label(self, row: list[str], rows: list[list[object]] | None = None) -> str:
        """Return the visible plugin section label, with a tiny per-section count.

        The plugin loop has become increasingly count-aware in plain command
        output (`plugin list`, `plugin errors`). The searchable picker should
        not make section size implicit again, so section headers and previews
        reuse the same coarse idea: `Errors (1)`, `Loaded (2)`, `Available (3)`.
        """

        base = str(self._plugin_section_label(row) or "")
        if not base:
            return ""
        pool = rows
        if pool is None and self.prompt is not None and self.prompt.kind == "plugin":
            pool = list(getattr(self.prompt, "suggestion_rows", []) or [])
        if not pool:
            return base
        count = 0
        for item in pool:
            vals = [str(x) for x in list(item[:4])]
            while len(vals) < 4:
                vals.append("")
            if str(self._plugin_section_label(vals) or "") == base:
                count += 1
        return f"{base} ({count})" if count > 0 else base

    def _plugin_section_sort_key(self, row: list[str]) -> tuple[int, str, str]:
        label = self._plugin_section_label(row)
        rank = {"Errors": 0, "Loaded": 1, "Available": 2}.get(label, 3)
        name = str(row[0] if row else "")
        return (int(rank), str(label).casefold(), name.casefold())


    def plugin_prompt_rows(self) -> list[list[str]]:
        rows: list[list[str]] = []
        for name in self.plugin_names():
            insert = str(name)
            row = self._prompt_plugin_row(insert)
            vals = list(row[:4])
            while len(vals) < 4:
                vals.append("")
            rows.append([str(vals[0]), str(vals[1]), str(vals[2]), str(vals[3])])
        rows.sort(key=self._plugin_section_sort_key)
        return rows

    def _plugin_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        q = str(query or "").strip()
        if q == "":
            return (0, 0, 0, 0, 0, 0, 0, 0, 0, "")

        key = str(row[0]) if row else ""
        key_key = self._completion_fuzzy_sort_key(key, q)
        if key_key is not None:
            return (0, *key_key, key.casefold())

        meta = " ".join([str(row[2]) if len(row) >= 3 else "", str(row[3]) if len(row) >= 4 else ""]).strip()
        if meta:
            folded_meta = meta.casefold()
            folded_q = q.casefold()
            if folded_q and folded_q in folded_meta:
                pos = folded_meta.find(folded_q)
                return (1, pos, pos, 0, 0, 0, 0, len(meta), len(key), key.casefold())

            meta_key = self._completion_fuzzy_sort_key(meta, q)
            if meta_key is not None:
                return (2, *meta_key, key.casefold())
        return None

    def plugin_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.plugin_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._plugin_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1]))
        out = [row for _key, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def _group_plugin_rows(self, rows: list[list[str]]) -> list[list[object]]:
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._plugin_section_label,
            label_sort_key=lambda label: {"Errors": 0, "Loaded": 1, "Available": 2}.get(str(label), 3),
        )

    def plugin_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group plugin picker rows by their visible picker section label."""
        rows = self.plugin_apropos_rows(query, limit=limit)
        grouped = self._group_plugin_rows(rows)
        out: list[list[object]] = []
        for sec in grouped:
            label = str(sec[0] if sec else "")
            items = list(sec[1] if len(sec) > 1 else [])
            display = f"{label} ({len(items)})" if label and items else label
            out.append([display, items])
        return out

    def plugin_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        return self._section_summary_rows(self._group_plugin_rows(self.plugin_apropos_rows(query, limit=limit)))


    def _buffer_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        return prompt_picker_row_sort_key(row, query)

    def buffer_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.buffer_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._buffer_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1]))
        out = [row for _key, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def _mark_section_label(self, row: list[str]) -> str:
        """Best-effort section label for mark picker rows.

        Marks are global navigation points, but in practice users usually think
        of them by the owning buffer first. Keep the label exact/simple so future
        UIs/LLMs can reuse it directly instead of reverse-engineering `menu`.
        """
        try:
            name = str(row[0] if row else "")
            if name in self.marks:
                buf_name, _cur = self.marks[name]
                return str(buf_name)
            menu = str(row[2] if len(row) > 2 else "")
            m = re.match(r"(.+):(\d+):(\d+)\s*$", menu)
            if m is not None:
                return str(m.group(1))
        except Exception:
            pass
        return "Marks"

    def _mark_section_label_rank(self, label: str) -> tuple[int, str]:
        lbl = str(label or "")
        rank = 1
        if self.active is not None and lbl == str(self.active):
            rank = 0
        elif lbl == "Marks":
            rank = 2
        return (int(rank), lbl.casefold())

    def _mark_section_sort_key(self, row: list[str]) -> tuple[int, str, str]:
        label = self._mark_section_label(row)
        name = str(row[0] if row else "")
        rank, folded = self._mark_section_label_rank(label)
        return (int(rank), str(folded), name.casefold())

    def mark_prompt_rows(self) -> list[list[str]]:
        rows: list[list[str]] = []
        for name in sorted(self.marks.keys()):
            if not self._mark_read_allowed(str(name)):
                continue
            insert = str(name)
            row = self._prompt_mark_row(insert)
            vals = list(row[:4])
            while len(vals) < 4:
                vals.append("")
            rows.append([str(vals[0]), str(vals[1]), str(vals[2]), str(vals[3])])
        rows.sort(key=self._mark_section_sort_key)
        return rows

    def _mark_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        return prompt_picker_row_sort_key(row, query)

    def mark_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.mark_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._mark_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1]))
        out = [row for _key, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def mark_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group mark rows by owning buffer for future pickers/UIs."""
        rows = self.mark_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._mark_section_label,
            label_sort_key=self._mark_section_label_rank,
        )

    def mark_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware broad mark-section rows.

        This gives scripts/future UIs the same first-stop summary plain
        ``showmarkgroups [QUERY]`` gives humans, instead of forcing them to walk
        every grouped ``markpick`` row just to answer what owning-buffer buckets
        are currently visible and roughly what lives in each one.
        """

        return self._section_summary_rows(self.mark_section_rows(query, limit=limit))

    def _jump_section_label(self, row: list[str]) -> str:
        """Best-effort section label for jumplist picker rows."""
        try:
            eb = self.cur()
            self._normalize_cursor_lists(eb)
            cur_i = int(eb.jump_index)
            idx1 = self.parse_visible_index_token(row[0] if row else "")
            if idx1 is None or cur_i < 0:
                return "Jumps"
            idx0 = int(idx1) - 1
            if idx0 == cur_i:
                return "Current"
            if idx0 < cur_i:
                return "Back"
            return "Forward"
        except Exception:
            return "Jumps"

    def _jump_section_label_rank(self, label: str) -> tuple[int, str]:
        lbl = str(label or "")
        rank = {"Current": 0, "Back": 1, "Forward": 2, "Jumps": 3}.get(lbl, 4)
        return (int(rank), lbl.casefold())

    def _jump_section_sort_key(self, row: list[str]) -> tuple[int, int, int]:
        label = self._jump_section_label(row)
        rank, _folded = self._jump_section_label_rank(label)
        try:
            eb = self.cur()
            self._normalize_cursor_lists(eb)
            cur_i = int(eb.jump_index)
            idx1 = self.parse_visible_index_token(row[0] if row else "")
            idx0 = int(idx1) - 1 if idx1 is not None else -1
            if label == "Back":
                return (int(rank), max(0, cur_i - idx0), 0)
            if label == "Forward":
                return (int(rank), max(0, idx0 - cur_i), 0)
            if idx0 >= 0:
                return (int(rank), 0, idx0)
        except Exception:
            pass
        return (int(rank), 0, 0)

    def jump_prompt_rows(self) -> list[list[str]]:
        """Return jumplist picker rows for the current buffer.

        Rows are [[insert kind menu info] ...]. `insert` is the visible `#N`
        jumplist token the broader `jumps` / `showjump` surfaces already print,
        while `menu`/`info` carry the useful context for fuzzy search.

        Prompt completion may ask for jump-adjacent command rows before any
        real buffer exists yet. Treat that safe-startup state as an empty
        jumplist instead of raising, so broad command discovery stays calm in a
        headless harness too.
        """
        if self.active is None or self.active not in self.buffers:
            return []
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        rows: list[list[str]] = []
        n = int(len(eb.jump_list))
        # Newest-first feels best for navigation history.
        for idx0 in range(n - 1, -1, -1):
            snap = eb.jump_list[idx0]
            curs, _anchors, _cursor_ids, primary = snap
            if not curs:
                continue
            pi = int(primary) if 0 <= int(primary) < len(curs) else 0
            c = curs[pi]
            insert = f"#{idx0 + 1}"
            marker = "*" if idx0 == int(eb.jump_index) else " "
            menu = f"{marker}{idx0 + 1}/{n} {int(c.line) + 1}:{int(c.col) + 1}"
            info = ""
            li = int(c.line)
            if 0 <= li < len(eb.buf.lines):
                s = eb.buf.lines[li].rstrip("\n").strip()
                if len(s) > 80:
                    s = s[:77] + "..."
                info = s
            rows.append([insert, "jump", str(menu), str(info)])
        if 0 <= int(eb.jump_index) < n:
            rows.sort(key=self._jump_section_sort_key)
        return rows

    def _jump_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        idx_q = self.parse_visible_index_token(str(query or "").strip())

        def _same_visible_index(_query: str, key: str) -> bool:
            idx_key = self.parse_visible_index_token(key)
            return idx_q is not None and idx_key is not None and idx_q == idx_key

        return prompt_picker_row_sort_key(row, query, exact_key_match=_same_visible_index)

    def jump_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.jump_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx0, row in enumerate(rows):
            key = self._jump_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx0, [str(x) for x in row]))

        scored.sort(key=lambda item: (item[0], item[1]))
        out = [row for _key, _idx, row in scored]
        return out[:limit] if limit is not None else out

    def jump_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group jumplist rows by relation to the current jump entry."""
        rows = self.jump_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._jump_section_label,
            label_sort_key=self._jump_section_label_rank,
        )

    def jump_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware jumplist-section summaries.

        This gives scripts/future UIs the same first-stop broad answer plain
        ``showjumpgroups [QUERY]`` gives humans, instead of forcing them to
        reopen grouped ``jumppick`` state just to answer which Current/Back/
        Forward buckets are visible and what one representative jump looks like.
        """

        out: list[list[object]] = []
        for sec in self.jump_section_rows(query, limit=limit):
            label = str(sec[0] if sec else "")
            items = list(sec[1] if len(sec) > 1 else [])
            if not label or not items:
                continue
            sample = [str(x) for x in list(items[0][:4])]
            while len(sample) < 4:
                sample.append("")
            detail = self.jump_detail_row(sample[0])
            sample_name = sample[0]
            sample_detail = str(sample[3] or sample[2])
            if detail is not None:
                try:
                    index = int(detail[1]) if len(detail) >= 2 else 0
                except Exception:
                    index = 0
                buffer_name = str(detail[4]) if len(detail) >= 5 else ""
                position = str(detail[5]) if len(detail) >= 6 else ""
                preview = str(detail[6]) if len(detail) >= 7 else ""
                if index > 0:
                    sample_name = f"#{index}"
                detail_parts: list[str] = []
                if buffer_name:
                    detail_parts.append(buffer_name)
                if position:
                    detail_parts.append(f"@ {position}" if buffer_name else position)
                sample_detail = " ".join(part for part in detail_parts if part)
                if preview:
                    sample_detail = f"{sample_detail} — {preview}" if sample_detail else preview
            out.append([label, len(items), sample_name, sample_detail])
        return out

    def _binding_row_sort_key(self, row: list[object], query: str) -> RowSortKey | None:
        return prompt_picker_row_sort_key(row, query)

