    # ----- keymap modes -----
    def active_key_mode_entries(self) -> list[ActiveKeyMode]:
        """Return active key modes in lookup order, de-duplicated by mode name.

        The public row helpers intentionally expose only names/once flags, but
        dispatch needs the full activation provenance so a mode pushed by script
        code keeps script authority when a later keypress resolves through it.
        """

        out: list[ActiveKeyMode] = []
        seen: set[str] = set()
        for km in reversed(self.key_mode_stack):
            m = str(km.name)
            if not m or m == 'global' or m in seen:
                continue
            seen.add(m)
            out.append(km)
        return out

    def active_key_mode_rows(self) -> list[list[object]]:
        return [[str(km.name), 1 if km.once else 0] for km in self.active_key_mode_entries()]

    def active_key_modes(self) -> list[str]:
        return [str(km.name) for km in self.active_key_mode_entries()]

    def _script_keymode_read_capability_enabled(self) -> bool:
        """Return true when scripts may inspect protected keymode names/state."""

        if not self.in_script_context():
            return False
        try:
            return bool(self.options.get("cap.keymode-read"))
        except Exception:
            return False

    @staticmethod
    def _keymode_activation_authority(km: object) -> RuntimeRegistrationAuthority:
        return RuntimeRegistrationAuthority(
            script_context=bool(getattr(km, "script_context", False)),
            plugin_load_root=(str(getattr(km, "plugin_load_root", "") or "") or None),
            plugin_generation=(
                int(getattr(km, "plugin_generation"))
                if getattr(km, "plugin_generation", None) not in (None, "")
                else None
            ),
            script_origin_id=(str(getattr(km, "script_origin_id", "") or "") or None),
            group=(str(getattr(km, "group", "") or "") or None),
        )

    def _keymode_access_denial(
        self,
        name: object,
        *,
        action: str = "read",
        capability: str = "cap.keymode-read",
    ) -> str:
        """Return a denial string when a script cannot inspect one keymode."""

        mode = str(name or "").strip()
        if not mode or mode == "global":
            return ""
        if not self.in_script_context():
            return ""
        current = self._current_runtime_authority(kind="editor")
        cap_enabled = self._script_keymode_read_capability_enabled()

        reasons: list[str] = []
        for km in self.active_key_mode_entries():
            if str(getattr(km, "name", "") or "") != mode:
                continue
            decision = keymode_access_policy(
                current,
                self._keymode_activation_authority(km),
                capability_enabled=cap_enabled,
            )
            if decision.allowed:
                return ""
            if decision.reason:
                reasons.append(str(decision.reason))

        exact_mode = None if mode in ("", "0", "global") else mode
        for b in self._binding_objects_for_mode(exact_mode):
            decision = keymode_access_policy(
                current,
                self._binding_authority(b),
                capability_enabled=cap_enabled,
            )
            if decision.allowed:
                return ""
            if decision.reason:
                reasons.append(str(decision.reason))

        if cap_enabled:
            return ""
        reason = reasons[0] if reasons else "not owned by current script"
        return f"script context cannot {str(action or 'read')} keymode: {mode} ({reason}; {capability})"

    def _keymode_read_allowed(self, name: object) -> bool:
        return not bool(self._keymode_access_denial(name, action="read"))

    def _visible_active_key_mode_entries(self) -> list[ActiveKeyMode]:
        """Return active keymodes visible to the caller's authority."""

        return [km for km in self.active_key_mode_entries() if self._keymode_read_allowed(str(km.name))]

    def visible_active_key_modes(self) -> list[str]:
        return [str(km.name) for km in self._visible_active_key_mode_entries()]

    def visible_active_key_mode_rows(self) -> list[list[object]]:
        return [[str(km.name), 1 if km.once else 0] for km in self._visible_active_key_mode_entries()]

    def visible_keymap_modes(self, *, include_internal: bool = False) -> list[str]:
        """Return binding modes visible to the current read authority."""

        internal = {"qreplace", "openurl", "prompt"}
        out: list[str] = []
        for mode in self.keymap.modes():
            m = str(mode)
            if not include_internal and (m in internal or m.startswith("_")):
                continue
            if self._keymode_read_allowed(m):
                out.append(m)
        if "global" not in out:
            out.insert(0, "global")
        return out

    def _visible_known_key_mode_names(self) -> list[str]:
        """Return the human-facing known-keymode list used by ``showkeymodes``.

        Internal capture/housekeeping modes stay reachable to trusted callers via
        the lower-level keymode hostcalls, but plain human-facing inventory keeps
        the known list focused on durable user-facing modes.  In script context,
        dynamic mode names are filtered through the keymode read policy so a
        lower-authority script cannot inventory trusted/user modal state.
        """

        return self.visible_keymap_modes(include_internal=False)

    def keymode_inventory_rows(self) -> list[list[object]]:
        """Return the tiny shared register behind plain ``showkeymodes``.

        This deliberately complements ``ed.keymode-rows`` instead of replacing
        it. The lower-level hostcall still exposes the raw active stack plus the
        unfiltered known-mode list, while this helper preserves the exact
        human-facing active/known inventory that scripts and future UIs would
        otherwise have to reconstruct from split stacks and local filtering
        policy.
        """

        rows: list[list[object]] = []
        active_rows = self.visible_active_key_mode_rows()
        if active_rows:
            for name, once in active_rows:
                rows.append(["active", str(name), int(once)])
        else:
            rows.append(["active", "global", 0])

        active_once = {str(name): int(once) for name, once in active_rows}
        for name in self._visible_known_key_mode_names():
            rows.append(["known", str(name), int(active_once.get(str(name), 0))])
        return rows

    def _keymode_inventory_preview_summary(self) -> str:
        """Return one tiny live keymode-inventory witness.

        Plain ``showkeymodes`` already previews the active/known inventory, and
        plain ``showkeymode`` should reuse that same root truth before it asks
        for one exact mode name. Keep the summary compact, human-facing, and
        aligned across prompt and runtime surfaces.
        """

        inventory = self.keymode_inventory_rows()
        active = [
            f"{str(name)}{'!' if int(once) else ''}"
            for section, name, once in inventory
            if str(section) == 'active' and str(name) != 'prompt'
        ] or ['global']
        known = [str(name) for section, name, _once in inventory if str(section) == 'known']
        summary = f"active {', '.join(active)} · known={len(known) or 1}"
        sample_mode = str(active[0]).removesuffix('!') if active else (known[0] if known else 'global')
        detail = self.keymode_detail_row(sample_mode)
        if detail is None:
            return summary
        try:
            binding_count = int(detail[4]) if len(detail) >= 5 else 0
        except Exception:
            binding_count = 0
        sample_key = str(detail[5]) if len(detail) >= 6 and detail[5] not in (0, '') else ''
        sample_action = str(detail[6]) if len(detail) >= 7 and detail[6] not in (0, '') else ''
        if sample_key and sample_action:
            return f"{summary} · {sample_mode} {sample_key}->{sample_action}"
        return f"{summary} · {sample_mode} bindings={binding_count}"

    def keymode_detail_row(self, name: str, *, strict_denial: bool = False) -> list[object] | None:
        """Return one tiny shared detail row for a visible or active keymode.

        Script-origin callers see same-origin keymodes and public ``global`` by
        default.  Trusted/user or other-origin dynamic modes require
        ``cap.keymode-read``.  Binding specs themselves remain protected by the
        keybinding read policy, so a caller with only keymode-read can learn that
        a mode exists without automatically learning its action specs.
        """

        mode = str(name or '').strip()
        if not mode:
            return None
        denial = self._keymode_access_denial(mode, action="read")
        exists = bool(mode == 'global' or mode in self.keymap.modes() or any(str(km.name) == mode for km in self.active_key_mode_entries()))
        if denial and exists:
            if strict_denial:
                raise PermissionError(denial)
            return None
        active_once = {str(row[0]): int(row[1]) for row in self.visible_active_key_mode_rows()}
        known_names = set(self._visible_known_key_mode_names())
        known_names.add('global')
        active = 1 if mode in active_once else 0
        known = 1 if mode in known_names else 0
        if not active and not known:
            return None
        rows = self.binding_info_rows_for(None if mode == 'global' else mode)
        binding_count = int(len(rows))
        sample_key: object = 0
        sample_action: object = 0
        sample_desc: object = 0
        if rows:
            sample_key = str(rows[0][0])
            sample_action = str(rows[0][1])
            if len(rows[0]) >= 3 and rows[0][2] not in (0, ''):
                sample_desc = str(rows[0][2])
        return [
            mode,
            active,
            known,
            int(active_once.get(mode, 0)),
            binding_count,
            sample_key,
            sample_action,
            sample_desc,
        ]

    def current_key_mode(self) -> str | None:
        modes = self.active_key_modes()
        return modes[0] if modes else None

    def current_key_mode_once(self) -> bool:
        rows = self.active_key_mode_rows()
        return bool(rows and rows[0][1])

    def current_capture_key_mode(self) -> str | None:
        if not self.key_mode_stack:
            return None
        top = self.key_mode_stack[-1]
        if getattr(top, "capture", False):
            return str(top.name)
        return None

    def current_key_mode_capture(self) -> bool:
        return self.current_capture_key_mode() is not None

    def _active_keymode_origin_kwargs(self) -> dict[str, object]:
        """Return provenance metadata for a keymode activated now."""

        return self.script_callback_origin_kwargs()

    def _make_active_key_mode(self, mode: str, *, once: bool = False, capture: bool = False) -> ActiveKeyMode:
        origin = self._active_keymode_origin_kwargs()
        gen = origin.get("plugin_generation")
        return ActiveKeyMode(
            str(mode),
            once=bool(once),
            capture=bool(capture),
            script_context=bool(origin.get("script_context")),
            plugin_load_root=(str(origin.get("plugin_load_root")) if origin.get("plugin_load_root") else None),
            plugin_generation=(int(gen) if gen not in (None, "") else None),
            script_origin_id=(str(origin.get("script_origin_id")) if origin.get("script_origin_id") else None),
            group=(
                str(getattr(self.vm, "current_editor_group", "") or "")
                if bool(origin.get("script_context")) and getattr(self.vm, "current_editor_group", None) not in (0, None, "")
                else None
            ),
        )

    def _script_owns_active_key_mode(self, km: ActiveKeyMode) -> bool:
        """Return true when the current script context owns an active mode."""

        if not bool(self.in_script_context()):
            return True
        if not bool(getattr(km, "script_context", False)):
            return False
        current_sid = self.current_script_origin_id()
        mode_sid = str(getattr(km, "script_origin_id", "") or "")
        return bool(current_sid and mode_sid and str(current_sid) == mode_sid)

    def _guard_active_keymode_mutation(self, km: ActiveKeyMode, action: str) -> None:
        """Prevent lower-authority scripts from rewriting protected keymode state."""

        if not bool(self.in_script_context()):
            return
        decision = script_runtime_mutation_policy(
            self._current_runtime_authority(kind="editor"),
            self._keymode_activation_authority(km),
        )
        if decision.allowed:
            return
        mode = str(getattr(km, "name", "") or "<unknown>")
        reason = str(decision.reason or "not owned by current script")
        if reason == "trusted registration":
            reason = "trusted active mode"
        raise PermissionError(f"script context cannot {action} active keymode: {mode} ({reason})")

    def remove_key_modes_group(self, group: object) -> int:
        """Remove active keymodes owned by a runtime cleanup group."""

        raw = str(group or "")
        if not raw:
            return 0
        before = len(self.key_mode_stack)
        self.key_mode_stack = [
            km for km in self.key_mode_stack
            if str(getattr(km, "group", "") or "") != raw
        ]
        return int(before - len(self.key_mode_stack))

    def retag_key_modes_group(self, old: object, new: object) -> int:
        """Retag active keymodes created by a staged plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        changed = 0
        out: list[ActiveKeyMode] = []
        for km in self.key_mode_stack:
            if str(getattr(km, "group", "") or "") == old_s:
                out.append(replace(km, group=new_s))
                changed += 1
            else:
                out.append(km)
        self.key_mode_stack = out
        return int(changed)

    def remove_interaction_group(self, group: object) -> int:
        """Drop delayed prompt/query/open-url state owned by a plugin group."""

        raw = str(group or "")
        if not raw:
            return 0
        removed = self.remove_key_modes_group(raw)
        prompt = getattr(self, "prompt", None)
        if prompt is not None and str(getattr(prompt, "group", "") or "") == raw:
            self.prompt = None
            removed += 1
        qreplace = getattr(self, "qreplace", None)
        qauth = getattr(qreplace, "authority", None) if qreplace is not None else None
        if qreplace is not None and str(getattr(qauth, "group", "") or "") == raw:
            try:
                eb = self.cur()
                self._normalize_cursor_lists(eb)
                eb.sel_anchors[eb.primary] = None
            except Exception:
                pass
            self.qreplace = None
            self.key_mode_stack = [
                km for km in self.key_mode_stack
                if not (str(km.name) == "qreplace" and str(getattr(km, "group", "") or "") == raw)
            ]
            removed += 1
        pending_auth = getattr(self, "_pending_open_url_authority", None)
        if getattr(self, "_pending_open_url", None) is not None and str(getattr(pending_auth, "group", "") or "") == raw:
            self._pending_open_url = None
            self._pending_open_url_source = ""
            self._pending_open_url_authority = RuntimeRegistrationAuthority(script_context=False)
            self.key_mode_stack = [
                km for km in self.key_mode_stack
                if not (str(km.name) == "openurl" and str(getattr(km, "group", "") or "") == raw)
            ]
            removed += 1
        return int(removed)

    def remove_plugin_interaction_generation(
        self,
        plugin_load_root: object,
        plugin_generation: object,
    ) -> int:
        """Drop delayed interaction state owned by one plugin generation."""

        def _matches(authority: RuntimeRegistrationAuthority | None) -> bool:
            return self._authority_matches_plugin_generation(
                authority,
                plugin_load_root=plugin_load_root,
                plugin_generation=plugin_generation,
            )

        removed = 0
        before = len(self.key_mode_stack)
        self.key_mode_stack = [km for km in self.key_mode_stack if not _matches(km)]
        removed += int(before - len(self.key_mode_stack))

        prompt = getattr(self, "prompt", None)
        if prompt is not None and _matches(prompt):
            self.prompt = None
            removed += 1

        qreplace = getattr(self, "qreplace", None)
        qauth = getattr(qreplace, "authority", None) if qreplace is not None else None
        if qreplace is not None and _matches(qauth):
            try:
                self._qreplace_clear_primary_selection()
            except Exception:
                pass
            self.qreplace = None
            removed += 1

        pending_auth = getattr(self, "_pending_open_url_authority", None)
        if getattr(self, "_pending_open_url", None) is not None and _matches(pending_auth):
            self._pending_open_url = None
            self._pending_open_url_source = ""
            self._pending_open_url_authority = RuntimeRegistrationAuthority(script_context=False)
            removed += 1

        return int(removed)

    def retag_interaction_group(self, old: object, new: object) -> int:
        """Retag delayed interaction state created during a staged plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        changed = self.retag_key_modes_group(old_s, new_s)
        prompt = getattr(self, "prompt", None)
        if prompt is not None and str(getattr(prompt, "group", "") or "") == old_s:
            prompt.group = new_s
            changed += 1
        qreplace = getattr(self, "qreplace", None)
        qauth = getattr(qreplace, "authority", None) if qreplace is not None else None
        if qreplace is not None and str(getattr(qauth, "group", "") or "") == old_s:
            qreplace.authority = replace(qauth, group=new_s)
            changed += 1
        pending_auth = getattr(self, "_pending_open_url_authority", None)
        if getattr(self, "_pending_open_url", None) is not None and str(getattr(pending_auth, "group", "") or "") == old_s:
            self._pending_open_url_authority = replace(pending_auth, group=new_s)
            changed += 1
        return int(changed)

    def set_key_mode(self, mode: str | None, *, capture: bool = False) -> None:
        if bool(self.in_script_context()):
            for km in list(self.key_mode_stack):
                self._guard_active_keymode_mutation(km, "replace")
        if mode is None or str(mode) == '' or str(mode) == 'global':
            self.key_mode_stack = []
            return
        self.key_mode_stack = [self._make_active_key_mode(str(mode), once=False, capture=bool(capture))]

    def push_key_mode(self, mode: str, *, once: bool = False, capture: bool = False) -> None:
        m = str(mode)
        if not m or m == 'global':
            return
        # Pushing above an active capture mode changes who receives the next key.
        # Scripts may stack their own capture flows, but cannot bypass a trusted
        # confirmation/qreplace/prompt capture by putting another mode on top.
        if bool(self.in_script_context()) and self.key_mode_stack and bool(getattr(self.key_mode_stack[-1], "capture", False)):
            self._guard_active_keymode_mutation(self.key_mode_stack[-1], "shadow")
        self.key_mode_stack.append(self._make_active_key_mode(m, once=bool(once), capture=bool(capture)))

    def pop_key_mode(self) -> str | None:
        if not self.key_mode_stack:
            return None
        if bool(self.in_script_context()):
            self._guard_active_keymode_mutation(self.key_mode_stack[-1], "pop")
        return self.key_mode_stack.pop().name

    def _install_builtin_keymode_bindings(self) -> None:
        """Install tiny internal keymode bindings that must work without plugins.

        Plugins are expected to provide the full default keymap, but some
        modal/editor-internal loops (like query-replace) should remain usable
        even in a headless test harness or minimal embed.
        """

        # Query-replace confirmation loop (capture mode).
        self.keymap.bind("y", "QueryReplaceYes", mode="qreplace")
        self.keymap.bind("Y", "QueryReplaceYes", mode="qreplace")
        self.keymap.bind("Enter", "QueryReplaceYes", mode="qreplace")

        self.keymap.bind("n", "QueryReplaceNo", mode="qreplace")
        self.keymap.bind("N", "QueryReplaceNo", mode="qreplace")

        self.keymap.bind("a", "QueryReplaceAll", mode="qreplace")
        self.keymap.bind("A", "QueryReplaceAll", mode="qreplace")

        self.keymap.bind("l", "QueryReplaceLast", mode="qreplace")
        self.keymap.bind("L", "QueryReplaceLast", mode="qreplace")

        self.keymap.bind("q", "QueryReplaceQuit", mode="qreplace")
        self.keymap.bind("Q", "QueryReplaceQuit", mode="qreplace")
        self.keymap.bind("Esc", "QueryReplaceQuit", mode="qreplace")

        # External URL open confirmation loop (capture mode).
        # This keeps docs browsing safe-by-default even when cap.open-url is enabled.
        self.keymap.bind("y", "OpenUrlYes", mode="openurl")
        self.keymap.bind("Y", "OpenUrlYes", mode="openurl")
        self.keymap.bind("Enter", "OpenUrlYes", mode="openurl")

        self.keymap.bind("n", "OpenUrlNo", mode="openurl")
        self.keymap.bind("N", "OpenUrlNo", mode="openurl")
        self.keymap.bind("Esc", "OpenUrlNo", mode="openurl")

        self.keymap.bind("c", "OpenUrlCopy", mode="openurl")
        self.keymap.bind("C", "OpenUrlCopy", mode="openurl")

        # Prompt picker navigation (non-command prompts).
        # This makes built-in pickers usable even without plugins.
        self.keymap.bind("UpArrow", "PromptSuggestPrev|PromptHistoryPrev", mode="prompt")
        self.keymap.bind("DownArrow", "PromptSuggestNext|PromptHistoryNext", mode="prompt")
        # PageUp/PageDown jump by a small window in picker lists (without mutating the query).
        # For command/find prompts, these fall back to history navigation.
        self.keymap.bind("PageUp", "PromptSuggestPageUp|PromptHistoryPrev", mode="prompt")
        self.keymap.bind("PageDown", "PromptSuggestPageDown|PromptHistoryNext", mode="prompt")
        # Section jumps for grouped suggestion lists.
        self.keymap.bind("Alt-UpArrow", "PromptSuggestPrevSection", mode="prompt")
        self.keymap.bind("Alt-DownArrow", "PromptSuggestNextSection", mode="prompt")
        self.keymap.bind("Ctrl-y", "PromptCopySelected", mode="prompt")
        self.keymap.bind("Ctrl-Home", "PromptSuggestFirst|PromptHome", mode="prompt")
        self.keymap.bind("Ctrl-End", "PromptSuggestLast|PromptEnd", mode="prompt")

    # ----- prompt keymode -----
    def _push_prompt_keymode(self) -> None:
        # Reserve the keymap mode name "prompt" for the built-in prompt bar.
        self.key_mode_stack = [km for km in self.key_mode_stack if km.name != 'prompt']
        self.key_mode_stack.append(self._make_active_key_mode('prompt', once=False))

    def _pop_prompt_keymode(self) -> None:
        self.key_mode_stack = [km for km in self.key_mode_stack if km.name != 'prompt']

    def resolve_key_binding(self, key: str):
        return self.keymap.get_binding(key, modes=self.active_key_modes())

    def binding_desc(self, binding: object) -> str:
        b = binding
        desc = str(getattr(b, 'desc', '') or '').strip()
        if desc:
            return desc

        spec = str(getattr(b, 'action_spec', '') or '').strip()
        if not spec:
            return ''
        steps = parse_action_chain(spec)
        if not steps:
            return ''

        def _short_doc(doc: str) -> str:
            d = str(doc).strip()
            if ' - ' in d:
                return d.split(' - ', 1)[1].strip()
            return d

        def _step_desc(action: str) -> str:
            act = str(action).strip()
            if not act:
                return ''
            if act.startswith('command:'):
                tail = act[len('command:') :].strip()
                if not tail:
                    return ''
                try:
                    cl = parse_cmdline(tail)
                except Exception:
                    cl = None
                name = cl.name if cl is not None else tail.split(None, 1)[0]
                cmd = self.command_dispatcher.get(name)
                if cmd is not None and cmd.doc:
                    return _short_doc(cmd.doc)
            a = self.actions.get(act)
            if a is not None and a.doc:
                return _short_doc(a.doc)
            return ''

        first = _step_desc(steps[0].action)
        if len(steps) <= 1:
            return first
        if first:
            return first + ' …'
        return ''

    # ----- keybinding read/access policy -----
    def _script_keybinding_read_capability_enabled(self) -> bool:
        """Return true when scripts may inspect protected keybinding specs."""

        if not self.in_script_context():
            return False
        try:
            return bool(self.options.get("cap.keybinding-read"))
        except Exception:
            return False

    def _binding_read_denial(
        self,
        binding: object | None,
        *,
        action: str = "read",
        capability: str = "cap.keybinding-read",
    ) -> str:
        """Return a denial string when a lower-authority caller cannot inspect a binding."""

        if binding is None:
            return ""
        current = self._current_runtime_authority(kind="editor")
        decision = binding_access_policy(
            current,
            self._binding_authority(binding),
            capability_enabled=self._script_keybinding_read_capability_enabled(),
        )
        if decision.allowed:
            return ""
        key = str(getattr(binding, "key", "") or "<unknown>")
        mode = str(getattr(binding, "mode", "") or "global")
        label = f"{key}@{mode}" if mode and mode != "global" else key
        reason = str(decision.reason or "not owned by current script")
        return f"script context cannot {str(action or 'read')} keybinding: {label} ({reason}; {capability})"

    def _guard_binding_read(self, binding: object | None, *, action: str = "read") -> None:
        denial = self._binding_read_denial(binding, action=action)
        if denial:
            raise PermissionError(denial)

    def _binding_read_allowed(self, binding: object | None) -> bool:
        return not bool(self._binding_read_denial(binding, action="read"))

    def _script_keybinding_press_capability_enabled(self) -> bool:
        """Return true when scripts may synthesize protected keybinding replay."""

        if not self.in_script_context():
            return False
        try:
            return bool(self.options.get("cap.keybinding-press"))
        except Exception:
            return False

    def _binding_press_denial(self, binding: object | None, *, mode_origin: object | None = None) -> str:
        """Return a denial string for synthetic/lower-authority key replay."""

        if binding is None or not self.in_script_context():
            return ""
        target_authority = self._binding_authority(binding)
        if mode_origin is not None and bool(getattr(mode_origin, "script_context", False)):
            target_authority = RuntimeRegistrationAuthority(
                script_context=True,
                plugin_load_root=(str(getattr(mode_origin, "plugin_load_root", "") or "") or None),
                plugin_generation=(
                    int(getattr(mode_origin, "plugin_generation"))
                    if getattr(mode_origin, "plugin_generation", None) not in (None, "")
                    else None
                ),
                script_origin_id=(str(getattr(mode_origin, "script_origin_id", "") or "") or None),
                group=(str(getattr(binding, "group", "") or "") or None),
            )
        current = self._current_runtime_authority(kind="editor")
        decision = binding_press_policy(
            current,
            target_authority,
            capability_enabled=self._script_keybinding_press_capability_enabled(),
        )
        if decision.allowed:
            return ""
        key = str(getattr(binding, "key", "") or "<unknown>")
        mode = str(getattr(binding, "mode", "") or "global")
        label = f"{key}@{mode}" if mode and mode != "global" else key
        reason = str(decision.reason or "not owned by current script")
        return f"script context cannot press keybinding: {label} ({reason}; cap.keybinding-press)"

    def _binding_same_origin_for_current_script(
        self,
        binding: object | None,
        *,
        mode_origin: object | None = None,
    ) -> bool:
        """Return true when the current script owns the replay target."""

        if binding is None or not self.in_script_context():
            return False
        target_authority = self._binding_authority(binding)
        if mode_origin is not None and bool(getattr(mode_origin, "script_context", False)):
            target_authority = RuntimeRegistrationAuthority(
                script_context=True,
                plugin_load_root=(str(getattr(mode_origin, "plugin_load_root", "") or "") or None),
                plugin_generation=(
                    int(getattr(mode_origin, "plugin_generation"))
                    if getattr(mode_origin, "plugin_generation", None) not in (None, "")
                    else None
                ),
                script_origin_id=(str(getattr(mode_origin, "script_origin_id", "") or "") or None),
                group=(str(getattr(binding, "group", "") or "") or None),
            )
        decision = script_runtime_mutation_policy(self._current_runtime_authority(kind="editor"), target_authority)
        return bool(decision.allowed)

    @staticmethod
    def _binding_span_row(binding: object) -> object:
        span = getattr(binding, "span", None)
        return 0 if span is None else [span.filename, int(span.line), int(span.col)]

    def _iter_binding_objects(self) -> list[Binding]:
        """Return all known binding objects in the keymap's stable display order."""

        try:
            return list(self.keymap._iter_bindings())  # type: ignore[attr-defined]
        except Exception:
            out: list[Binding] = []
            try:
                bindings = getattr(self.keymap, "_bindings", {})
                for mode in sorted(bindings.keys()):
                    for key in sorted(bindings[mode].keys()):
                        out.append(bindings[mode][key])
            except Exception:
                pass
            return out

    def _binding_objects_for_mode(self, mode: str | None = None) -> list[Binding]:
        m = self.keymap._norm_mode(mode)  # type: ignore[attr-defined]
        bindings = getattr(self.keymap, "_bindings", {}).get(m, {})
        return [bindings[key] for key in sorted(bindings.keys())]

    def _resolved_binding_objects(self, modes: list[str] | None = None) -> dict[str, Binding]:
        seen_modes: set[str] = set()
        order = [self.keymap._norm_mode(m) for m in (modes or [])] + ["global"]  # type: ignore[attr-defined]
        winners: dict[str, Binding] = {}
        bindings = getattr(self.keymap, "_bindings", {})
        for mode in order:
            if mode in seen_modes:
                continue
            seen_modes.add(mode)
            for key, binding in bindings.get(mode, {}).items():
                if str(key) not in winners:
                    winners[str(key)] = binding
        return winners

    def binding_rows(self) -> list[list[object]]:
        rows: list[list[object]] = []
        for b in self._iter_binding_objects():
            if not self._binding_read_allowed(b):
                continue
            rows.append([b.key, b.action_spec, self._binding_span_row(b)])
        return rows

    def binding_detail_rows(self) -> list[list[object]]:
        rows: list[list[object]] = []
        for b in self._iter_binding_objects():
            if not self._binding_read_allowed(b):
                continue
            rows.append([b.key, b.action_spec, b.group or 0, self._binding_span_row(b)])
        return rows

    def binding_mode_rows(self) -> list[list[object]]:
        rows: list[list[object]] = []
        for b in self._iter_binding_objects():
            if not self._binding_read_allowed(b):
                continue
            rows.append([b.mode, b.key, b.action_spec, b.group or 0, self._binding_span_row(b)])
        return rows

    def binding_info_rows_for(self, mode: str | None = None) -> list[list[object]]:
        out: list[list[object]] = []
        exact_mode = None if mode in (None, "", "0", "global") else str(mode)
        lookup_mode = "global" if exact_mode is None else exact_mode
        for b in self._binding_objects_for_mode(exact_mode):
            if not self._binding_read_allowed(b):
                continue
            desc = str(getattr(b, "desc", "") or "")
            resolved_desc = desc if desc else self.binding_desc(
                self.keymap.get_binding(str(b.key), modes=[lookup_mode])
            )
            out.append([b.key, b.action_spec, resolved_desc or 0, b.group or 0, self._binding_span_row(b)])
        return out

    def binding_detail_rows_for(self, mode: str | None = None) -> list[list[object]]:
        rows: list[list[object]] = []
        exact_mode = None if mode in (None, "", "0", "global") else str(mode)
        for b in self._binding_objects_for_mode(exact_mode):
            if not self._binding_read_allowed(b):
                continue
            rows.append([b.key, b.action_spec, b.group or 0, self._binding_span_row(b)])
        return rows

    def available_binding_rows(self) -> list[list[object]]:
        rows: list[list[object]] = []
        winners = self._resolved_binding_objects(self.active_key_modes())
        for key in sorted(winners.keys()):
            b = winners[key]
            if not self._binding_read_allowed(b):
                continue
            rows.append([b.mode, b.key, b.action_spec, b.group or 0, self._binding_span_row(b)])
        return rows

    def available_binding_info_rows(self) -> list[list[object]]:
        out: list[list[object]] = []
        winners = self._resolved_binding_objects(self.active_key_modes())
        for key in sorted(winners.keys()):
            b = winners[key]
            if not self._binding_read_allowed(b):
                continue
            desc = str(getattr(b, "desc", "") or "")
            resolved_desc = desc if desc else self.binding_desc(b)
            out.append([b.mode, b.key, b.action_spec, resolved_desc or 0, b.group or 0, self._binding_span_row(b)])
        return out

    def available_binding_inventory_rows(self) -> list[list[object]]:
        once_modes = {str(mode) for mode, once in self.active_key_mode_rows() if once}
        rows = self.available_binding_info_rows()
        out: list[list[object]] = []
        for mode, key, action, desc, _group, _span in rows:
            label = str(desc) if desc not in (0, None, '') else str(action)
            out.append([mode, key, action, label, 1 if str(mode) in once_modes else 0])
        return out

    def _binding_inventory_preview_summary(self) -> str:
        """Return one tiny live resolved-binding witness for plain ``showkey``.

        ``showkey KEY`` is an exact inspector, but its root entry point should
        not collapse back to generic command metadata when Micromax already
        knows the live reachable binding register. Keep the summary compact and
        prefer one active non-global winner when present so modal/prefix state
        stays visible before Enter and after it.
        """

        rows = [list(row) for row in self.available_binding_inventory_rows()]
        summary = self._count_label(len(rows), 'binding')
        if not rows:
            return f"{summary} · {self._active_keymode_binding_witness()}"

        def _score(row: list[object]) -> tuple[int, int, int]:
            mode = str(row[0]) if len(row) >= 1 else 'global'
            label = str(row[3]) if len(row) >= 4 and row[3] not in (0, None, '') else ''
            action = str(row[2]) if len(row) >= 3 else ''
            try:
                once = int(row[4]) if len(row) >= 5 else 0
            except Exception:
                once = 0
            return (
                0 if once else 1,
                0 if mode != 'global' else 1,
                0 if label and label != action else 1,
            )

        target = min(rows, key=_score)
        mode = str(target[0]) if len(target) >= 1 else 'global'
        key = str(target[1]) if len(target) >= 2 else ''
        action = str(target[2]) if len(target) >= 3 else ''
        label = str(target[3]) if len(target) >= 4 and target[3] not in (0, None, '') else ''
        try:
            once = int(target[4]) if len(target) >= 5 else 0
        except Exception:
            once = 0
        if not key or not action:
            return f"{summary} · {self._active_keymode_binding_witness()}"
        detail = f"{key}@{mode}{'!' if once else ''}->{action}"
        if label and label != action:
            detail += f" ({label})"
        return f"{summary} · {detail}"

    def _resolved_binding_for_key(self, key: str, modes: list[str] | None = None) -> Binding | None:
        return self.keymap.get_binding(str(key), modes=(self.active_key_modes() if modes is None else modes))

    def binding_detail_row(self, key: str, *, strict_denial: bool = False) -> list[object] | int:
        """Return the tiny shared resolved-binding detail row behind ``showkey``.

        Script-origin callers see only same-origin bindings unless
        ``cap.keybinding-read`` is enabled.  ``strict_denial`` lets hostcalls
        fail before consuming operands; command-line display paths simply hide
        protected bindings as if absent.
        """

        b = self._resolved_binding_for_key(str(key), modes=self.active_key_modes())
        if b is None:
            return 0
        denial = self._binding_read_denial(b, action="read")
        if denial:
            if strict_denial:
                raise PermissionError(denial)
            return 0
        desc: object = str(getattr(b, "desc", "") or "") or self.binding_desc(b) or 0
        return [b.mode, b.key, b.action_spec, desc, b.group or 0, self._binding_span_row(b)]

    def resolve_key_row(self, key: str, *, strict_denial: bool = False) -> list[object] | int:
        b = self._resolved_binding_for_key(str(key), modes=self.active_key_modes())
        if b is None:
            return 0
        denial = self._binding_read_denial(b, action="resolve")
        if denial:
            if strict_denial:
                raise PermissionError(denial)
            return 0
        return [b.mode, b.key, b.action_spec, b.group or 0, self._binding_span_row(b)]

    def resolve_key_info_row(self, key: str, *, strict_denial: bool = False) -> list[object] | int:
        return self.binding_detail_row(str(key), strict_denial=bool(strict_denial))

    def script_callback_origin_kwargs(self) -> dict[str, object]:
        """Return authority metadata for callbacks registered now.

        Keybindings, saved macro steps, timers, hooks, and command callbacks can
        all outlive the script call that created them.  The durable bits are the
        origin authority (script vs. interactive) and the optional plugin package
        root used for package-local source loads.
        """

        try:
            from_script = bool(self.in_script_context())
        except Exception:
            from_script = False
        plugin_root = getattr(self.vm, "current_plugin_load_root", None)
        plugin_generation = getattr(self.vm, "current_plugin_generation", None)
        return {
            "script_context": from_script,
            "plugin_load_root": (str(plugin_root) if plugin_root and from_script else None),
            "plugin_generation": (
                int(plugin_generation)
                if plugin_generation not in (None, "") and from_script
                else None
            ),
            "script_origin_id": (self.current_script_origin_id() if from_script else None),
        }

    def key_binding_origin_kwargs(self) -> dict[str, object]:
        """Backward-compatible name for keybinding registration metadata."""

        return self.script_callback_origin_kwargs()

    def _mode_activation_for_binding(self, binding: Binding) -> ActiveKeyMode | None:
        """Return the active mode entry that selected *binding*, when any."""

        mode = str(getattr(binding, "mode", "global") or "global")
        if mode == "global":
            return None
        for km in self.active_key_mode_entries():
            if str(km.name) == mode:
                return km
        return None

    def _run_key_binding(self, binding: Binding, *, mode_origin: ActiveKeyMode | None = None) -> bool:
        """Run a resolved key binding, preserving binding and mode authority.

        Binding provenance alone is not enough: a lower-authority script can
        activate an existing trusted mode and return.  If the eventual keypress
        resolves through that script-activated mode, the mode activation is the
        delayed authority object, so it wins over the binding's ambient trust.

        Conversely, script-originated synthetic keypresses must not borrow the
        authority of existing trusted/user or other-origin bindings.  They may
        replay same-origin bindings, or explicitly opt into replaying protected
        binding *specs* via ``cap.keybinding-press``, but protected specs still
        execute under the caller's script authority.
        """

        spec = str(getattr(binding, "action_spec", "") or "")
        if self.in_script_context():
            denial = self._binding_press_denial(binding, mode_origin=mode_origin)
            if denial:
                self.message(f"key press: {denial}")
                return False
            origin = mode_origin if mode_origin is not None and bool(getattr(mode_origin, "script_context", False)) else None
            if origin is not None and self._binding_same_origin_for_current_script(binding, mode_origin=origin):
                return bool(
                    self.run_script_origin_callback(
                        lambda: self.run_action_chain(spec),
                        plugin_load_root=getattr(origin, "plugin_load_root", None),
                        group=getattr(binding, "group", None),
                        plugin_generation=getattr(origin, "plugin_generation", None),
                        script_origin_id=getattr(origin, "script_origin_id", None),
                        rollback_on_false=True,
                    )
                )
            if bool(getattr(binding, "script_context", False)) and self._binding_same_origin_for_current_script(binding):
                return bool(
                    self.run_script_origin_callback(
                        lambda: self.run_action_chain(spec),
                        plugin_load_root=getattr(binding, "plugin_load_root", None),
                        group=getattr(binding, "group", None),
                        plugin_generation=getattr(binding, "plugin_generation", None),
                        script_origin_id=getattr(binding, "script_origin_id", None),
                        rollback_on_false=True,
                    )
                )
            # ``cap.keybinding-press`` intentionally replays a protected action
            # spec under the *caller* script context, not under the target
            # binding's trusted/other-origin authority.
            return self.run_action_chain(spec)

        origin = mode_origin if mode_origin is not None and bool(getattr(mode_origin, "script_context", False)) else None
        if origin is not None:
            return bool(
                self.run_script_origin_callback(
                    lambda: self.run_action_chain(spec),
                    plugin_load_root=getattr(origin, "plugin_load_root", None),
                    group=getattr(binding, "group", None),
                    plugin_generation=getattr(origin, "plugin_generation", None),
                    script_origin_id=getattr(origin, "script_origin_id", None),
                    rollback_on_false=True,
                )
            )
        if not bool(getattr(binding, "script_context", False)):
            return self.run_action_chain(spec)
        return bool(
            self.run_script_origin_callback(
                lambda: self.run_action_chain(spec),
                plugin_load_root=getattr(binding, "plugin_load_root", None),
                group=getattr(binding, "group", None),
                plugin_generation=getattr(binding, "plugin_generation", None),
                script_origin_id=getattr(binding, "script_origin_id", None),
                rollback_on_false=True,
            )
        )

    def dispatch_key(self, key: str) -> bool:
        """Resolve and execute a bound key.

        One-shot keymodes get first crack at the next key press. If the key is
        not bound in the topmost one-shot mode, that mode is popped and lookup
        falls through to the remaining active modes and global bindings.
        """

        while self.key_mode_stack and self.key_mode_stack[-1].once:
            top = self.key_mode_stack[-1]
            b = self.keymap.get_binding(key, modes=[top.name])
            if b is not None:
                try:
                    return self._run_key_binding(b, mode_origin=top)
                finally:
                    if self.key_mode_stack and self.key_mode_stack[-1] == top:
                        self.key_mode_stack.pop()
            self.key_mode_stack.pop()

        # Capture modes intercept all keypresses: if a key is not bound in the
        # active capture mode, it does not fall through to global bindings.
        if self.key_mode_stack and getattr(self.key_mode_stack[-1], 'capture', False):
            top = self.key_mode_stack[-1]
            b = self.keymap.get_binding(key, modes=[top.name])
            if b is None:
                return False
            try:
                return self._run_key_binding(b, mode_origin=top)
            finally:
                if top.once and self.key_mode_stack and self.key_mode_stack[-1] == top:
                    self.key_mode_stack.pop()

        # Docs/help buffers act like a tiny in-editor browser:
        # - Enter follows the markdown link under cursor (best-effort).
        # - Backspace goes back in the docs navigation stack.
        # - y copies the link target under cursor (like "copy link address").
        if self.prompt is None and self.current_help_doc_topic():
            if key == "Enter":
                return bool(self.help_follow())
            if key == "Backspace":
                return bool(self.help_back())
            if key in {"y", "Y"}:
                return bool(self.help_copy_link_target())


        b = self.resolve_key_binding(key)
        if b is None:
            # Fallback: treat unbound printable keys as text input.
            # - when a prompt is active, edit the prompt
            # - otherwise, insert into the buffer
            if len(key) == 1 and key.isprintable() and key not in ('\n', '\r', '\t'):
                self.input['text'] = key
                return self.run_action('PromptInsertText' if self.prompt is not None else 'InsertText')
            return False
        return self._run_key_binding(b, mode_origin=self._mode_activation_for_binding(b))

    def _emit_mx_hook(self, hook_word: str, *args: Any) -> None:
        """Fire a micromax hook word if present.

        Hooks are best-effort: exceptions are caught and recorded as messages.
        Hook handlers run in the editor's embedded VM but are treated as
        notifications: we discard any stack effects after the call.
        """

        try:
            if self.vm.find_word(hook_word) is None:
                return
            depth = len(self.vm.stack)
            self.vm.stack.extend(args)
            self.vm.eval(hook_word, filename="<editor-hook>")
            del self.vm.stack[depth:]
        except Exception as e:
            self.message(f"hook {hook_word}: error: {e}")

    # ----- undo snapshot helpers -----
    def _snapshot_buffer_state(self, eb: EditorBuffer) -> tuple[str, list[Cursor], list[Cursor | None], list[int], int]:
        self._normalize_cursor_lists(eb)
        return (
            eb.buf.get_text(),
            [Cursor(c.line, c.col) for c in eb.cursors],
            [Cursor(a.line, a.col) if a else None for a in eb.sel_anchors],
            [int(x) for x in eb.cursor_ids],
            int(eb.primary),
        )

    def _restore_buffer_state(self, eb: EditorBuffer, snap: tuple[str, list[Cursor], list[Cursor | None], list[int], int]) -> None:
        text, curs, anchors, cursor_ids, primary = snap
        eb.buf.set_text(text)
        eb.cursors[:] = [Cursor(c.line, c.col) for c in curs]
        eb.sel_anchors[:] = [Cursor(a.line, a.col) if a else None for a in anchors]
        eb.cursor_ids[:] = [int(x) for x in cursor_ids]
        eb.primary = int(primary)
        self._normalize_cursor_lists(eb)

    def _record_undo_snapshot(
        self,
        eb: EditorBuffer,
        before: tuple[str, list[Cursor], list[Cursor | None], list[int], int],
        after: tuple[str, list[Cursor], list[Cursor | None], list[int], int],
        desc: str,
    ) -> None:
        def _undo() -> None:
            self._restore_buffer_state(eb, before)

        def _redo() -> None:
            self._restore_buffer_state(eb, after)

        def _target() -> str:
            name = str(getattr(eb.buf, "path", "") or getattr(eb, "name", "") or "").strip()
            self._normalize_cursor_lists(eb)
            if eb.cursors:
                c = eb.cursors[eb.primary]
                if name:
                    return f"{name} @ {c.line + 1}:{c.col}"
                return f"{c.line + 1}:{c.col}"
            return name

        self.undo.record(
            Edit(
                undo=_undo,
                redo=_redo,
                description=desc,
                target=_target,
                authority=self._clone_mark_authority(self._current_runtime_authority(kind="editor")),
            )
        )

    def _sync_buffer_fastdirty_mode(self, eb: EditorBuffer) -> None:
        try:
            eb.buf.set_fastdirty(bool(self.options.get("fastdirty", local=eb.local_options)))
        except Exception:
            pass

    def _sync_all_buffer_fastdirty_modes(self) -> None:
        for eb in self.buffers.values():
            self._sync_buffer_fastdirty_mode(eb)

    # ----- buffers -----
    def new_buffer(
        self,
        name: str = "*scratch*",
        text: str = "",
        *,
        path: str | None = None,
        fileformat: str | None = None,
        encoding: str | None = None,
    ) -> None:
        cid = self._alloc_cursor_id()
        ft = detect_filetype(str(path or ""), str(text or ""))
        ff = str(fileformat or self.options.get("fileformat") or "unix").strip().lower()
        if ff not in ("unix", "dos"):
            ff = "unix"
        enc = str(encoding or self.options.get("encoding") or "utf-8").strip() or "utf-8"
        self.buffers[name] = EditorBuffer(
            name=name,
            buf=Buffer(text, path=path),
            cursors=[Cursor(0, 0)],
            sel_anchors=[None],
            cursor_ids=[cid],
            primary=0,
            local_options={"filetype": ft, "fileformat": ff, "encoding": enc},
        )
        self._normalize_buffer_authority()
        self._buffer_authority[str(name)] = self._current_runtime_authority(kind="editor")
        self._sync_buffer_fastdirty_mode(self.buffers[name])
        self._activate_buffer(name)
        if path:
            self._refresh_buffer_disk_signature(self.buffers[name])

    def filetype(self) -> str:
        """Return the active buffer's detected filetype."""
        eb = self.cur()
        ft = eb.local_options.get("filetype")
        if isinstance(ft, str) and ft:
            return ft
        # Best-effort fallback.
        ft2 = detect_filetype(str(eb.buf.path or ""), eb.buf.get_text())
        eb.local_options["filetype"] = ft2
        return ft2

    def _snapshot_buffer_identity(self, eb: EditorBuffer) -> BufferIdentitySnapshot:
        """Capture identity fields that save-as mutates before a write."""

        return BufferIdentitySnapshot(
            ref=eb,
            name=str(eb.name),
            path=str(eb.buf.path) if eb.buf.path is not None else None,
            local_options=dict(eb.local_options),
            active=str(self.active) if self.active is not None else None,
            buffer_mru=tuple(str(x) for x in self._buffer_mru),
            buffer_authority=self._snapshot_buffer_authority(),
            marks={
                str(mark): (str(buf_name), Cursor(int(cur.line), int(cur.col)))
                for mark, (buf_name, cur) in self.marks.items()
            },
            mark_authority=self._snapshot_mark_authority(),
            disk_signature=getattr(eb, "disk_signature", None),
            disk_content_hash=getattr(eb, "disk_content_hash", None),
            script_dirty_since_sync=bool(getattr(eb, "script_dirty_since_sync", False)),
        )

    def _restore_buffer_identity(self, snap: BufferIdentitySnapshot) -> None:
        """Restore the buffer/name/path view captured by ``snap``."""

        eb = snap.ref
        for name, candidate in list(self.buffers.items()):
            if candidate is eb and str(name) != str(snap.name):
                del self.buffers[name]
        self.buffers[str(snap.name)] = eb
        eb.name = str(snap.name)
        eb.buf.path = snap.path
        eb.local_options.clear()
        eb.local_options.update(dict(snap.local_options))
        eb.disk_signature = snap.disk_signature
        eb.disk_content_hash = snap.disk_content_hash
        eb.script_dirty_since_sync = bool(snap.script_dirty_since_sync)
        self.active = snap.active
        self._buffer_mru = [str(x) for x in snap.buffer_mru if str(x) in self.buffers]
        self._restore_buffer_authority(snap.buffer_authority)
        self.marks = {
            str(mark): (str(buf_name), Cursor(int(cur.line), int(cur.col)))
            for mark, (buf_name, cur) in snap.marks.items()
        }
        self._restore_mark_authority(snap.mark_authority)

    def _save_as_conflicting_buffer(self, eb: EditorBuffer, target: str) -> str:
        """Return the open buffer conflicting with ``target``, or ``''``."""

        target_name = str(target or "")
        target_norm = self._normalize_path(target_name)
        for name, other in self.buffers.items():
            if other is eb:
                continue
            if str(name) == target_name:
                return str(name)
            other_path = str(getattr(other.buf, "path", "") or "")
            if target_norm and other_path and self._normalize_path(other_path) == target_norm:
                return str(name)
        return ""

    def _update_buffer_path(self, eb: EditorBuffer, path: str) -> None:
        eb.buf.path = str(path)
        eb.local_options["filetype"] = detect_filetype(str(path), eb.buf.get_text())

    def _autosave_seconds(self, eb: EditorBuffer) -> int:
        try:
            raw = self.options.get("autosave", local=eb.local_options)
            return max(0, int(raw or 0))
        except Exception:
            return 0

    def _script_dirty_autosave_blocked(self, eb: EditorBuffer) -> bool:
        """True when autosave would be a script-originated disk write without cap.fs-save."""

        if not bool(getattr(eb, "script_dirty_since_sync", False)):
            return False
        try:
            return not bool(self.options.get("cap.fs-save"))
        except Exception:
            return True

    def _note_buffer_changed(self, eb: EditorBuffer) -> None:
        if not bool(getattr(eb.buf, "dirty", False)):
            eb.autosave_dirty_since = None
            eb.script_dirty_since_sync = False
            return
        if self.in_script_context():
            eb.script_dirty_since_sync = True
        if self._script_dirty_autosave_blocked(eb):
            eb.autosave_dirty_since = None
            return
        if self._autosave_seconds(eb) <= 0:
            eb.autosave_dirty_since = None
            return
        if not str(getattr(eb.buf, "path", "") or ""):
            eb.autosave_dirty_since = None
            return
        if bool(self.options.get("readonly", local=eb.local_options)):
            eb.autosave_dirty_since = None
            return
        eb.autosave_dirty_since = self.now()

    def _arm_autosave_if_needed(self, eb: EditorBuffer, *, now: float | None = None) -> None:
        if not bool(getattr(eb.buf, "dirty", False)):
            eb.autosave_dirty_since = None
            eb.script_dirty_since_sync = False
            return
        if self._script_dirty_autosave_blocked(eb):
            eb.autosave_dirty_since = None
            return
        if self._autosave_seconds(eb) <= 0:
            eb.autosave_dirty_since = None
            return
        if not str(getattr(eb.buf, "path", "") or ""):
            eb.autosave_dirty_since = None
            return
        if bool(self.options.get("readonly", local=eb.local_options)):
            eb.autosave_dirty_since = None
            return
        if eb.autosave_dirty_since is None:
            eb.autosave_dirty_since = float(self.now() if now is None else now)

    def _autosave_buffer_due(self, eb: EditorBuffer, *, now: float | None = None) -> bool:
        when = float(self.now() if now is None else now)
        self._arm_autosave_if_needed(eb, now=when)
        since = eb.autosave_dirty_since
        if since is None:
            return False
        secs = self._autosave_seconds(eb)
        if secs <= 0:
            return False
        return (when - float(since)) >= float(secs)

    def _detect_fileformat_from_text(self, text: str) -> str:
        """Return a tiny line-ending format guess for opened text."""

        s = str(text or "")
        i = s.find("\n")
        if i > 0 and s[i - 1] == "\r":
            return "dos"
        return "unix"

    def _normalize_encoding_name(self, raw: object) -> str:
        """Return a usable codec name (best-effort)."""

        enc = str(raw or "").strip() or "utf-8"
        try:
            return str(codecs.lookup(enc).name or enc)
        except LookupError:
            return enc

    def _persist_enabled(self) -> bool:
        """Return True if editor-owned persistence is enabled (cap.persist)."""

        try:
            return bool(self.options.get("cap.persist"))
        except Exception:
            return False

    def _persist_store_path(self, raw: str, *, default: str) -> Path | None:
        """Resolve a persistence file path under cap.persist-root (best-effort)."""

        if not self._persist_enabled():
            return None

        s = str(raw or "").strip() or str(default or "").strip()
        if not s:
            return None

        p = persist_resolve_path(self, s)
        if not persist_path_allowed(self, p):
            self.message(persist_deny_reason(self, p))
            return None
        return p

    def _persisted_runtime_authority(self, kind: str, path: Path | str | None = None) -> RuntimeRegistrationAuthority:
        """Return lower-authority provenance for rows restored from disk.

        Persistence files are editor-owned and explicitly gated by ``cap.persist``,
        but their contents still came from a mutable filesystem file.  A restored
        recent or prompt-history row should therefore not masquerade as fresh
        interactive/user state when later script-origin code tries to replay or
        destroy it.  Use a stable origin token outside the current script-origin
        namespace so trusted user actions can still use the row, while scripts
        must create their own rows or hold a narrow cleanup capability.
        """

        label = str(kind or "persist").strip() or "persist"
        suffix = ""
        if path is not None:
            try:
                suffix = ":" + self._normalize_path(str(path))
            except Exception:
                suffix = ":" + str(path)
        return RuntimeRegistrationAuthority(
            script_context=True,
            script_origin_id=f"persist:{label}{suffix}",
            group=f"persist:{label}",
        )

    def _recent_store_path(self) -> Path | None:
        """Return the configured recent-files persistence path (or None)."""

        raw = os.environ.get("MICROMAX_RECENT_FILE") or str(self.options.get("recent.file") or "")
        return self._persist_store_path(raw, default="~/.config/micromax/recent.json")

    def load_recent_files(self) -> bool:
        """Load recent file MRU from disk (best-effort).

        This is gated by options:
        - `recent.persist` (opt-in)
        - `cap.persist` (unsafe; off by default)

        Returns True when a file existed and was loaded.
        """
        if not bool(self.options.get("recent.persist")):
            return False
        p = self._recent_store_path()
        if p is None:
            return False
        try:
            text = read_persist_text(self, p)
            if text is None:
                return False
            data = json.loads(text)
            if isinstance(data, list):
                xs = [str(x) for x in data if isinstance(x, (str, int, float))]
                out: list[str] = []
                seen: set[str] = set()
                for raw in xs:
                    n = self._normalize_path(str(raw))
                    if not n or n in seen:
                        continue
                    seen.add(n)
                    out.append(str(raw))
                self.recent_files[:] = out[: int(self._recent_limit)]
                persisted = self._persisted_runtime_authority("recent", p)
                self.recent_files_authority[:] = [
                    self._clone_mark_authority(persisted) for _ in self.recent_files
                ]
        except Exception as e:
            self.message(f"recent load error: {e}")
            return False
        return True

    def save_recent_files(self) -> bool:
        """Persist recent file MRU to disk (best-effort)."""
        if not bool(self.options.get("recent.persist")):
            return False
        p = self._recent_store_path()
        if p is None:
            return False
        try:
            write_persist_text(self, p, json.dumps(list(self.recent_files), indent=2, ensure_ascii=False) + "\n")
        except Exception as e:
            self.message(f"recent save error: {e}")
            return False
        return True

    def _history_store_path(self) -> Path | None:
        """Return the configured prompt-history persistence path (or None)."""

        raw = os.environ.get("MICROMAX_HISTORY_FILE") or str(self.options.get("history.file") or "")
        return self._persist_store_path(raw, default="~/.config/micromax/history.json")

    def load_prompt_history(self) -> bool:
        """Load prompt history from disk (best-effort).

        This is gated by options:
        - `history.persist` (opt-in)
        - `cap.persist` (unsafe; off by default)

        Returns True when a file existed and was loaded.
        """

        if not bool(self.options.get("history.persist")):
            return False
        p = self._history_store_path()
        if p is None:
            return False
        try:
            text = read_persist_text(self, p)
            if text is None:
                return False
            data = json.loads(text)
        except Exception as e:
            self.message(f"history load error: {e}")
            return False

        limit = 200
        try:
            limit = max(1, int(self.options.get("history.limit")))
        except Exception:
            limit = 200

        def _norm_list(v: object) -> list[str]:
            if not isinstance(v, list):
                return []
            out: list[str] = []
            for it in v:
                if isinstance(it, (str, int, float)):
                    s = str(it).strip("\n")
                    if s:
                        out.append(s)
            # Clamp to last N (most recent).
            return out[-limit:]

        persisted = self._persisted_runtime_authority("prompt-history", p)

        if isinstance(data, dict):
            for k, v in data.items():
                kk = str(k)
                xs = _norm_list(v)
                if xs:
                    self.history[kk] = xs
                    self.history_authority[kk] = [
                        self._clone_mark_authority(persisted) for _ in xs
                    ]
        elif isinstance(data, list):
            # Legacy: treat a bare list as command history.
            xs = _norm_list(data)
            if xs:
                self.history["command"] = xs
                self.history_authority["command"] = [
                    self._clone_mark_authority(persisted) for _ in xs
                ]
        else:
            return False

        self._normalize_prompt_history_authority()
        return True

    def save_prompt_history(self) -> bool:
        """Persist prompt history to disk (best-effort)."""

        if not bool(self.options.get("history.persist")):
            return False
        p = self._history_store_path()
        if p is None:
            return False

        limit = 200
        try:
            limit = max(1, int(self.options.get("history.limit")))
        except Exception:
            limit = 200

        # Clamp each kind and keep the JSON deterministic.
        self._normalize_prompt_history_authority()
        data: dict[str, list[str]] = {}
        for k in sorted(self.history.keys(), key=lambda x: str(x)):
            xs = self.history.get(k, [])
            if not isinstance(xs, list):
                continue
            out: list[str] = []
            for it in xs:
                s = str(it).strip("\n")
                if s:
                    out.append(s)
            if out:
                data[str(k)] = out[-limit:]

        try:
            write_persist_text(self, p, json.dumps(data, indent=2, ensure_ascii=False) + "\n")
        except Exception as e:
            self.message(f"history save error: {e}")
            return False

        return True

    def _plugin_cleanup_log_store_path(self) -> Path | None:
        """Return the configured cleanup-diagnostic persistence path."""

        raw = os.environ.get("MICROMAX_PLUGIN_CLEANUP_LOG") or str(self.options.get("plugin.cleanup-log.file") or "")
        return self._persist_store_path(raw, default="~/.config/micromax/plugin-cleanup.jsonl")

    def _plugin_cleanup_log_enabled(self) -> bool:
        """Return true when cleanup failures should be persisted."""

        try:
            return bool(self.options.get("plugin.cleanup-log.persist")) and self._persist_enabled()
        except Exception:
            return False

    def _plugin_cleanup_log_limit(self) -> int:
        try:
            return max(1, int(self.options.get("plugin.cleanup-log.limit")))
        except Exception:
            return 200

    @staticmethod
    def _plugin_name_from_cleanup_group(group: object) -> str:
        text = str(group or "")
        prefix = "plugin:"
        if text.startswith(prefix):
            text = text[len(prefix):]
        if "#" in text:
            text = text.split("#", 1)[0]
        return text

    def _plugin_cleanup_log_line_dicts(self, report: object) -> list[dict[str, object]]:
        """Return JSONL records for one failed cleanup/retag report."""

        failures = getattr(report, "failures", ())
        if not failures:
            return []
        group = str(getattr(report, "group", "") or "")
        plugin_name = self._plugin_name_from_cleanup_group(group)
        action = str(getattr(report, "action", "") or "")
        target_group = str(getattr(report, "target_group", "") or "")
        now = time.time()
        out: list[dict[str, object]] = []
        for failure in failures:
            out.append({
                "ts": now,
                "plugin": plugin_name,
                "action": action,
                "group": group,
                "target_group": target_group,
                "surface": str(getattr(failure, "surface", "") or ""),
                "operation": str(getattr(failure, "action", "") or ""),
                "detail": str(getattr(failure, "detail", "") or "failed"),
            })
        return out

    def record_plugin_cleanup_report(self, report: object) -> bool:
        """Persist failed plugin cleanup/retag diagnostics when explicitly enabled.

        The in-memory report list remains the immediate truth used by plugin
        unload/reload.  This opt-in JSONL store is only a diagnostic receipt,
        gated by the existing ``cap.persist`` persistence boundary, so failures
        remain inspectable after a process restart without giving plugins a new
        ambient write channel.
        """

        if bool(getattr(report, "ok", True)):
            return False
        if not self._plugin_cleanup_log_enabled():
            return False
        p = self._plugin_cleanup_log_store_path()
        if p is None:
            return False
        records = self._plugin_cleanup_log_line_dicts(report)
        if not records:
            return False
        try:
            existing_text = read_persist_text(self, p)
            existing_lines = [line for line in str(existing_text or "").splitlines() if line.strip()]
            new_lines = [json.dumps(record, sort_keys=True, ensure_ascii=False) for record in records]
            limit = self._plugin_cleanup_log_limit()
            lines = (existing_lines + new_lines)[-limit:]
            write_persist_text(self, p, "\n".join(lines) + "\n")
        except Exception as e:
            self.message(f"plugin cleanup-log save error: {e}")
            return False
        return True

    def plugin_cleanup_log_rows(self, name: str = "") -> list[list[object]]:
        """Return persisted cleanup-failure rows from the opt-in JSONL log."""

        if self.in_script_context() and not self._script_plugin_read_capability_enabled():
            return []
        if not self._plugin_cleanup_log_enabled():
            return []
        p = self._plugin_cleanup_log_store_path()
        if p is None:
            return []
        flt = str(name or "").strip()
        try:
            text = read_persist_text(self, p)
        except Exception as e:
            self.message(f"plugin cleanup-log load error: {e}")
            return []
        if not text:
            return []
        rows: list[list[object]] = []
        for line in str(text).splitlines():
            raw = line.strip()
            if not raw:
                continue
            try:
                data = json.loads(raw)
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            plugin_name = str(data.get("plugin", "") or "")
            if flt and plugin_name != flt:
                continue
            rows.append([
                plugin_name,
                str(data.get("action", "") or ""),
                str(data.get("group", "") or ""),
                str(data.get("target_group", "") or ""),
                str(data.get("surface", "") or ""),
                str(data.get("operation", "") or ""),
                str(data.get("detail", "") or "failed"),
            ])
        return rows

    # ----- saved-cursor provenance / delayed navigation policy -----
    def _normalize_saved_cursor_authority(self) -> None:
        """Keep saved-cursor provenance aligned with the visible register."""

        auth = getattr(self, "_saved_cursors_authority", None)
        if not isinstance(auth, dict):
            auth = {}
            self._saved_cursors_authority = auth
        for key in list(auth.keys()):
            if str(key) not in self._saved_cursors:
                auth.pop(str(key), None)
        for key in list(self._saved_cursors.keys()):
            if str(key) not in auth:
                auth[str(key)] = RuntimeRegistrationAuthority(script_context=False)

    def _snapshot_saved_cursors(self) -> dict[str, dict[str, int]]:
        """Return a detached saved-cursor row snapshot."""

        out: dict[str, dict[str, int]] = {}
        for key, item in list(self._saved_cursors.items()):
            if not isinstance(item, dict):
                continue
            try:
                out[str(key)] = {
                    "line": max(0, int(item.get("line", 0) or 0)),
                    "col": max(0, int(item.get("col", 0) or 0)),
                }
            except Exception:
                continue
        return out

    def _snapshot_saved_cursor_authority(self) -> dict[str, RuntimeRegistrationAuthority]:
        """Return a detached saved-cursor provenance snapshot."""

        self._normalize_saved_cursor_authority()
        return {
            str(key): self._clone_mark_authority(auth)
            for key, auth in getattr(self, "_saved_cursors_authority", {}).items()
        }

    def _restore_saved_cursor_authority(
        self,
        snapshot: dict[str, RuntimeRegistrationAuthority] | None,
    ) -> None:
        """Restore saved-cursor provenance, defaulting missing live rows to trusted."""

        snap = snapshot or {}
        self._saved_cursors_authority = {
            str(key): self._clone_mark_authority(snap.get(str(key)))
            for key in self._saved_cursors.keys()
        }
        self._normalize_saved_cursor_authority()

    def _restore_saved_cursors(
        self,
        rows: dict[str, dict[str, int]] | None,
        authority: dict[str, RuntimeRegistrationAuthority] | None = None,
    ) -> None:
        """Restore saved-cursor rows and their provenance sidecar."""

        self._saved_cursors = {}
        for key, item in (rows or {}).items():
            if not isinstance(item, dict):
                continue
            try:
                self._saved_cursors[str(key)] = {
                    "line": max(0, int(item.get("line", 0) or 0)),
                    "col": max(0, int(item.get("col", 0) or 0)),
                }
            except Exception:
                continue
        self._restore_saved_cursor_authority(authority or {})

    def _remove_saved_cursor_rows_for_authority(
        self,
        predicate: Callable[[RuntimeRegistrationAuthority], bool],
    ) -> int:
        """Prune savecursor rows whose authority matches *predicate*."""

        self._normalize_saved_cursor_authority()
        removed = 0
        for key, authority in list(getattr(self, "_saved_cursors_authority", {}).items()):
            auth = self._clone_mark_authority(authority)
            if not predicate(auth):
                continue
            self._saved_cursors.pop(str(key), None)
            self._saved_cursors_authority.pop(str(key), None)
            removed += 1
        self._normalize_saved_cursor_authority()
        if removed:
            try:
                self.save_saved_cursors()
            except Exception:
                pass
        return int(removed)

    def remove_saved_cursor_group(self, group: object) -> int:
        """Remove saved-cursor rows owned by one runtime group."""

        raw = str(group or "")
        if not raw:
            return 0
        return self._remove_saved_cursor_rows_for_authority(
            lambda authority: self._authority_group_matches(authority, raw)
        )

    def retag_saved_cursor_group(self, old: object, new: object) -> int:
        """Retag staged saved-cursor rows after successful plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        self._normalize_saved_cursor_authority()
        changed = 0
        for key, authority in list(getattr(self, "_saved_cursors_authority", {}).items()):
            auth = self._clone_mark_authority(authority)
            if not self._authority_group_matches(auth, old_s):
                continue
            self._saved_cursors_authority[str(key)] = self._authority_with_group(auth, new_s)
            changed += 1
        self._normalize_saved_cursor_authority()
        return int(changed)

    def remove_plugin_saved_cursor_generation(
        self,
        plugin_load_root: object,
        plugin_generation: object,
    ) -> int:
        """Remove saved-cursor rows owned by one unloaded plugin generation."""

        return self._remove_saved_cursor_rows_for_authority(
            lambda authority: self._authority_matches_plugin_generation(
                authority,
                plugin_load_root=plugin_load_root,
                plugin_generation=plugin_generation,
            )
        )

    def _saved_cursor_entry_authority(self, norm_path: object) -> RuntimeRegistrationAuthority:
        """Return authority attached to one saved-cursor row."""

        self._normalize_saved_cursor_authority()
        return self._clone_mark_authority(
            getattr(self, "_saved_cursors_authority", {}).get(str(norm_path or ""))
        )

    def _guard_saved_cursor_entry(
        self,
        norm_path: object,
        action: str,
        *,
        quiet: bool = False,
    ) -> bool:
        """Return whether the current caller may mutate/replay a saved cursor row."""

        norm = str(norm_path or "")
        if not norm or norm not in self._saved_cursors:
            return True
        if not self.in_script_context():
            return True
        action_s = str(action or "")
        try:
            if action_s in {"restore", "replay"} and bool(self.options.get("cap.cursor-restore")):
                return True
        except Exception:
            pass
        current = self._current_runtime_authority(kind="editor")
        target = self._saved_cursor_entry_authority(norm)
        decision = script_runtime_mutation_policy(current, target)
        if decision.allowed:
            return True
        if not quiet:
            reason = str(decision.reason or "not owned by current script")
            self.message(f"savecursor {str(action or 'access')}: script context cannot use saved cursor ({reason})")
        return False

    @staticmethod
    def _same_saved_cursor_position(a: object, b: object) -> bool:
        """Return whether two saved-cursor row objects describe the same landing."""

        try:
            aa = a if isinstance(a, dict) else {}
            bb = b if isinstance(b, dict) else {}
            return int(aa.get("line", 0) or 0) == int(bb.get("line", 0) or 0) and int(
                aa.get("col", 0) or 0
            ) == int(bb.get("col", 0) or 0)
        except Exception:
            return False

    def _cursor_store_path(self) -> Path | None:
        """Return the configured savecursor persistence path (or None)."""

        raw = os.environ.get("MICROMAX_CURSOR_FILE") or str(self.options.get("savecursor.file") or "")
        return self._persist_store_path(raw, default="~/.config/micromax/cursor.json")

    def load_saved_cursors(self) -> bool:
        """Load saved primary-cursor positions from disk (best-effort).

        This is gated by options:
        - `savecursor` (opt-in)
        - `cap.persist` (unsafe; off by default)

        Returns True when a file existed and was loaded.
        """

        if not bool(self.options.get("savecursor")):
            return False
        p = self._cursor_store_path()
        if p is None:
            return False
        try:
            text = read_persist_text(self, p)
            if text is None:
                return False
            data = json.loads(text)
        except Exception as e:
            self.message(f"savecursor load error: {e}")
            return False

        if not isinstance(data, dict):
            return False

        out: dict[str, dict[str, int]] = {}
        out_authority: dict[str, RuntimeRegistrationAuthority] = {}
        persisted_authority = self._persisted_runtime_authority("saved-cursor", p)
        for raw_path, raw_pos in data.items():
            norm = self._normalize_path(str(raw_path))
            if not norm:
                continue
            line = 0
            col = 0
            try:
                if isinstance(raw_pos, dict):
                    line = max(0, int(raw_pos.get("line", 0) or 0))
                    col = max(0, int(raw_pos.get("col", 0) or 0))
                elif isinstance(raw_pos, (list, tuple)) and len(raw_pos) >= 2:
                    line = max(0, int(raw_pos[0] or 0))
                    col = max(0, int(raw_pos[1] or 0))
                else:
                    continue
            except Exception:
                continue
            out[norm] = {"line": int(line), "col": int(col)}
            out_authority[norm] = self._clone_mark_authority(persisted_authority)

        self._saved_cursors = out
        self._saved_cursors_authority = out_authority
        self._normalize_saved_cursor_authority()
        return True

    def save_saved_cursors(self) -> bool:
        """Persist saved primary-cursor positions to disk (best-effort)."""

        if not bool(self.options.get("savecursor")):
            return False
        p = self._cursor_store_path()
        if p is None:
            return False

        self._normalize_saved_cursor_authority()
        data: dict[str, dict[str, int]] = {}
        for key in sorted(self._saved_cursors.keys()):
            item = self._saved_cursors.get(key)
            if not isinstance(item, dict):
                continue
            try:
                data[str(key)] = {
                    "line": max(0, int(item.get("line", 0) or 0)),
                    "col": max(0, int(item.get("col", 0) or 0)),
                }
            except Exception:
                continue

        try:
            write_persist_text(self, p, json.dumps(data, indent=2, ensure_ascii=False) + "\n")
        except Exception as e:
            self.message(f"savecursor save error: {e}")
            return False
        return True

    def _remember_cursor_for_buffer(self, eb: EditorBuffer | None) -> bool:
        """Remember one buffer's primary cursor position (best-effort)."""

        if eb is None or not bool(self.options.get("savecursor")):
            return False
        raw = str(getattr(eb.buf, "path", "") or "")
        norm = self._normalize_path(raw)
        if not norm:
            return False
        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]
        new_item = {"line": max(0, int(c.line)), "col": max(0, int(c.col))}
        old_item = self._saved_cursors.get(norm)
        if old_item is not None:
            if self._same_saved_cursor_position(old_item, new_item):
                return True
            if not self._guard_saved_cursor_entry(norm, "remember", quiet=True):
                return False
        self._saved_cursors[norm] = new_item
        self._saved_cursors_authority[norm] = self._current_runtime_authority(kind="editor")
        self._normalize_saved_cursor_authority()
        try:
            self.save_saved_cursors()
        except Exception:
            pass
        return True

    def _restore_cursor_for_buffer(self, eb: EditorBuffer | None) -> bool:
        """Restore one buffer's primary cursor position when available."""

        if eb is None or not bool(self.options.get("savecursor")):
            return False
        raw = str(getattr(eb.buf, "path", "") or "")
        norm = self._normalize_path(raw)
        if not norm:
            return False
        item = self._saved_cursors.get(norm)
        if not isinstance(item, dict):
            return False
        if not self._guard_saved_cursor_entry(norm, "restore", quiet=True):
            return False

        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]
        try:
            line = max(0, int(item.get("line", 0) or 0))
            col = max(0, int(item.get("col", 0) or 0))
        except Exception:
            return False
        max_line = max(0, len(eb.buf.lines) - 1)
        c.line = min(line, max_line)
        try:
            max_col = len(str(eb.buf.lines[c.line]))
        except Exception:
            max_col = 0
        c.col = min(col, max(0, max_col))
        eb.sel_anchors[eb.primary] = None
        self._normalize_cursor_lists(eb)
        return True

    def _project_root_for_path(self, path: str) -> str:
        """Best-effort project root: walk up looking for .git/.hg/.svn/pyproject/etc."""
        raw = str(path or "")
        if not raw:
            return ""
        try:
            p = Path(raw).expanduser().resolve(strict=False)
        except Exception:
            p = Path(raw).expanduser()
        cur = p.parent if p.is_file() else p
        for _ in range(8):
            if not cur:
                break
            try:
                if (cur / '.git').exists() or (cur / '.hg').exists() or (cur / '.svn').exists():
                    return str(cur)
                if (cur / 'pyproject.toml').exists() or (cur / 'package.json').exists() or (cur / 'Cargo.toml').exists():
                    return str(cur)
            except Exception:
                pass
            if cur.parent == cur:
                break
            cur = cur.parent
        return ""

    def _normalize_path(self, path: str) -> str:
        """Best-effort normalize a filesystem path for comparisons/MRUs.

        We keep buffer names stable (what the user typed) but use normalization
        for deduping and matching *the same file* across relative/tilde paths.
        """
        raw = str(path or "")
        if not raw:
            return ""
        p = Path(raw).expanduser()
        try:
            return str(p.resolve(strict=False))
        except Exception:
            return str(p)

    def _normalize_recent_files_authority(self) -> None:
        """Keep recent-file provenance aligned with the MRU register."""

        missing = len(self.recent_files) - len(self.recent_files_authority)
        if missing > 0:
            self.recent_files_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del self.recent_files_authority[len(self.recent_files):]

    def _snapshot_recent_files_authority(self) -> tuple[RuntimeRegistrationAuthority, ...]:
        self._normalize_recent_files_authority()
        return tuple(self._clone_mark_authority(auth) for auth in self.recent_files_authority)

    def _restore_recent_files_authority(
        self,
        snapshot: tuple[RuntimeRegistrationAuthority, ...] | list[RuntimeRegistrationAuthority] | None,
    ) -> None:
        self.recent_files_authority[:] = [self._clone_mark_authority(auth) for auth in list(snapshot or [])]
        self._normalize_recent_files_authority()

    def _remove_recent_file_rows_for_authority(
        self,
        predicate: Callable[[RuntimeRegistrationAuthority], bool],
    ) -> int:
        """Prune recent-file MRU rows whose authority matches *predicate*."""

        self._normalize_recent_files_authority()
        kept_files: list[str] = []
        kept_authority: list[RuntimeRegistrationAuthority] = []
        removed = 0
        for path, authority in zip(list(self.recent_files), list(self.recent_files_authority)):
            auth = self._clone_mark_authority(authority)
            if predicate(auth):
                removed += 1
                continue
            kept_files.append(str(path))
            kept_authority.append(auth)
        self.recent_files[:] = kept_files
        self.recent_files_authority[:] = kept_authority
        self._normalize_recent_files_authority()
        if removed:
            try:
                self.save_recent_files()
            except Exception:
                pass
        return int(removed)

    def remove_recent_files_group(self, group: object) -> int:
        """Remove recent-file rows owned by one runtime group."""

        raw = str(group or "")
        if not raw:
            return 0
        return self._remove_recent_file_rows_for_authority(
            lambda authority: self._authority_group_matches(authority, raw)
        )

    def retag_recent_files_group(self, old: object, new: object) -> int:
        """Retag staged recent-file rows after successful plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        self._normalize_recent_files_authority()
        changed = 0
        for idx, authority in enumerate(list(self.recent_files_authority)):
            auth = self._clone_mark_authority(authority)
            if not self._authority_group_matches(auth, old_s):
                continue
            self.recent_files_authority[idx] = self._authority_with_group(auth, new_s)
            changed += 1
        self._normalize_recent_files_authority()
        return int(changed)

    def remove_plugin_recent_files_generation(
        self,
        plugin_load_root: object,
        plugin_generation: object,
    ) -> int:
        """Remove recent-file rows owned by one unloaded plugin generation."""

        return self._remove_recent_file_rows_for_authority(
            lambda authority: self._authority_matches_plugin_generation(
                authority,
                plugin_load_root=plugin_load_root,
                plugin_generation=plugin_generation,
            )
        )

    def _recent_file_entry_read_allowed(self, index: int) -> bool:
        """Return whether the current runtime authority may read one MRU row."""

        self._normalize_recent_files_authority()
        if not (0 <= int(index) < len(self.recent_files_authority)):
            return True
        decision = recent_access_policy(
            self._current_runtime_authority(kind="editor"),
            self._clone_mark_authority(self.recent_files_authority[int(index)]),
            capability_enabled=self._script_recent_read_capability_enabled(),
        )
        return bool(decision.allowed)

    def visible_recent_files(self) -> list[str]:
        """Return recent file paths visible to the current runtime authority."""

        self._normalize_recent_files_authority()
        return [
            str(path)
            for idx, path in enumerate(list(self.recent_files))
            if self._recent_file_entry_read_allowed(idx)
        ]

    def _visible_recent_file_index_for_path(self, path: str) -> int | None:
        """Return the 1-based visible recent slot for ``path`` when readable."""

        want = self._normalize_path(str(path or ""))
        if not want:
            return None
        visible_slot = 0
        self._normalize_recent_files_authority()
        for idx, raw in enumerate(list(self.recent_files)):
            if not self._recent_file_entry_read_allowed(idx):
                continue
            visible_slot += 1
            if self._normalize_path(str(raw or "")) == want:
                return int(visible_slot)
        return None

    def _guard_recent_file_entry_mutation(self, index: int, action: str) -> None:
        """Raise if current lower-authority code may not erase/reorder a recent row."""

        self._normalize_recent_files_authority()
        if not (0 <= int(index) < len(self.recent_files_authority)):
            return
        if str(action or "") in {"clear", "drop-oldest", "reorder"} and self._script_history_clear_capability_enabled():
            return
        label = str(self.recent_files[int(index)]) if 0 <= int(index) < len(self.recent_files) else ""
        self._guard_runtime_registration_mutation(
            kind="recent-file MRU",
            target=f"{int(index) + 1}:{label}:{action}",
            authority=self._clone_mark_authority(self.recent_files_authority[int(index)]),
            current_kind="editor",
        )

    def _guard_recent_file_range_mutation(self, start: int, end: int, action: str) -> None:
        self._normalize_recent_files_authority()
        lo = max(0, int(start))
        hi = min(len(self.recent_files_authority), int(end))
        for idx in range(lo, hi):
            self._guard_recent_file_entry_mutation(idx, action)

    def _can_update_recent_files(self, existing_index: int | None, drop_indices: list[int]) -> bool:
        """Return whether an incidental MRU update may mutate existing rows.

        Opening/saving a file should not fail merely because a lower-authority
        script is not allowed to reorder a trusted/user MRU entry.  Explicit
        destructive operations such as ``recent clear`` still raise through the
        guard path.
        """

        try:
            if existing_index is not None:
                self._guard_recent_file_entry_mutation(int(existing_index), "reorder")
            for idx in list(drop_indices):
                self._guard_recent_file_entry_mutation(int(idx), "drop-oldest")
        except PermissionError:
            return False
        return True

    def _push_recent_file(self, path: str) -> bool:
        """Insert path into the recent-files MRU (front).

        Recent lists are intentionally tiny and deterministic.  Lower-authority
        scripts may add their own rows, but incidental open/save updates skip
        rather than destroying trusted or other-origin MRU rows.
        """
        raw = str(path or "")
        if raw == "":
            return False
        norm = self._normalize_path(raw)
        if norm == "":
            return False
        self._normalize_recent_files_authority()
        original_files = list(self.recent_files)
        original_authority = self._snapshot_recent_files_authority()

        existing_index: int | None = None
        for i, existing in enumerate(list(self.recent_files)):
            if self._normalize_path(existing) == norm:
                existing_index = int(i)
                break

        projected_original_indices = [
            idx for idx in range(len(self.recent_files)) if existing_index is None or idx != existing_index
        ]
        limit = max(0, int(self._recent_limit))
        # The new/current path occupies projected slot 0.  Slots after the
        # configured limit are original MRU entries that would be dropped.
        drop_indices = projected_original_indices[max(0, limit - 1):] if len(projected_original_indices) + 1 > limit else []
        if not self._can_update_recent_files(existing_index, drop_indices):
            self.recent_files[:] = original_files
            self._restore_recent_files_authority(original_authority)
            return False

        if existing_index is not None:
            del self.recent_files[existing_index]
            del self.recent_files_authority[existing_index]
        self.recent_files.insert(0, raw)
        self.recent_files_authority.insert(0, self._current_runtime_authority(kind="editor"))
        if len(self.recent_files) > int(self._recent_limit):
            self._guard_recent_file_range_mutation(int(self._recent_limit), len(self.recent_files), "drop-oldest")
            self.recent_files[:] = self.recent_files[: int(self._recent_limit)]
            self.recent_files_authority[:] = self.recent_files_authority[: int(self._recent_limit)]

        try:
            self.save_recent_files()
        except Exception:
            pass
        return True

    def clear_recent_files(self) -> int:
        """Clear the MRU register and return how many entries were forgotten."""

        self._guard_recent_file_range_mutation(0, len(self.recent_files), "clear")
        forgotten = len(self.recent_files)
        self.recent_files.clear()
        self.recent_files_authority.clear()
        try:
            self.save_recent_files()
        except Exception:
            pass
        return int(forgotten)


    def _buffer_for_path(self, path: str):
        """Return the open buffer visiting ``path`` when one exists.

        Compare using the same best-effort path normalization already used by the
        recent-file MRU, so inspectable recent inventory stays honest even when
        the same file is spelled differently across relative/tilde/absolute
        paths.
        """

        want = self._normalize_path(str(path or ""))
        if want == "":
            return None
        for name in self.buffer_names():
            eb = self.buffers.get(str(name))
            if eb is None:
                continue
            here = str(getattr(eb.buf, "path", "") or getattr(eb, "name", "") or "")
            if self._normalize_path(here) == want:
                return eb
        return None

    def recent_inventory_rows(self, *, limit: int | None = None) -> list[list[object]]:
        """Return tiny inspectable recent-file inventory rows.

        Rows are ``[index path position active open dirty readonly disk_truth
        action_truth]`` and mirror the richer plain ``recent`` inventory
        instead of forcing scripts or future UIs to reconstruct that surface
        from raw MRU paths or picker grouping rows.

        ``index`` stays 1-based like the plain command, ``position`` is the
        current primary cursor label for still-open buffers, the flag fields are
        ``0`` / ``1`` values matching the visible `*` / `[open]` /
        `[dirty]` / `[readonly]` cues, and the trailing truth fields reuse the
        same tiny `existing file` / `new file` plus `current buffer` /
        `switch buffer` / `empty buffer @ 1:0` dialect already trusted by the
        exact recent-file surfaces.
        """

        xs = self.visible_recent_files()
        if limit is not None:
            xs = xs[: max(0, int(limit))]

        rows: list[list[object]] = []
        active_name = str(self.active or "")
        for idx, raw in enumerate(xs, start=1):
            path = str(raw)
            eb = self._buffer_for_path(path)
            position = ""
            active = 0
            open_flag = 0
            dirty = 0
            readonly = 0
            if eb is not None:
                open_flag = 1
                try:
                    active = 1 if active_name == str(getattr(eb, "name", "") or path) else 0
                except Exception:
                    active = 0
                try:
                    dirty = 1 if bool(getattr(eb.buf, "dirty", False)) else 0
                except Exception:
                    dirty = 0
                try:
                    readonly = 1 if bool(self.is_protected_buffer(eb)) else 0
                except Exception:
                    readonly = 0
                try:
                    self._normalize_cursor_lists(eb)
                    cidx = int(getattr(eb, "primary", 0) or 0)
                    cursors = list(getattr(eb, "cursors", []) or [])
                    if cidx < 0 or cidx >= len(cursors):
                        cidx = 0
                    c = cursors[cidx] if cursors else Cursor(0, 0)
                    position = f"{int(c.line) + 1}:{int(c.col)}"
                except Exception:
                    position = ""
            disk_truth, action_truth = self._recent_file_truth_cues(path)
            rows.append([int(idx), path, position, int(active), int(open_flag), int(dirty), int(readonly), disk_truth, action_truth])
        return rows

    def _recent_prompt_display_row(self, path: str) -> list[str]:
        """Return one richer visible recent-prompt row for ``path``."""

        stored = str(path or "")
        try:
            pp = Path(stored)
            fallback_menu = str(pp.name) if pp.name else "file"
            fallback_info = str(pp.parent) if str(pp.parent) not in (".", "") else ""
        except Exception:
            fallback_menu, fallback_info = "file", ""

        row = self.recent_detail_row(stored)
        if row is None:
            return [stored, "recent", fallback_menu, fallback_info]

        actual = str(row[1]) if len(row) >= 2 else stored
        try:
            index = int(row[2]) if len(row) >= 3 else 0
        except Exception:
            index = 0
        position = str(row[3]) if len(row) >= 4 else ""
        try:
            active = int(row[4]) if len(row) >= 5 else 0
        except Exception:
            active = 0
        try:
            open_flag = int(row[5]) if len(row) >= 6 else 0
        except Exception:
            open_flag = 0
        try:
            dirty = int(row[6]) if len(row) >= 7 else 0
        except Exception:
            dirty = 0
        try:
            readonly = int(row[7]) if len(row) >= 8 else 0
        except Exception:
            readonly = 0
        disk_truth = str(row[10]) if len(row) >= 11 else ""
        action_truth = str(row[11]) if len(row) >= 12 else ""

        try:
            pp = Path(actual)
            menu = str(pp.name) if pp.name else fallback_menu
            info = str(pp.parent) if str(pp.parent) not in (".", "") else ""
        except Exception:
            menu, info = fallback_menu, fallback_info

        if index > 0:
            menu += f" #{index}"
        flags: list[str] = []
        if active:
            flags.append("active")
        elif open_flag:
            flags.append("open")
        if dirty:
            flags.append("dirty")
        if readonly:
            flags.append("readonly")
        if flags:
            menu += " [" + ", ".join(flags) + "]"
        if position and open_flag:
            menu += f" @ {position}"

        info = self._append_palette_action_cue(info, disk_truth)
        info = self._append_palette_action_cue(info, action_truth)
        return [actual, "recent", menu, info]

    def recent_prompt_rows(self) -> list[list[str]]:
        """Base rows for recent-file inventory/grouping: [[path kind menu info] ...]."""
        out: list[list[str]] = []
        for raw in self.visible_recent_files():
            p = str(raw)
            try:
                pp = Path(p)
                menu = str(pp.name) if pp.name else "file"
                info = str(pp.parent) if str(pp.parent) not in (".", "") else ""
            except Exception:
                menu, info = "file", ""
            out.append([p, "recent", menu, info])
        return out

    def _recent_section_label(self, row: list[str], *, by_project: bool = True) -> str:
        """Best-effort visible section label for recent-file rows.

        Recent-file pickers already expose grouped rows headlessly; this helper
        keeps the live prompt, TUI headers, section jumps, preview/status, and
        hostcalls aligned on the same small grouping policy.
        """

        path = str(row[0] if row else "")
        if by_project:
            try:
                root = self._project_root_for_path(path)
            except Exception:
                root = ""
            if root:
                return str(root)
        return self._path_parent_section_label(path, fallback="Recent Files")

    def _recent_section_row(self, row: list[str], *, by_project: bool = True) -> list[str]:
        """Return a recent picker row rewritten for its visible section.

        When a project root is known, make the row a little more scan-friendly by
        showing the project name + path relative to that root, similar to the
        grouped headless hostcall shape.

        Preserve any tiny MRU/action suffix already present on the menu too, so
        project-grouped ``recentpick`` rows do not silently drop recency, live
        state, or cursor-position cues that the adjacent literal recent rows and
        exact ``showrecent`` surface already expose.
        """

        vals = [str(x) for x in list(row[:4])]
        while len(vals) < 4:
            vals.append("")
        if not by_project:
            return vals
        path = str(vals[0])
        root = self._project_root_for_path(path)
        if not root:
            return vals
        try:
            rel = str(Path(path).expanduser().resolve(strict=False).relative_to(Path(root)))
        except Exception:
            rel = str(Path(path).name)
        detail = str(vals[3] or "")
        suffix = ""
        if " | " in detail:
            _head, suffix = detail.split(" | ", 1)
        root_menu = str(Path(root).name or "project")
        menu = str(vals[2] or "")
        menu_suffix = ""
        try:
            base_name = str(Path(path).name or "")
        except Exception:
            base_name = ""
        if base_name and menu.startswith(base_name):
            menu_suffix = menu[len(base_name) :]
        vals[2] = root_menu + menu_suffix
        vals[3] = rel
        if suffix:
            vals[3] += f" | {suffix}"
        return vals

    def _recent_section_rows(self, query: str = "", *, limit: int | None = None, by_project: bool = True, rich: bool = False) -> list[list[object]]:
        """Group recent-file rows by visible section label.

        Groups preserve the first-seen section order from the MRU/apropos row
        stream so recent-file pickers stay recency-friendly instead of sorting
        buckets alphabetically.
        """

        rows = self.recent_apropos_rows(query, limit=limit)
        buckets: dict[str, list[list[str]]] = {}
        order: list[str] = []
        for row in rows:
            vals = [str(x) for x in row[:4]]
            while len(vals) < 4:
                vals.append("")
            label = self._recent_section_label(vals, by_project=by_project)
            if label not in buckets:
                buckets[label] = []
                order.append(label)
            display_vals = self._recent_prompt_display_row(vals[0]) if rich else vals
            buckets[label].append(self._recent_section_row(display_vals, by_project=by_project))
        return [[label, buckets[label]] for label in order]

    def recent_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.recent_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows
        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._buffer_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))
        scored.sort(key=lambda item: (item[0], item[1]))
        out2 = [row for _k, _idx, row in scored]
        return out2[:limit] if limit is not None else out2

    def recent_section_rows_by_dir(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group recent file rows into directory sections."""
        return self._recent_section_rows(query, limit=limit, by_project=False)

    def recent_section_rows_by_project(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group recent file rows into project-root sections (Helix-style)."""
        return self._recent_section_rows(query, limit=limit, by_project=True)

    def _recent_section_summary_rows(
        self,
        query: str = "",
        *,
        limit: int | None = None,
        by_project: bool = True,
    ) -> list[list[object]]:
        """Return recent-group summaries using the same visible sample-row dialect.

        Broad recent-bucket inspectors should not fall back to raw `path —
        parent` examples when the adjacent picker rows already carry richer MRU
        and live-buffer truth. Keep the shared `[label count sample_name
        sample_detail]` shape, but let the sample fields reuse the first
        visible grouped recent row instead of a flattened raw path echo.
        """

        sections = self._recent_section_rows(query, limit=limit, by_project=by_project, rich=True)
        out: list[list[object]] = []
        for sec in sections:
            label = str(sec[0] if sec else "")
            items = list(sec[1] if len(sec) > 1 else [])
            if not label or not items:
                continue
            sample = [str(x) for x in list(items[0][:4])]
            while len(sample) < 4:
                sample.append("")
            raw_visible = self._recent_prompt_display_row(sample[0])
            sample_name = str(raw_visible[2] if len(raw_visible) >= 3 else sample[2] or sample[0])
            try:
                sample_basename = str(Path(str(sample[0] or "")).name or "")
            except Exception:
                sample_basename = ""
            sample_detail = self._trim_leading_location_echo(str(sample[3] or ""), label, sample_basename)
            out.append([label, len(items), sample_name, sample_detail])
        return out

    def recent_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware project-grouped recent-file section summaries."""
        return self._recent_section_summary_rows(query, limit=limit, by_project=True)

    def recent_dir_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return tiny count-aware directory-grouped recent-file section summaries."""
        return self._recent_section_summary_rows(query, limit=limit, by_project=False)

    def recent_dir_names(self) -> list[str]:
        """Return visible recent-directory bucket labels in first-seen MRU order."""

        out: list[str] = []
        seen: set[str] = set()
        for row in self.recent_prompt_rows():
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            label = self._recent_section_label(vals, by_project=False)
            if label in seen:
                continue
            seen.add(label)
            out.append(str(label))
        return out

    def _normalize_recent_dir_query(self, query: str) -> str:
        raw = str(query or "").strip()
        if raw == "":
            return ""
        if raw.casefold() == "recent files":
            return "recent files"
        return str(self._normalize_path(raw) or raw)

    def _recent_dir_detail_row_for_label(self, query: str) -> list[object] | None:
        """Return one tiny exact recent-directory row for a visible bucket label."""

        raw_query = str(query or "")
        want = self._normalize_recent_dir_query(raw_query)
        if want == "":
            return None

        rows = self.recent_section_rows_by_dir("")
        for section in rows:
            if not isinstance(section, list) or len(section) < 2:
                continue
            label = str(section[0] or "")
            if self._normalize_recent_dir_query(label) != want:
                continue
            items = list(section[1] or [])
            count = len(items)
            sample_path = ""
            sample_detail = ""
            sample_menu = ""
            sample_info = ""
            active_count = 0
            open_count = 0
            dirty_count = 0
            readonly_count = 0
            if items:
                first = [str(x) for x in list(items[0][:4])]
                while len(first) < 4:
                    first.append("")
                sample_path = str(first[0])
                sample_detail = str(first[3])
                rich_first = self._recent_prompt_display_row(sample_path)
                if rich_first:
                    sample_menu = str(rich_first[2]) if len(rich_first) >= 3 else ""
                    sample_info = str(rich_first[3]) if len(rich_first) >= 4 else ""
            for item in items:
                vals = [str(x) for x in list(item[:4])]
                while len(vals) < 4:
                    vals.append("")
                path = str(vals[0])
                eb = self._buffer_for_path(path)
                if eb is None:
                    continue
                open_count += 1
                try:
                    if str(self.active or "") == str(getattr(eb, "name", "") or path):
                        active_count += 1
                except Exception:
                    pass
                try:
                    if bool(getattr(eb.buf, "dirty", False)):
                        dirty_count += 1
                except Exception:
                    pass
                try:
                    if bool(self.is_protected_buffer(eb)):
                        readonly_count += 1
                except Exception:
                    pass
            return [
                raw_query,
                label,
                int(count),
                int(active_count),
                int(open_count),
                int(dirty_count),
                int(readonly_count),
                sample_path,
                sample_detail,
                sample_menu,
                sample_info,
            ]
        return None

    def recent_dir_detail_row(self, query: str) -> list[object] | None:
        """Return one tiny exact recent-directory row.

        This gives scripts/future UIs the same first-stop side-effect-free
        answer plain ``showrecentdir DIR`` gives humans, instead of forcing
        them to reopen grouped ``recentdirpick`` state or infer counts back out
        of broad summary text.
        """

        return self._recent_dir_detail_row_for_label(str(query))

    def recent_dir_detail_row_by_index(self, index: object) -> list[object] | None:
        """Return one exact recent-directory row addressed by visible MRU slot.

        Recent-facing rows already advertise one file as ``#N``. This sibling
        keeps the adjacent exact recent-directory inspection path aligned with
        that visible slot truth instead of forcing callers to reopen one recent
        file first just to recover its parent directory label.
        """

        slot = self.parse_recent_slot_token(index)
        if slot is None:
            return None
        row = self.recent_detail_row_by_index(slot)
        if row is None:
            return None
        try:
            actual = str(row[1]) if len(row) >= 2 else ""
        except Exception:
            actual = ""
        if not actual:
            return None
        label = self._path_parent_section_label(actual, fallback="Recent Files")
        detail = self._recent_dir_detail_row_for_label(label)
        if detail is None:
            return None
        vals = list(detail)
        if vals:
            vals[0] = slot
        return vals

    def _recent_detail_row_for_path(self, path: str) -> list[object] | None:
        """Return one tiny exact recent-file row for ``path`` when present.

        Matching follows the same best-effort path normalization already used by
        recent-file MRU dedupe so callers can ask about the same file using
        relative, tilde, or absolute spellings without scraping the full
        ``recent`` inventory or reopening picker state.
        """

        query = str(path or "")
        want = self._normalize_path(query)
        if want == "":
            return None

        index = 0
        stored = ""
        visible_index = 0
        self._normalize_recent_files_authority()
        for raw_index, raw in enumerate(list(self.recent_files)):
            if not self._recent_file_entry_read_allowed(raw_index):
                continue
            visible_index += 1
            here = str(raw or "")
            if self._normalize_path(here) == want:
                index = int(visible_index)
                stored = here
                break
        if index <= 0 or stored == "":
            return None

        eb = self._buffer_for_path(stored)
        position = ""
        active = 0
        open_flag = 0
        dirty = 0
        readonly = 0
        if eb is not None:
            open_flag = 1
            try:
                active = 1 if str(self.active or "") == str(getattr(eb, "name", "") or stored) else 0
            except Exception:
                active = 0
            try:
                dirty = 1 if bool(getattr(eb.buf, "dirty", False)) else 0
            except Exception:
                dirty = 0
            try:
                readonly = 1 if bool(self.is_protected_buffer(eb)) else 0
            except Exception:
                readonly = 0
            try:
                self._normalize_cursor_lists(eb)
                cidx = int(getattr(eb, "primary", 0) or 0)
                cursors = list(getattr(eb, "cursors", []) or [])
                if cidx < 0 or cidx >= len(cursors):
                    cidx = 0
                c = cursors[cidx] if cursors else Cursor(0, 0)
                position = f"{int(c.line) + 1}:{int(c.col)}"
            except Exception:
                position = ""

        try:
            root = self._project_root_for_path(stored)
        except Exception:
            root = ""
        if root:
            section = str(root)
            try:
                detail = str(Path(stored).expanduser().resolve(strict=False).relative_to(Path(root)))
            except Exception:
                detail = str(Path(stored).name)
        else:
            section = self._path_parent_section_label(stored, fallback="Recent Files")
            detail = str(Path(stored).name)

        disk_truth, action_truth = self._recent_file_truth_cues(stored)

        return [
            query,
            stored,
            int(index),
            position,
            int(active),
            int(open_flag),
            int(dirty),
            int(readonly),
            str(section),
            str(detail),
            str(disk_truth),
            str(action_truth),
        ]

    def recent_detail_row(self, path: str) -> list[object] | None:
        """Return one tiny exact recent-file row.

        This gives scripts/future UIs the same first-stop side-effect-free
        answer plain ``showrecent PATH`` gives humans, instead of forcing them
        to scrape ``recent`` inventory text or reopen grouped picker state.
        """

        return self._recent_detail_row_for_path(str(path))

    def parse_visible_index_token(self, value: object) -> int | None:
        """Return one 1-based visible index from ``N`` or ``#N``.

        Several human-facing inventory/register surfaces already print entries
        as ``#N`` while adjacent command and host surfaces historically
        accepted only bare integers. Accepting either shape keeps the visible
        dialect and the headless scripting surface aligned instead of forcing
        callers to strip one tiny prefix before asking for exact truth.
        """

        try:
            raw = str(value).strip()
        except Exception:
            return None
        if not raw:
            return None
        if raw.startswith("#"):
            raw = raw[1:].strip()
        if not raw:
            return None
        try:
            index = int(raw, 10)
        except Exception:
            return None
        return index if index > 0 else None

    def parse_recent_slot_token(self, value: object) -> int | None:
        """Return one visible recent slot from ``N`` or ``#N``.

        Recent-facing rows already tend to print slot identity as ``#N`` while
        the command and host surfaces historically accepted only bare integers.
        Accepting either shape keeps the human-facing dialect and the headless
        scripting surface aligned instead of forcing callers to strip one tiny
        prefix before asking for exact recent-file truth.
        """

        return self.parse_visible_index_token(value)

    def recent_detail_row_by_index(self, index: object) -> list[object] | None:
        """Return one tiny exact recent-file row addressed by 1-based MRU slot.

        Plain ``recent`` and picker feedback already use stable visible slot
        numbers. This sibling keeps that numbered recent-file truth directly
        inspectable without requiring scripts or humans to translate one slot
        back into a path first.
        """

        slot = self.parse_recent_slot_token(index)
        if slot is None:
            return None
        xs = self.visible_recent_files()
        if slot > len(xs):
            return None
        row = self._recent_detail_row_for_path(xs[slot - 1])
        if row is None:
            return None
        vals = list(row)
        if vals:
            vals[0] = slot
        return vals

    def format_recent_picker_feedback(self, label: str, path: str, *, selected_index: int = 0) -> str:
        """Return tiny picker-open feedback for one chosen recent-file target.

        Dedicated recent-file pickers already know that the selected target came
        from recent state rather than an arbitrary raw ``open``. Keep that same
        recent-aware dialect visible after Enter instead of falling back to a
        generic open message that forgets the picker route.

        Prefer the pre-submit MRU slot when one chosen picker target already had
        a live numbered row. Picker submits reopen files, which naturally bumps
        them to the front of the MRU list; using the post-open slot would make a
        row selected as ``#3`` immediately report back as ``#1``. Keeping the
        chosen slot visible makes the final message line up with the row the
        human or future LLM actually selected.
        """

        head = str(label or '').strip() or 'recentpick'
        row = self.recent_detail_row(str(path))
        index = 0
        try:
            index = max(0, int(selected_index or 0))
        except Exception:
            index = 0
        if index <= 0 and row is not None:
            try:
                index = int(row[2]) if len(row) >= 3 else 0
            except Exception:
                index = 0
        if index > 0:
            head += f" #{index}"
        msg = f"{head} -> {self.format_cursor_target()}"
        if row is None:
            return msg
        disk_truth = str(row[10]) if len(row) >= 11 else ""
        action_truth = str(row[11]) if len(row) >= 12 else ""
        extras = [part for part in (disk_truth, action_truth) if str(part).strip()]
        if extras:
            msg += " | " + " | ".join(str(part) for part in extras)
        return msg

    def _format_jump_detail_head(self, detail_row: list[object] | None) -> str:
        """Return a tiny stable visible-slot/lane prefix for one jump detail row."""

        row = list(detail_row) if isinstance(detail_row, list) else None
        if row is None:
            return ""
        try:
            index = int(row[1]) if len(row) >= 2 else 0
        except Exception:
            index = 0
        lane = str(row[2]) if len(row) >= 3 else ''
        try:
            depth = int(row[3]) if len(row) >= 4 else 0
        except Exception:
            depth = 0
        shown = str(row[0]) if row else ''
        visible = {str(index)} if index > 0 else set()
        if index > 0:
            visible.add(f"#{index}")
        if shown not in visible and index > 0:
            shown = f"#{index}"
        head = shown
        tag = lane or 'jump'
        if lane == 'current':
            tag = 'current'
        elif depth > 0:
            tag = f"{lane} {depth}"
        if tag:
            head = f"{head} [{tag}]" if head else f"[{tag}]"
        return str(head).strip()

    def _format_jump_navigation_brief(self, detail_row: list[object] | None) -> str:
        """Return a tiny ``#N [lane depth] buffer @ line:col`` jumplist summary."""

        row = list(detail_row) if isinstance(detail_row, list) else None
        if row is None:
            return ""
        head = self._format_jump_detail_head(row)
        name = str(row[4]) if len(row) >= 5 else ''
        position = str(row[5]) if len(row) >= 6 else ''
        parts = [part for part in (head, name) if str(part).strip()]
        msg = " ".join(str(part) for part in parts if str(part).strip())
        if position:
            msg = f"{msg} @ {position}" if msg else f"@ {position}"
        return str(msg).strip()

    def jump_navigation_model(self) -> dict[str, Any]:
        """Return a tiny structured jumplist-navigation snapshot.

        Jumplist feedback is now typed and truthful at command/action time, but
        future UIs, scripts, tests, and LLMs should not have to scrape the last
        transient message just to answer whether ``jumpback`` / ``jumpforward``
        are actionable or which visible slot is current.
        """

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        n = int(len(eb.jump_list))
        cur_i = int(eb.jump_index)
        current_row = self.jump_detail_row(f"#{cur_i + 1}") if n > 0 and 0 <= cur_i < n else None
        back_count = max(0, cur_i) if current_row is not None else 0
        forward_count = max(0, n - cur_i - 1) if current_row is not None else 0
        back_row = self.jump_detail_row(f"#{cur_i}") if back_count > 0 else None
        forward_row = self.jump_detail_row(f"#{cur_i + 2}") if forward_count > 0 else None

        def _row_fields(prefix: str, row: list[object] | None, *, count: int = 0, command: str = "") -> dict[str, Any]:
            out: dict[str, Any] = {}
            available = row is not None
            try:
                index = int(row[1]) if row is not None and len(row) >= 2 else 0
            except Exception:
                index = 0
            lane = str(row[2]) if row is not None and len(row) >= 3 else ''
            try:
                depth = int(row[3]) if row is not None and len(row) >= 4 else 0
            except Exception:
                depth = 0
            target = str(row[4]) if row is not None and len(row) >= 5 else ''
            position = str(row[5]) if row is not None and len(row) >= 6 else ''
            preview = str(row[6]) if row is not None and len(row) >= 7 else ''
            slot = f"#{index}" if index > 0 else ''
            out[f"{prefix}_available"] = 1 if available else 0
            out[f"{prefix}_index"] = int(index)
            out[f"{prefix}_slot"] = str(slot)
            out[f"{prefix}_lane"] = str(lane)
            out[f"{prefix}_depth"] = int(depth)
            out[f"{prefix}_target"] = str(target)
            out[f"{prefix}_position"] = str(position)
            out[f"{prefix}_preview"] = str(preview)
            if prefix in ('jump_back', 'jump_forward'):
                out[f"{prefix}_count"] = int(max(0, int(count)))
                out[f"{prefix}_command"] = str(command if available else '')
            return out

        summary = self._format_jump_navigation_brief(current_row)
        if back_row is not None:
            tail = self._format_jump_navigation_brief(back_row)
            summary = f"{summary} <- {tail} (+{back_count})" if summary else f"{tail} (+{back_count})"
        if forward_row is not None:
            tail = self._format_jump_navigation_brief(forward_row)
            summary = f"{summary} -> {tail} (+{forward_count})" if summary else f"{tail} (+{forward_count})"

        actions: list[str] = []
        if back_row is not None:
            actions.append('jumpback')
        if forward_row is not None:
            actions.append('jumpforward')

        out: dict[str, Any] = {
            'jump_navigation_available': 1 if current_row is not None else 0,
            'jump_entry_count': int(n if current_row is not None else 0),
            'jump_navigation_scope': 'buffer',
            'jump_navigation_persisted': 0,
            'jump_navigation_summary': str(summary),
            'jump_navigation_actions': list(actions),
            'jump_navigation_action_summary': ', '.join(actions),
        }
        out.update(_row_fields('jump_current', current_row))
        out.update(_row_fields('jump_back', back_row, count=back_count, command='jumpback'))
        out.update(_row_fields('jump_forward', forward_row, count=forward_count, command='jumpforward'))
        return out

    def format_jump_picker_feedback(
        self,
        label: str,
        target: str,
        *,
        detail_row: list[object] | None = None,
    ) -> str:
        """Return tiny picker-jump feedback for one chosen visible jump slot.

        Dedicated jumplist pickers already know the chosen visible slot before
        they mutate history. Keep that exact slot/lane truth visible after Enter
        instead of falling back to the generic ``jump: ...`` message that hides
        which picker row actually ran.

        Prefer the pre-submit exact row when one typed or selected target was
        already known, because jumping naturally reshapes current/back/forward
        lanes. Recomputing after the jump could turn a chosen ``#2 [back 1]``
        row into ``#2 [current]`` even though the human or future LLM selected
        the former.
        """

        head = str(label or '').strip() or 'jumppick'
        row = list(detail_row) if isinstance(detail_row, list) else None
        if row is None:
            row = self.jump_detail_row(str(target))
        if row is None:
            return f"{head} -> {self.format_cursor_target()}"
        detail = self._format_jump_detail_head(row)
        if detail:
            head += f" {detail}"
        return f"{head} -> {self.format_cursor_target()}"

    # ----- docs/help buffers -----
    def clear_docs_root_cache(self) -> None:
        """Forget the cached docs-root path after cwd/env-sensitive changes."""

        for attr in ('_docs_root_cache_key', '_docs_root_cache_path'):
            if hasattr(self, attr):
                try:
                    delattr(self, attr)
                except Exception:
                    pass

    def docs_root(self) -> Path:
        """Return the docs root directory (best-effort).

        The default docs root is cwd-relative, but asking ``Path.cwd()`` in every
        completion probe can dominate hot prompt paths in slow cloud filesystems.
        Cache by the raw ``MICROMAX_DOCS`` value; the built-in ``cd`` command and
        explicit docs refresh clear this cache.
        """

        raw_env = os.environ.get("MICROMAX_DOCS")
        raw = str(raw_env) if raw_env is not None else "<default>"
        cached_key = getattr(self, '_docs_root_cache_key', None)
        cached_path = getattr(self, '_docs_root_cache_path', None)
        if cached_key == raw and isinstance(cached_path, Path):
            return cached_path
        try:
            cwd = Path(os.getcwd())
        except Exception:
            cwd = None
        root = docs_root_from_env(raw_env, cwd=cwd)
        self._docs_root_cache_key = raw
        self._docs_root_cache_path = root
        return root

    def _scan_docs(self) -> list[dict[str, str]]:
        """Return a small docs index as a list of dicts.

        Each entry contains: topic, path, title, summary. Filesystem scanning
        and process-local caching live in ``micromax_editor.docs_index``; this
        wrapper keeps the editor's instance-local copy and heading semantics.
        """

        root = self.docs_root()
        root_token = docs_root_cache_token(root)
        cache_root = getattr(self, '_scan_docs_cache_root', None)
        cache_rows = getattr(self, '_scan_docs_cache_rows', None)
        if cache_root == root_token and isinstance(cache_rows, list):
            return [dict(row) for row in cache_rows]

        out = scan_docs(root, heading_scan=self._md_heading_scan)
        self._scan_docs_cache_root = root_token
        self._scan_docs_cache_rows = [dict(row) for row in out]
        return [dict(row) for row in out]

    def refresh_docs_cache(self) -> None:
        """Clear docs catalog/prompt caches for this editor and process."""

        clear_docs_scan_cache()
        for attr in (
            '_docs_root_cache_key',
            '_docs_root_cache_path',
            '_scan_docs_cache_root',
            '_scan_docs_cache_rows',
            '_docs_catalog_cache_key',
            '_docs_catalog_cache',
            '_doc_prompt_rows_cache_root',
            '_doc_prompt_rows_cache_rows',
            '_doc_section_labels',
            '_doc_section_label_ranks',
            '_doc_detail_rows_by_topic',
            '_doc_detail_rows_by_norm_path',
        ):
            if hasattr(self, attr):
                try:
                    delattr(self, attr)
                except Exception:
                    pass

    def _docs_catalog(self) -> dict[str, dict[str, str]]:
        """Return a tiny cached docs catalog keyed by common target spellings."""

        root_token = docs_root_cache_token(self.docs_root())
        cache_key = getattr(self, "_docs_catalog_cache_key", None)
        cache = getattr(self, "_docs_catalog_cache", None)
        if cache_key == root_token and isinstance(cache, dict):
            return {str(k): dict(v) for k, v in cache.items()}

        out = build_docs_catalog(self._scan_docs())
        self._docs_catalog_cache_key = root_token
        self._docs_catalog_cache = {str(k): dict(v) for k, v in out.items()}
        return {str(k): dict(v) for k, v in out.items()}

    def _help_doc_title_for_target(self, doc: str) -> str:
        """Resolve a docs target like ``94-softwrap.md`` to a human title."""

        raw = unquote(str(doc or "").strip())
        if not raw:
            return ""

        entry = self._docs_catalog().get(raw.casefold())
        if entry is not None:
            return str(entry.get("title", "") or "")

        path = self.find_doc_path(raw)
        if path:
            entry2 = self._docs_catalog().get(str(path).casefold())
            if entry2 is not None:
                return str(entry2.get("title", "") or "")
        return ""

    def _help_heading_titles_by_fragment(self) -> dict[str, str]:
        """Return current help-buffer heading titles keyed by resolved fragment."""

        topic = self.current_help_doc_topic()
        if not topic:
            return {}
        eb = self.cur()
        nlines = len(eb.buf.lines)
        if (
            topic == self._help_heading_title_cache_topic
            and nlines == self._help_heading_title_cache_nlines
        ):
            return dict(self._help_heading_title_cache)

        out: dict[str, str] = {}
        for _line0, _level, title, frag, _col0 in self._md_heading_entries(eb.buf.lines):
            f = str(frag or "").strip()
            if f:
                out.setdefault(f, str(title or ""))

        self._help_heading_title_cache_topic = str(topic)
        self._help_heading_title_cache_nlines = int(nlines)
        self._help_heading_title_cache = dict(out)
        return dict(out)

    def _help_doc_heading_titles_for_target(self, doc: str) -> dict[str, str]:
        """Resolve a docs target to ``{fragment: title}`` heading metadata."""

        raw = unquote(str(doc or "").strip())
        if not raw:
            return self._help_heading_titles_by_fragment()

        entry = self._docs_catalog().get(raw.casefold())
        path = str(entry.get("path", "") or "") if entry is not None else ""
        if not path:
            path = self.find_doc_path(raw) or ""
        if not path:
            return {}
        key = self._normalize_path(path) or str(path)
        cache = getattr(self, "_docs_heading_title_cache", {})
        if key in cache:
            return dict(cache[key])

        out: dict[str, str] = {}
        try:
            lines = Path(path).read_text(encoding="utf-8").splitlines()
            for _line0, _level, title, frag, _col0 in self._md_heading_entries(lines):
                f = str(frag or "").strip()
                if f:
                    out.setdefault(f, str(title or ""))
        except Exception:
            out = {}

        cache[key] = dict(out)
        self._docs_heading_title_cache = cache
        return dict(out)

    def _doc_section_info_for_path(self, path: str) -> tuple[int, str]:
        """Best-effort visible section label for a docs path."""

        return doc_section_info_for_path(path)

    def _doc_section_label(self, row: list[str]) -> str:
        topic = str(row[0] if row else "")
        cache = getattr(self, "_doc_section_labels", {})
        if topic and topic in cache:
            return str(cache[topic])
        path = self.find_doc_path(topic) if topic else None
        if path:
            return str(self._doc_section_info_for_path(path)[1])
        return "Docs"

    def _doc_section_label_rank(self, label: str) -> tuple[int, str]:
        ranks = getattr(self, "_doc_section_label_ranks", {})
        if label in ranks:
            return (int(ranks[label]), str(label).casefold())
        return (999, str(label).casefold())

    def doc_prompt_rows(self) -> list[list[str]]:
        """Rows for docs picker: [[topic kind menu info] ...]."""

        root = self.docs_root()
        root_token = docs_root_cache_token(root)
        cached_root = getattr(self, '_doc_prompt_rows_cache_root', None)
        cached_rows = getattr(self, '_doc_prompt_rows_cache_rows', None)
        if cached_root == root_token and isinstance(cached_rows, list):
            return [list(row) for row in cached_rows]

        model = build_doc_prompt_state(self._scan_docs(), normalize_path=self._normalize_path)
        self._doc_section_labels = dict(model.section_labels)
        self._doc_section_label_ranks = dict(model.section_ranks)
        self._doc_detail_rows_by_topic = {
            key: list(value) for key, value in model.detail_rows_by_topic.items()
        }
        self._doc_detail_rows_by_norm_path = {
            key: list(value) for key, value in model.detail_rows_by_norm_path.items()
        }
        out = [list(row) for row in model.rows]
        self._doc_prompt_rows_cache_root = root_token
        self._doc_prompt_rows_cache_rows = [list(row) for row in out]
        return [list(row) for row in out]

    def doc_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Group docs picker rows by their numbered docs family."""
        rows = self.doc_apropos_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self._doc_section_label,
            label_sort_key=self._doc_section_label_rank,
        )

    def doc_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        return self._section_summary_rows(
            self.doc_section_rows(query, limit=limit),
            sample_detail_fn=self._section_summary_prompt_row_detail,
        )

    def doc_apropos_rows(self, query: str, *, limit: int | None = None) -> list[list[str]]:
        q = str(query or "").strip()
        rows = self.doc_prompt_rows()
        if q == "":
            return rows[:limit] if limit is not None else rows

        scored: list[tuple[RowSortKey, int, list[str]]] = []
        for idx, row in enumerate(rows):
            key = self._apropos_row_sort_key(row, q)
            if key is None:
                continue
            scored.append((key, idx, [str(x) for x in row]))
        scored.sort(key=lambda item: (item[0], item[1]))
        out2 = [row for _k, _idx, row in scored]
        return out2[:limit] if limit is not None else out2

    def _contained_doc_path_from_explicit_target(
        self, raw: str, *, allow_outside_root: bool = False
    ) -> str | None:
        """Resolve an explicit docs path, normally without escaping docs root.

        Help/docs navigation is a documentation surface, not a general file-open
        or file-read surface. Topic names still resolve through the docs catalog
        below, but path-like spellings from scripts and editor commands are only
        accepted when the final resolved markdown file remains inside
        ``docs_root()``. The headless CLI can opt into ``allow_outside_root``
        for user-supplied fixture/docs paths without widening script hostcall
        authority.
        """

        value = unquote(str(raw or "").strip())
        if not value:
            return None
        if not (value.endswith(".md") or ("/" in value) or ("\\" in value)):
            return None

        try:
            root = self.docs_root().resolve(strict=False)
        except Exception:
            root = self.docs_root()

        src = Path(value).expanduser()
        candidates: list[Path] = []
        if src.is_absolute():
            candidates.append(src)
        else:
            # Prefer docs-root-relative paths like ``94-softwrap.md`` while
            # preserving the common repo-root spelling ``docs/94-softwrap.md``.
            candidates.append(self.docs_root() / src)
            if src.parts and str(src.parts[0]).casefold() == "docs" and len(src.parts) > 1:
                candidates.append(self.docs_root() / Path(*src.parts[1:]))
            try:
                candidates.append(Path.cwd() / src)
            except Exception:
                pass

        seen: set[str] = set()
        for cand in candidates:
            try:
                resolved = cand.resolve(strict=True)
            except Exception:
                continue
            key = str(resolved)
            if key in seen:
                continue
            seen.add(key)
            if resolved.suffix.casefold() != ".md":
                continue
            try:
                if not resolved.is_file():
                    continue
            except Exception:
                continue
            if not allow_outside_root:
                try:
                    resolved.relative_to(root)
                except ValueError:
                    continue
            return str(resolved)
        return None

    def find_doc_path(self, topic_or_path: str, *, allow_outside_root: bool = False) -> str | None:
        """Resolve a docs topic (or docs-contained markdown path).

        ``allow_outside_root`` is reserved for trusted CLI entry points that are
        handed an explicit path by the user. Editor commands and script hostcalls
        keep the safer docs-root containment default.
        """

        raw = str(topic_or_path or "").strip()
        if not raw:
            return None

        explicit = self._contained_doc_path_from_explicit_target(
            raw, allow_outside_root=allow_outside_root
        )
        if explicit:
            return explicit

        want = raw.casefold()
        for ent in self._scan_docs():
            topic = str(ent.get("topic", ""))
            stem = Path(str(ent.get("path", ""))).stem
            if want in {topic.casefold(), stem.casefold()}:
                return str(ent.get("path"))
        return None

    def open_help_doc(
        self, topic: str, *, push_stack: bool = True, allow_outside_root: bool = False
    ) -> bool:
        """Open a docs markdown file into a protected read-only help buffer.

        By default this remains docs-root contained. The CLI may pass
        ``allow_outside_root=True`` for explicit user-provided markdown paths.
        """

        path = self.find_doc_path(topic, allow_outside_root=allow_outside_root)
        if not path:
            return False

        p = Path(path)
        stem = p.stem
        slug = re.sub(r"^\d+\-", "", stem)
        name = f"help:{slug or stem}"
        new_help = str(slug or stem)
        restore_entry: dict[str, Any] | None = None
        replay_entry: dict[str, Any] | None = None
        replay_lane = ""
        replay_authority: RuntimeRegistrationAuthority | None = None
        cur_entry: dict[str, Any] | None = None
        cur_authority: RuntimeRegistrationAuthority = RuntimeRegistrationAuthority(script_context=False)

        # Help navigation: when switching to a different docs topic, push the
        # current local docs target. That source can be the visible help page or
        # a dormant session-local help target when we branch from outside the
        # help buffer. When the topic is unchanged but only dormant, reopening it
        # should still bridge back to the same remembered landing instead of
        # silently resetting to the top just because the old help buffer closed.
        #
        # If the requested docs topic already matches the immediate back or
        # forward target, reuse that adjacent local history step instead of
        # treating the open as a brand-new branch. This keeps explicit `help
        # docs TOPIC` / `help TOPIC` opens in sync with the tiny browser-like
        # replay loop without guessing across ambiguous deeper history.
        if bool(push_stack):
            cur_entry = self._help_navigation_source_entry()
            cur_authority = self._help_current_authority()
            cur_help = self._help_history_topic(cur_entry) if cur_entry is not None else ""
            active_entry = self._current_help_history_entry()
            can_reuse_adjacent = bool(cur_entry is not None and cur_help and new_help and cur_help != new_help)
            back_tail = self._help_stack[-1] if self._help_stack else None
            forward_tail = self._help_forward_stack[-1] if self._help_forward_stack else None
            back_match = bool(can_reuse_adjacent and self._help_history_topic(back_tail) == new_help)
            forward_match = bool(can_reuse_adjacent and self._help_history_topic(forward_tail) == new_help)
            if back_match and not forward_match and back_tail is not None and self._help_history_resolvable(back_tail):
                replay_entry = back_tail
                replay_lane = "back"
                self._normalize_help_history_authority()
                if self._help_stack_authority:
                    replay_authority = self._clone_mark_authority(self._help_stack_authority[-1])
                    self._guard_help_history_authority(replay_authority, lane="back", action="replay")
            elif forward_match and not back_match and forward_tail is not None and self._help_history_resolvable(forward_tail):
                replay_entry = forward_tail
                replay_lane = "forward"
                self._normalize_help_history_authority()
                if self._help_forward_stack_authority:
                    replay_authority = self._clone_mark_authority(self._help_forward_stack_authority[-1])
                    self._guard_help_history_authority(replay_authority, lane="forward", action="replay")
            else:
                if new_help and cur_help != new_help and self._help_forward_stack:
                    self._clear_help_history_stack("forward", "clear-forward")
                if cur_help and cur_help != new_help:
                    self._push_help_history(
                        "back",
                        cur_entry if cur_entry is not None else cur_help,
                        authority=cur_authority,
                    )
                elif cur_entry is not None and active_entry is None and cur_help == new_help:
                    restore_entry = cur_entry

        # If already open (by normalized path), just switch to it.
        target_norm = self._normalize_path(str(p))
        if target_norm:
            for bname, eb in self.buffers.items():
                if eb.buf.path and self._normalize_path(str(eb.buf.path)) == target_norm:
                    self.switch_buffer(bname)
                    # Mark as protected in case it was opened via `open`.
                    try:
                        self.cur().local_options["readonly"] = True
                        self.cur().local_options["help_doc"] = str(slug or stem)
                    except Exception:
                        pass
                    if replay_entry is not None and replay_lane:
                        if replay_lane == "back":
                            _entry, replay_authority = self._pop_help_history_stack_tail("back", "replay")
                            if cur_entry is not None:
                                self._push_help_history("forward", cur_entry, authority=cur_authority)
                        elif replay_lane == "forward":
                            _entry, replay_authority = self._pop_help_history_stack_tail("forward", "replay")
                            if cur_entry is not None:
                                self._push_help_history("back", cur_entry, authority=cur_authority)
                        self._restore_help_history_entry(replay_entry, authority=replay_authority)
                    elif restore_entry is not None:
                        self._restore_help_history_entry(restore_entry, authority=cur_authority)
                    else:
                        self._remember_help_session_entry()
                    return True

        try:
            text = p.read_text(encoding="utf-8")
        except Exception as e:
            self.message(f"help: {e}")
            return False

        self.new_buffer(name=name, text=text, path=str(p))
        try:
            eb2 = self.cur()
            eb2.local_options["readonly"] = True
            eb2.local_options["help_doc"] = str(slug or stem)
            eb2.buf.mark_clean()
        except Exception:
            pass
        if replay_entry is not None and replay_lane:
            if replay_lane == "back":
                _entry, replay_authority = self._pop_help_history_stack_tail("back", "replay")
                if cur_entry is not None:
                    self._push_help_history("forward", cur_entry, authority=cur_authority)
            elif replay_lane == "forward":
                _entry, replay_authority = self._pop_help_history_stack_tail("forward", "replay")
                if cur_entry is not None:
                    self._push_help_history("back", cur_entry, authority=cur_authority)
            self._restore_help_history_entry(replay_entry, authority=replay_authority)
        elif restore_entry is not None:
            self._restore_help_history_entry(restore_entry, authority=cur_authority)
        else:
            self._remember_help_session_entry()
        return True

    def refresh_capabilities(self) -> None:
        """Refresh capability feature advertisement based on current options."""

        refresh_vm_features(self, self.vm)

    def check_external_url(self, url: object) -> ExternalUrlCheck:
        """Validate a URL before handing it to the host opener."""

        return validate_external_url(url)

    def open_url(self, url: str) -> bool:
        """Open an external URL (capability-gated; best-effort)."""

        if not bool(self.options.get("cap.open-url")):
            return False
        checked = self.check_external_url(url)
        if not checked.ok:
            return False
        u = str(checked.url)
        try:
            return bool(self._open_url_fn(u, new=2))
        except TypeError:
            # Some openers don't accept keyword args.
            try:
                return bool(self._open_url_fn(u))
            except Exception:
                return False
        except Exception:
            return False

    def current_help_doc_topic(self) -> str | None:
        """Return the current help-doc topic slug (or None)."""

        try:
            eb = self.cur()
        except Exception:
            return None
        try:
            if not bool(eb.local_options.get("readonly")):
                return None
            t = eb.local_options.get("help_doc")
            s = str(t or "").strip()
            return s or None
        except Exception:
            return None

    def _help_history_entry(self, topic: str, *, line: int | None = None, col: int | None = None) -> dict[str, Any]:
        """Return a small docs-history entry for ``helpback`` reuse."""

        out: dict[str, Any] = {"topic": str(topic or "").strip()}
        if line is not None:
            out["line"] = int(line)
        if col is not None:
            out["col"] = int(col)
        return out

    def _normalize_help_history_authority(self) -> None:
        """Keep docs-help history provenance aligned with local stacks."""

        missing = len(self._help_stack) - len(self._help_stack_authority)
        if missing > 0:
            self._help_stack_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del self._help_stack_authority[len(self._help_stack):]

        missing = len(self._help_forward_stack) - len(self._help_forward_stack_authority)
        if missing > 0:
            self._help_forward_stack_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del self._help_forward_stack_authority[len(self._help_forward_stack):]

        if self._help_history_topic(self._help_session_entry) and self._help_session_authority is None:
            self._help_session_authority = RuntimeRegistrationAuthority(script_context=False)

    def _help_current_authority(self) -> RuntimeRegistrationAuthority:
        """Return authority for the active/dormant docs-history source."""

        self._normalize_help_history_authority()
        if self._help_history_topic(self._help_session_entry):
            return self._clone_mark_authority(self._help_session_authority)
        # Reload pre-pruning may intentionally clear stale session-help rows while
        # a help buffer opened by the old plugin is still visible.  In that gap,
        # derive authority from the active help buffer instead of laundering the
        # current docs target into ambient trusted/user history.
        active = self._current_help_history_entry()
        if active is not None:
            try:
                eb = self.cur()
                if self._help_history_topic(active) and str(eb.local_options.get("help_doc", "") or "").strip():
                    return self._buffer_registration_authority(eb.name)
            except Exception:
                pass
        return RuntimeRegistrationAuthority(script_context=False)

    def _help_stack_lists(self, which: str) -> tuple[list[object], list[RuntimeRegistrationAuthority]]:
        if str(which or "").strip().lower() == "forward":
            return self._help_forward_stack, self._help_forward_stack_authority
        return self._help_stack, self._help_stack_authority

    def _guard_help_history_authority(
        self,
        authority: RuntimeRegistrationAuthority,
        *,
        lane: str,
        action: str,
    ) -> None:
        destructive = {
            "clear",
            "clear-forward",
            "drop-empty",
            "drop-oldest",
            "prune",
        }
        if str(action or "") in destructive and self._script_history_clear_capability_enabled():
            return
        self._guard_runtime_registration_mutation(
            kind="help history",
            target=f"{str(lane or 'history')}:{str(action or 'mutate')}",
            authority=self._clone_mark_authority(authority),
            current_kind="editor",
        )

    def _guard_help_history_stack_range(self, which: str, start: int, end: int, action: str) -> None:
        self._normalize_help_history_authority()
        _stack, auths = self._help_stack_lists(which)
        lo = max(0, int(start))
        hi = min(len(auths), int(end))
        for idx in range(lo, hi):
            self._guard_help_history_authority(auths[idx], lane=str(which or "back"), action=action)

    def _clear_help_history_stack(self, which: str, action: str) -> None:
        self._normalize_help_history_authority()
        stack, auths = self._help_stack_lists(which)
        self._guard_help_history_stack_range(which, 0, len(stack), action)
        stack.clear()
        auths.clear()

    def _pop_help_history_stack_tail(self, which: str, action: str) -> tuple[object, RuntimeRegistrationAuthority]:
        self._normalize_help_history_authority()
        stack, auths = self._help_stack_lists(which)
        if not stack:
            return None, RuntimeRegistrationAuthority(script_context=False)
        idx = len(stack) - 1
        self._guard_help_history_authority(auths[idx], lane=str(which or "back"), action=action)
        entry = stack.pop()
        authority = auths.pop() if auths else RuntimeRegistrationAuthority(script_context=False)
        return entry, self._clone_mark_authority(authority)


    def _help_history_topic(self, entry: object) -> str:
        """Return the docs topic stored in a history entry (legacy-safe)."""

        if isinstance(entry, dict):
            return str(entry.get("topic", "") or "").strip()
        return str(entry or "").strip()

    def _help_history_linecol(self, entry: object) -> tuple[int | None, int | None]:
        """Return saved ``(line, col)`` from a history entry when present."""

        if not isinstance(entry, dict):
            return (None, None)
        try:
            line = int(entry["line"]) if "line" in entry else None
        except Exception:
            line = None
        try:
            col = int(entry["col"]) if "col" in entry else None
        except Exception:
            col = None
        return (line, col)

    def _help_history_position(self, entry: object) -> str:
        """Return tiny ``line:col`` text for one docs-history entry."""

        line, col = self._help_history_linecol(entry)
        if line is None or col is None:
            return ""
        return f"{int(line) + 1}:{int(col)}"

    def _help_history_resolvable(self, entry: object) -> bool:
        """Return whether one remembered docs target still resolves locally."""

        topic = self._help_history_topic(entry)
        if not topic:
            return False
        return bool(self.find_doc_path(topic))

    def _help_history_state(self, lane: str, entry: object) -> str:
        """Return a tiny trust-state label for one docs-history row/target."""

        if str(lane or "") == "current":
            return "active" if self._help_history_topic(entry) else ""
        return "ready" if self._help_history_resolvable(entry) else "missing"

    def _help_history_warning(self, command: str, entry: object) -> str:
        """Return a tiny warning when one replay target exists but is blocked."""

        topic = self._help_history_topic(entry)
        if not topic or self._help_history_resolvable(entry):
            return ""
        return f"{str(command or '').strip()}: missing doc: {topic}"

    def _help_history_prunable(self, entry: object) -> bool:
        """Return whether one remembered docs target should be prunable."""

        topic = self._help_history_topic(entry)
        return bool(topic) and not self._help_history_resolvable(entry)

    def _help_prune_counts(self) -> tuple[int, int, int, int]:
        """Return ``(session, back, forward, total)`` missing-target prune counts."""

        session_count = 1 if self._help_history_prunable(self._help_session_entry) else 0
        back_count = sum(1 for entry in self._help_stack if self._help_history_prunable(entry))
        forward_count = sum(1 for entry in self._help_forward_stack if self._help_history_prunable(entry))
        total = int(session_count + back_count + forward_count)
        return (int(session_count), int(back_count), int(forward_count), int(total))

    def _current_help_history_entry(self) -> dict[str, Any] | None:
        """Return the current docs page as a small history entry."""

        topic = self.current_help_doc_topic()
        if not topic:
            return None
        try:
            eb = self.cur()
            c = eb.cursors[eb.primary]
            return self._help_history_entry(topic, line=int(c.line), col=int(c.col))
        except Exception:
            return self._help_history_entry(topic)

    def _help_session_entry_model(self) -> dict[str, Any] | None:
        """Return the last known session-local docs target when available."""

        active = self._current_help_history_entry()
        if active is not None:
            return active
        entry = self._help_session_entry
        topic = self._help_history_topic(entry)
        if not topic:
            return None
        line, col = self._help_history_linecol(entry)
        return self._help_history_entry(topic, line=line, col=col)

    def _help_navigation_source_entry(self) -> dict[str, Any] | None:
        """Return the local docs target that a new docs open should branch from.

        Active help buffers take priority, but once docs state goes dormant the
        session-local remembered target is still the honest branch head for the
        tiny help-history loop. Opening a different docs page from outside the
        help buffer should therefore continue that local trail instead of
        silently overwriting it.
        """

        active = self._current_help_history_entry()
        if active is not None:
            return active
        return self._help_session_entry_model()

    def _remember_help_session_entry(
        self,
        entry: object | None = None,
        *,
        authority: RuntimeRegistrationAuthority | None = None,
    ) -> None:
        """Remember one session-local docs target without pretending persistence."""

        target = entry if entry is not None else self._current_help_history_entry()
        topic = self._help_history_topic(target)
        if not topic:
            return
        line, col = self._help_history_linecol(target)
        self._help_session_entry = self._help_history_entry(topic, line=line, col=col)
        self._help_session_authority = self._clone_mark_authority(
            authority if authority is not None else self._current_runtime_authority(kind="editor")
        )

    def _remember_help_session_entry_for_buffer(self, eb: EditorBuffer | None) -> None:
        """Remember the visible docs target from ``eb`` when it is a help buffer."""

        if eb is None:
            return
        try:
            if not bool(eb.local_options.get("readonly")):
                return
            topic = str(eb.local_options.get("help_doc", "") or "").strip()
            if not topic:
                return
            idx = int(eb.primary)
            c = eb.cursors[idx]
            self._remember_help_session_entry(self._help_history_entry(topic, line=int(c.line), col=int(c.col)))
        except Exception:
            return

    def _restore_help_history_entry(
        self,
        entry: object,
        *,
        authority: RuntimeRegistrationAuthority | None = None,
    ) -> None:
        """Best-effort restore of a docs-history cursor target."""

        line, col = self._help_history_linecol(entry)
        if line is None or col is None:
            self._remember_help_session_entry(entry, authority=authority)
            return
        try:
            eb = self.cur()
            if not eb.buf.lines:
                self._remember_help_session_entry(entry, authority=authority)
                return
            line = max(0, min(int(line), len(eb.buf.lines) - 1))
            row = str(eb.buf.lines[line])
            col = max(0, min(int(col), len(row)))
            idx = int(eb.primary)
            eb.cursors[idx] = Cursor(int(line), int(col))
            if idx < len(eb.sel_anchors):
                eb.sel_anchors[idx] = None
            self._remember_help_session_entry(
                self._help_history_entry(
                    self.current_help_doc_topic() or self._help_history_topic(entry),
                    line=int(line),
                    col=int(col),
                ),
                authority=authority,
            )
        except Exception:
            self._remember_help_session_entry(entry, authority=authority)
            return

    @staticmethod
    def _clone_help_history_entry(entry: object) -> object:
        """Return a small detached copy of one help-history entry."""

        if isinstance(entry, dict):
            return dict(entry)
        if entry is None:
            return None
        return str(entry)

    def _snapshot_help_history_state(self) -> dict[str, object]:
        """Capture help-history stacks and authority for plugin rollback."""

        self._normalize_help_history_authority()
        return {
            "back": [self._clone_help_history_entry(entry) for entry in list(self._help_stack)],
            "back_authority": [
                self._clone_mark_authority(authority)
                for authority in list(self._help_stack_authority)
            ],
            "forward": [
                self._clone_help_history_entry(entry)
                for entry in list(self._help_forward_stack)
            ],
            "forward_authority": [
                self._clone_mark_authority(authority)
                for authority in list(self._help_forward_stack_authority)
            ],
            "session": self._clone_help_history_entry(self._help_session_entry),
            "session_authority": self._clone_mark_authority(self._help_session_authority),
        }

    def _restore_help_history_state(self, snapshot: object) -> None:
        """Restore help-history state captured by ``_snapshot_help_history_state``."""

        data = snapshot if isinstance(snapshot, dict) else {}
        self._help_stack[:] = [
            self._clone_help_history_entry(entry)
            for entry in list(data.get("back", []) or [])
        ]
        self._help_stack_authority[:] = [
            self._clone_mark_authority(authority)
            for authority in list(data.get("back_authority", []) or [])
        ]
        self._help_forward_stack[:] = [
            self._clone_help_history_entry(entry)
            for entry in list(data.get("forward", []) or [])
        ]
        self._help_forward_stack_authority[:] = [
            self._clone_mark_authority(authority)
            for authority in list(data.get("forward_authority", []) or [])
        ]
        self._help_session_entry = self._clone_help_history_entry(data.get("session"))
        self._help_session_authority = self._clone_mark_authority(data.get("session_authority"))
        self._normalize_help_history_authority()

    def _remove_help_history_rows_for_authority(self, predicate: Callable[[RuntimeRegistrationAuthority], bool]) -> int:
        """Prune help-history rows whose stored authority matches *predicate*."""

        self._normalize_help_history_authority()
        removed = 0
        for stack, auths in (
            (self._help_stack, self._help_stack_authority),
            (self._help_forward_stack, self._help_forward_stack_authority),
        ):
            kept_entries: list[object] = []
            kept_auths: list[RuntimeRegistrationAuthority] = []
            for entry, authority in zip(list(stack), list(auths)):
                auth = self._clone_mark_authority(authority)
                if predicate(auth):
                    removed += 1
                    continue
                kept_entries.append(self._clone_help_history_entry(entry))
                kept_auths.append(auth)
            stack[:] = kept_entries
            auths[:] = kept_auths
        session_auth = self._clone_mark_authority(self._help_session_authority)
        if self._help_history_topic(self._help_session_entry) and predicate(session_auth):
            self._help_session_entry = None
            self._help_session_authority = RuntimeRegistrationAuthority(script_context=False)
            removed += 1
        self._normalize_help_history_authority()
        return int(removed)

    def remove_help_history_group(self, group: object) -> int:
        """Remove help-history rows owned by one runtime group."""

        raw = str(group or "")
        if not raw:
            return 0
        return self._remove_help_history_rows_for_authority(
            lambda authority: self._authority_group_matches(authority, raw)
        )

    def retag_help_history_group(self, old: object, new: object) -> int:
        """Retag staged help-history rows after successful plugin reload."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        self._normalize_help_history_authority()
        changed = 0
        for auths in (self._help_stack_authority, self._help_forward_stack_authority):
            for idx, authority in enumerate(list(auths)):
                auth = self._clone_mark_authority(authority)
                if not self._authority_group_matches(auth, old_s):
                    continue
                auths[idx] = self._authority_with_group(auth, new_s)
                changed += 1
        session_auth = self._clone_mark_authority(self._help_session_authority)
        if self._help_history_topic(self._help_session_entry) and self._authority_group_matches(session_auth, old_s):
            self._help_session_authority = self._authority_with_group(session_auth, new_s)
            changed += 1
        self._normalize_help_history_authority()
        return int(changed)

    def remove_plugin_help_history_generation(
        self,
        plugin_load_root: object,
        plugin_generation: object,
    ) -> int:
        """Remove help-history rows owned by one unloaded plugin generation."""

        return self._remove_help_history_rows_for_authority(
            lambda authority: self._authority_matches_plugin_generation(
                authority,
                plugin_load_root=plugin_load_root,
                plugin_generation=plugin_generation,
            )
        )

    def _push_help_history(
        self,
        which: str,
        entry: object,
        *,
        authority: RuntimeRegistrationAuthority | None = None,
    ) -> None:
        """Append a docs-history entry to the requested local stack."""

        topic = self._help_history_topic(entry)
        if not topic:
            return
        self._normalize_help_history_authority()
        stack, auths = self._help_stack_lists(which)
        limit = max(1, int(self._help_stack_limit))
        if len(stack) + 1 > limit:
            drop = len(stack) + 1 - limit
            self._guard_help_history_stack_range(which, 0, int(drop), "drop-oldest")
            del stack[:drop]
            del auths[:drop]
        stack.append(entry)
        auths.append(
            self._clone_mark_authority(
                authority if authority is not None else self._current_runtime_authority(kind="editor")
            )
        )

    def _record_help_position_history(self, line1: int, col1: int = 1) -> bool:
        """Record the current docs position before a same-page help jump.

        This is intentionally smaller than full cursor history: it only runs for
        explicit docs-navigation actions (`helpjump`, same-page `helpfollow`,
        help-outline/help-nav picks). The goal is to make those moves retraceable
        through `helpback` / `helpforward` without promoting arbitrary cursor
        motion to docs-history state.
        """

        cur_entry = self._current_help_history_entry()
        if cur_entry is None:
            return False
        cur_line, cur_col = self._help_history_linecol(cur_entry)
        target_line = max(0, int(line1) - 1)
        target_col = max(0, int(col1) - 1)
        if cur_line == target_line and cur_col == target_col:
            return False
        if self._help_forward_stack:
            self._clear_help_history_stack("forward", "clear-forward")
        self._push_help_history("back", cur_entry, authority=self._help_current_authority())
        return True

    def _jump_help_target(self, line1: int, col1: int = 1, *, push_history: bool = True) -> bool:
        """Jump within the current docs buffer, optionally recording help history."""

        if push_history:
            self._record_help_position_history(line1, col1)
        ok = self._jump_current_buffer_to(line1, col1)
        if ok:
            self._remember_help_session_entry()
        return ok

    def _help_history_tail_model(self, stack: list[object], *, lane: str) -> tuple[int, str, str, str, str]:
        """Return ``(count, topic, title, position, state)`` for a history tail."""

        count = int(len(stack))
        entry = stack[-1] if stack else None
        topic = self._help_history_topic(entry) if entry is not None else ""
        title = self._help_doc_title_for_target(topic) if topic else ""
        position = self._help_history_position(entry)
        state = self._help_history_state(lane, entry) if entry is not None else ""
        return (count, str(topic), str(title), str(position), str(state))

    def help_history_rows(self) -> list[list[object]]:
        """Return compact docs-history rows for commands/hostcalls.

        Rows are ``[lane depth topic title position state]`` where ``lane`` is
        one of ``current``, ``dormant``, ``back``, or ``forward`` and ``state``
        is ``active``, ``ready``, or ``missing``. ``depth`` is 0 for the
        current/dormant row or a 1-based actionable distance within the
        corresponding stack. Immediate back/forward targets come first so
        callers do not need to know that the underlying stacks are stored
        oldest-to-newest.
        """

        rows: list[list[object]] = []
        cur = self._current_help_history_entry()
        if cur is not None:
            topic = self._help_history_topic(cur)
            title = self._help_doc_title_for_target(topic) if topic else ""
            rows.append(["current", 0, str(topic), str(title), self._help_history_position(cur), self._help_history_state("current", cur)])
        else:
            session = self._help_session_entry_model()
            if session is not None:
                topic = self._help_history_topic(session)
                title = self._help_doc_title_for_target(topic) if topic else ""
                rows.append(["dormant", 0, str(topic), str(title), self._help_history_position(session), self._help_history_state("dormant", session)])
        for depth, entry in enumerate(reversed(list(self._help_stack)), start=1):
            topic = self._help_history_topic(entry)
            title = self._help_doc_title_for_target(topic) if topic else ""
            rows.append(["back", int(depth), str(topic), str(title), self._help_history_position(entry), self._help_history_state("back", entry)])
        for depth, entry in enumerate(reversed(list(self._help_forward_stack)), start=1):
            topic = self._help_history_topic(entry)
            title = self._help_doc_title_for_target(topic) if topic else ""
            rows.append(["forward", int(depth), str(topic), str(title), self._help_history_position(entry), self._help_history_state("forward", entry)])
        return rows

    def help_navigation_model(self) -> dict[str, Any]:
        """Return a tiny structured docs-navigation snapshot.

        This keeps the current docs page and the next back/forward targets
        separate so future UIs, scripts, tests, and LLMs do not have to infer
        docs-history availability from the last transient message.
        """

        cur = self._current_help_history_entry()
        session = self._help_session_entry_model()
        active = cur is not None
        topic = self._help_history_topic(cur) if cur is not None else ""
        title = self._help_doc_title_for_target(topic) if topic else ""
        position = self._help_history_position(cur)
        session_topic = self._help_history_topic(session) if session is not None else ""
        session_title = self._help_doc_title_for_target(session_topic) if session_topic else ""
        session_position = self._help_history_position(session)
        back_count, back_topic, back_title, back_position, back_state = self._help_history_tail_model(list(self._help_stack), lane="back")
        forward_count, forward_topic, forward_title, forward_position, forward_state = self._help_history_tail_model(list(self._help_forward_stack), lane="forward")

        session_known = bool(session_topic)
        # Split witness from actionability: a current help page still counts as the
        # session-local head, but `helpresume` is only actionable once that head is
        # dormant and still resolvable.
        resume_available = bool((not active) and session_known and session is not None and self._help_history_resolvable(session))
        back_available = bool(back_count > 0 and back_state == "ready")
        forward_available = bool(forward_count > 0 and forward_state == "ready")
        resume_warning = self._help_history_warning("helpresume", session) if session_known else ""
        back_warning = self._help_history_warning("helpback", self._help_stack[-1]) if back_count > 0 else ""
        forward_warning = self._help_history_warning("helpforward", self._help_forward_stack[-1]) if forward_count > 0 else ""

        base_topic = str(topic or session_topic or "")
        base_position = str(position or session_position or "")
        summary = str(base_topic or "")
        base = summary or "help"
        if base_topic and base_position and ((back_count > 0 and back_topic == base_topic) or (forward_count > 0 and forward_topic == base_topic)):
            base = f"{base} @ {base_position}"
        if not active and base_topic:
            base = f"{base} (dormant)" if resume_available else f"{base} (dormant missing)"
            summary = base
        if back_count > 0:
            tail = str(back_topic or "?")
            if back_position:
                tail += f" @ {back_position}"
            if back_state == "missing":
                tail += " [missing]"
            summary = f"{base} <- {tail} (+{back_count})"
        elif summary:
            summary = str(summary)
        if forward_count > 0:
            tail = str(forward_topic or "?")
            if forward_position:
                tail += f" @ {forward_position}"
            if forward_state == "missing":
                tail += " [missing]"
            prefix = summary or base
            summary = f"{prefix} -> {tail} (+{forward_count})"

        _, _, _, prune_count = self._help_prune_counts()

        actions: list[str] = []
        if resume_available and not active:
            actions.append("helpresume")
        if back_available:
            actions.append("helpback")
        if forward_available:
            actions.append("helpforward")
        if prune_count > 0:
            actions.append("helpprune")
        warnings = [w for w in [resume_warning if (session_known and not active) else "", back_warning, forward_warning] if w]

        return {
            "help_topic": str(topic),
            "help_title": str(title),
            "help_position": str(position),
            "help_navigation_active": 1 if active else 0,
            "help_navigation_dormant": 1 if (not active and session_known) else 0,
            "help_session_available": 1 if session_known else 0,
            "help_session_topic": str(session_topic),
            "help_session_title": str(session_title),
            "help_session_position": str(session_position),
            "help_resume_available": 1 if resume_available else 0,
            "help_resume_target": str(session_topic),
            "help_resume_title": str(session_title),
            "help_resume_position": str(session_position),
            "help_resume_warning": str(resume_warning if (session_known and not active) else ""),
            "help_resume_command": "helpresume" if (resume_available and not active) else "",
            "help_back_available": 1 if back_available else 0,
            "help_back_count": int(back_count),
            "help_back_target": str(back_topic),
            "help_back_title": str(back_title),
            "help_back_position": str(back_position),
            "help_back_warning": str(back_warning),
            "help_back_command": "helpback" if back_available else "",
            "help_forward_available": 1 if forward_available else 0,
            "help_forward_count": int(forward_count),
            "help_forward_target": str(forward_topic),
            "help_forward_title": str(forward_title),
            "help_forward_position": str(forward_position),
            "help_forward_warning": str(forward_warning),
            "help_forward_command": "helpforward" if forward_available else "",
            "help_prune_available": 1 if prune_count > 0 else 0,
            "help_prune_count": int(prune_count),
            "help_prune_command": "helpprune" if prune_count > 0 else "",
            "help_navigation_scope": "session",
            "help_navigation_persisted": 0,
            "help_navigation_summary": str(summary),
            "help_navigation_actions": list(actions),
            "help_navigation_action_summary": ", ".join(actions),
            "help_navigation_warning_summary": "; ".join(warnings),
        }

    def _prune_help_history_stack(self, which: str, action: str) -> int:
        """Prune missing docs targets from one history stack with provenance checks."""

        self._normalize_help_history_authority()
        stack, auths = self._help_stack_lists(which)
        if not stack:
            return 0
        kept_entries: list[object] = []
        kept_auths: list[RuntimeRegistrationAuthority] = []
        removed = 0
        for entry, authority in zip(list(stack), list(auths)):
            if self._help_history_prunable(entry):
                self._guard_help_history_authority(authority, lane=str(which or "back"), action=action)
                removed += 1
            else:
                kept_entries.append(entry)
                kept_auths.append(self._clone_mark_authority(authority))
        stack[:] = kept_entries
        auths[:] = kept_auths
        return int(removed)

    def help_prune(self) -> bool:
        """Drop missing docs targets from local session/back/forward history."""

        self._normalize_help_history_authority()
        session_count, back_count, forward_count, total = self._help_prune_counts()
        if total <= 0:
            self.message("helpprune: nothing to prune")
            return False
        if session_count > 0:
            self._guard_help_history_authority(self._help_session_authority, lane="session", action="prune")
        if back_count > 0:
            self._prune_help_history_stack("back", "prune")
        if forward_count > 0:
            self._prune_help_history_stack("forward", "prune")
        if session_count > 0:
            self._help_session_entry = None
            self._help_session_authority = RuntimeRegistrationAuthority(script_context=False)
        parts: list[str] = []
        if session_count > 0:
            parts.append(f"session {session_count}")
        if back_count > 0:
            parts.append(f"back {back_count}")
        if forward_count > 0:
            parts.append(f"forward {forward_count}")
        detail = "; ".join(parts)
        self.message(f"helpprune: pruned {total} missing help target(s) ({detail})")
        return True

    def help_resume(self) -> bool:
        """Reopen the last dormant session-local docs target without mutating history."""

        if self._current_help_history_entry() is not None:
            self.message(f"helpresume: already active: {self.format_help_target()}")
            return False
        self._normalize_help_history_authority()
        entry = self._help_session_entry_model()
        authority = self._help_current_authority()
        topic = self._help_history_topic(entry)
        if not topic:
            self.message("helpresume: no session help target")
            return False
        if self.open_help_doc(topic, push_stack=False):
            self._restore_help_history_entry(entry, authority=authority)
            self.message(f"helpresume: {self.format_help_target()}")
            return True
        self.message(self._help_history_warning("helpresume", entry) or f"helpresume: missing doc: {topic}")
        return False

    def help_back(self) -> bool:
        """Go back to the previous docs help page (best-effort)."""

        self._normalize_help_history_authority()
        if not self._help_stack:
            self.message("helpback: back stack empty")
            return False
        entry = self._help_stack[-1]
        topic = self._help_history_topic(entry)
        if not topic:
            self._pop_help_history_stack_tail("back", "drop-empty")
            self.message("helpback: back stack empty")
            return False
        current_entry = self._help_navigation_source_entry()
        current_authority = self._help_current_authority()
        self._guard_help_history_authority(self._help_stack_authority[-1], lane="back", action="replay")
        # Avoid re-pushing onto the stack. Only consume the entry once the
        # target is known to reopen so stale missing-doc history stays visible.
        if self.open_help_doc(topic, push_stack=False):
            replay_entry, replay_authority = self._pop_help_history_stack_tail("back", "replay")
            if current_entry is not None:
                self._push_help_history("forward", current_entry, authority=current_authority)
            self._restore_help_history_entry(replay_entry, authority=replay_authority)
            self.message(f"helpback: {self.format_help_target()}")
            return True
        self.message(self._help_history_warning("helpback", entry) or f"helpback: missing doc: {topic}")
        return False

    def help_forward(self) -> bool:
        """Go forward to the next docs help page after ``helpback``."""

        self._normalize_help_history_authority()
        if not self._help_forward_stack:
            self.message("helpforward: forward stack empty")
            return False
        entry = self._help_forward_stack[-1]
        topic = self._help_history_topic(entry)
        if not topic:
            self._pop_help_history_stack_tail("forward", "drop-empty")
            self.message("helpforward: forward stack empty")
            return False
        current_entry = self._help_navigation_source_entry()
        current_authority = self._help_current_authority()
        self._guard_help_history_authority(
            self._help_forward_stack_authority[-1], lane="forward", action="replay"
        )
        if self.open_help_doc(topic, push_stack=False):
            replay_entry, replay_authority = self._pop_help_history_stack_tail("forward", "replay")
            if current_entry is not None:
                self._push_help_history("back", current_entry, authority=current_authority)
            self._restore_help_history_entry(replay_entry, authority=replay_authority)
            self.message(f"helpforward: {self.format_help_target()}")
            return True
        self.message(self._help_history_warning("helpforward", entry) or f"helpforward: missing doc: {topic}")
        return False



    def _md_norm_ref_id(self, s: str) -> str:
        """Normalize a markdown reference-id (case-insensitive, collapse whitespace)."""

        return md_norm_ref_id(s)

    def _md_reference_defs(self, lines: list[object]) -> dict[str, str]:
        """Parse markdown reference definitions: [id]: target "title".

        This is intentionally small and conservative: it supports the common forms
        used in docs/help pages without needing a full markdown parser.
        """

        defs: dict[str, str] = {}
        xs = list(lines)
        fence_flags = md_fenced_code_line_flags(xs)
        html_block_flags = md_html_block_line_flags(xs)
        comment_spans = md_html_comment_line_spans(xs)


        for i, ln in enumerate(xs):
            if i < len(fence_flags) and fence_flags[i]:
                continue
            if i < len(html_block_flags) and html_block_flags[i]:
                continue
            s = str(ln)
            j = md_leading_spaces_upto3(s)
            if j is None or j >= len(s) or s[j:j+1] != '[' or md_backslash_escaped(s, j):
                continue
            spans = comment_spans[i] if i < len(comment_spans) else []
            if md_span_contains(spans, j, j + 1):
                continue
            span = md_balanced_span(s, j, opener='[', closer=']')
            if span is None:
                continue
            a, b = span
            k = b
            while k < len(s) and s[k].isspace():
                k += 1
            if s[k:k+1] != ':':
                continue
            raw_id = s[a + 1:b - 1]
            if not md_link_label_has_text(raw_id):
                continue
            rid = self._md_norm_ref_id(raw_id)
            if not rid:
                continue

            target = md_reference_def_target(
                s[k + 1 :],
                md_docs_continuation_line(xs, i + 1, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans),
                md_docs_continuation_line(xs, i + 2, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans),
            )
            if target:
                defs[rid] = target
        return defs

    def _md_footnote_defs(self, lines: list[object]) -> dict[str, tuple[int, int]]:
        """Parse markdown footnote definitions: ``[^id]: body``.

        Returns ``footnote-id -> (line1, col1)`` using a tiny, best-effort parse.
        We only need the anchor location for docs-buffer navigation, so indented
        continuation lines are left alone.
        """

        defs: dict[str, tuple[int, int]] = {}
        xs = list(lines)
        fence_flags = md_fenced_code_line_flags(xs)
        html_block_flags = md_html_block_line_flags(xs)
        comment_spans = md_html_comment_line_spans(xs)
        for i, ln in enumerate(xs):
            if i < len(fence_flags) and fence_flags[i]:
                continue
            if i < len(html_block_flags) and html_block_flags[i]:
                continue
            s = str(ln)
            col0 = md_leading_spaces_upto3(s)
            if col0 is None:
                continue
            m = re.match(r"\[\^(?P<id>[^\]]+)\]\s*:\s*", s[col0:])
            if not m:
                continue
            spans = comment_spans[i] if i < len(comment_spans) else []
            if md_span_contains(spans, int(col0), int(col0) + 1):
                continue
            rid = self._md_norm_ref_id(m.group('id') or '')
            if not rid:
                continue
            defs[rid] = (i + 1, int(col0) + 1)
        return defs

    def _md_target_from_parens(self, inner: str) -> str:
        """Extract a link target from inside markdown (...) content.

        This uses :func:`md_inline_link_target` so invalid inline-link forms can
        fall back to reference-link parsing.
        """

        return md_inline_link_target(inner)

    def help_follow(self) -> bool:
        """Follow a markdown link under the cursor in a help/docs buffer."""

        eb = self.cur()
        if not self.current_help_doc_topic():
            self.message("helpfollow: not in a docs buffer")
            return False
        row = self.help_link_detail_row()
        if row is None:
            self.message("helpfollow: no link under cursor")
            return False
        target = str(row[2] if len(row) >= 3 else "")
        low = target.strip().casefold()
        is_external = low.startswith("http://") or low.startswith("https://") or low.startswith("mailto:")
        ok = bool(self._follow_help_link(target, base_path=str(eb.buf.path) if eb.buf.path else None))
        if ok and not is_external:
            self.message(f"helpjump: {self.format_help_target()}")
        return ok

    def help_copy_link_target(self) -> bool:
        """Copy the markdown link target under the cursor (docs/help buffers only)."""

        if not self.current_help_doc_topic():
            self.message("helplinkcopy: not in a docs buffer")
            return False
        row = self.help_link_detail_row()
        if row is None:
            self.message("helplinkcopy: no link under cursor")
            return False
        target = str(row[2] if len(row) >= 3 else "")
        self.set_clipboard_items([target], kind="items")
        self.message(f"helplinkcopy: {target}")
        return True

    def _open_url_feedback_prefix(self, source: str = "") -> str:
        """Return the command surface prefix for opening an external URL."""

        return "helpfollow" if str(source or "").strip().lower() == "help" else "urlopen"

    def _copy_url_feedback_prefix(self, source: str = "") -> str:
        """Return the command surface prefix for copying a pending external URL."""

        return "helplinkcopy" if str(source or "").strip().lower() == "help" else "urlcopy"

    # ----- URL-under-cursor helpers -----

    _URL_TOKEN_RE = re.compile(r'(?:https?://|mailto:)[^\s<>()\[\]{}"\']+')

    def _trim_url_token(self, tok: str) -> str:
        s = str(tok or "").strip()
        if not s:
            return ""

        left_wrap = set("<([{") | {"'", chr(34)}
        right_wrap = set(">)]}") | {"'", chr(34), ".", ",", ";", "!"}

        while s and s[0] in left_wrap:
            s = s[1:]
        while s and s[-1] in right_wrap:
            s = s[:-1]
        return s.strip()

    def url_under_cursor(self) -> str | None:
        """Best-effort URL under the primary cursor (any buffer).

        This is intentionally conservative and only recognizes:
        - http://...
        - https://...
        - mailto:...

        The cursor must be within the detected URL span.
        """

        eb = self.cur()
        if not eb.buf.lines:
            return None
        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]
        idx = max(0, min(int(c.line), len(eb.buf.lines) - 1))
        line = str(eb.buf.lines[idx])
        col = int(c.col)

        for m in self._URL_TOKEN_RE.finditer(line):
            a, b = int(m.start()), int(m.end())
            if a <= col <= b:
                u = self._trim_url_token(str(m.group(0) or ""))
                return u or None
        return None

    def open_url_under_cursor(self) -> bool:
        """Open an external URL under cursor (capability-gated; confirm by default)."""

        u = self.url_under_cursor()
        if not u:
            self.message("urlopen: no url under cursor")
            return False

        if not bool(self.options.get("cap.open-url")):
            self.message(f"urlopen: disabled (cap.open-url). Enable with: set cap.open-url true\n{u}")
            return False

        if bool(self.options.get("open-url.confirm")):
            return bool(self.begin_open_url_confirm(u, source="cursor"))

        ok = self.open_url(u)
        if ok:
            self.message(f"urlopen: {u}")
            return True
        self.message(f"urlopen: failed: {u}")
        return False

    def copy_url_under_cursor(self) -> bool:
        """Copy the URL under cursor into the clipboard (any buffer)."""

        u = self.url_under_cursor()
        if not u:
            self.message("urlcopy: no url under cursor")
            return False
        self.set_clipboard_items([u], kind="items")
        self.message(f"urlcopy: {u}")
        return True


    def _help_link_match_under_cursor(self, eb: "EditorBuffer") -> tuple[int, MdLinkMatch] | None:
        """Best-effort markdown link match under the primary cursor."""

        if not eb.buf.lines:
            return None
        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]
        idx = max(0, min(int(c.line), len(eb.buf.lines) - 1))
        line = str(eb.buf.lines[idx])
        col = int(c.col)

        lines = eb.buf.lines
        fence_flags = md_fenced_code_line_flags(lines)
        html_block_flags = md_html_block_line_flags(lines)
        indented_code_flags = md_indented_code_line_flags(lines, fence_flags=fence_flags, html_block_flags=html_block_flags)
        if idx < len(fence_flags) and fence_flags[idx]:
            return None
        if idx < len(html_block_flags) and html_block_flags[idx]:
            return None
        if idx < len(indented_code_flags) and indented_code_flags[idx]:
            return None

        # Markdown link scan (best-effort).
        # Supported forms:
        #   - inline links: [label](target "title")
        #   - reference links: [label][id] and [label][] (collapsed)
        #   - shortcut reference links: [id]
        #   - autolinks: <https://...> and <mailto:...>

        defs = self._md_reference_defs(lines)
        footdefs = self._md_footnote_defs(lines)
        comment_spans = md_html_comment_line_spans(lines)
        line_comment_spans = comment_spans[idx] if idx < len(comment_spans) else []

        next_line = md_docs_continuation_line(lines, idx + 1, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans)
        next_next_line = md_docs_continuation_line(lines, idx + 2, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans)
        for match in md_link_matches(line, defs, footdefs, masked_spans=line_comment_spans, next_line=next_line, next_next_line=next_next_line):
            if int(match.start) <= col <= int(match.end):
                return (idx, match)

        return None

    def _help_link_target_under_cursor(self, eb: "EditorBuffer") -> str | None:
        """Best-effort markdown link target under the primary cursor."""

        found = self._help_link_match_under_cursor(eb)
        if found is None:
            return None
        _line_idx, match = found
        return str(match.target or '') or None

    def help_link_detail_row(self) -> list[object] | None:
        """Return one tiny shared detail row for the current docs-link target.

        The row matches the exact link target humans already trust through
        ``helpfollow`` / ``helplinkcopy`` so scripts and future UIs can inspect
        one current docs-link target without rescanning all link rows or
        inferring section/position context from picker text. Returns ``None``
        when there is no current docs buffer or no followable link under the
        primary cursor.
        """

        topic = self.current_help_doc_topic()
        if not topic:
            return None
        eb = self.cur()
        found = self._help_link_match_under_cursor(eb)
        if found is None:
            return None
        line_idx, match = found
        label = str(match.display or match.target or "").strip()
        target = str(match.target or "").strip()
        if not target:
            return None
        info = md_help_link_target_info(target)
        kind = str(info.get("target_kind", "") or "")
        row = [label, 'link', target, f"{line_idx + 1}:{int(match.label_start) + 1}"]
        section = str(self._helplink_heading_label(row) or "Top")
        return [str(topic), label, target, kind, int(line_idx + 1), int(match.label_start) + 1, section]

    def _follow_help_link(self, target: str, *, base_path: str | None) -> bool:
        """Follow a docs-help link target (internal docs, relative file, or external URL)."""

        t = str(target or "").strip().strip('"').strip("'")
        if not t:
            return False

        low = t.casefold()
        if low.startswith("http://") or low.startswith("https://") or low.startswith("mailto:"):
            checked = self.check_external_url(t)
            if not checked.ok:
                self.message(f"{self._open_url_feedback_prefix('help')}: {checked.reason}: {t}")
                return False
            u = str(checked.url)
            if bool(self.options.get("cap.open-url")):
                # Safe-by-default: confirm before opening external URLs.
                if bool(self.options.get("open-url.confirm")):
                    return bool(self.begin_open_url_confirm(u, source="help"))

                ok = self.open_url(u)
                if ok:
                    self.message(f"{self._open_url_feedback_prefix('help')}: {u}")
                    return True
                self.message(f"{self._open_url_feedback_prefix('help')}: failed: {u}")
                return False
            # Keep the UX explicit: this is intentionally capability-gated.
            # (Docs page `98-help-browser.md` includes the same hint.)
            self.message(
                f"{self._open_url_feedback_prefix('help')}: disabled (cap.open-url). Enable with: set cap.open-url true\n{u}"
            )
            return False

        # Same-page or cross-doc markdown fragments.
        doc_part, hash_mark, frag_part = t.partition("#")
        frag = unquote(str(frag_part or "").strip()) if hash_mark else ""
        if hash_mark and not doc_part.strip():
            return self._jump_help_fragment(frag, push_history=True)

        # Relative docs paths are percent-decoded before resolution so links like
        # ``topic%20name.md`` behave like ordinary local files.
        resolved_doc = unquote(str(doc_part or t).strip())
        if base_path and resolved_doc:
            try:
                base = Path(str(base_path)).parent
                cand = (base / resolved_doc).resolve()
                if cand.exists() and cand.is_file():
                    ok = bool(self.open_help_doc(str(cand), push_stack=True))
                    if ok:
                        if frag:
                            return self._jump_help_fragment(frag, push_history=False)
                        return True
                    # A real path that is not a docs-contained markdown file is
                    # deliberately treated like an unresolved docs target below
                    # rather than silently failing or reading outside docs_root.
            except Exception:
                pass

        # Otherwise treat as a docs topic (slug) or explicit path.
        if self.open_help_doc(resolved_doc, push_stack=True):
            if frag:
                return self._jump_help_fragment(frag, push_history=False)
            return True
        self.message(f"help docs: no such doc: {resolved_doc}")
        return False


    def begin_open_url_confirm(self, url: str, *, source: str = "") -> bool:
        """Begin a capture-mode confirmation loop for opening an external URL."""

        checked = self.check_external_url(url)
        if not checked.ok:
            return False
        u = str(checked.url)
        if not bool(self.options.get("cap.open-url")):
            return False

        if str(getattr(self, "_pending_open_url", "") or "").strip():
            if not self._check_interaction_response(
                getattr(self, "_pending_open_url_authority", None),
                kind="openurl",
                action="replace",
            ):
                return False

        # Remove any prior openurl mode so we don't stack confirmations.
        self.key_mode_stack = [km for km in self.key_mode_stack if km.name != "openurl"]

        self._pending_open_url = u
        self._pending_open_url_source = str(source or "")
        self._pending_open_url_authority = self._current_runtime_authority(kind="editor")
        self.push_key_mode("openurl", capture=True)
        source_tag = str(source or "").strip().lower()
        if source_tag == "help":
            head = "open external link from help?"
        elif source_tag == "cursor":
            head = "open external link under cursor?"
        elif source_tag == "command":
            head = "open external link from command?"
        else:
            head = "open external link?"
        self.message(f"{head} y/Enter=open n/Esc=cancel c=copy\n{u}")
        return True

    def _finish_open_url_confirm(self) -> None:
        self._pending_open_url = None
        self._pending_open_url_source = ""
        self._pending_open_url_authority = RuntimeRegistrationAuthority(script_context=False)
        self.key_mode_stack = [km for km in self.key_mode_stack if km.name != "openurl"]

    def _open_url_confirm_response_allowed(self, action: str) -> bool:
        """Return whether the current caller may answer the pending URL prompt."""

        if not str(getattr(self, "_pending_open_url", "") or "").strip():
            return False
        return self._check_interaction_response(
            getattr(self, "_pending_open_url_authority", None),
            kind="openurl",
            action=str(action or "respond"),
        )

    def open_url_confirm_yes(self) -> bool:
        """Approve the pending external URL confirmation if authority allows."""

        if not self._open_url_confirm_response_allowed("approve"):
            return False
        u = str(self._pending_open_url or "").strip()
        source = str(getattr(self, "_pending_open_url_source", "") or "")
        if not u:
            self._finish_open_url_confirm()
            return False
        self._finish_open_url_confirm()
        ok = self.open_url(u)
        if ok:
            self.message(f"{self._open_url_feedback_prefix(source)}: {u}")
            return True
        self.message(f"{self._open_url_feedback_prefix(source)}: failed: {u}")
        return False

    def open_url_confirm_no(self) -> bool:
        """Cancel the pending external URL confirmation if authority allows."""

        if not self._open_url_confirm_response_allowed("cancel"):
            return False
        u = str(self._pending_open_url or "").strip()
        self._finish_open_url_confirm()
        if u:
            self.message("canceled")
        return True

    def open_url_confirm_copy(self) -> bool:
        """Copy the pending external URL if authority and clipboard policy allow."""

        if not self._open_url_confirm_response_allowed("copy"):
            return False
        u = str(self._pending_open_url or "").strip()
        source = str(getattr(self, "_pending_open_url_source", "") or "")
        if not u:
            self._finish_open_url_confirm()
            return False
        self.set_clipboard_items([u], kind="items")
        self._finish_open_url_confirm()
        self.message(f"{self._copy_url_feedback_prefix(source)}: {u}")
        return True

    def help_link_rows(self, query: str = "", *, limit: int | None = None) -> list[list[str]]:
        """Return markdown links in the current help/docs buffer as rows.

        Rows are: [label kind target info]
        """

        topic = self.current_help_doc_topic()
        if not topic:
            return []
        eb = self.cur()
        rows: list[list[str]] = []
        lines = eb.buf.lines
        defs = self._md_reference_defs(lines)
        footdefs = self._md_footnote_defs(lines)
        fence_flags = md_fenced_code_line_flags(lines)
        html_block_flags = md_html_block_line_flags(lines)
        indented_code_flags = md_indented_code_line_flags(lines, fence_flags=fence_flags, html_block_flags=html_block_flags)
        comment_spans = md_html_comment_line_spans(lines)
        for i, ln in enumerate(lines):
            if i < len(fence_flags) and fence_flags[i]:
                continue
            if i < len(html_block_flags) and html_block_flags[i]:
                continue
            if i < len(indented_code_flags) and indented_code_flags[i]:
                continue
            s = str(ln)
            spans = comment_spans[i] if i < len(comment_spans) else []
            next_line = md_docs_continuation_line(lines, i + 1, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans)
            next_next_line = md_docs_continuation_line(lines, i + 2, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans)
            for match in md_link_matches(s, defs, footdefs, masked_spans=spans, next_line=next_line, next_next_line=next_next_line):
                info = f"{i+1}:{int(match.label_start)+1}"
                rows.append([str(match.display or match.target), 'link', str(match.target), info])

        q = str(query or '').strip()
        if q:
            scored: list[tuple[RowSortKey, int, list[str]]] = []
            for idx, row in enumerate(rows):
                key = self._helplink_row_sort_key(row, q)
                if key is None:
                    continue
                scored.append((key, idx, row))
            scored.sort(key=lambda item: (item[0], item[1]))
            rows = [r for _k, _i, r in scored]

        if limit is not None:
            return rows[: max(1, int(limit))]
        return rows

    def _helplink_section_label(self, row: list[str]) -> str:
        """Backward-compat section label helper for docs-link rows.

        Rows are: [label kind target info]

        New code should prefer:
          - `_helplink_kind_label` (Docs/Files/External)
          - `_helplink_heading_label` (nearest heading breadcrumb)
        """

        return self._helplink_kind_label(row)

    def _helplink_kind_label(self, row: list[str]) -> str:
        """Classify docs links as Docs/Files/External (stable default)."""

        try:
            tgt = str(row[2] if len(row) > 2 else "")
            info = md_help_link_target_info(tgt)
            kind = str(info.get("target_kind", "") or "")
            if kind in {"external", "mailto"}:
                return "External"
            if kind in {"file", "file-fragment"}:
                return "Files"
        except Exception:
            pass
        return "Docs"

    def _help_heading_paths(self) -> list[tuple[int, str]]:
        """Return [(line1, path), ...] heading paths for the current docs buffer.

        The "path" is a breadcrumb-like label built from heading levels.
        We intentionally treat the page's H1 as a document title and omit it
        from the breadcrumb, so most pages yield readable section labels like
        "Links" or "External links" rather than "Help browser › Links".

        Paths are best-effort and cached by (topic, nlines).
        """

        topic = self.current_help_doc_topic()
        if not topic:
            return []
        eb = self.cur()
        nlines = len(eb.buf.lines)
        if topic == self._help_heading_cache_topic and nlines == self._help_heading_cache_nlines:
            return list(self._help_heading_cache)

        idx: list[tuple[int, str]] = []
        stack: list[str] = []

        for line0, level, title, _frag, _col0 in self._md_heading_entries(eb.buf.lines):
            # Ignore H1 as a "document title".
            if level == 1:
                stack = []
                continue

            # Shift levels down so H2 becomes breadcrumb level 1.
            lvl = max(1, min(level - 1, 6))
            stack = stack[: max(0, int(lvl) - 1)]
            stack.append(title)
            path = " › ".join(stack).strip()
            idx.append((int(line0) + 1, path))

        self._help_heading_cache_topic = str(topic)
        self._help_heading_cache_nlines = int(nlines)
        self._help_heading_cache = list(idx)
        return list(idx)

    def _md_heading_title_parts(self, raw_title: str, *, col0: int) -> tuple[str, str, int] | None:
        """Normalize tiny markdown heading title text for pickers/fragments.

        Returns ``(display, explicit_id, col0)`` where ``display`` is human-facing
        text (common inline markup stripped) and ``explicit_id`` is any trailing
        attr-list id like ``{#frag}`` / ``{: #frag }``.
        """

        title0 = str(raw_title or "").strip()
        if not title0:
            return None

        explicit_id = ""
        title = title0

        attr_m = re.search(r"\s+(?P<attrs>\{(?::)?\s*[^{}]*\})\s*$", title0)
        if attr_m is not None:
            attrs = str(attr_m.group("attrs") or "")
            id_m = re.search(r"#(?P<id>[^\s}]+)", attrs)
            if id_m is not None:
                explicit_id = str(id_m.group("id") or "").strip()
                title = title0[: int(attr_m.start())].rstrip()

        display = md_strip_inline_markup(title)
        if not display:
            display = title.strip()
        if not display:
            return None
        return (display, explicit_id, int(col0))

    def _md_heading_parts(self, line: str) -> tuple[int, str, str, int] | None:
        """Parse one ATX heading line into (level, title, fragment_id, col0).

        ``title`` is cleaned for human display/picker use. ``fragment_id`` is the
        explicit custom id (``{#id}`` / ``{: #id }``) when present, otherwise the
        empty string so callers can derive an automatic slug.
        """

        s = str(line)
        col0 = md_leading_spaces_upto3(s)
        if col0 is None:
            return None
        m = re.match(r"(?P<hashes>#{1,6})\s+(?P<title>.+?)\s*(?:#+\s*)?$", s[col0:])
        if not m:
            return None
        raw_title = str(m.group("title") or "").strip()
        if not raw_title:
            return None
        level = len(str(m.group("hashes") or ""))
        level = max(1, min(int(level), 6))
        col0 = int(col0) + int(m.start("title"))

        title_parts = self._md_heading_title_parts(raw_title, col0=col0)
        if title_parts is None:
            return None
        display, explicit_id, col0 = title_parts
        return (level, display, explicit_id, col0)

    def _md_heading_scan(self, lines: list[object]) -> list[tuple[int, int, int, str, str, int]]:
        """Return tiny markdown heading metadata for one docs/help buffer.

        Entries are ``(line0, line1_exclusive, level, title, fragment_id, col0)``.
        Policy stays intentionally small/shared: ATX headings are supported fully,
        and setext headings recognize one or more preceding paragraph-like lines
        before a ``===`` or ``---`` underline outside fenced code blocks.
        """

        xs = [str(x) for x in (lines or [])]
        if not xs:
            return []

        fence_flags = md_fenced_code_line_flags(xs)
        html_block_flags = md_html_block_line_flags(xs)
        comment_spans = md_html_comment_line_spans(xs)
        out: list[tuple[int, int, int, str, str, int]] = []
        for i, s in enumerate(xs):
            if i < len(fence_flags) and fence_flags[i]:
                continue
            if i < len(html_block_flags) and html_block_flags[i]:
                continue
            spans = comment_spans[i] if i < len(comment_spans) else []

            atx = self._md_heading_parts(s)
            if atx is not None:
                level, title, explicit_id, col0 = atx
                if not md_span_contains(spans, int(col0), int(col0) + 1):
                    out.append((i, i + 1, level, title, explicit_id, col0))
                continue

            m = _SETEXT_UNDERLINE_RE.match(s)
            if m is None or i <= 0:
                continue

            parts_rev: list[str] = []
            start = i
            col0 = 0
            for j in range(i - 1, -1, -1):
                if j < len(fence_flags) and fence_flags[j]:
                    break
                if j < len(html_block_flags) and html_block_flags[j]:
                    break
                title_line = str(xs[j])
                stripped = title_line.strip()
                if not stripped:
                    break
                if self._md_heading_parts(title_line) is not None:
                    break
                if re.match(r"^[ ]{0,3}(?:>|[*+-]\s|\d+[.)]\s)", title_line):
                    break
                if re.match(r"^\s{4,}", title_line):
                    break
                if _FENCE_OPEN_RE.match(title_line):
                    break
                if _SETEXT_UNDERLINE_RE.match(title_line) is not None:
                    break

                title_spans = comment_spans[j] if j < len(comment_spans) else []
                line_col0 = len(title_line) - len(title_line.lstrip(' '))
                if md_span_contains(title_spans, int(line_col0), int(line_col0) + 1):
                    break

                start = j
                col0 = line_col0
                parts_rev.append(stripped)

            if not parts_rev:
                continue

            level = 1 if str(m.group('run') or '').startswith('=') else 2
            raw_title = " ".join(reversed(parts_rev)).strip()
            title_parts = self._md_heading_title_parts(raw_title, col0=col0)
            if title_parts is None:
                continue
            display, explicit_id, col0 = title_parts
            out.append((start, i + 1, level, display, explicit_id, col0))

        return out

    def _md_heading_entries(self, lines: list[object]) -> list[tuple[int, int, str, str, int]]:
        """Return tiny markdown heading entries for one docs/help buffer.

        Entries are ``(line0, level, title, fragment_id, col0)``. This is a thin
        compatibility view over ``_md_heading_scan`` so callers that only care
        about the heading target line keep a simple tuple shape.
        """

        return [(line0, level, title, frag, col0) for line0, _line1, level, title, frag, col0 in self._md_heading_scan(lines)]

    def _md_section_entry_by_line(self, lines: list[object]) -> dict[int, dict[str, Any]]:
        """Return nearest-heading section metadata keyed by source line index.

        Each value is a tiny breadcrumb-like snapshot describing the nearest
        preceding markdown heading that owns that line in docs/help source.
        This keeps visible row-local section context shareable with future
        UIs/scripts/LLMs without forcing them to rerun heading scans.
        """

        xs = [str(x) for x in (lines or [])]
        if not xs:
            return {}

        scan = self._md_heading_scan(xs)
        if not scan:
            return {}

        seen_heading_ids: dict[str, int] = {}
        heading_entries: list[tuple[int, dict[str, Any]]] = []
        stack: list[dict[str, Any]] = []
        for line0, line1, level, title, explicit_fragment, col0 in scan:
            stack = stack[: max(0, int(level) - 1)]
            resolved_fragment = str(explicit_fragment or md_heading_auto_id(title, seen=seen_heading_ids))
            source_kind = 'atx' if int(line1) <= int(line0) + 1 else 'setext'
            frag_source = 'explicit' if str(explicit_fragment) else 'auto'
            node = {
                'title': str(title),
                'fragment': str(resolved_fragment),
                'level': int(level),
            }
            stack.append(node)
            heading_entries.append(
                (
                    int(line0),
                    {
                        'kind': 'section',
                        'heading_line': int(line0),
                        'heading_end_line': max(int(line0), int(line1) - 1),
                        'heading_col': int(col0),
                        'level': int(level),
                        'title': str(title),
                        'fragment': str(resolved_fragment),
                        'explicit_fragment': str(explicit_fragment),
                        'fragment_source': str(frag_source),
                        'source_kind': str(source_kind),
                        'path': ' › '.join(str(part.get('title', '') or '') for part in stack if str(part.get('title', '') or '')),
                        'path_titles': [str(part.get('title', '') or '') for part in stack if str(part.get('title', '') or '')],
                    },
                )
            )

        out: dict[int, dict[str, Any]] = {}
        current: dict[str, Any] | None = None
        entry_idx = 0
        for line_idx in range(len(xs)):
            while entry_idx < len(heading_entries) and int(heading_entries[entry_idx][0]) <= int(line_idx):
                current = dict(heading_entries[entry_idx][1])
                entry_idx += 1
            if current is not None:
                out[int(line_idx)] = dict(current)
        return out

    def _md_heading_line_roles(self, lines: list[object]) -> dict[int, tuple[str, int]]:
        """Return tiny heading render roles keyed by source line index.

        Roles are ``(role, level)`` where ``role`` is one of:
        - ``"title"`` for ATX heading lines and the title lines of setext headings
        - ``"underline"`` for the ``===`` / ``---`` underline line of a setext heading

        This is a tiny shared compatibility helper for docs/help rendering so
        setext headings can reuse the same heading scan the docs browser already
        trusts for titles, outline rows, fragments, and heading breadcrumbs.
        """

        out: dict[int, tuple[str, int]] = {}
        for line0, line1, level, _title, _frag, _col0 in self._md_heading_scan(lines):
            if int(line1) <= int(line0) + 1:
                out[int(line0)] = ("title", int(level))
                continue
            for i in range(int(line0), max(int(line0), int(line1) - 1)):
                out[int(i)] = ("title", int(level))
            out[max(int(line0), int(line1) - 1)] = ("underline", int(level))
        return out

    def _md_fenced_code_line_roles(self, lines: list[object]) -> dict[int, str]:
        """Return tiny fenced-code render roles keyed by source line index.

        Roles are one of:
        - ``"fence"`` for the opening/closing fence lines
        - ``"body"`` for interior lines of the fenced block

        This intentionally reuses the same tiny fence policy already trusted by
        docs/help navigation and link-underlining precedence, so live docs/help
        rendering can make fenced examples visibly code-ish without growing a
        second fence parser in the TUI.
        """

        xs = [str(x) for x in (lines or [])]
        if not xs:
            return {}

        out: dict[int, str] = {}
        in_fence = False
        fence_ch = ''
        fence_len = 0

        for i, s in enumerate(xs):
            if not in_fence:
                m = _FENCE_OPEN_RE.match(s)
                if m is None:
                    continue
                fence = str(m.group('fence') or '')
                if not fence:
                    continue
                in_fence = True
                fence_ch = fence[0]
                fence_len = len(fence)
                out[int(i)] = 'fence'
                continue

            if re.match(rf"^[ ]{{0,3}}{re.escape(fence_ch)}{{{int(fence_len)},}}[     ]*$", s):
                out[int(i)] = 'fence'
                in_fence = False
                fence_ch = ''
                fence_len = 0
                continue

            out[int(i)] = 'body'

        return out

    def _md_block_entries_by_line(self, lines: list[object]) -> dict[int, list[dict[str, Any]]]:
        """Return tiny parsed block-ish docs/help metadata keyed by line index.

        This stays deliberately source-view-first: it reuses the same tiny fence,
        HTML-block, and indented-code scans Micromax already trusts for docs/help
        precedence and styling, but packages the visible rows as explicit entries
        so future UIs/scripts/LLMs do not have to infer fence info strings or
        block grouping from `line_role` alone.
        """

        xs = [str(x) for x in (lines or [])]
        if not xs:
            return {}

        html_block_flags = md_html_block_line_flags(xs)
        indented_code_flags = md_indented_code_line_flags(xs, html_block_flags=html_block_flags)
        out: dict[int, list[dict[str, Any]]] = {}

        in_fence = False
        fence_ch = ''
        fence_len = 0
        fence_info_string = ''
        fence_language = ''
        fence_block_index = 0
        for i, s in enumerate(xs):
            if not in_fence:
                m = _FENCE_OPEN_RE.match(s)
                if m is None:
                    continue
                fence = str(m.group('fence') or '')
                if not fence:
                    continue
                fence_block_index += 1
                in_fence = True
                fence_ch = fence[0]
                fence_len = len(fence)
                rest = str(m.group('rest') or '')
                info_string = rest.strip(' \t')
                language = str(info_string.split()[0]) if info_string else ''
                fence_info_string = str(info_string)
                fence_language = str(language)
                out.setdefault(int(i), []).append(
                    {
                        'kind': 'fenced-code',
                        'role': 'opener',
                        'block_index': int(fence_block_index),
                        'start': int(m.start('fence')),
                        'end': int(m.end('fence')),
                        'text': str(s),
                        'marker': str(fence_ch),
                        'marker_kind': str(md_fenced_code_marker_kind(fence_ch)),
                        'marker_count': int(fence_len),
                        'indent': int(m.start('fence')),
                        'info_string': str(fence_info_string),
                        'language': str(fence_language),
                        'has_language': 1 if fence_language else 0,
                    }
                )
                continue

            m_close = re.match(rf"^(?P<indent>[ ]{{0,3}})(?P<fence>{re.escape(fence_ch)}{{{int(fence_len)},}})(?P<trailing>[ \t]*)$", s)
            if m_close is not None:
                fence = str(m_close.group('fence') or '')
                out.setdefault(int(i), []).append(
                    {
                        'kind': 'fenced-code',
                        'role': 'closer',
                        'block_index': int(fence_block_index),
                        'start': int(m_close.start('fence')),
                        'end': int(m_close.end('fence')),
                        'text': str(s),
                        'marker': str(fence_ch),
                        'marker_kind': str(md_fenced_code_marker_kind(fence_ch)),
                        'marker_count': int(len(fence)),
                        'indent': int(m_close.start('fence')),
                        'info_string': str(fence_info_string),
                        'language': str(fence_language),
                        'has_language': 1 if fence_language else 0,
                    }
                )
                in_fence = False
                fence_ch = ''
                fence_len = 0
                fence_info_string = ''
                fence_language = ''
                continue

            out.setdefault(int(i), []).append(
                {
                    'kind': 'fenced-code',
                    'role': 'body',
                    'block_index': int(fence_block_index),
                    'start': 0,
                    'end': int(len(s)),
                    'text': str(s),
                    'marker': str(fence_ch),
                    'marker_kind': str(md_fenced_code_marker_kind(fence_ch)),
                    'marker_count': int(fence_len),
                    'info_string': str(fence_info_string),
                    'language': str(fence_language),
                    'has_language': 1 if fence_language else 0,
                }
            )

        html_block_index = 0
        in_html = False
        for i, flag in enumerate(html_block_flags):
            if not flag:
                in_html = False
                continue
            if not in_html:
                html_block_index += 1
                in_html = True
            s = xs[i]
            out.setdefault(int(i), []).append(
                {
                    'kind': 'html-block',
                    'role': 'line',
                    'block_index': int(html_block_index),
                    'start': 0,
                    'end': int(len(s)),
                    'text': str(s),
                }
            )

        indented_code_index = 0
        in_indented = False
        for i, flag in enumerate(indented_code_flags):
            if not flag:
                in_indented = False
                continue
            if not in_indented:
                indented_code_index += 1
                in_indented = True
            s = xs[i]
            leading = re.match(r'^[ \t]+', s)
            indent_text = str(leading.group(0) or '') if leading else ''
            out.setdefault(int(i), []).append(
                {
                    'kind': 'indented-code',
                    'role': 'line',
                    'block_index': int(indented_code_index),
                    'start': 0,
                    'end': int(len(s)),
                    'text': str(s),
                    'indent_text': str(indent_text),
                    'indent_width': int(len(indent_text)),
                }
            )

        return out

    def _md_definition_entries_by_line(self, lines: list[object]) -> dict[int, list[dict[str, Any]]]:
        """Return tiny parsed markdown definition metadata keyed by line index.

        This stays intentionally small and reuses the same tiny definition scans
        already trusted by docs/help navigation and live TUI styling. Starter
        rows carry the visible marker token plus normalized ids/targets;
        continuation rows carry the owning definition id so future UIs/scripts/
        LLMs can tell which wrapped reference or indented footnote body they are
        looking at without reparsing visible prose.
        """

        xs = list(lines)
        if not xs:
            return {}

        fence_flags = md_fenced_code_line_flags(xs)
        html_block_flags = md_html_block_line_flags(xs)
        comment_spans = md_html_comment_line_spans(xs)
        out: dict[int, list[dict[str, Any]]] = {}

        for i, ln in enumerate(xs):
            if i < len(fence_flags) and fence_flags[i]:
                continue
            if i < len(html_block_flags) and html_block_flags[i]:
                continue
            s = str(ln)
            col0 = md_leading_spaces_upto3(s)
            if col0 is None:
                continue
            spans = comment_spans[i] if i < len(comment_spans) else []
            if md_span_contains(spans, int(col0), int(col0) + 1):
                continue

            m_fn = re.match(r"\[\^(?P<id>[^\]]+)\]\s*:\s*", s[col0:])
            if m_fn:
                rid = self._md_norm_ref_id(m_fn.group('id') or '')
                if rid:
                    a = int(col0)
                    match_text = str(m_fn.group(0) or '')
                    render_b = int(col0) + int(m_fn.end())
                    colon_offset = int(match_text.find(':'))
                    b = int(col0) + (colon_offset + 1 if colon_offset >= 0 else int(m_fn.end()))
                    marker_text = str(s[a:b])
                    starter = {
                        'kind': 'footnote-definition',
                        'role': 'starter',
                        'id': str(rid),
                        'start': int(a),
                        'end': int(b),
                        'text': marker_text,
                        'render_end': int(render_b),
                        'target': f'#^{rid}',
                        'target_kind': 'footnote',
                        'target_doc': '',
                        'target_fragment': f'^{rid}',
                    }
                    out.setdefault(int(i), []).append(starter)

                    j = int(i) + 1
                    continuation_index = 0
                    while j < len(xs):
                        if j < len(fence_flags) and fence_flags[j]:
                            break
                        if j < len(html_block_flags) and html_block_flags[j]:
                            break
                        sj = str(xs[j])
                        if not sj.strip():
                            break
                        spans_j = comment_spans[j] if j < len(comment_spans) else []
                        stripped = sj.lstrip(' ')
                        if sj.startswith('\t'):
                            stripped = sj[1:]
                        elif len(sj) - len(stripped) < 4:
                            break
                        first_col = len(sj) - len(stripped)
                        if md_span_contains(spans_j, int(first_col), int(first_col) + 1):
                            break
                        continuation_index += 1
                        out.setdefault(int(j), []).append(
                            {
                                'kind': 'footnote-definition-cont',
                                'role': 'continuation',
                                'parent_kind': 'footnote-definition',
                                'id': str(rid),
                                'continuation_index': int(continuation_index),
                                'start': 0,
                                'end': int(len(sj)),
                                'text': str(sj),
                                'target': f'#^{rid}',
                                'target_kind': 'footnote',
                                'target_doc': '',
                                'target_fragment': f'^{rid}',
                            }
                        )
                        j += 1
                    continue

            if col0 >= len(s) or s[col0:col0 + 1] != '[' or md_backslash_escaped(s, col0):
                continue
            span = md_balanced_span(s, col0, opener='[', closer=']')
            if span is None:
                continue
            a, b = span
            k = b
            while k < len(s) and s[k].isspace():
                k += 1
            if s[k:k + 1] != ':':
                continue
            raw_id = s[a + 1:b - 1]
            if not md_link_label_has_text(raw_id):
                continue
            rid = self._md_norm_ref_id(raw_id)
            if not rid:
                continue

            target, used_lines = md_reference_def_target_info(
                s[k + 1 :],
                md_docs_continuation_line(xs, i + 1, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans),
                md_docs_continuation_line(xs, i + 2, fence_flags=fence_flags, html_block_flags=html_block_flags, comment_spans=comment_spans),
            )
            if not target:
                continue
            resolved = md_help_link_target_info(target)
            marker_text = str(s[int(a):int(k + 1)])
            starter = {
                'kind': 'reference-definition',
                'role': 'starter',
                'id': str(rid),
                'start': int(a),
                'end': int(k + 1),
                'text': marker_text,
                'target': str(target),
                'target_kind': str(resolved.get('target_kind', '') or ''),
                'target_doc': str(resolved.get('doc', '') or ''),
                'target_fragment': str(resolved.get('fragment', '') or ''),
            }
            out.setdefault(int(i), []).append(starter)
            for off in range(1, int(used_lines) + 1):
                cont_line = int(i) + int(off)
                if 0 <= cont_line < len(xs):
                    sj = str(xs[cont_line])
                    out.setdefault(cont_line, []).append(
                        {
                            'kind': 'reference-definition-cont',
                            'role': 'continuation',
                            'parent_kind': 'reference-definition',
                            'id': str(rid),
                            'continuation_index': int(off),
                            'start': 0,
                            'end': int(len(sj)),
                            'text': str(sj),
                            'target': str(target),
                            'target_kind': str(resolved.get('target_kind', '') or ''),
                            'target_doc': str(resolved.get('doc', '') or ''),
                            'target_fragment': str(resolved.get('fragment', '') or ''),
                        }
                    )

        return out

    def _md_definition_line_roles(self, lines: list[object]) -> dict[int, tuple[str, int, int]]:
        """Return tiny markdown definition render roles keyed by source line index.

        Roles are ``(role, col0, col1)`` where ``role`` is one of:
        - ``"reference"`` for reference-definition starter lines
        - ``"reference-cont"`` for tiny wrapped destination/title continuation lines
        - ``"footnote"`` for footnote-definition starter lines
        - ``"footnote-cont"`` for tiny indented footnote continuation lines

        ``col0:col1`` marks the starter token span to emphasize on definition
        opener lines (for example ``[visionref]:`` or ``[^note]:``). Continuation
        lines use ``0:0``.

        This intentionally reuses the same tiny shared definition logic already
        trusted by docs/help navigation instead of adding another render-only
        parser path in the TUI.
        """

        out: dict[int, tuple[str, int, int]] = {}
        for idx, entries in self._md_definition_entries_by_line(lines).items():
            if not entries:
                continue
            entry = dict(entries[0])
            kind = str(entry.get('kind', '') or '')
            if kind == 'reference-definition':
                out[int(idx)] = ('reference', int(entry.get('start', 0) or 0), int(entry.get('end', 0) or 0))
            elif kind == 'reference-definition-cont':
                out[int(idx)] = ('reference-cont', 0, 0)
            elif kind == 'footnote-definition':
                out[int(idx)] = ('footnote', int(entry.get('start', 0) or 0), int(entry.get('render_end', entry.get('end', 0)) or 0))
            elif kind == 'footnote-definition-cont':
                out[int(idx)] = ('footnote-cont', 0, 0)
        return out

    def _help_heading_targets(self, eb: "EditorBuffer") -> dict[str, tuple[int, int]]:
        """Return fragment-id -> (line1, col1) for headings in a docs buffer."""

        seen: dict[str, int] = {}
        out: dict[str, tuple[int, int]] = {}
        for line0, _level, title, explicit_id, col0 in self._md_heading_entries(eb.buf.lines):
            frag = str(explicit_id or md_heading_auto_id(title, seen=seen)).strip()
            if not frag:
                continue
            out[frag.casefold()] = (int(line0) + 1, int(col0) + 1)
        return out

    def _jump_current_buffer_to(self, line1: int, col1: int = 1) -> bool:
        """Move the primary cursor to 1-based ``line1:col1`` (best-effort)."""

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        new_c = eb.buf.clamp(Cursor(max(0, int(line1) - 1), max(0, int(col1) - 1)))
        cur = eb.cursors[eb.primary]
        if (new_c.line, new_c.col) != (cur.line, cur.col) and bool(self.options.get("jumplist.auto", local=eb.local_options)):
            self.push_jump()
            eb.cursors[eb.primary] = new_c
            self.push_jump()
            return True
        eb.cursors[eb.primary] = new_c
        return True

    def _jump_help_fragment(self, frag: str, *, push_history: bool = True) -> bool:
        """Jump to ``#fragment`` in the current docs buffer (best-effort)."""

        topic = self.current_help_doc_topic()
        if not topic:
            self.message("helpfollow: not in a docs buffer")
            return False
        eb = self.cur()
        want = unquote(str(frag or "").strip()).strip()
        if want.startswith("#"):
            want = want[1:].strip()
        if not want:
            return False

        targets = self._help_heading_targets(eb)
        pos = targets.get(want.casefold())
        if pos is None:
            footdefs = self._md_footnote_defs(eb.buf.lines)
            foot_key = str(want)
            if foot_key.startswith('^'):
                foot_key = foot_key[1:]
            pos = footdefs.get(md_norm_ref_id(foot_key))
        if pos is None:
            self.message(f"helpjump: no section or footnote: #{want}")
            return False
        line1, col1 = pos
        return self._jump_help_target(line1, col1, push_history=push_history)

    def _help_heading_fragments_by_line(self) -> dict[int, str]:
        """Return heading-line -> resolved fragment ids for the current docs page."""

        topic = self.current_help_doc_topic()
        if not topic:
            return {}
        eb = self.cur()
        nlines = len(eb.buf.lines)
        if (
            topic == self._help_heading_fragment_cache_topic
            and nlines == self._help_heading_fragment_cache_nlines
        ):
            return dict(self._help_heading_fragment_cache)

        seen: dict[str, int] = {}
        out: dict[int, str] = {}
        for line0, _level, title, explicit_id, _col0 in self._md_heading_entries(eb.buf.lines):
            frag = str(explicit_id or md_heading_auto_id(title, seen=seen)).strip()
            if frag:
                out[int(line0) + 1] = frag

        self._help_heading_fragment_cache_topic = str(topic)
        self._help_heading_fragment_cache_nlines = int(nlines)
        self._help_heading_fragment_cache = dict(out)
        return dict(out)

    def _help_heading_path_for_line(self, line1: int) -> str:
        """Return the nearest heading breadcrumb for 1-based line number."""

        line = max(1, int(line1))
        idx = self._help_heading_paths()
        if not idx:
            return "Top"
        lines = [n for n, _p in idx]
        j = int(bisect_right(lines, line)) - 1
        if j < 0:
            return "Top"
        try:
            return str(idx[j][1] or "Top")
        except Exception:
            return "Top"

    def _help_outline_sections_by_line(self) -> dict[int, str]:
        """Return heading-line -> parent breadcrumb labels for outline rows.

        Unlike docs-link heading labels, outline grouping keeps the document H1 in
        the parent breadcrumb so child H2 rows on large docs pages do not all
        collapse back into a generic ``Top`` bucket.
        """

        topic = self.current_help_doc_topic()
        if not topic:
            return {}
        eb = self.cur()
        nlines = len(eb.buf.lines)
        if (
            topic == self._help_outline_section_cache_topic
            and nlines == self._help_outline_section_cache_nlines
        ):
            return dict(self._help_outline_section_cache)

        out: dict[int, str] = {}
        stack: list[str] = []
        for line0, level, title, _frag, _col0 in self._md_heading_entries(eb.buf.lines):
            lvl = max(1, min(int(level), 6))
            stack = stack[: max(0, lvl - 1)]
            parent = " › ".join(stack).strip() or "Top"
            out[int(line0) + 1] = parent
            stack.append(str(title))

        self._help_outline_section_cache_topic = str(topic)
        self._help_outline_section_cache_nlines = int(nlines)
        self._help_outline_section_cache = dict(out)
        return dict(out)

    def help_outline_section_label(self, row: list[str]) -> str:
        """Section label for a help-outline row based on parent headings."""

        try:
            info = str(row[3] if len(row) > 3 else "")
            if ":" in info:
                line_s, _col_s = info.split(":", 1)
                line = int(line_s)
                return str(self._help_outline_sections_by_line().get(line, "Top") or "Top")
        except Exception:
            pass
        return "Top"

    def _help_outline_query_meta(self, row: list[str]) -> str:
        """Hidden parent-breadcrumb metadata used to rank heading queries.

        The visible row shape stays small (`[title kind menu info]`), but outline,
        navigator, and `helpjump` queries should still be able to match parent
        breadcrumb terms such as ``Guide Links`` or ``Guide Deep dive``.

        This deliberately favors the *parent* breadcrumb over the full path so a
        query like ``Guide Links`` still ranks the actual ``Links`` heading above
        deeper descendants such as ``Deep dive`` that merely live under that path.
        """

        parts: list[str] = []
        section = str(self.help_outline_section_label(row) or "")
        if section and section != "Top":
            parts.append(section)
        menu = str(row[2] if len(row) > 2 else "")
        if menu:
            parts.append(menu)
        info = str(row[3] if len(row) > 3 else "")
        if info:
            parts.append(info)
            if ":" in info:
                try:
                    line_s, _col_s = info.split(":", 1)
                    frag = str(self._help_heading_fragments_by_line().get(int(line_s), "") or "")
                    if frag:
                        parts.append(frag)
                except Exception:
                    pass
        return " ".join(part for part in parts if part).strip()

    def _help_outline_row_sort_key(self, row: list[str], query: str) -> RowSortKey | None:
        q = str(query or "").strip()
        if q == "":
            return (0, 0, 0, 0, 0, 0, 0, 0, 0, "")

        name = str(row[0] if row else "")
        name_key = self._completion_fuzzy_sort_key(name, q)
        if name_key is not None:
            return (0, *name_key, name.casefold())

        meta = self._help_outline_query_meta(row)
        multi_key = self._multi_term_field_key(
            [(0, name), (1, meta)],
            q,
            fallback_rank=1,
            tie_name=name,
        )
        if multi_key is not None:
            return multi_key

        if meta:
            folded_meta = meta.casefold()
            folded_q = q.casefold()
            if folded_q and folded_q in folded_meta:
                pos = folded_meta.find(folded_q)
                return (2, pos, pos, 0, 0, 0, 0, len(meta), len(name), name.casefold())

            meta_key = self._completion_fuzzy_sort_key(meta, q)
            if meta_key is not None:
                return (3, *meta_key, name.casefold())
        return None

    def _helplink_query_meta(self, row: list[str]) -> str:
        """Hidden heading/kind metadata used to rank docs-link queries.

        Link labels stay visibly small (``[label kind target info]``), but link
        pickers should still be able to reuse the same section context users can
        already see in docs pages and grouped picker headers. That lets queries
        like ``External micro editor`` or ``Reference Vision ref`` combine the
        link label with its nearest-heading context instead of forcing a bare
        label-only search.
        """

        parts: list[str] = []
        heading = str(self._helplink_heading_label(row) or "")
        if heading and heading != "Top":
            parts.append(heading)
        kind = str(self._helplink_kind_label(row) or "")
        if kind:
            parts.append(kind)
        target = str(row[2] if len(row) > 2 else "")
        if target:
            parts.append(target)
            info_map = md_help_link_target_info(target)
            target_doc = str(info_map.get("doc", "") or "")
            target_fragment = str(info_map.get("fragment", "") or "")
            if target_doc:
                title = self._help_doc_title_for_target(target_doc)
                if title:
                    parts.append(title)
            if target_fragment:
                if target_doc:
                    frag_titles = self._help_doc_heading_titles_for_target(target_doc)
                else:
                    frag_titles = self._help_heading_titles_by_fragment()
                frag_title = str(frag_titles.get(target_fragment, "") or "")
                if frag_title:
                    parts.append(frag_title)
        info = str(row[3] if len(row) > 3 else "")
        if info and " — " in info:
            parts.append(info.split(" — ", 1)[1])
        return " ".join(part for part in parts if part).strip()

    def _helplink_row_sort_key(self, row: list[str], query: str) -> RowSortKey | None:
        q = str(query or "").strip()
        if q == "":
            return (0, 0, 0, 0, 0, 0, 0, 0, 0, "")

        name = str(row[0] if row else "")
        name_key = self._completion_fuzzy_sort_key(name, q)
        if name_key is not None:
            return (0, *name_key, name.casefold())

        meta = self._helplink_query_meta(row)
        multi_key = self._multi_term_field_key(
            [(0, name), (1, meta)],
            q,
            fallback_rank=1,
            tie_name=name,
        )
        if multi_key is not None:
            return multi_key

        if meta:
            folded_meta = meta.casefold()
            folded_q = q.casefold()
            if folded_q and folded_q in folded_meta:
                pos = folded_meta.find(folded_q)
                return (2, pos, pos, 0, 0, 0, 0, len(meta), len(name), name.casefold())

            meta_key = self._completion_fuzzy_sort_key(meta, q)
            if meta_key is not None:
                return (3, *meta_key, name.casefold())
        return None

    def _helplink_heading_label(self, row: list[str]) -> str:
        """Section label for a docs link row based on nearest markdown heading."""

        try:
            info = str(row[3] if len(row) > 3 else "")
            if ":" in info:
                line_s, _col_s = info.split(":", 1)
                line = int(line_s)
                return self._help_heading_path_for_line(line)
        except Exception:
            pass
        return "Top"

    def helplink_section_label(self, row: list[str]) -> str:
        """Section label for docs-link pickers.

        Controlled by option `help.linksections`:
          - "kind" (default): Docs/Files/External
          - "heading": nearest heading breadcrumb (Top/Links/External links/...)
        """

        mode = str(self.options.get("help.linksections") or "kind").strip().lower()
        if mode == "heading":
            return self._helplink_heading_label(row)
        return self._helplink_kind_label(row)

    def help_link_section_rows_kind(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Grouped link rows by kind (Docs/Files/External)."""

        rows = self.help_link_rows(query, limit=limit)
        section_order = ["Docs", "Files", "External"]
        buckets: dict[str, list[list[str]]] = {label: [] for label in section_order}
        for row in rows:
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            label = self._helplink_kind_label(vals)
            buckets.setdefault(label, [])
            buckets[label].append(vals)
        out: list[list[object]] = []
        for label in section_order:
            items = buckets.get(label, [])
            if items:
                out.append([label, items])
        return out

    def help_link_section_rows_heading(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Grouped link rows by nearest markdown heading."""

        rows = self.help_link_rows(query, limit=limit)
        buckets: dict[str, list[list[str]]] = {}
        for row in rows:
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            label = self._helplink_heading_label(vals)
            if label not in buckets:
                buckets[label] = []
            buckets[label].append(vals)
        return [[label, items] for (label, items) in buckets.items() if items]

    def help_link_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Grouped link rows for the current docs/help buffer.

        Shape: [[label, rows] ...], where rows are [[label kind target info] ...].
        """

        mode = str(self.options.get("help.linksections") or "kind").strip().lower()
        if mode == "heading":
            return self.help_link_section_rows_heading(query, limit=limit)
        return self.help_link_section_rows_kind(query, limit=limit)

    def help_outline_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Grouped outline rows by their parent-heading breadcrumb label."""

        rows = self.help_outline_rows(query, limit=limit)
        return self._group_prompt_rows_by_section(
            rows,
            label_fn=self.help_outline_section_label,
        )

    def help_outline_rows(self, query: str = "", *, limit: int | None = None) -> list[list[str]]:
        """Return markdown headings in the current help/docs buffer as rows.

        Rows are: [title kind menu info]
          - title: heading text (without leading hashes)
          - kind: "heading"
          - menu: heading level marker ("h1".."h6")
          - info: "line:col" position (1-based)
        """

        topic = self.current_help_doc_topic()
        if not topic:
            return []
        eb = self.cur()
        rows: list[list[str]] = []
        for line0, level, title, _frag, col0 in self._md_heading_entries(eb.buf.lines):
            menu = f"h{level}"
            info = f"{int(line0)+1}:{int(col0)+1}"
            rows.append([title, "heading", menu, info])

        q = str(query or "").strip()
        if q:
            scored: list[tuple[RowSortKey, int, list[str]]] = []
            for idx, row in enumerate(rows):
                key = self._help_outline_row_sort_key(row, q)
                if key is None:
                    continue
                scored.append((key, idx, row))
            scored.sort(key=lambda item: (item[0], item[1]))
            rows = [r for _k, _i, r in scored]

        if limit is not None:
            return rows[: max(1, int(limit))]
        return rows

    def help_nav_section_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Return combined headings + link rows for the current docs/help buffer.

        Shape: ``[[label, rows] ...]``, where rows are in the familiar
        ``[name kind menu info]`` shape.

        Sections are ordered as:
          - heading breadcrumb groups from ``helpoutlinepick``
          - Docs/Files/External (or heading-grouped links)

        This keeps the combined navigator aligned with the dedicated outline and
        link pickers instead of collapsing all headings into one generic bucket.
        """

        # Split the total limit to keep both headings and links represented.
        head_cap: int | None
        link_cap: int | None
        if limit is None:
            head_cap = None
            link_cap = None
        else:
            lim = max(1, int(limit))
            head_cap = max(1, lim // 2)
            link_cap = max(1, lim - head_cap)

        heading_sections = self.help_outline_section_rows(query, limit=head_cap)
        # Reuse the same link grouping policy as `helplinkpick` so the
        # combined navigator stays consistent with the dedicated link picker.
        link_sections = self.help_link_section_rows(query, limit=link_cap)

        # helpnav polish: include the nearest heading breadcrumb in link-row info
        # so links are easier to scan and search (without changing helplink rows).
        for sec in link_sections:
            try:
                if not isinstance(sec, list) or len(sec) < 2:
                    continue
                rows = sec[1]
                if not isinstance(rows, list):
                    continue
                for row in rows:
                    if not isinstance(row, list) or len(row) < 4:
                        continue
                    info = str(row[3] or '')
                    if ':' not in info:
                        continue
                    try:
                        line_s, _col_s = info.split(':', 1)
                        line = int(line_s)
                    except Exception:
                        continue
                    crumb = self._help_heading_path_for_line(line)
                    if crumb and crumb != 'Top' and crumb not in info:
                        row[3] = f"{info} — {crumb}"
            except Exception:
                continue

        out: list[list[object]] = []
        for sec in heading_sections:
            try:
                if isinstance(sec, list) and len(sec) >= 2 and sec[1]:
                    out.append([sec[0], sec[1]])
            except Exception:
                continue
        # Preserve link-section order from help_link_section_rows.
        for sec in link_sections:
            try:
                if isinstance(sec, list) and len(sec) >= 2 and sec[1]:
                    out.append([sec[0], sec[1]])
            except Exception:
                continue
        return out

    def help_nav_section_summary_rows(self, query: str = "", *, limit: int | None = None) -> list[list[object]]:
        """Tiny broad summaries for the current docs/help navigator.

        This keeps the combined heading+link navigator inspectable at the same
        first-stop level as newer broad help/docs/plugin/hook summary helpers:
        callers can ask what current-doc navigation buckets exist *before*
        walking every grouped row or opening the picker.
        """

        return self._section_summary_rows(
            self.help_nav_section_rows(query, limit=limit),
            sample_detail_fn=self._section_summary_prompt_row_detail,
        )

    def help_nav_rows(self, query: str = "", *, limit: int | None = None) -> list[list[str]]:
        """Flattened combined docs navigator rows.

        This is used by the built-in help navigator picker (`helpnavpick`).
        """

        sections = self.help_nav_section_rows(query, limit=limit)
        flat: list[list[str]] = []
        for sec in sections:
            if not isinstance(sec, list) or len(sec) < 2:
                continue
            rows = sec[1]
            if not isinstance(rows, list):
                continue
            for row in rows:
                try:
                    vals = [str(x) for x in list(row[:4])]
                    while len(vals) < 4:
                        vals.append("")
                    flat.append(vals)
                except Exception:
                    continue

        if limit is not None:
            return flat[: max(1, int(limit))]
        return flat



    def close_buffer(self, name: str | None = None, *, force: bool = False) -> bool:
        """Close (delete) a buffer by name, or the active buffer when name is None.

        If the buffer is dirty, this uses a double-tap guard (unless force=True),
        mirroring the `quit` command's safety behavior.
        """
        target = str(name or (self.active or ""))
        if not target or target not in self.buffers:
            return False
        eb = self.buffers[target]
        try:
            self._guard_buffer_access(target, action="close", capability="cap.buffer-discard")
        except PermissionError as e:
            self.message(f"close: {e}")
            return False
        if eb.buf.dirty:
            try:
                require_buffer_discard_capability(self, "close", [target])
            except BufferCapabilityError as e:
                self.message(str(e))
                return False
        if eb.buf.dirty and not bool(force):
            if self._close_armed and self._close_armed_name == target:
                # proceed
                pass
            else:
                self._close_armed = True
                self._close_armed_name = target
                self.message(f"unsaved changes in: {target}; run `close` again or `close -f` to force")
                return False

        self._close_armed = False
        self._close_armed_name = ""

        self._remember_cursor_for_buffer(eb)
        self._remember_help_session_entry_for_buffer(eb)

        # Drop marks pointing at this buffer (keeps navigation helpers sane),
        # but do not let lower-authority scripts erase trusted/user marks by
        # closing a clean buffer that happens to contain them.
        try:
            self._guard_mark_buffer_cleanup(target, "close-buffer")
        except PermissionError as e:
            self.message(f"close: {e}")
            return False
        for mk, (bufname, _cur) in list(self.marks.items()):
            if bufname == target:
                del self.marks[mk]
                self._mark_authority.pop(mk, None)

        # Delete the buffer.
        del self.buffers[target]
        self._buffer_authority.pop(target, None)

        # Choose a new active buffer.
        if self.active == target:
            self._buffer_mru = [x for x in self._buffer_mru if x != target and x in self.buffers]
            nxt = self.previous_buffer_name()
            if nxt:
                self._activate_buffer(nxt)
            elif self.buffers:
                names = list(self.buffers.keys())
                self._activate_buffer(names[-1])
            else:
                self.new_buffer("*scratch*", "")
        else:
            self._buffer_mru = [x for x in self._buffer_mru if x in self.buffers]
        return True

    def buffer_names(self) -> list[str]:
        """Return all open buffer names in stable sorted order."""

        return sorted(str(name) for name in self.buffers.keys())

    def _buffer_detail_row_for_name(self, name: str) -> list[object] | None:
        """Return one tiny exact buffer-detail row for ``name``.

        The row stays intentionally small and reuses the same active/dirty/
        readonly/position policy already visible in plain ``buffers`` while
        adding the section/path/line-count cues humans otherwise only see by
        opening grouped picker state.
        """

        if not self._buffer_read_allowed(str(name)):
            return None
        eb = self.buffers.get(str(name))
        if eb is None:
            return None

        position = ""
        try:
            self._normalize_cursor_lists(eb)
            idx = int(getattr(eb, "primary", 0) or 0)
            cursors = list(getattr(eb, "cursors", []) or [])
            if idx < 0 or idx >= len(cursors):
                idx = 0
            c = cursors[idx] if cursors else Cursor(0, 0)
            position = f"{int(c.line) + 1}:{int(c.col)}"
        except Exception:
            position = ""

        dirty = 0
        readonly = 0
        try:
            dirty = 1 if bool(getattr(eb.buf, "dirty", False)) else 0
        except Exception:
            dirty = 0
        try:
            readonly = 1 if bool(self.is_protected_buffer(eb)) else 0
        except Exception:
            readonly = 0

        try:
            row = self._prompt_buffer_row(str(name))
            vals = [str(x) for x in list(row[:4])]
            while len(vals) < 4:
                vals.append("")
            section = self._buffer_section_label(vals)
            path = str(vals[3].split(" | ", 1)[0]).strip() if vals[3] else ""
        except Exception:
            section = "Buffers"
            path = str(getattr(eb.buf, "path", "") or "")

        try:
            line_count = int(len(getattr(eb.buf, "lines", []) or []))
        except Exception:
            line_count = 0

        return [
            str(name),
            position,
            1 if str(name) == str(self.active or "") else 0,
            int(dirty),
            int(readonly),
            str(section),
            str(path),
            int(line_count),
        ]

    def buffer_detail_row(self, name: str) -> list[object] | None:
        """Return one tiny exact buffer-detail row visible to this authority.

        This gives scripts/future UIs the same first-stop side-effect-free
        answer plain ``showbuffer NAME`` gives humans, instead of forcing them
        to scrape ``buffers`` inventory text or call mutating ``buffer NAME``.
        Lower-authority script callers see only same-origin buffers unless
        ``cap.buffer-read`` is enabled.
        """

        if not self._buffer_read_allowed(str(name)):
            return None
        return self._buffer_detail_row_for_name(str(name))

    def buffer_inventory_rows(self) -> list[list[object]]:
        """Return tiny inspectable buffer inventory rows.

        Rows are ``[name position active dirty readonly]`` where ``position`` is
        the current primary cursor as a small 1-based ``line:col`` label and the
        remaining fields are ``0`` / ``1`` flags mirroring the current plain
        `buffers` inventory cues.

        This deliberately complements the thinner raw ``buffer_names()`` surface
        instead of replacing it.
        """

        rows: list[list[object]] = []
        for name in self.visible_buffer_names():
            row = self._buffer_detail_row_for_name(str(name))
            if row is None:
                continue
            rows.append(list(row[:5]))
        return rows

    def _touch_buffer_mru(self, name: str) -> None:
        """Record that buffer `name` became active (best-effort)."""
        n = str(name or "").strip()
        if not n:
            return
        self._buffer_mru = [n] + [x for x in self._buffer_mru if x != n]
        if self.buffers:
            self._buffer_mru = [x for x in self._buffer_mru if x in self.buffers]

    def _activate_buffer(self, name: str) -> None:
        """Set active buffer and touch MRU (expects buffer exists)."""
        prev = self.buffers.get(str(self.active or "")) if self.active else None
        if prev is not None and str(self.active or "") != str(name):
            self._remember_cursor_for_buffer(prev)
            self._remember_help_session_entry_for_buffer(prev)
        self.active = str(name)
        self._touch_buffer_mru(str(name))

    def previous_buffer_name(self) -> str:
        """Return the most-recently-used *other* buffer name, or ''."""
        cur = str(self.active or "")
        for n in list(self._buffer_mru):
            if n and n != cur and n in self.buffers:
                return n
        return ""

    def close_buffers(self, names: list[str], *, keep: str | None = None) -> None:
        """Close many buffers (forcefully; caller handles dirty confirmation)."""
        close_set = {str(n) for n in names if str(n) in self.buffers}
        if not close_set:
            return

        dirty = [n for n in close_set if bool(getattr(self.buffers.get(n).buf, "dirty", False))]
        require_buffer_discard_capability(self, "close", dirty)

        for n in sorted(close_set):
            self._guard_buffer_access(n, action="close", capability="cap.buffer-discard")

        for n in sorted(close_set):
            self._guard_mark_buffer_cleanup(n, "close-buffer")

        for mk, (bn, _cur) in list(self.marks.items()):
            if bn in close_set:
                del self.marks[mk]
                self._mark_authority.pop(mk, None)

        for n in close_set:
            ebn = self.buffers.get(n)
            self._remember_cursor_for_buffer(ebn)
            self._remember_help_session_entry_for_buffer(ebn)
            if n in self.buffers:
                del self.buffers[n]
                self._buffer_authority.pop(n, None)

        self._buffer_mru = [x for x in self._buffer_mru if x in self.buffers]

        k = str(keep or "")
        if k and k in self.buffers:
            self._activate_buffer(k)
            return

        for n in list(self._buffer_mru):
            if n in self.buffers:
                self._activate_buffer(n)
                return

        if self.buffers:
            names2 = list(self.buffers.keys())
            self._activate_buffer(names2[-1])
        else:
            self.new_buffer("*scratch*", "")

    def switch_buffer(self, name: str) -> bool:
        """Make `name` the active buffer if it exists."""
        n = str(name)
        if n not in self.buffers:
            return False
        self._activate_buffer(n)
        return True

    def rename_buffer(self, old: str, new: str) -> bool:
        """Rename a buffer key (and update mark targets).

        This keeps buffer identity stable enough for marks and scripts while
        still allowing commands like `save as` to retitle the buffer.
        """
        o = str(old)
        n = str(new)
        if o not in self.buffers:
            return False
        if n == o:
            return True
        if n in self.buffers:
            # refuse to clobber
            return False
        try:
            self._guard_mark_buffer_cleanup(o, "rename-buffer")
        except PermissionError as e:
            self.message(f"rename buffer: {e}")
            return False
        auth = self._buffer_registration_authority(o)
        eb = self.buffers.pop(o)
        self._buffer_authority.pop(o, None)
        eb.name = n
        self.buffers[n] = eb
        self._buffer_authority[n] = auth
        if self.active == o:
            self._activate_buffer(n)
        # Update MRU entry (if any).
        self._buffer_mru = [n if x == o else x for x in self._buffer_mru]
        self._buffer_mru = [x for i,x in enumerate(self._buffer_mru) if x and x not in self._buffer_mru[:i]]
        # Update mark targets.
        for mk, (bn, cur) in list(self.marks.items()):
            if bn == o:
                self.marks[mk] = (n, Cursor(cur.line, cur.col))
        return True

    def mark_set(self, name: str) -> bool:
        """Set a named mark at the primary cursor in the active buffer."""
        mk = str(name or "").strip()
        if not mk:
            return False
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]
        target = (eb.name, Cursor(int(c.line), int(c.col)))
        current = self.marks.get(mk)
        if current is not None:
            if self._same_mark_target(current, target):
                # Idempotent repeats do not downgrade a trusted/user mark to a
                # lower-authority script/plugin mark.
                self._mark_authority.setdefault(mk, RuntimeRegistrationAuthority(script_context=False))
                return True
            self._guard_runtime_registration_mutation(
                kind="mark",
                target=mk,
                authority=self._mark_registration_authority(mk),
                current_kind="editor",
            )
        self.marks[mk] = target
        self._mark_authority[mk] = self._current_mark_authority()
        return True

    def mark_jump(self, name: str) -> bool:
        """Jump to a named mark, pushing the jumplist."""
        mk = str(name or "").strip()
        if not mk:
            return False
        if mk not in self.marks:
            return False
        self._guard_mark_access(mk, action="jump", capability="cap.mark-jump")
        buf_name, tgt = self.marks[mk]
        if buf_name not in self.buffers:
            return False
        # Save where we were.
        self.push_jump()
        self.switch_buffer(buf_name)
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        eb.primary = max(0, min(int(eb.primary), len(eb.cursors) - 1))
        eb.cursors[eb.primary] = eb.buf.clamp(Cursor(int(tgt.line), int(tgt.col)))
        eb.sel_anchors[eb.primary] = None
        return True

    def mark_rows(self) -> list[list[object]]:
        """Return rows for marks as [[name buffer line col] ...]."""
        rows: list[list[object]] = []
        for name in sorted(self.marks.keys()):
            if not self._mark_read_allowed(str(name)):
                continue
            bn, cur = self.marks[name]
            rows.append([str(name), str(bn), int(cur.line), int(cur.col)])
        return rows

    def _mark_detail_row_for_name(self, name: str) -> list[object] | None:
        """Return one tiny exact mark row for ``name`` when present."""

        mark_name = str(name or "")
        if mark_name == "" or mark_name not in self.marks:
            return None
        if not self._mark_read_allowed(mark_name):
            return None

        active_name = str(self.active or "")
        here_line = -1
        here_col = -1
        try:
            eb = self.cur()
            self._normalize_cursor_lists(eb)
            c = self.primary_cursor()
            if active_name == str(getattr(eb, 'name', '') or ''):
                here_line = int(c.line)
                here_col = int(c.col)
        except Exception:
            pass

        bn, cur = self.marks[mark_name]
        line_i = int(cur.line)
        col_i = int(cur.col)
        position = f"{line_i + 1}:{col_i}"
        preview = ""
        eb = self.buffers.get(str(bn))
        if eb is not None and 0 <= line_i < len(eb.buf.lines):
            preview = str(eb.buf.lines[line_i]).rstrip("\n").strip()
            if len(preview) > 80:
                preview = preview[:77] + "..."
        active = 1 if str(bn) == active_name else 0
        here = 1 if active and line_i == here_line and col_i == here_col else 0
        return [str(mark_name), str(bn), position, preview, int(active), int(here)]

    def mark_detail_row(self, name: str) -> list[object] | None:
        """Return one tiny exact mark-detail row.

        This gives scripts/future UIs the same first-stop side-effect-free
        answer plain ``showmark NAME`` gives humans, instead of forcing them to
        scrape ``marks`` inventory text or call mutating ``markjump NAME``.
        """

        return self._mark_detail_row_for_name(str(name))

    def mark_inventory_rows(self) -> list[list[object]]:
        """Return tiny inspectable mark inventory rows.

        Rows are ``[name buffer position preview active here]`` where ``position``
        is a small 1-based ``line:col`` label, ``preview`` is the trimmed source
        line at the mark when available, and ``active`` / ``here`` are ``0`` or
        ``1`` flags mirroring the current human-facing ``marks`` inventory cues.

        This deliberately complements the thinner raw ``mark_rows()`` surface
        instead of replacing it.
        """

        rows: list[list[object]] = []
        for name in sorted(self.marks.keys()):
            row = self._mark_detail_row_for_name(str(name))
            if row is None:
                continue
            rows.append(list(row))
        return rows

    def _mark_inventory_preview_summary(self) -> str:
        """Return one tiny live mark-inventory witness.

        Plain ``showmark`` is still a usage-shaped exact inspector, but its
        root entry point should not collapse back to generic command metadata
        when Micromax already knows the current mark set. Keep the preview
        compact and prefer a ``[here]`` or active mark when present so the
        summary highlights the navigation anchor most likely to matter next.
        """

        rows = [list(row) for row in self.mark_inventory_rows()]
        summary = self._count_label(len(rows), 'mark')
        if not rows:
            return summary

        def _score(row: list[object]) -> tuple[int, int, str]:
            name = str(row[0]) if len(row) >= 1 else ''
            try:
                active = int(row[4]) if len(row) >= 5 else 0
            except Exception:
                active = 0
            try:
                here = int(row[5]) if len(row) >= 6 else 0
            except Exception:
                here = 0
            return (
                0 if here else 1,
                0 if active else 1,
                name,
            )

        target = min(rows, key=_score)
        name = str(target[0]) if len(target) >= 1 else ''
        detail = self.mark_detail_row(name) if name else None
        if detail is None:
            return summary
        buffer_name = str(detail[1]) if len(detail) >= 2 else ''
        position = str(detail[2]) if len(detail) >= 3 else ''
        preview = str(detail[3]) if len(detail) >= 4 else ''
        try:
            active = int(detail[4]) if len(detail) >= 5 else 0
        except Exception:
            active = 0
        try:
            here = int(detail[5]) if len(detail) >= 6 else 0
        except Exception:
            here = 0
        if not name:
            return summary
        brief = name
        if buffer_name:
            brief += f' -> {buffer_name}'
        flags: list[str] = []
        if active:
            flags.append('active')
        if here:
            flags.append('here')
        if flags:
            brief += ' [' + ', '.join(flags) + ']'
        if position:
            brief += f' @ {position}'
        if preview:
            brief += f' — {preview}'
        return f"{summary} · {brief}"

    def cur(self) -> EditorBuffer:
        if self.active is None or self.active not in self.buffers:
            raise RuntimeError("No active buffer")
        return self.buffers[self.active]

    def primary_index(self) -> int:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        return int(eb.primary)

    def set_primary_index(self, i: int) -> None:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if not eb.cursors:
            eb.primary = 0
            return
        eb.primary = max(0, min(int(i), len(eb.cursors) - 1))
        self._normalize_cursor_lists(eb)

    def primary_cursor(self) -> Cursor:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        return eb.cursors[eb.primary]

    def format_cursor_target(self) -> str:
        """Return a tiny `name @ line:col` label for the current primary cursor."""
        eb = self.cur()
        name = str(getattr(eb.buf, "path", "") or getattr(eb, "name", "") or "").strip()
        c = self.primary_cursor()
        if name:
            return f"{name} @ {c.line + 1}:{c.col}"
        return f"{c.line + 1}:{c.col}"

    def format_help_target(self) -> str:
        """Return a tiny `topic @ line:col` label for the current help/doc cursor."""
        topic = str(self.current_help_doc_topic() or "").strip()
        c = self.primary_cursor()
        if topic:
            return f"{topic} @ {c.line + 1}:{c.col}"
        return self.format_cursor_target()

    def format_search_target(self, *, prefix: str = "find") -> str:
        """Return a tiny search-feedback label with target + optional `i/n` summary."""
        target = self.format_cursor_target()
        try:
            summary = str(self.search_position_model().get("summary", "") or "").strip()
        except Exception:
            summary = ""
        if summary:
            return f"{prefix}: {target} ({summary})"
        return f"{prefix}: {target}"

    @staticmethod
    def _count_label(n: int, singular: str, plural: str | None = None) -> str:
        n_i = int(n)
        if plural is None:
            plural = singular + "s"
        word = singular if n_i == 1 else plural
        return f"{n_i} {word}"

    def format_clipboard_feedback(
        self,
        *,
        verb: str,
        count: int,
        count_label: str,
        total_chars: int,
        include_target: bool = False,
    ) -> str:
        msg = f"{verb}: {self._count_label(count, count_label)}, {self._count_label(total_chars, 'char')}"
        if include_target:
            msg += f" -> {self.format_cursor_target()}"
        return msg

    def _alloc_cursor_id(self) -> int:
        cid = int(self._next_cursor_id)
        self._next_cursor_id += 1
        return cid

    def _normalize_cursor_lists(self, eb: EditorBuffer) -> None:
        """Normalize multi-cursor invariants.

        Invariants (rev14):
          - `cursors` + `sel_anchors` are the same length
          - list order is document order (line,col)
          - duplicate cursor positions are removed
          - `primary` points at the primary cursor
          - cursor and anchor positions are clamped to the buffer
        """

        # Keep sel_anchors aligned with cursors.
        if len(eb.sel_anchors) < len(eb.cursors):
            eb.sel_anchors.extend([None] * (len(eb.cursors) - len(eb.sel_anchors)))
        if len(eb.sel_anchors) > len(eb.cursors):
            eb.sel_anchors[:] = eb.sel_anchors[: len(eb.cursors)]

        # Keep cursor_ids aligned with cursors.
        if len(eb.cursor_ids) < len(eb.cursors):
            eb.cursor_ids.extend([self._alloc_cursor_id() for _ in range(len(eb.cursors) - len(eb.cursor_ids))])
        if len(eb.cursor_ids) > len(eb.cursors):
            eb.cursor_ids[:] = eb.cursor_ids[: len(eb.cursors)]

        if not eb.cursors:
            eb.cursors[:] = [Cursor(0, 0)]
            eb.sel_anchors[:] = [None]
            eb.cursor_ids[:] = [self._alloc_cursor_id()]
            eb.primary = 0

        # Clamp primary index.
        if eb.primary < 0:
            eb.primary = 0
        if eb.primary >= len(eb.cursors):
            eb.primary = max(0, len(eb.cursors) - 1)

        # Clamp cursor + anchor positions.
        items: list[tuple[Cursor, Cursor | None, int, bool, int]] = []
        for i, c in enumerate(eb.cursors):
            cc = eb.buf.clamp(Cursor(c.line, c.col))
            a = eb.sel_anchors[i]
            aa = eb.buf.clamp(Cursor(a.line, a.col)) if a is not None else None
            cid = int(eb.cursor_ids[i])
            items.append((cc, aa, cid, i == eb.primary, i))

        # Deduplicate by cursor position.
        chosen: dict[tuple[int, int], tuple[Cursor, Cursor | None, int, bool, int]] = {}
        for c, a, cid, is_primary, idx in items:
            key = (c.line, c.col)
            if key not in chosen:
                chosen[key] = (c, a, cid, is_primary, idx)
                continue
            c0, a0, cid0, p0, idx0 = chosen[key]

            # Prefer the primary cursor when merging duplicates, else earliest.
            take_new = False
            if is_primary and not p0:
                take_new = True
            elif is_primary == p0 and idx < idx0:
                take_new = True

            if take_new:
                # Preserve a non-empty anchor if possible.
                if a is None and a0 is not None:
                    a = a0
                chosen[key] = (c, a, cid, is_primary, idx)
            else:
                if a0 is None and a is not None:
                    chosen[key] = (c0, a, cid0, p0, idx0)

        deduped = list(chosen.values())
        deduped.sort(key=lambda t: (t[0].line, t[0].col, t[2]))

        # Rebuild lists + primary index.
        new_primary = 0
        for j, (_c, _a, _cid, p, _idx) in enumerate(deduped):
            if p:
                new_primary = j
                break

        eb.cursors[:] = [Cursor(c.line, c.col) for (c, _a, _cid, _p, _idx) in deduped]
        eb.sel_anchors[:] = [Cursor(a.line, a.col) if a is not None else None for (_c, a, _cid, _p, _idx) in deduped]
        eb.cursor_ids[:] = [int(cid) for (_c, _a, cid, _p, _idx) in deduped]
        eb.primary = new_primary

    # ----- selection (per cursor) -----
    def selection(self, i: int | None = None) -> Selection | None:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if i is None:
            i = eb.primary
        if i < 0 or i >= len(eb.cursors):
            return None
        a = eb.sel_anchors[i]
        if a is None:
            return None
        return Selection(a, eb.cursors[i])

    def has_selection(self, i: int | None = None) -> bool:
        """Return True if there is a non-empty selection.

        - i is None: any cursor
        - i >= 0: that cursor index
        """

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if i is not None:
            sel = self.selection(i)
            return sel is not None and not sel.is_empty()
        for j in range(len(eb.cursors)):
            sel = self.selection(j)
            if sel is not None and not sel.is_empty():
                return True
        return False

    def has_primary_selection(self) -> bool:
        """Return True if the primary cursor has a non-empty selection."""
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        sel = self.selection(None)
        return sel is not None and not sel.is_empty()

    def clear_selection(self, i: int | None = None) -> None:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if i is None:
            # clear all
            eb.sel_anchors[:] = [None] * len(eb.cursors)
            return
        if i == -1:
            i = eb.primary
        if 0 <= i < len(eb.sel_anchors):
            eb.sel_anchors[i] = None


    # ----- selection/cursor recovery stack -----
    def _normalize_selection_stack_authority(self, eb: EditorBuffer) -> None:
        """Keep the selection recovery stack provenance sidecar aligned."""

        missing = len(eb.sel_stack) - len(eb.sel_stack_authority)
        if missing > 0:
            eb.sel_stack_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del eb.sel_stack_authority[len(eb.sel_stack):]

    def _snapshot_selection_stack_authority(self, eb: EditorBuffer) -> tuple[RuntimeRegistrationAuthority, ...]:
        self._normalize_selection_stack_authority(eb)
        return tuple(self._clone_mark_authority(auth) for auth in eb.sel_stack_authority)

    def _restore_selection_stack_authority(
        self,
        eb: EditorBuffer,
        snapshot: tuple[RuntimeRegistrationAuthority, ...] | list[RuntimeRegistrationAuthority] | None,
    ) -> None:
        values = list(snapshot or [])
        eb.sel_stack_authority[:] = [self._clone_mark_authority(auth) for auth in values]
        self._normalize_selection_stack_authority(eb)

    def _guard_selection_stack_entry_mutation(self, eb: EditorBuffer, index: int, action: str) -> None:
        self._normalize_selection_stack_authority(eb)
        if not (0 <= int(index) < len(eb.sel_stack_authority)):
            return
        self._guard_runtime_registration_mutation(
            kind="selection recovery stack",
            target=f"{eb.name}:{int(index) + 1}:{action}",
            authority=self._clone_mark_authority(eb.sel_stack_authority[int(index)]),
            current_kind="editor",
        )

    def _guard_clear_saved_selections(self, eb: EditorBuffer) -> None:
        self._normalize_selection_stack_authority(eb)
        for idx in range(len(eb.sel_stack_authority)):
            self._guard_selection_stack_entry_mutation(eb, idx, "clear")

    def _authority_group_matches(self, authority: object, group: object) -> bool:
        """Return true when an authority row belongs to one runtime group."""

        raw = str(group or "")
        if not raw:
            return False
        return str(getattr(authority, "group", "") or "") == raw

    def _authority_with_group(
        self,
        authority: RuntimeRegistrationAuthority,
        group: object,
    ) -> RuntimeRegistrationAuthority:
        """Return an authority clone with only its cleanup group changed."""

        raw = str(group or "")
        return RuntimeRegistrationAuthority(
            script_context=bool(getattr(authority, "script_context", False)),
            plugin_load_root=(str(getattr(authority, "plugin_load_root", "") or "") or None),
            plugin_generation=(
                int(getattr(authority, "plugin_generation"))
                if getattr(authority, "plugin_generation", None) not in (None, "")
                else None
            ),
            plugin_replaces_generation=(
                int(getattr(authority, "plugin_replaces_generation"))
                if getattr(authority, "plugin_replaces_generation", None) not in (None, "")
                else None
            ),
            script_origin_id=(str(getattr(authority, "script_origin_id", "") or "") or None),
            group=(raw or None),
        )

    def _remove_selection_stack_rows_for_authority(
        self,
        eb: EditorBuffer,
        predicate: Callable[[RuntimeRegistrationAuthority], bool],
    ) -> int:
        """Prune saved-selection rows matched by *predicate*."""

        self._normalize_selection_stack_authority(eb)
        removed = 0
        kept_stack: list[tuple[list[Cursor], list[Cursor | None], list[int], int]] = []
        kept_authority: list[RuntimeRegistrationAuthority] = []
        for snap, authority in zip(list(eb.sel_stack), list(eb.sel_stack_authority)):
            auth = self._clone_mark_authority(authority)
            if predicate(auth):
                removed += 1
                continue
            kept_stack.append(snap)
            kept_authority.append(auth)
        if removed:
            eb.sel_stack[:] = kept_stack
            eb.sel_stack_authority[:] = kept_authority
        return int(removed)

    def _retag_selection_stack_group(self, eb: EditorBuffer, old: object, new: object) -> int:
        self._normalize_selection_stack_authority(eb)
        changed = 0
        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        for idx, authority in enumerate(list(eb.sel_stack_authority)):
            if not self._authority_group_matches(authority, old_s):
                continue
            eb.sel_stack_authority[idx] = self._authority_with_group(authority, new_s)
            changed += 1
        return int(changed)

    def push_selections(self) -> None:
        """Push the current cursor+selection state onto a small stack.

        This is inspired by selection-oriented editors where it's easy to
        accidentally clear/merge selections; having a tiny recovery stack is
        a cheap, testable escape hatch. This stack is *not* part of undo.
        """

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        snap = (
            [Cursor(c.line, c.col) for c in eb.cursors],
            [Cursor(a.line, a.col) if a else None for a in eb.sel_anchors],
            [int(x) for x in eb.cursor_ids],
            int(eb.primary),
        )
        self._normalize_selection_stack_authority(eb)
        eb.sel_stack.append(snap)
        eb.sel_stack_authority.append(self._current_runtime_authority(kind="editor"))

    def pop_selections(self) -> bool:
        """Pop and restore the last saved cursor+selection state."""

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        self._normalize_selection_stack_authority(eb)
        if not eb.sel_stack:
            return False
        self._guard_selection_stack_entry_mutation(eb, len(eb.sel_stack) - 1, "pop")
        curs, anchors, cursor_ids, primary = eb.sel_stack.pop()
        if eb.sel_stack_authority:
            eb.sel_stack_authority.pop()
        eb.cursors[:] = [Cursor(c.line, c.col) for c in curs]
        eb.sel_anchors[:] = [Cursor(a.line, a.col) if a else None for a in anchors]
        eb.cursor_ids[:] = [int(x) for x in cursor_ids]
        eb.primary = int(primary)
        self._normalize_cursor_lists(eb)
        return True

    def clear_saved_selections(self) -> None:
        eb = self.cur()
        self._guard_clear_saved_selections(eb)
        eb.sel_stack.clear()
        eb.sel_stack_authority.clear()

    # ----- jumplist (navigation) -----
    def _normalize_jump_list_authority(self, eb: EditorBuffer) -> None:
        """Keep jumplist provenance aligned with the navigation register."""

        missing = len(eb.jump_list) - len(eb.jump_list_authority)
        if missing > 0:
            eb.jump_list_authority.extend(
                RuntimeRegistrationAuthority(script_context=False) for _ in range(missing)
            )
        elif missing < 0:
            del eb.jump_list_authority[len(eb.jump_list):]

    def _snapshot_jump_list_authority(self, eb: EditorBuffer) -> tuple[RuntimeRegistrationAuthority, ...]:
        self._normalize_jump_list_authority(eb)
        return tuple(self._clone_mark_authority(auth) for auth in eb.jump_list_authority)

    def _restore_jump_list_authority(
        self,
        eb: EditorBuffer,
        snapshot: tuple[RuntimeRegistrationAuthority, ...] | list[RuntimeRegistrationAuthority] | None,
    ) -> None:
        eb.jump_list_authority[:] = [self._clone_mark_authority(auth) for auth in list(snapshot or [])]
        self._normalize_jump_list_authority(eb)

    def _guard_jump_list_entry_mutation(self, eb: EditorBuffer, index: int, action: str) -> None:
        """Raise if current lower-authority code may not erase a jump row."""

        self._normalize_jump_list_authority(eb)
        if not (0 <= int(index) < len(eb.jump_list_authority)):
            return
        if str(action or "") in {"clear", "truncate", "drop-oldest", "drop", "evict"} and self._script_history_clear_capability_enabled():
            return
        self._guard_runtime_registration_mutation(
            kind="jumplist",
            target=f"{eb.name}:{int(index) + 1}:{action}",
            authority=self._clone_mark_authority(eb.jump_list_authority[int(index)]),
            current_kind="editor",
        )

    def _guard_jump_list_range_mutation(self, eb: EditorBuffer, start: int, end: int, action: str) -> None:
        self._normalize_jump_list_authority(eb)
        lo = max(0, int(start))
        hi = min(len(eb.jump_list_authority), int(end))
        for idx in range(lo, hi):
            self._guard_jump_list_entry_mutation(eb, idx, action)

    def _guard_jump_list_navigation(self, eb: EditorBuffer, target_index: int, action: str) -> None:
        """Raise when a lower-authority caller would move trusted jump state.

        Moving through the jumplist is not a text edit, but it is still a
        mutation of the user's navigation recovery register: it changes the
        current jump slot and restores cursor state from an older row.  Treat
        both the current row and the target row as protected state when a script
        or deferred plugin callback is active.
        """

        self._normalize_jump_list_authority(eb)
        current = int(eb.jump_index)
        if 0 <= current < len(eb.jump_list_authority):
            self._guard_jump_list_entry_mutation(eb, current, f"{action}-from")
        target = int(target_index)
        if target != current and 0 <= target < len(eb.jump_list_authority):
            self._guard_jump_list_entry_mutation(eb, target, f"{action}-to")

    def _snapshot_cursor_only(self, eb: EditorBuffer) -> tuple[list[Cursor], list[Cursor | None], list[int], int]:
        self._normalize_cursor_lists(eb)
        return (
            [Cursor(c.line, c.col) for c in eb.cursors],
            [Cursor(a.line, a.col) if a else None for a in eb.sel_anchors],
            [int(x) for x in eb.cursor_ids],
            int(eb.primary),
        )

    def _restore_cursor_only(
        self,
        eb: EditorBuffer,
        snap: tuple[list[Cursor], list[Cursor | None], list[int], int],
    ) -> None:
        curs, anchors, cursor_ids, primary = snap
        eb.cursors[:] = [Cursor(c.line, c.col) for c in curs]
        eb.sel_anchors[:] = [Cursor(a.line, a.col) if a else None for a in anchors]
        eb.cursor_ids[:] = [int(x) for x in cursor_ids]
        eb.primary = int(primary)
        self._normalize_cursor_lists(eb)

    def push_jump(self) -> bool:
        """Push current cursor/selection state onto the jumplist.

        This is the navigation sibling of undo: it tracks *where you were*.
        Inspired by Vim/Helix jump lists.
        """

        eb = self.cur()
        self._normalize_jump_list_authority(eb)
        snap = self._snapshot_cursor_only(eb)

        # Deduplicate consecutive identical entries.
        if eb.jump_list and eb.jump_index == len(eb.jump_list) - 1:
            if eb.jump_list[-1] == snap:
                return False

        # If we've jumped back, truncate the "forward" tail (browser/Vim semantics).
        if eb.jump_index >= 0 and eb.jump_index < len(eb.jump_list) - 1:
            self._guard_jump_list_range_mutation(eb, eb.jump_index + 1, len(eb.jump_list), "truncate")
            eb.jump_list[:] = eb.jump_list[: eb.jump_index + 1]
            eb.jump_list_authority[:] = eb.jump_list_authority[: eb.jump_index + 1]

        # Preflight bounded-history eviction before appending so a denied
        # script push cannot leave a 101st row behind after the guard fires.
        MAX_JUMPS = 100
        prospective_drop = max(0, (len(eb.jump_list) + 1) - MAX_JUMPS)
        if prospective_drop > 0:
            self._guard_jump_list_range_mutation(eb, 0, prospective_drop, "drop-oldest")

        eb.jump_list.append(snap)
        eb.jump_list_authority.append(self._current_runtime_authority(kind="editor"))
        eb.jump_index = len(eb.jump_list) - 1

        # Bounded size.
        if len(eb.jump_list) > MAX_JUMPS:
            drop = len(eb.jump_list) - MAX_JUMPS
            eb.jump_list[:] = eb.jump_list[drop:]
            eb.jump_list_authority[:] = eb.jump_list_authority[drop:]
            eb.jump_index = max(-1, eb.jump_index - drop)

        return True

    def jump_back(self) -> bool:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if eb.jump_index <= 0 or not eb.jump_list:
            return False
        target = int(eb.jump_index) - 1
        self._guard_jump_list_navigation(eb, target, "jumpback")
        eb.jump_index = target
        self._restore_cursor_only(eb, eb.jump_list[eb.jump_index])
        return True

    def jump_forward(self) -> bool:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if not eb.jump_list:
            return False
        if eb.jump_index < 0:
            return False
        if eb.jump_index >= len(eb.jump_list) - 1:
            return False
        target = int(eb.jump_index) + 1
        self._guard_jump_list_navigation(eb, target, "jumpforward")
        eb.jump_index = target
        self._restore_cursor_only(eb, eb.jump_list[eb.jump_index])
        return True

    def _peek_jump_navigation_detail_row(self, direction: str) -> list[object] | None:
        """Return the next back/forward jumplist row before navigation mutates it.

        Plain ``jumpback`` / ``jumpforward`` already know which visible history
        slot they are about to restore. Capture that exact pre-move row so the
        final success message can preserve the same slot/lane truth instead of
        collapsing back to a generic landed-target string.
        """

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        n = int(len(eb.jump_list))
        cur_i = int(eb.jump_index)
        if n <= 0 or cur_i < 0 or cur_i >= n:
            return None
        want_i = cur_i - 1 if str(direction) == 'back' else cur_i + 1
        if want_i < 0 or want_i >= n:
            return None
        return self.jump_detail_row(f"#{want_i + 1}")

    def jump_back_feedback(self) -> bool:
        """Jump backward and report the landed target or failure explicitly."""
        detail_row = self._peek_jump_navigation_detail_row('back')
        ok = self.jump_back()
        if ok:
            self.message(self.format_jump_picker_feedback("jumpback", "", detail_row=detail_row))
        else:
            self.message("jumpback: no earlier jump")
        return ok

    def jump_forward_feedback(self) -> bool:
        """Jump forward and report the landed target or failure explicitly."""
        detail_row = self._peek_jump_navigation_detail_row('forward')
        ok = self.jump_forward()
        if ok:
            self.message(self.format_jump_picker_feedback("jumpforward", "", detail_row=detail_row))
        else:
            self.message("jumpforward: no later jump")
        return ok

    def _format_undo_redo_feedback(self, verb: str, edit: Edit) -> str:
        desc = str(getattr(edit, "description", "") or "").strip() or "change"
        target = ""
        try:
            target_fn = getattr(edit, "target", None)
            if callable(target_fn):
                target = str(target_fn() or "").strip()
        except Exception:
            target = ""
        msg = f"{verb}: {desc}"
        if target:
            msg += f" -> {target}"
        return msg

    def _undo_redo_entry_authority(self, edit: Edit) -> RuntimeRegistrationAuthority:
        """Return replay authority attached to an undo/redo entry.

        Legacy in-memory entries from before the provenance field existed are
        treated as trusted/user entries.  New entries are stamped when they are
        recorded, using the same runtime authority model as marks, registers,
        keybindings, timers, and hooks.
        """

        return self._clone_mark_authority(getattr(edit, "authority", None))

    def _guard_undo_redo_replay(self, verb: str, edit: Edit) -> bool:
        """Return whether the current caller may replay ``edit``.

        Undo/redo is a destructive recovery register: replaying a trusted entry
        can erase user edits just as surely as clearing jump/message history can
        erase evidence.  Trusted interactive callers retain normal authority.
        Lower-authority scripts may replay only entries they own unless the
        explicit unsafe capability is enabled by trusted code.
        """

        if not self.in_script_context():
            return True
        try:
            if bool(self.options.get("cap.undo-redo")):
                return True
        except Exception:
            pass
        current = self._current_runtime_authority(kind="editor")
        target = self._undo_redo_entry_authority(edit)
        decision = script_runtime_mutation_policy(current, target)
        if decision.allowed:
            return True
        reason = str(decision.reason or "not owned by current script")
        self.message(f"{verb}: script context cannot replay undo history ({reason})")
        return False

    def undo_feedback(self) -> bool:
        edit = self.undo.peek_undo()
        if edit is None:
            self.message("undo: nothing to undo")
            return False
        if not self._guard_undo_redo_replay("undo", edit):
            return False
        if not self.undo.undo():
            self.message("undo: nothing to undo")
            return False
        self.message(self._format_undo_redo_feedback("undo", edit))
        return True

    def redo_feedback(self) -> bool:
        edit = self.undo.peek_redo()
        if edit is None:
            self.message("redo: nothing to redo")
            return False
        if not self._guard_undo_redo_replay("redo", edit):
            return False
        if not self.undo.redo():
            self.message("redo: nothing to redo")
            return False
        self.message(self._format_undo_redo_feedback("redo", edit))
        return True

    def jump_to_index(self, idx: int) -> bool:
        """Jump to an explicit jumplist entry (0-based index)."""
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        if not eb.jump_list:
            return False
        i = int(idx)
        if i < 0 or i >= len(eb.jump_list):
            return False
        self._guard_jump_list_navigation(eb, i, "jumpto")
        eb.jump_index = i
        self._restore_cursor_only(eb, eb.jump_list[eb.jump_index])
        try:
            self.ensure_cursor_visible()
        except Exception:
            pass
        return True

    def jump_info(self) -> tuple[int, int]:
        eb = self.cur()
        return int(eb.jump_index), int(len(eb.jump_list))

    def _jump_history_snapshot_parts(self, snap: tuple[list[Cursor], list[Cursor | None], list[int], int]) -> tuple[str, str]:
        """Return tiny ``(position, preview)`` text for one jumplist snapshot."""

        curs, _anchors, _cursor_ids, primary = snap
        if not curs:
            return ("", "")
        pi = int(primary) if 0 <= int(primary) < len(curs) else 0
        c = curs[pi]
        position = f"{int(c.line) + 1}:{int(c.col)}"
        preview = ""
        li = int(c.line)
        eb = self.cur()
        if 0 <= li < len(eb.buf.lines):
            preview = str(eb.buf.lines[li]).rstrip("\n").strip()
            if len(preview) > 80:
                preview = preview[:77] + "..."
        return (position, preview)

    def jump_history_rows(self) -> list[list[object]]:
        """Return a tiny ordered jumplist register for the current buffer.

        Rows are ``[lane depth index buffer position preview]`` where ``lane`` is
        one of ``current``, ``back``, or ``forward`` and ``depth`` is 0 for the
        current row or a 1-based actionable distance within the corresponding
        side of the jumplist.
        """

        try:
            eb = self.cur()
        except Exception:
            return []
        self._normalize_cursor_lists(eb)
        rows: list[list[object]] = []
        n = int(len(eb.jump_list))
        cur_i = int(eb.jump_index)
        if n <= 0 or cur_i < 0 or cur_i >= n:
            return rows

        def _append(idx0: int, lane: str, depth: int) -> None:
            snap = eb.jump_list[idx0]
            position, preview = self._jump_history_snapshot_parts(snap)
            rows.append([str(lane), int(depth), int(idx0) + 1, str(eb.name), position, preview])

        _append(cur_i, "current", 0)
        for depth, idx0 in enumerate(range(cur_i - 1, -1, -1), start=1):
            _append(int(idx0), "back", int(depth))
        for depth, idx0 in enumerate(range(cur_i + 1, n), start=1):
            _append(int(idx0), "forward", int(depth))
        return rows

    def jump_detail_row(self, query: str) -> list[object] | None:
        """Return one tiny exact jumplist row for a 1-based entry index.

        This gives scripts/future UIs the same first-stop side-effect-free
        answer plain ``showjump N`` gives humans, instead of forcing them to
        scrape the broader ``jumps`` register or reopen grouped ``jumppick``
        state just to inspect one known history entry.
        """

        raw_query = str(query or "")
        idx1 = self.parse_visible_index_token(raw_query)
        if idx1 is None:
            return None

        for row in self.jump_history_rows():
            try:
                row_idx = int(row[2]) if len(row) >= 3 else 0
            except Exception:
                row_idx = 0
            if row_idx != idx1:
                continue
            lane = str(row[0]) if row else ""
            try:
                depth = int(row[1]) if len(row) >= 2 else 0
            except Exception:
                depth = 0
            name = str(row[3]) if len(row) >= 4 else ""
            position = str(row[4]) if len(row) >= 5 else ""
            preview = str(row[5]) if len(row) >= 6 else ""
            return [raw_query, int(row_idx), lane, int(depth), name, position, preview]
        return None

    def _jump_inventory_preview_summary(self) -> str:
        """Return one tiny live jumplist witness.

        Plain ``showjump`` is still a usage-shaped exact inspector, but its
        root entry point should not collapse back to generic command metadata
        when Micromax already knows the current jumplist. Keep the preview
        compact and reuse the current exact jump row so prompt/runtime root
        paths stay aligned on one tiny truthful substrate.
        """

        rows = [list(row) for row in self.jump_history_rows()]
        summary = self._count_label(len(rows), 'jump')
        if not rows:
            return summary

        current = rows[0]
        try:
            index = int(current[2]) if len(current) >= 3 else 0
        except Exception:
            index = 0
        detail = self.jump_detail_row(f'#{index}') if index > 0 else None
        if detail is None:
            return summary
        brief = self._format_jump_navigation_brief(detail)
        preview = str(detail[6]) if len(detail) >= 7 else ''
        parts = [summary, brief]
        msg = ' · '.join(part for part in parts if str(part).strip())
        if preview:
            msg += f' — {preview}'
        return msg or summary

    def clear_jumps(self) -> None:
        eb = self.cur()
        self._guard_jump_list_range_mutation(eb, 0, len(eb.jump_list), "clear")
        eb.jump_list.clear()
        eb.jump_list_authority.clear()
        eb.jump_index = -1

    def _remove_jump_rows_for_authority(
        self,
        eb: EditorBuffer,
        predicate: Callable[[RuntimeRegistrationAuthority], bool],
    ) -> int:
        """Prune jumplist rows matched by *predicate* and repair current index."""

        self._normalize_jump_list_authority(eb)
        removed = 0
        old_index = int(eb.jump_index)
        kept_jumps: list[tuple[list[Cursor], list[Cursor | None], list[int], int]] = []
        kept_authority: list[RuntimeRegistrationAuthority] = []
        kept_old_indices: list[int] = []
        for idx, (snap, authority) in enumerate(zip(list(eb.jump_list), list(eb.jump_list_authority))):
            auth = self._clone_mark_authority(authority)
            if predicate(auth):
                removed += 1
                continue
            kept_jumps.append(snap)
            kept_authority.append(auth)
            kept_old_indices.append(int(idx))
        if not removed:
            return 0

        eb.jump_list[:] = kept_jumps
        eb.jump_list_authority[:] = kept_authority
        if not kept_old_indices:
            eb.jump_index = -1
        elif old_index < 0:
            eb.jump_index = -1
        elif old_index in kept_old_indices:
            eb.jump_index = kept_old_indices.index(old_index)
        else:
            before = [i for i, old in enumerate(kept_old_indices) if old < old_index]
            eb.jump_index = before[-1] if before else 0
        return int(removed)

    def _retag_jump_list_group(self, eb: EditorBuffer, old: object, new: object) -> int:
        self._normalize_jump_list_authority(eb)
        changed = 0
        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        for idx, authority in enumerate(list(eb.jump_list_authority)):
            if not self._authority_group_matches(authority, old_s):
                continue
            eb.jump_list_authority[idx] = self._authority_with_group(authority, new_s)
            changed += 1
        return int(changed)

    def remove_recovery_group(self, group: object) -> int:
        """Remove selection/jump recovery rows owned by a runtime group.

        Saved selections and jumplist entries are delayed navigation/recovery
        state.  They are not executable like macros, but unloading a plugin
        should not leave behind plugin-authored recovery rows that keep changing
        later editor navigation surfaces after the plugin's commands, keys,
        timers, hooks, prompts, and macros have been removed.
        """

        raw = str(group or "")
        if not raw:
            return 0
        removed = 0
        for eb in list(self.buffers.values()):
            removed += self._remove_selection_stack_rows_for_authority(
                eb,
                lambda authority, raw=raw: self._authority_group_matches(authority, raw),
            )
            removed += self._remove_jump_rows_for_authority(
                eb,
                lambda authority, raw=raw: self._authority_group_matches(authority, raw),
            )
        return int(removed)

    def retag_recovery_group(self, old: object, new: object) -> int:
        """Retag staged selection/jump recovery rows to the stable plugin group."""

        old_s = str(old or "")
        new_s = str(new or "")
        if not old_s or not new_s or old_s == new_s:
            return 0
        changed = 0
        for eb in list(self.buffers.values()):
            changed += self._retag_selection_stack_group(eb, old_s, new_s)
            changed += self._retag_jump_list_group(eb, old_s, new_s)
        return int(changed)

    def selection_range(self, i: int | None = None) -> tuple[Cursor, Cursor] | None:
        sel = self.selection(i)
        if sel is None:
            return None
        s, e = sel.normalized()
        if (s.line, s.col) == (e.line, e.col):
            return None
        return s, e

    def selection_text(self, i: int | None = None) -> str:
        rng = self.selection_range(i)
        if rng is None:
            return ""
        s, e = rng
        return self.cur().buf.get_range_text(s, e)

    def _all_selection_ranges(self) -> list[tuple[int, Cursor, Cursor]]:
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        out: list[tuple[int, Cursor, Cursor]] = []
        for i in range(len(eb.cursors)):
            rng = self.selection_range(i)
            if rng is None:
                continue
            s, e = rng
            out.append((i, s, e))
        return out

    def _delete_selections(self) -> bool:
        """Delete all non-empty selections across cursors."""
        eb = self.cur()
        ranges = self._all_selection_ranges()
        if not ranges:
            return False
        # Delete from bottom to top so earlier coordinates remain valid.
        ranges.sort(key=lambda t: (t[1].line, t[1].col), reverse=True)
        for i, s, e in ranges:
            eb.cursors[i] = eb.buf.delete_range(s, e)
            eb.sel_anchors[i] = None
        return True

    # ----- files -----
    def _parse_open_target(self, raw_path: str) -> tuple[str, Cursor | None]:
        """Parse a tiny micro-esque ``file:line[:col]`` open target.

        The policy stays intentionally conservative and shared-core:
        - gated by the ``parsecursor`` option
        - if the literal path already exists, keep it literal (so existing
          colon-containing filenames remain openable)
        - line numbers are 1-based, columns are 0-based
        - malformed suffixes stay literal paths
        """

        raw = str(raw_path or "")
        if not bool(self.options.get("parsecursor")):
            return (raw, None)

        try:
            literal = Path(raw).expanduser()
            if literal.exists():
                return (raw, None)
        except OSError:
            return (raw, None)

        parts = raw.rsplit(':', 2)
        path_part = ""
        line_s = ""
        col_s: str | None = None
        if len(parts) == 2 and parts[0] and parts[1].isdigit():
            path_part, line_s = parts
            col_s = None
        elif len(parts) == 3 and parts[0] and parts[1].isdigit() and parts[2].isdigit():
            path_part, line_s, col_s = parts
        else:
            return (raw, None)

        line_no = max(1, int(line_s or "1")) - 1
        col_no = max(0, int(col_s or "0"))
        return (path_part, Cursor(line_no, col_no))

    def _set_buffer_primary_cursor(self, eb: EditorBuffer, cur: Cursor) -> None:
        """Clamp/set the primary cursor and clear its selection."""
        self._normalize_cursor_lists(eb)
        idx = int(eb.primary)
        eb.cursors[idx] = eb.buf.clamp(Cursor(int(cur.line), int(cur.col)))
        eb.sel_anchors[idx] = None

    def _disk_hash_budget(self, eb: EditorBuffer) -> int:
        """Return the configured small-file hashing budget for freshness checks."""

        try:
            return max(0, int(self.options.get("save.checkexternal.hashmax", local=eb.local_options)))
        except Exception:
            return 0

    def _capture_disk_freshness(
        self,
        eb: EditorBuffer,
        path: str | Path,
        *,
        include_hash: bool = True,
    ) -> FileFreshness:
        """Capture the stat witness and optional small-file digest for ``path``."""

        budget = self._disk_hash_budget(eb) if include_hash else 0
        return capture_file_freshness(path, max_hash_bytes=budget)

    def _refresh_buffer_disk_signature(self, eb: EditorBuffer) -> None:
        """Refresh the buffer's on-disk freshness witness after open/save."""

        if not eb.buf.path:
            eb.disk_signature = None
            eb.disk_content_hash = None
            return
        try:
            fresh = self._capture_disk_freshness(eb, str(eb.buf.path))
        except OSError:
            eb.disk_signature = None
            eb.disk_content_hash = None
            return
        eb.disk_signature = fresh.signature
        eb.disk_content_hash = fresh.content_hash

    def buffer_disk_state(
        self,
        eb: EditorBuffer | None = None,
        *,
        path: str | None = None,
        use_buffer_witness: bool = True,
    ) -> dict[str, object]:
        """Return a tiny, user-facing disk freshness model for one buffer.

        ``save.checkexternal`` protects the write path, but users also need a
        cheap way to see that a clean buffer has gone stale before the next
        save attempt.  The model is intentionally stat-based and compact:

        - ``fresh`` means the current stat witness matches the last open/save;
        - ``changed`` means the path still exists but no longer matches;
        - ``missing`` means a previously-synced path disappeared;
        - ``new`` / ``pathless`` / ``untracked`` are non-warning states;
        - ``unknown`` records stat/symlink errors without guessing.
        """

        target = self.cur() if eb is None else eb
        path = str(path if path is not None else (getattr(target.buf, "path", "") or ""))
        previous = getattr(target, "disk_signature", None) if use_buffer_witness else None
        out: dict[str, object] = {
            "disk_state": "pathless",
            "disk_summary": "",
            "disk_changed": 0,
            "disk_missing": 0,
            "disk_known": 1 if previous is not None else 0,
            "disk_warning": 0,
            "disk_error": "",
        }
        if not path:
            return out

        try:
            # Status is rendered often; keep it stat-cheap.  The write path
            # still asks for the optional small-file digest so save remains the
            # stronger data-loss boundary.
            current_fresh = self._capture_disk_freshness(target, path, include_hash=False)
            current = current_fresh.signature
            current_hash = current_fresh.content_hash
        except OSError as e:
            out.update(
                {
                    "disk_state": "unknown",
                    "disk_summary": "disk:unknown",
                    "disk_warning": 1,
                    "disk_error": str(e),
                }
            )
            return out

        if is_missing_file_signature(current):
            if previous is None or is_missing_file_signature(previous):
                out["disk_state"] = "new"
            else:
                out.update(
                    {
                        "disk_state": "missing",
                        "disk_summary": "disk:missing",
                        "disk_missing": 1,
                        "disk_warning": 1,
                    }
                )
            return out

        if previous is None:
            out["disk_state"] = "untracked"
            return out

        changed = current != previous
        previous_hash = getattr(target, "disk_content_hash", None) if use_buffer_witness else None
        if not changed and previous_hash is not None and current_hash is not None:
            changed = current_hash != previous_hash
        if changed:
            out.update(
                {
                    "disk_state": "changed",
                    "disk_summary": "disk:changed",
                    "disk_changed": 1,
                    "disk_warning": 1,
                }
            )
            return out

        out["disk_state"] = "fresh"
        return out

    def disk_state_rows(self, *, include_fresh: bool = False) -> list[list[object]]:
        """Return per-buffer disk freshness rows for recovery dashboards.

        Rows are ``[name state warning changed missing dirty active path error]``.
        By default this returns only warning rows so a multi-buffer recovery
        check does not drown stale/missing buffers in ordinary fresh buffers.
        Pass ``include_fresh=True`` for a complete inventory.
        """

        rows: list[list[object]] = []
        for name in self.buffer_names():
            eb = self.buffers.get(str(name))
            if eb is None:
                continue
            state = self.buffer_disk_state(eb)
            state_name = str(state.get("disk_state", "") or "")
            warning = 1 if int(state.get("disk_warning", 0) or 0) else 0
            if not include_fresh and not warning:
                continue
            try:
                dirty = 1 if bool(getattr(eb.buf, "dirty", False)) else 0
            except Exception:
                dirty = 0
            path = str(getattr(eb.buf, "path", "") or "")
            rows.append(
                [
                    str(name),
                    state_name,
                    warning,
                    1 if int(state.get("disk_changed", 0) or 0) else 0,
                    1 if int(state.get("disk_missing", 0) or 0) else 0,
                    dirty,
                    1 if str(name) == str(self.active or "") else 0,
                    path,
                    str(state.get("disk_error", "") or ""),
                ]
            )
        return rows

    def _check_save_disk_fresh(self, eb: EditorBuffer, path: Path, *, force: bool = False) -> FileFreshness | None:
        """Refuse to overwrite a path that changed since the buffer synced."""

        if force:
            return None
        if not bool(self.options.get("save.checkexternal", local=eb.local_options)):
            return None
        previous = getattr(eb, "disk_signature", None)
        if previous is None:
            return None
        try:
            current = self._capture_disk_freshness(eb, path)
        except OSError as e:
            raise RuntimeError(f"could not check save target freshness: {e}") from e
        changed = current.signature != previous
        previous_hash = getattr(eb, "disk_content_hash", None)
        if not changed and previous_hash is not None and current.content_hash is not None:
            changed = current.content_hash != previous_hash
        if changed:
            raise RuntimeError(
                "file changed on disk; run `diff`, `revert!`, or `save!` to choose a recovery path"
            )
        return current

    def open_file(
        self,
        path: str,
        *,
        initial_cursor: Cursor | None = None,
        containment_root: str | Path | None = None,
    ) -> bool:
        parsed_path, parsed_cursor = self._parse_open_target(path)
        target_cursor = initial_cursor if initial_cursor is not None else parsed_cursor
        p = Path(str(parsed_path or "")).expanduser()
        fileformat = str(self.options.get("fileformat") or "unix")
        encoding_raw = str(self.options.get("encoding") or "utf-8").strip() or "utf-8"
        encoding = self._normalize_encoding_name(encoding_raw)

        # Refuse to open directories (deterministic UX + avoids exceptions).
        # Script/capability opens use the fd-backed stat seam so a late symlink
        # or parent swap cannot turn this preflight into an ambient path probe.
        try:
            if containment_root is not None and str(containment_root).strip():
                st = stat_path_contained(p, containment_root=containment_root)
                if st.exists and st.kind == "dir":
                    self.message(f"open: is a directory: {p}")
                    return False
            elif p.exists() and p.is_dir():
                self.message(f"open: is a directory: {p}")
                return False
        except OSError:
            pass

        # If this file is already open (by normalized path), just switch to it.
        target_norm = self._normalize_path(str(p))
        if target_norm:
            for name, eb in self.buffers.items():
                if eb.buf.path and self._normalize_path(str(eb.buf.path)) == target_norm:
                    denial = self._buffer_access_denial(
                        name, action="switch", capability="cap.buffer-switch"
                    )
                    if denial:
                        self.message(f"open: already open but inaccessible: {denial}")
                        return False
                    self.switch_buffer(name)
                    if target_cursor is not None:
                        self._set_buffer_primary_cursor(self.cur(), target_cursor)
                    self._push_recent_file(str(eb.buf.path))
                    return True

        text = ""
        if p.exists():
            disk = read_file_for_editor(p, encoding=encoding, containment_root=containment_root)
            text = str(disk.text)
            fileformat = str(disk.fileformat or self._detect_fileformat_from_text(text))
        self.new_buffer(name=str(p), text=text, path=str(p), fileformat=fileformat, encoding=encoding_raw)
        if target_cursor is not None:
            self._set_buffer_primary_cursor(self.cur(), target_cursor)
        else:
            self._restore_cursor_for_buffer(self.cur())
        self._push_recent_file(str(p))

        # lifecycle hook
        try:
            self._emit_mx_hook("ed.on-open", str(self.cur().name), str(p), self.filetype())
        except Exception:
            pass
        return True

    def revert_buffer_from_disk(
        self,
        *,
        force: bool = False,
        path: str | None = None,
        containment_root: str | Path | None = None,
    ) -> dict[str, object]:
        """Reload the active path-backed buffer from disk.

        This is the explicit recovery sibling for ``save.checkexternal``.  A
        stale clean buffer can be refreshed without inventing a new open buffer;
        a dirty buffer refuses by default so unsaved edits are not discarded by
        accident.  ``force=True`` is the deliberate discard lane used by
        ``revert!``.  Script/capability wrappers may pass ``path`` when a
        relative buffer path is anchored under ``cap.fs-root``; the buffer
        identity is only retitled after the disk read succeeds.
        """

        eb = self.cur()
        current_path = str(getattr(eb.buf, "path", "") or "")
        target_path = str(path if path is not None else current_path).strip()
        if not target_path:
            raise RuntimeError("buffer has no path")
        if bool(getattr(eb.buf, "dirty", False)) and force:
            require_buffer_discard_capability(
                self,
                "revert!",
                [str(getattr(eb, "name", "") or self.active or "current")],
            )
        if bool(getattr(eb.buf, "dirty", False)) and not force:
            raise RuntimeError("unsaved changes (dirty buffer); use revert! to discard local edits")

        disk = self._read_current_disk_file(eb, path=target_path, containment_root=containment_root)
        text = str(disk.text)
        fileformat = str(disk.fileformat or "unix")
        encoding_raw = (
            str(self.options.get("encoding", local=eb.local_options) or disk.encoding or "utf-8").strip()
            or "utf-8"
        )

        retitle_snap = None
        if current_path and self._normalize_path(current_path) != self._normalize_path(target_path):
            conflict = self._save_as_conflicting_buffer(eb, target_path)
            if conflict:
                raise RuntimeError(f"target already open: {conflict}")
            retitle_snap = self._snapshot_buffer_identity(eb)

        try:
            if retitle_snap is not None:
                self._update_buffer_path(eb, target_path)
                if not self.rename_buffer(str(retitle_snap.name), target_path):
                    raise RuntimeError(f"could not retitle buffer: {target_path}")

            before = self._snapshot_buffer_state(eb)
            before_text = eb.buf.get_text()
            if text != before_text:
                eb.buf.set_text(text)
                self._normalize_cursor_lists(eb)
                after = self._snapshot_buffer_state(eb)
                self._record_undo_snapshot(eb, before, after, "revert from disk")
            else:
                # Still clamp cursors: external edits with equivalent normalized
                # text should not leave stale cursor coordinates around.
                self._normalize_cursor_lists(eb)

            eb.local_options["fileformat"] = fileformat
            eb.local_options["encoding"] = encoding_raw
            eb.local_options["filetype"] = detect_filetype(target_path, text)
            eb.buf.mark_clean()
            self._refresh_buffer_disk_signature(eb)
            eb.autosave_dirty_since = None
            eb.script_dirty_since_sync = False
            self._remember_cursor_for_buffer(eb)
            return {
                "path": str(eb.buf.path or target_path),
                "fileformat": fileformat,
                "encoding": encoding_raw,
                "forced": bool(force),
                "changed_text": bool(text != before_text),
            }
        except Exception:
            if retitle_snap is not None:
                self._restore_buffer_identity(retitle_snap)
            raise

    def _save_buffer(
        self,
        eb: EditorBuffer,
        *,
        force: bool = False,
        containment_root: str | Path | None = None,
    ) -> dict[str, object]:
        if bool(self.options.get("readonly", local=eb.local_options)):
            raise RuntimeError("Buffer is read-only")
        if not eb.buf.path:
            raise RuntimeError("Buffer has no path")
        p = Path(str(eb.buf.path))
        if p.exists() and p.is_dir():
            raise IsADirectoryError(f"is a directory: {p}")
        expected_state = self._check_save_disk_fresh(eb, p, force=force)

        before_text = eb.buf.get_text()
        normalized_text = before_text
        cleanup_parts: list[str] = []

        if bool(self.options.get("rmtrailingws", local=eb.local_options)):
            trimmed_lines = [str(line).rstrip(" \t") for line in eb.buf.lines]
            trimmed_text = "\n".join(trimmed_lines)
            if trimmed_text != normalized_text:
                normalized_text = trimmed_text
                cleanup_parts.append("trim trailing whitespace")

        if (
            bool(self.options.get("eofnewline", local=eb.local_options))
            and normalized_text != ""
            and not normalized_text.endswith("\n")
        ):
            normalized_text += "\n"
            cleanup_parts.append("add eof newline")

        if bool(self.options.get("mkparents", local=eb.local_options)):
            ensure_parent_directory(p.parent, containment_root=containment_root)

        fileformat = str(self.options.get("fileformat", local=eb.local_options) or "unix").strip().lower()
        if fileformat == "dos":
            save_text = normalized_text.replace("\n", "\r\n")
        else:
            save_text = normalized_text
        encoding_raw = str(self.options.get("encoding", local=eb.local_options) or "utf-8")
        encoding = self._normalize_encoding_name(encoding_raw)
        payload = save_text.encode(encoding)

        undo_snapshot = self.undo.snapshot()
        before = self._snapshot_buffer_state(eb)
        before_dirty = bool(getattr(eb.buf, "dirty", False))
        before_fastdirty = bool(getattr(eb.buf, "fastdirty", False))
        before_version = int(getattr(eb.buf, "version", 0))
        before_saved_sig = getattr(eb.buf, "_saved_sig", None)
        applied_cleanup = False
        try:
            if normalized_text != before_text:
                eb.buf.set_text(normalized_text)
                self._normalize_cursor_lists(eb)
                after = self._snapshot_buffer_state(eb)
                desc = cleanup_parts[0] if len(cleanup_parts) == 1 else "normalize save text"
                self._record_undo_snapshot(eb, before, after, desc)
                applied_cleanup = True
            write_result = write_file_bytes(
                p,
                payload,
                atomic=bool(self.options.get("save.atomic", local=eb.local_options)),
                preserve_mode=bool(self.options.get("save.preserveperm", local=eb.local_options)),
                fsync=bool(self.options.get("save.fsync", local=eb.local_options)),
                expected_state=expected_state,
                expected_hash_max=self._disk_hash_budget(eb),
                containment_root=containment_root,
            )
        except Exception:
            if applied_cleanup:
                self._restore_buffer_state(eb, before)
                eb.buf.dirty = before_dirty
                eb.buf.fastdirty = before_fastdirty
                eb.buf.version = before_version
                if before_saved_sig is not None:
                    eb.buf._saved_sig = before_saved_sig
                self.undo.restore(undo_snapshot)
            raise

        eb.buf.mark_clean()
        self._refresh_buffer_disk_signature(eb)
        eb.autosave_dirty_since = None
        eb.script_dirty_since_sync = False
        self._push_recent_file(str(eb.buf.path))
        self._remember_cursor_for_buffer(eb)
        try:
            self._emit_mx_hook("ed.on-save", str(eb.name), str(eb.buf.path))
        except Exception:
            pass
        return {
            "path": str(eb.buf.path),
            "cleanup_parts": list(cleanup_parts),
            "fileformat": fileformat,
            "encoding": str(encoding_raw).strip() or "utf-8",
            "atomic": bool(getattr(write_result, "atomic", False)),
            "write_path": str(getattr(write_result, "write_path", eb.buf.path)),
            "followed_symlink": bool(getattr(write_result, "followed_symlink", False)),
            "forced": bool(force),
        }

    def save(
        self,
        *,
        force: bool = False,
        containment_root: str | Path | None = None,
    ) -> dict[str, object]:
        return self._save_buffer(self.cur(), force=force, containment_root=containment_root)

    def save_as(
        self,
        path: str,
        *,
        force: bool = False,
        containment_root: str | Path | None = None,
    ) -> dict[str, object]:
        """Save the active buffer under ``path`` without half-renaming on failure."""

        raw = str(path or "").strip()
        if not raw:
            raise RuntimeError("save-as target is empty")
        target = str(Path(raw).expanduser())
        eb = self.cur()
        current_path = str(getattr(eb.buf, "path", "") or "")
        if current_path and self._normalize_path(current_path) == self._normalize_path(target):
            return self.save(force=force, containment_root=containment_root)
        conflict = self._save_as_conflicting_buffer(eb, target)
        if conflict:
            raise RuntimeError(f"target already open: {conflict}")

        snap = self._snapshot_buffer_identity(eb)
        try:
            self._update_buffer_path(eb, target)
            # A save-as target is a new disk identity.  Keep the old file
            # witness in the rollback snapshot, but compare the commit against
            # the target's current known state so same-turn races are still
            # caught when save.checkexternal is enabled.
            try:
                fresh = self._capture_disk_freshness(eb, target)
                eb.disk_signature = fresh.signature
                eb.disk_content_hash = fresh.content_hash
            except OSError:
                eb.disk_signature = None
                eb.disk_content_hash = None
            if not self.rename_buffer(str(snap.name), target):
                raise RuntimeError(f"could not retitle buffer: {target}")
            return self.save(force=force, containment_root=containment_root)
        except Exception:
            self._restore_buffer_identity(snap)
            raise

    def _read_current_disk_file(
        self,
        eb: EditorBuffer,
        *,
        path: str | None = None,
        containment_root: str | Path | None = None,
    ):
        raw_path = str(path if path is not None else (eb.buf.path or "")).strip()
        if not raw_path:
            raise RuntimeError("buffer has no path")
        p = Path(raw_path)
        if p.exists() and p.is_dir():
            raise IsADirectoryError(f"is a directory: {p}")
        encoding_raw = str(self.options.get("encoding", local=eb.local_options) or "utf-8")
        encoding = self._normalize_encoding_name(encoding_raw)
        return read_file_for_editor(p, encoding=encoding, containment_root=containment_root)

    def disk_diff_lines(
        self,
        *,
        max_lines: int = 80,
        path: str | None = None,
        containment_root: str | Path | None = None,
    ) -> list[str]:
        """Return a bounded unified diff of disk contents versus the active buffer."""

        eb = self.cur()
        disk = self._read_current_disk_file(eb, path=path, containment_root=containment_root)
        return unified_file_diff_lines(
            disk_text=str(disk.text),
            buffer_text=eb.buf.get_text(),
            disk_label=f"disk:{disk.path}",
            buffer_label=f"buffer:{eb.name}",
            max_lines=max_lines,
        )

    def autosave_dirty_buffers(self, *, now: float | None = None, immediate: bool = False) -> list[str]:
        when = float(self.now() if now is None else now)
        saved: list[str] = []
        for eb in list(self.buffers.values()):
            if not bool(getattr(eb.buf, "dirty", False)):
                eb.autosave_dirty_since = None
                continue
            if self._autosave_seconds(eb) <= 0:
                eb.autosave_dirty_since = None
                continue
            if self._script_dirty_autosave_blocked(eb):
                eb.autosave_dirty_since = None
                continue
            if not str(getattr(eb.buf, "path", "") or ""):
                continue
            if bool(self.options.get("readonly", local=eb.local_options)):
                continue
            if not immediate and not self._autosave_buffer_due(eb, now=when):
                continue
            if immediate and eb.autosave_dirty_since is None:
                eb.autosave_dirty_since = when
            try:
                self._save_buffer(eb)
                saved.append(str(eb.name))
            except Exception as e:
                eb.autosave_dirty_since = when
                self.message(f"autosave error: {eb.name}: {e}")
        return saved

    def load_user_init(self, *, path: str | None = None) -> bool:
        """Load a user init/rc file (best-effort).

        Default path: ~/.config/micromax/init.mx
        Override via the MICROMAX_INIT environment variable or the explicit path arg.

        Returns True when a file existed and was evaluated successfully.
        """
        raw = path or os.environ.get("MICROMAX_INIT") or "~/.config/micromax/init.mx"
        p = Path(raw).expanduser()
        if not p.exists() or p.is_dir():
            return False
        try:
            self.vm.eval(p.read_text(encoding="utf-8"), filename=str(p))
        except Exception as e:
            self.message(f"init error: {e}")
            return False
        return True

    # ----- viewport (scrolling model) -----
    def viewport_model(self) -> dict[str, int]:
        """Return the current viewport model.

        This is UI-owned state, but stored in the headless core so actions can
        keep the cursor visible and future renderers can share semantics.
        """
        return {
            "top_line": int(self.viewport_top_line),
            "top_subline": int(self.viewport_top_subline),
            "left_col": int(self.viewport_left_col),
            "height": int(self.viewport_height),
            "width": int(self.viewport_width),
        }

    def set_viewport(
        self,
        *,
        top_line: int | None = None,
        top_subline: int | None = None,
        left_col: int | None = None,
        height: int | None = None,
        width: int | None = None,
        follow_cursor: bool = True,
    ) -> None:
        """Set viewport fields (best-effort clamped)."""
        if height is not None:
            self.viewport_height = max(1, int(height))
        if width is not None:
            self.viewport_width = max(1, int(width))

        eb = self.cur()
        softwrap = bool(self.options.get("softwrap", local=eb.local_options))
        # When softwrap is enabled, horizontal scrolling is disabled.
        if softwrap:
            self.viewport_left_col = 0
        max_top = max(0, len(eb.buf.lines) - 1)
        # Softwrap introduces a secondary vertical offset: which wrapped row within
        # `top_line` is at the top of the viewport.
        if not bool(self.options.get("softwrap", local=eb.local_options)):
            self.viewport_top_subline = 0
        if top_subline is not None:
            self.viewport_top_subline = max(0, int(top_subline))
        if top_line is not None:
            self.viewport_top_line = max(0, min(int(top_line), max_top))
            if top_subline is None:
                self.viewport_top_subline = 0
        if left_col is not None:
            # When softwrap is enabled, horizontal scrolling is disabled.
            if bool(self.options.get("softwrap", local=eb.local_options)):
                self.viewport_left_col = 0
            else:
                self.viewport_left_col = max(0, int(left_col))
        if follow_cursor:
            self.ensure_cursor_visible()

    # ----- softwrap visual-row mapping helpers -----
    def _softwrap_contindent_setting(self, eb: "EditorBuffer") -> int:
        try:
            return int(self.options.get("softwrap.contindent", local=eb.local_options))
        except Exception:
            return -1

    def _tabmovement_step(self, eb: "EditorBuffer", line: str, col: int, *, direction: int) -> int:
        """Return the horizontal cursor delta for micro-esque `tabmovement`.

        When `tabstospaces` and `tabmovement` are both enabled, leading runs of
        exactly `tabsize` spaces behave like one tab stop for left/right motion.
        This mirrors micro's conservative rule closely:

        - only the leading indentation run participates
        - only exact all-space chunks of width `tabsize` are collapsed
        - otherwise movement stays character-wise
        """
        try:
            enabled = bool(self.options.get("tabmovement", local=eb.local_options))
            spaces = bool(self.options.get("tabstospaces", local=eb.local_options))
            tabsize = int(self.options.get("tabsize", local=eb.local_options))
        except Exception:
            return -1 if int(direction) < 0 else 1

        if (not enabled) or (not spaces) or tabsize <= 1:
            return -1 if int(direction) < 0 else 1

        s = str(line or "")
        col = max(0, min(int(col), len(s)))

        def _indent_only(prefix: str) -> bool:
            return all(ch in (" ", "\t") for ch in str(prefix or ""))

        if int(direction) < 0:
            start = col - tabsize
            if start >= 0 and s[start:col] == (" " * tabsize) and _indent_only(s[:start]):
                return -tabsize
            return -1

        end = col + tabsize
        if end <= len(s) and s[col:end] == (" " * tabsize) and _indent_only(s[:col]):
            return tabsize
        return 1

    @staticmethod
    def _leading_ws_cols(s: str) -> int:
        return viewport_math.leading_ws_cols(s)

    def _contindent_for_line(self, eb: "EditorBuffer", s: str, *, w: int) -> int:
        """Continuation indent for wrapped fragments under softwrap."""

        return viewport_math.contindent_for_line(
            s,
            width=int(w),
            setting=self._softwrap_contindent_setting(eb),
        )

    @staticmethod
    def _wrap_seg(w: int, cont: int) -> int:
        return viewport_math.wrap_seg(w, cont)

    def _wordwrap_enabled(self, eb: "EditorBuffer") -> bool:
        try:
            return bool(self.options.get("wordwrap", local=eb.local_options))
        except Exception:
            return False

    @staticmethod
    def _find_wordwrap_break(s: str, start: int, end: int) -> int | None:
        return viewport_math.find_wordwrap_break(s, start, end)

    def _wrap_row_starts_for_line_with_cont(
        self,
        eb: "EditorBuffer",
        s: str,
        w: int,
        cont: int,
    ) -> list[int]:
        return viewport_math.wrap_row_starts_for_line(
            s,
            width=int(w),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wrap_row_starts_for_line(self, eb: "EditorBuffer", s: str, *, w: int) -> list[int]:
        cont = self._contindent_for_line(eb, s, w=w)
        return self._wrap_row_starts_for_line_with_cont(eb, s, int(w), int(cont))

    def _wrap_start_for_row_in_line(self, eb: "EditorBuffer", s: str, *, w: int, row: int) -> int:
        cont = self._contindent_for_line(eb, s, w=w)
        return viewport_math.wrap_start_for_row_in_line(
            s,
            width=int(w),
            row=int(row),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wrap_end_for_row_in_line(self, eb: "EditorBuffer", s: str, *, w: int, row: int) -> int:
        cont = self._contindent_for_line(eb, s, w=w)
        return viewport_math.wrap_end_for_row_in_line(
            s,
            width=int(w),
            row=int(row),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wrap_cap_for_row_in_line(self, eb: "EditorBuffer", s: str, *, w: int, row: int) -> int:
        cont = self._contindent_for_line(eb, s, w=w)
        return viewport_math.wrap_cap_for_row_in_line(
            s,
            width=int(w),
            row=int(row),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wraps_for_line_with_cont(self, eb: "EditorBuffer", s: str, w: int, cont: int) -> int:
        return viewport_math.wraps_for_line(
            s,
            width=int(w),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wrap_row_for_col_with_cont(self, eb: "EditorBuffer", s: str, col: int, w: int, cont: int) -> int:
        """Return wrap-row index for a character column in a softwrapped line."""

        return viewport_math.wrap_row_for_col(
            s,
            int(col),
            width=int(w),
            contindent=int(cont),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _wraps_for_line(self, eb: "EditorBuffer", s: str, *, w: int) -> int:
        cont = self._contindent_for_line(eb, s, w=w)
        return self._wraps_for_line_with_cont(eb, s, int(w), int(cont))

    def _visual_row_index(self, eb: "EditorBuffer", line: int, wrap_row: int, *, w: int) -> int:
        """Return global visual-row index for (line, wrap_row)."""

        return viewport_math.visual_row_index(
            eb.buf.lines,
            int(line),
            int(wrap_row),
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _cursor_visual_yx(self, eb: "EditorBuffer", c: "Cursor", *, w: int) -> tuple[int, int]:
        """Return (global_y, x_in_wrap_row) for cursor c under width w."""

        point = viewport_math.cursor_visual_yx(
            eb.buf.lines,
            line=int(c.line),
            col=int(c.col),
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )
        return (int(point.y), int(point.x))

    def _total_visual_rows(self, eb: "EditorBuffer", *, w: int) -> int:
        return viewport_math.total_visual_rows(
            eb.buf.lines,
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _doc_pos_for_visual_row(self, eb: "EditorBuffer", target_y: int, goal_x: int, *, w: int) -> "Cursor":
        """Map a global visual-row index + desired x to a document Cursor."""

        line, col = viewport_math.doc_pos_for_visual_row(
            eb.buf.lines,
            target_y=int(target_y),
            goal_x=int(goal_x),
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )
        return Cursor(int(line), int(col))

    def _viewport_visual_start(self, eb: "EditorBuffer", *, w: int) -> int:
        """Return global visual-row index for the viewport's top."""

        return viewport_math.viewport_visual_start(
            eb.buf.lines,
            top_line=int(self.viewport_top_line),
            top_subline=int(self.viewport_top_subline),
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )

    def _set_viewport_from_visual_start(self, eb: "EditorBuffer", start_y: int, *, w: int) -> None:
        """Set viewport_top_line/top_subline from a global visual-row index."""

        top = viewport_math.viewport_top_for_visual_start(
            eb.buf.lines,
            start_y=int(start_y),
            width=int(w),
            contindent_setting=self._softwrap_contindent_setting(eb),
            wordwrap=self._wordwrap_enabled(eb),
        )
        self.viewport_top_line = int(top.line)
        self.viewport_top_subline = int(top.subline)


    def _move_cursors_visual(self, dy: int, *, extend_selection: bool = False) -> bool:
        """Move all cursors by dy visual rows when softwrap is enabled."""
        eb = self.cur()
        self._normalize_cursor_lists(eb)
        w = int(self.viewport_width)
        if w <= 0:
            # no viewport width yet; fall back to logical-line motion
            for i, c in enumerate(eb.cursors):
                eb.cursors[i] = eb.buf.clamp(Cursor(int(c.line) + int(dy), int(c.col)))
            if not extend_selection:
                self.clear_selection()
            return True

        total = self._total_visual_rows(eb, w=w)
        # Maintain per-cursor goal x (visual column) for vertical motions.
        if not hasattr(eb, "goal_x_by_cursor"):
            eb.goal_x_by_cursor = {}  # type: ignore[attr-defined]

        for i, c in enumerate(eb.cursors):
            cid = int(eb.cursor_ids[i]) if i < len(eb.cursor_ids) else i
            y, x = self._cursor_visual_yx(eb, c, w=w)
            goal_x = int(eb.goal_x_by_cursor.get(cid, x))  # type: ignore[attr-defined]
            target_y = max(0, min(int(y) + int(dy), max(0, total - 1)))
            eb.cursors[i] = eb.buf.clamp(self._doc_pos_for_visual_row(eb, target_y, goal_x, w=w))

        if not extend_selection:
            self.clear_selection()
        return True

    def ensure_cursor_visible(self) -> None:
        """Adjust viewport so the primary cursor is visible."""
        try:
            eb = self.cur()
            self._normalize_cursor_lists(eb)
            c = eb.cursors[eb.primary]
        except Exception:
            return
        h = int(self.viewport_height)
        w = int(self.viewport_width)
        if h <= 0 or w <= 0:
            return

        try:
            raw_scrollmargin = int(self.options.get("scrollmargin", local=eb.local_options))
        except Exception:
            raw_scrollmargin = 0
        scrollmargin = max(0, min(int(raw_scrollmargin), max(0, (h - 1) // 2)))

        softwrap = bool(self.options.get("softwrap", local=eb.local_options))

        # vertical
        if not softwrap:
            if int(c.line) < int(self.viewport_top_line) + scrollmargin:
                self.viewport_top_line = max(0, int(c.line) - scrollmargin)
            elif int(c.line) > int(self.viewport_top_line) + h - 1 - scrollmargin:
                self.viewport_top_line = max(0, int(c.line) - h + 1 + scrollmargin)
            self.viewport_top_subline = 0
        else:
            # Softwrap scrolling is in *visual rows* (wrapped fragments), not logical lines.
            start_y = self._viewport_visual_start(eb, w=w)
            cur_y, _cur_x = self._cursor_visual_yx(eb, c, w=w)
            total = self._total_visual_rows(eb, w=w)
            max_start = max(0, total - h)
            if cur_y < start_y + scrollmargin:
                start_y = cur_y - scrollmargin
            elif cur_y > start_y + h - 1 - scrollmargin:
                start_y = cur_y - h + 1 + scrollmargin
            start_y = max(0, min(int(start_y), int(max_start)))
            self._set_viewport_from_visual_start(eb, start_y, w=w)

        # horizontal
        if bool(self.options.get("softwrap", local=eb.local_options)):
            # softwrap disables horizontal scrolling
            self.viewport_left_col = 0
        else:
            if int(c.col) < int(self.viewport_left_col):
                self.viewport_left_col = int(c.col)
            elif int(c.col) >= int(self.viewport_left_col) + w:
                self.viewport_left_col = max(0, int(c.col) - w + 1)

        # Clamp top against buffer length.
        self.viewport_top_line = max(0, min(int(self.viewport_top_line), max(0, len(eb.buf.lines) - 1)))
        if softwrap and eb.buf.lines:
            wraps = self._wraps_for_line(eb, eb.buf.lines[int(self.viewport_top_line)], w=int(w))
            self.viewport_top_subline = max(0, min(int(self.viewport_top_subline), max(0, wraps - 1)))
        else:
            self.viewport_top_subline = 0
        self.viewport_left_col = max(0, int(self.viewport_left_col))


    def view_rows(self, *, height: int | None = None, width: int | None = None) -> list[tuple[int, int, str]]:
        """Return screen rows for the active buffer under the current viewport.

        Each row is a tuple: (line_index, start_col, fragment).

        - When softwrap is disabled, start_col is the viewport's left_col and
          fragment is a simple substring slice.
        - When softwrap is enabled, long logical lines are wrapped into multiple
          screen rows and start_col is the wrap's starting *character* column.

        Notes:
          - This is a **rendering model**, not a UI. It intentionally ignores
            styling/spans for now.
          - Tabs are treated as single characters here; a future renderer can
            expand tabs to visual columns.
        """

        eb = self.cur()
        h = int(height if height is not None else self.viewport_height)
        w = int(width if width is not None else self.viewport_width)
        if h <= 0 or w <= 0:
            return []

        top = int(self.viewport_top_line)
        left = int(self.viewport_left_col)
        softwrap = bool(self.options.get("softwrap", local=eb.local_options))

        rows: list[tuple[int, int, str]] = []
        if not softwrap:
            for row in range(h):
                li = top + row
                if li >= len(eb.buf.lines):
                    break
                ln = eb.buf.lines[li]
                frag = ln[left : left + w]
                rows.append((li, left, frag))
            return rows

        # softwrap: walk logical lines, emit wrapped fragments until the screen fills.
        li = top
        first_subline = max(0, int(self.viewport_top_subline))
        while li < len(eb.buf.lines) and len(rows) < h:
            ln = eb.buf.lines[li]
            if ln == "":
                rows.append((li, 0, ""))
                li += 1
                continue

            cont = self._contindent_for_line(eb, ln, w=w)
            wraps = self._wraps_for_line_with_cont(eb, ln, w, cont)
            sub = first_subline if li == top else 0
            sub = max(0, min(int(sub), max(0, wraps - 1)))

            while len(rows) < h and sub < wraps:
                start = self._wrap_start_for_row_in_line(eb, ln, w=w, row=sub)
                cap = self._wrap_cap_for_row_in_line(eb, ln, w=w, row=sub)
                prefix = (" " * cont) if sub > 0 and cont > 0 else ""
                frag = prefix + ln[start : start + cap]
                rows.append((li, start, frag))
                sub += 1
            li += 1
        return rows

    def cursor_view_pos(self, *, height: int | None = None, width: int | None = None) -> tuple[int, int]:
        """Return (y, x) of the primary cursor within the current viewport.

        For softwrap, this maps the cursor into wrapped screen rows.
        """
        try:
            eb = self.cur()
            self._normalize_cursor_lists(eb)
            c = eb.cursors[eb.primary]
        except Exception:
            return (0, 0)

        h = int(height if height is not None else self.viewport_height)
        w = int(width if width is not None else self.viewport_width)
        if h <= 0 or w <= 0:
            return (0, 0)

        top = int(self.viewport_top_line)
        left = int(self.viewport_left_col)
        softwrap = bool(self.options.get("softwrap", local=eb.local_options))

        if not softwrap:
            return (int(c.line) - top, int(c.col) - left)

        start_y = self._viewport_visual_start(eb, w=w)
        cy, cx = self._cursor_visual_yx(eb, c, w=w)
        y = int(cy) - int(start_y)
        x = int(cx)
        return (y, x)

    # ----- timers (host-driven, deterministic) -----
    def now(self) -> float:
        return float(self._now_fn())

    def schedule_timer_checked(
        self,
        *,
        delay_ms: int,
        xt: Any,
        group: str | None = None,
        script_context: bool = False,
        plugin_load_root: object = None,
        plugin_generation: object = None,
        script_origin_id: object = None,
    ) -> int:
        """Schedule a timer after enforcing the host pending-work budget."""

        try:
            max_pending = int(getattr(self, "max_pending_timers", 1024))
        except Exception:
            max_pending = 1024
        pending = int(self.timers.pending_count())
        if max_pending >= 0 and pending >= max_pending:
            raise MicromaxError(
                f"ed.after: pending timer budget exceeded ({pending} >= {max_pending})"
            )
        return int(
            self.timers.schedule(
                now=self.now(),
                delay_ms=int(delay_ms),
                xt=xt,
                group=group,
                script_context=bool(script_context),
                plugin_load_root=(str(plugin_load_root) if plugin_load_root else None),
                plugin_generation=(
                    int(plugin_generation)
                    if plugin_generation not in (None, "")
                    else None
                ),
                script_origin_id=(str(script_origin_id) if script_origin_id else None),
            )
        )

    def pump_timers(self, *, limit: int = 1000) -> int:
        """Run due timer callbacks.

        Timer callbacks run in the embedded VM and are treated like hooks:
        best-effort notifications. We isolate stack effects and record
        exceptions as editor messages.
        """

        now = self.now()
        allow = self._timer_fire_allowed if self.in_script_context() else None
        tasks = self.timers.pop_due(now=now, limit=int(limit), allow=allow)
        ran = 0
        for t in tasks:
            depth = len(self.vm.stack)
            try:
                if bool(getattr(t, "script_context", False)):
                    self.run_script_origin_callback(
                        lambda t=t: self.vm.exec_xt(t.xt),
                        plugin_load_root=getattr(t, "plugin_load_root", None),
                        group=getattr(t, "group", None),
                        plugin_generation=getattr(t, "plugin_generation", None),
                        script_origin_id=getattr(t, "script_origin_id", None),
                    )
                else:
                    self.vm.exec_xt(t.xt)
            except Exception as e:
                self.message(f"timer {t.task_id} error: {e}")
            finally:
                del self.vm.stack[depth:]
            ran += 1
        if not self.in_script_context():
            try:
                self.autosave_dirty_buffers(now=now)
            except Exception:
                pass
        return int(ran)

    # ----- syntax highlighting (span model) -----
    def highlight_tags(self) -> list[str]:
        return list(HIGHLIGHT_TAGS)

    def highlight_spans(self, start: int, count: int) -> list[list[list[object]]]:
        """Return per-line highlight spans for the active buffer.

        Result is a list aligned with the requested range: out[0] contains
        spans for line `start`. Each per-line span is [start_col, end_col, tag].

        This is intentionally tiny; renderers/themes decide how to map tags to
        color or attributes.
        """

        eb = self.cur()
        lines = eb.buf.lines
        if int(count) <= 0 or not lines:
            return []
        a = max(0, int(start))
        b = min(len(lines), a + int(count))
        ft = str(self.filetype())
        return [highlight_line(ft, str(lines[i])) for i in range(a, b)]

    def page_height(self, *, eb: EditorBuffer | None = None) -> int:
        """Return the current page movement size.

        If a UI has set a viewport height, page movement uses it. Otherwise we
        fall back to the `page.height` option.
        """
        if int(self.viewport_height) > 0:
            return int(self.viewport_height)
        eb2 = eb or self.cur()
        return int(self.options.get("page.height", local=eb2.local_options))

    def page_step(self, *, eb: EditorBuffer | None = None) -> int:
        """Return the effective PageUp/PageDown jump.

        The jump is the page height minus the configured overlap, clamped so a
        page move always advances by at least one logical/visual row.
        """
        eb2 = eb or self.cur()
        page = max(1, int(self.page_height(eb=eb2)))
        try:
            raw_overlap = int(self.options.get("pageoverlap", local=eb2.local_options))
        except Exception:
            raw_overlap = 0
        overlap = max(0, min(int(raw_overlap), max(0, page - 1)))
        return max(1, int(page) - int(overlap))

    def is_protected_buffer(self, eb: EditorBuffer | None = None) -> bool:
        """Return True if this buffer is marked as protected/read-only."""

        eb2 = eb or self.cur()
        try:
            return bool(self.options.get("readonly", local=eb2.local_options))
        except Exception:
            return False

    # ----- status / infobar model -----
    def editor_mode(self) -> str:
        """Return a tiny, headless editor mode label.

        This is intentionally conservative: until we have richer modal editing,
        the statusline model only distinguishes normal editing from active prompt
        modes. Macro recording/playback are reported as orthogonal flags in the
        status model instead of becoming separate editor modes.
        """

        if self.prompt is not None:
            kind = str(self.prompt.kind or "").strip().lower()
            return kind or "prompt"
        capture_mode = self.current_capture_key_mode()
        if capture_mode is not None:
            return str(capture_mode)
        return "normal"

    def capture_status_model(self) -> dict[str, Any]:
        """Return a small, portable model for active capture keymodes.

        Capture keymodes already exist as shared editor behavior (`qreplace`,
        `openurl`), but future UIs/statuslines/scripts should not have to parse
        transient TUI message text to understand them.
        """

        mode = str(self.current_capture_key_mode() or "")
        out: dict[str, Any] = {
            "capture_kind": "",
            "capture_summary": "",
            "capture_detail": "",
            "capture_progress": "",
            "capture_source": "",
            "capture_search": "",
            "capture_replace": "",
            "capture_url": "",
            "capture_examined": 0,
            "capture_count": 0,
            "capture_replaced": 0,
        }
        if not mode:
            return out

        out["capture_kind"] = mode
        if mode == "qreplace" and self.qreplace is not None:
            sess = self.qreplace
            if not self._interaction_read_allowed(getattr(sess, "authority", None), kind="qreplace"):
                out.update({"capture_summary": "?replace"})
                return out
            examined = max(0, int(sess.examined or 0))
            total = max(0, int(sess.total or 0))
            shown = min(examined, total) if total > 0 else 0
            replaced = max(0, int(sess.replaced or 0))
            progress = f"{shown}/{total}" if total > 0 else ""
            head = "?replace"
            bits: list[str] = []
            if progress:
                bits.append(progress)
            if replaced > 0:
                bits.append(f"{replaced} repl")
            if bits:
                head += " [" + " • ".join(bits) + "]"
            out.update(
                {
                    "capture_summary": head,
                    "capture_detail": f"{sess.search} -> {sess.value}".strip(),
                    "capture_progress": progress,
                    "capture_search": str(sess.search),
                    "capture_replace": str(sess.value),
                    "capture_examined": examined,
                    "capture_count": total,
                    "capture_replaced": replaced,
                }
            )
            return out

        if mode == "openurl":
            if not self._interaction_read_allowed(
                getattr(self, "_pending_open_url_authority", None),
                kind="openurl",
            ):
                out.update({"capture_summary": "?open external link"})
                return out
            source = str(getattr(self, "_pending_open_url_source", "") or "").strip().lower()
            if source == "help":
                head = "?open external link from help"
            elif source == "cursor":
                head = "?open external link under cursor"
            elif source == "command":
                head = "?open external link from command"
            else:
                head = "?open external link"
            detail = str(getattr(self, "_pending_open_url", "") or "").strip()
            out.update(
                {
                    "capture_summary": head,
                    "capture_detail": detail,
                    "capture_source": source,
                    "capture_url": detail,
                }
            )
            return out

        out["capture_summary"] = mode
        return out

    def interaction_status_model(self) -> dict[str, Any]:
        """Return a tiny shared model for the active bottom-row interaction.

        This intentionally sits one level above the raw prompt/capture state: it
        describes the *current visible prompt-style interaction surface* that the
        minimal TUI would show on the bottom row, while still staying plain and
        inspectable for future UIs, statuslines, scripts, and tests.
        """

        out: dict[str, Any] = {
            "interaction_active": 0,
            "interaction_kind": "",
            "interaction_prefix": "",
            "interaction_summary": "",
            "interaction_detail": "",
            "interaction_position": "",
            "interaction_line": "",
        }

        capture = self.capture_status_model()
        capture_kind = str(capture.get("capture_kind", "") or "")
        if capture_kind:
            summary = str(capture.get("capture_summary", "") or "")
            detail = str(capture.get("capture_detail", "") or "")
            position = str(capture.get("capture_progress", "") or "")
            line = summary
            if detail:
                line += "  | " + detail
            out.update(
                {
                    "interaction_active": 1,
                    "interaction_kind": capture_kind,
                    "interaction_prefix": "?",
                    "interaction_summary": summary,
                    "interaction_detail": detail,
                    "interaction_position": position,
                    "interaction_line": line,
                }
            )
            return out

        if self.prompt is None:
            return out

        kind = str(self.prompt.kind or "")
        if kind in ("command", "palette"):
            prefix = ":"
        elif kind == "find":
            prefix = "/"
        else:
            prefix = "?"
        prompt_visible = self._can_read_prompt_state(self.prompt)
        summary = prefix + str(self.prompt.text or "") if prompt_visible else f"{prefix}<prompt>"
        position = ""
        detail = ""
        if prompt_visible and kind == "find":
            position = str(self.search_position_model().get("summary", "") or "")
        elif prompt_visible and kind not in ("command", "find"):
            position = str(self.prompt_current_position().get("summary", "") or "")
            detail = str(self.prompt_current_preview() or "")

        line = summary
        if position:
            line += "  [" + position + "]"
        if detail:
            line += "  | " + detail

        out.update(
            {
                "interaction_active": 1,
                "interaction_kind": kind,
                "interaction_prefix": prefix,
                "interaction_summary": summary,
                "interaction_detail": detail,
                "interaction_position": position,
                "interaction_line": line,
            }
        )
        return out

    def interaction_model(self, width: int) -> dict[str, Any]:
        """Return a tiny shared layout model for the visible prompt/capture row.

        This is the width-aware sibling of ``interaction_status_model()``: it
        preserves the same prompt/capture metadata while also exposing the final
        visible row text that the minimal curses TUI would paint for a given
        width.
        """

        w = max(0, int(width))
        out: dict[str, Any] = {
            "active": 0,
            "width": w,
            "kind": "",
            "prefix": "",
            "summary": "",
            "detail": "",
            "position": "",
            "raw_line": "",
            "text": "",
            "truncated": 0,
        }
        if w <= 0:
            return out

        interaction = self.interaction_status_model()
        raw_line = str(interaction.get("interaction_line", "") or "")
        if not raw_line:
            return out

        text = _ellipsize_right(raw_line, w)
        out.update(
            {
                "active": 1,
                "kind": str(interaction.get("interaction_kind", "") or ""),
                "prefix": str(interaction.get("interaction_prefix", "") or ""),
                "summary": str(interaction.get("interaction_summary", "") or ""),
                "detail": str(interaction.get("interaction_detail", "") or ""),
                "position": str(interaction.get("interaction_position", "") or ""),
                "raw_line": raw_line,
                "text": text,
                "truncated": 1 if text != raw_line else 0,
            }
        )
        return out

    def keymenu_model(self, width: int) -> dict[str, Any]:
        """Return a tiny shared model for the visible keymenu row.

        The model stays deliberately small and text-first: it exposes the
        current context plus the visible shortcut entries so future UIs,
        scripts, tests, and LLMs do not need to reverse-engineer the row from a
        dimmed curses string.
        """

        w = max(0, int(width))
        out: dict[str, Any] = {
            "active": 0,
            "width": w,
            "context": "",
            "entries": [],
            "text": "",
            "truncated": 0,
        }
        if w <= 0:
            return out
        try:
            local = self.cur().local_options
            visible = bool(self.options.get("keymenu", local=local))
        except Exception:
            local = None
            visible = True

        prompt = self.prompt
        capture_mode = self.current_capture_key_mode()
        context = "normal"
        entries: list[dict[str, str]] = []

        def add_entry(key: str, label: str) -> None:
            entries.append({"key": str(key), "label": str(label), "text": f"{key} {label}".strip()})

        if prompt is not None:
            kind = str(prompt.kind or "")
            context = kind or "prompt"
            if kind not in ("command", "find") and prompt.suggestion_rows:
                add_entry("Enter", "Choose")
                add_entry("Esc", "Cancel")
                add_entry("Up/Down", "Move")
                add_entry("PgUp/PgDn", "Page")
                add_entry("Alt-Up/Down", "Section")
            elif kind == "find":
                add_entry("Enter", "Next")
                add_entry("Esc", "Cancel")
                add_entry("Up/Down", "Hist")
                add_entry("Home/End", "Move")
            else:
                add_entry("Enter", "Run")
                add_entry("Esc", "Cancel")
                add_entry("Up/Down", "Hist")
                add_entry("Home/End", "Move")
        elif capture_mode == "qreplace":
            context = "qreplace"
            add_entry("Y/Enter", "Replace")
            add_entry("N", "Skip")
            add_entry("A", "All")
            add_entry("L", "Last")
            add_entry("Q/Esc", "Quit")
        elif capture_mode == "openurl":
            context = "openurl"
            add_entry("Y/Enter", "Open")
            add_entry("N/Esc", "Cancel")
            add_entry("C", "Copy")
        else:
            add_entry("^Q", "Quit")
            add_entry("^S", "Save")
            add_entry("^F", "Find")
            add_entry("^E", "Cmd")
            add_entry("^O", "Open")
            add_entry("^G", "Help")

        raw_text = "  ".join(str(row.get("text", "") or "") for row in entries if str(row.get("text", "") or ""))
        text = raw_text[:w]
        out.update(
            {
                "active": 1 if visible else 0,
                "context": context,
                "entries": entries,
                "text": text,
                "truncated": 1 if text != raw_text else 0,
            }
        )
        return out

    def keymenu_text(self, width: int) -> str:
        """Return a tiny nano-style key-menu summary for the current context."""

        return str(self.keymenu_model(width).get("text", "") or "")

    def constantshow_text(self) -> str:
        """Return a tiny cursor summary for the idle infobar."""

        st = self.status_model()
        line = max(1, int(st.get("display_line", 1) or 1))
        total = max(1, int(st.get("line_count", 1) or 1))
        col = max(1, int(st.get("display_col", 1) or 1))
        pct = max(0, min(100, int(st.get("percentage", 0) or 0)))
        return f"Ln {line}/{total}, Col {col} ({pct}%)"

    def infobar_model(self, width: int) -> dict[str, Any]:
        """Return a tiny shared layout model for the visible idle infobar row.

        This mirrors the current tiny policy used by the curses TUI: the left
        side carries the last message, `constantshow` optionally claims the
        right edge for a compact cursor summary, and the right side wins when
        space is tight.
        """

        w = max(0, int(width))
        out: dict[str, Any] = {
            "active": 0,
            "width": w,
            "message_raw": "",
            "summary_raw": "",
            "message": "",
            "summary": "",
            "padding": "",
            "padding_width": 0,
            "constantshow": 0,
            "truncated_message": 0,
            "truncated_summary": 0,
            "text": "",
        }
        if w <= 0:
            return out

        try:
            eb = self.cur()
            local = eb.local_options
        except Exception:
            eb = None
            local = None
        if not bool(self.options.get("infobar", local=local)):
            return out
        st = self.status_model()
        if bool(st.get("interaction_active", 0) or 0):
            return out

        message_raw = str(st.get("last_message", "") or "")
        constantshow = 1 if bool(self.options.get("constantshow", local=local)) else 0
        summary_raw = self.constantshow_text().strip() if constantshow else ""
        message = message_raw
        summary = summary_raw
        padding = ""
        truncated_message = 0
        truncated_summary = 0

        if not constantshow or not summary_raw:
            message = _ellipsize_right(message_raw, w)
            truncated_message = 1 if message != message_raw else 0
            out.update(
                {
                    "active": 1,
                    "message_raw": message_raw,
                    "summary_raw": summary_raw,
                    "message": message,
                    "summary": "",
                    "constantshow": constantshow,
                    "truncated_message": truncated_message,
                    "text": message,
                }
            )
            return out

        if len(summary_raw) >= w:
            summary = _ellipsize_left(summary_raw, w)
            truncated_summary = 1 if summary != summary_raw else 0
            out.update(
                {
                    "active": 1,
                    "message_raw": message_raw,
                    "summary_raw": summary_raw,
                    "message": "",
                    "summary": summary,
                    "constantshow": constantshow,
                    "truncated_message": 1 if message_raw else 0,
                    "truncated_summary": truncated_summary,
                    "text": summary,
                }
            )
            return out

        if not message_raw:
            padding = " " * max(0, w - len(summary_raw))
            out.update(
                {
                    "active": 1,
                    "message_raw": message_raw,
                    "summary_raw": summary_raw,
                    "message": "",
                    "summary": summary_raw,
                    "padding": padding,
                    "padding_width": len(padding),
                    "constantshow": constantshow,
                    "text": (padding + summary_raw)[:w],
                }
            )
            return out

        sep = "  "
        avail_message = w - len(summary_raw) - len(sep)
        if avail_message <= 0:
            summary = _ellipsize_left(summary_raw, w)
            truncated_summary = 1 if summary != summary_raw else 0
            out.update(
                {
                    "active": 1,
                    "message_raw": message_raw,
                    "summary_raw": summary_raw,
                    "message": "",
                    "summary": summary,
                    "constantshow": constantshow,
                    "truncated_message": 1 if message_raw else 0,
                    "truncated_summary": truncated_summary,
                    "text": summary,
                }
            )
            return out

        message = _ellipsize_right(message_raw, avail_message)
        truncated_message = 1 if message != message_raw else 0
        padding = " " * max(0, w - len(message) - len(summary_raw))
        out.update(
            {
                "active": 1,
                "message_raw": message_raw,
                "summary_raw": summary_raw,
                "message": message,
                "summary": summary_raw,
                "padding": padding,
                "padding_width": len(padding),
                "constantshow": constantshow,
                "truncated_message": truncated_message,
                "truncated_summary": truncated_summary,
                "text": (message + padding + summary_raw)[:w],
            }
        )
        return out

    def infobar_text(self, width: int) -> str:
        """Return the idle infobar line for the current editor state."""

        return str(self.infobar_model(width).get("text", "") or "")

    def line_number_gutter_width(self) -> int:
        """Return the tiny reference gutter width for line numbers.

        The minimal curses TUI currently reserves ``digits(total_lines) + 1``
        cells when `ruler` is on. Exposing that tiny policy here keeps future
        UIs/scripts/LLMs from re-deriving it from renderer code.
        """

        eb = self.cur()
        if not bool(self.options.get("ruler", local=eb.local_options)):
            return 0
        digits = max(1, len(str(max(1, len(eb.buf.lines)))))
        return digits + 1

    def line_number_gutter_text(self, *, line_index: int, wrap_start_col: int, gutter_width: int) -> str:
        """Return the display text for one rendered buffer row's line-number cell.

        Policy (tiny, deterministic, micro-esque):
          - if the ruler is off, return ``""``
          - wrapped continuation rows show a blank gutter
          - `relativeruler` shows relative numbers off the current line while the
            current line still shows its absolute 1-based line number
          - the final column is reserved as a spacer before buffer text
        """

        if int(gutter_width) <= 0:
            return ""
        if int(wrap_start_col) > 0:
            return " " * int(gutter_width)

        eb = self.cur()
        cur_line = int(eb.cursors[eb.primary].line) if eb.cursors else 0
        is_relative = bool(self.options.get("relativeruler", local=eb.local_options))
        li = max(0, int(line_index))
        n = (li + 1) if (not is_relative or li == cur_line) else abs(li - cur_line)
        cell_w = max(1, int(gutter_width) - 1)
        return f"{n:>{cell_w}} "

    def scrollbar_gutter_width(self) -> int:
        """Return the tiny reference right-edge scrollbar gutter width."""

        eb = self.cur()
        return 1 if bool(self.options.get("scrollbar", local=eb.local_options)) else 0

    def scrollbar_thumb_span(self, *, total_rows: int, start_row: int, window_rows: int) -> tuple[int, int] | None:
        """Return the tiny scrollbar thumb span as ``(top, size)`` within the window.

        The model intentionally works on abstract rows so callers can use
        logical lines in ordinary views and visual rows under softwrap.
        """

        win = max(0, int(window_rows))
        total = max(0, int(total_rows))
        start = max(0, int(start_row))
        if win <= 0 or total <= win or total <= 0:
            return None

        thumb = max(1, min(win, round((win * win) / total)))
        max_top = max(0, win - thumb)
        max_start = max(1, total - win)
        top = round(min(start, max_start) * max_top / max_start)
        top = max(0, min(int(top), max_top))
        return (int(top), int(thumb))

    def scrollbar_thumb_char(self) -> str:
        """Return the tiny one-cell scrollbar thumb glyph."""

        try:
            eb = self.cur()
            raw = str(self.options.get("scrollbarchar", local=eb.local_options) or "")
        except Exception:
            raw = ""
        return raw[:1] or "|"

    def gutter_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible gutter model for one screen size.

        This lifts the remaining small reference-TUI gutter truth into one
        inspectable editor-side snapshot: the left line-number cells and the
        right-edge scrollbar thumb rows are exposed with stable screen
        positions, so future UIs, tests, scripts, and LLMs do not need to
        rebuild those visible gutters from scattered layout helpers.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        left_w = int(layout.get("gutter_left", 0) or 0)
        right_w = int(layout.get("gutter_right", 0) or 0)
        viewport_h = int(layout.get("viewport_height", 0) or 0)
        scrollbar_x = int(layout.get("scrollbar_x", max(0, w - right_w)) or max(0, w - right_w))
        out: dict[str, Any] = {
            "active": 0,
            "lines": h,
            "cols": w,
            "left_width": left_w,
            "right_width": right_w,
            "line_numbers_active": 0,
            "scrollbar_active": 0,
            "scrollbar_x": int(scrollbar_x),
            "line_numbers": [],
            "scrollbar_rows": [],
        }

        rows = list(window.get("rows") or [])
        number_rows: list[dict[str, Any]] = []
        if left_w > 0:
            cur_line = int(self.primary_cursor().line)
            for row in rows:
                li = int(row.get("line", 0) or 0)
                start_col = int(row.get("start_col", 0) or 0)
                text = self.line_number_gutter_text(
                    line_index=li,
                    wrap_start_col=start_col,
                    gutter_width=left_w,
                )
                number_rows.append(
                    {
                        "screen_y": int(row.get("screen_y", 0) or 0),
                        "screen_x": 0,
                        "width": left_w,
                        "line": li,
                        "start_col": start_col,
                        "current": 1 if start_col == 0 and li == cur_line else 0,
                        "text": text,
                    }
                )

        scrollbar_rows: list[dict[str, Any]] = []
        if right_w > 0 and viewport_h > 0:
            eb = self.cur()
            softwrap_enabled = bool(self.options.get("softwrap", local=eb.local_options))
            if softwrap_enabled:
                total_rows = self._total_visual_rows(eb, w=max(1, int(layout.get("viewport_width", 1) or 1)))
                start_row = self._viewport_visual_start(eb, w=max(1, int(layout.get("viewport_width", 1) or 1)))
            else:
                total_rows = max(1, len(eb.buf.lines))
                vp = dict(window.get("viewport") or {})
                start_row = max(0, int(vp.get("top_line", vp.get("top", 0)) or 0))
            thumb = self.scrollbar_thumb_span(total_rows=total_rows, start_row=start_row, window_rows=viewport_h)
            if thumb is not None:
                thumb_top, thumb_size = thumb
                thumb_char = self.scrollbar_thumb_char()
                for yy in range(int(thumb_top), min(int(viewport_h), int(thumb_top) + int(thumb_size))):
                    scrollbar_rows.append(
                        {
                            "screen_y": int(yy),
                            "screen_x": int(scrollbar_x),
                            "width": right_w,
                            "kind": "thumb",
                            "text": thumb_char,
                        }
                    )

        out.update(
            {
                "active": 1 if number_rows or scrollbar_rows else 0,
                "line_numbers_active": 1 if number_rows else 0,
                "scrollbar_active": 1 if scrollbar_rows else 0,
                "line_numbers": number_rows,
                "scrollbar_rows": scrollbar_rows,
            }
        )
        return out

    def screen_layout_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the tiny reference screen-layout model for the curses UI.

        This keeps the reference editor's row/column reservation policy
        inspectable: future UIs, tests, scripts, and LLMs can see how much of a
        screen is consumed by gutters, picker suggestions, and bottom chrome
        without scraping curses output or repeating the layout math by hand.
        Combine it with `bottom_rows_model(width)` when the visible bottom-row
        *text* matters.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        out: dict[str, Any] = {
            "lines": h,
            "cols": w,
            "viewport_x": 0,
            "viewport_y": 0,
            "viewport_width": 0,
            "viewport_height": 0,
            "suggestions_y": 0,
            "suggestions_height": 0,
            "suggestions_width": 0,
            "gutter_left": 0,
            "gutter_right": 0,
            "scrollbar_x": 0,
            "bottom_rows": [],
            "bottom_rows_count": 0,
            "chrome_top_y": -1,
            "prompt_y": -1,
            "status_y": -1,
            "keymenu_y": -1,
        }
        if h <= 0 or w <= 0:
            return out

        gutter_left = int(self.line_number_gutter_width())
        gutter_right = int(self.scrollbar_gutter_width())

        bottom_rows_text = self.bottom_rows_model(w)
        bottom_rows: list[dict[str, Any]] = []
        if bottom_rows_text:
            start_y = max(0, h - len(bottom_rows_text))
            for idx, row in enumerate(bottom_rows_text):
                kind = str(row.get("kind", "") or "")
                slot = str(row.get("slot", "") or "")
                y = int(start_y + idx)
                entry = {"kind": kind, "slot": slot, "y": y}
                bottom_rows.append(entry)
                if slot == "prompt" and int(out.get("prompt_y", -1)) < 0:
                    out["prompt_y"] = y
                if kind == "statusline" and int(out.get("status_y", -1)) < 0:
                    out["status_y"] = y
                if kind == "keymenu" and int(out.get("keymenu_y", -1)) < 0:
                    out["keymenu_y"] = y
            out["chrome_top_y"] = int(start_y)

        sug_h = 0
        if self.prompt is not None and self.prompt.kind not in ("command", "find") and self.prompt.suggestion_rows:
            sug_h = min(8, max(1, h // 4))

        viewport_h = max(1, h - len(bottom_rows) - sug_h)
        viewport_w = max(1, w - gutter_left - gutter_right)
        scrollbar_x = int(gutter_left + viewport_w)

        out.update(
            {
                "viewport_x": int(gutter_left),
                "viewport_y": 0,
                "viewport_width": int(viewport_w),
                "viewport_height": int(viewport_h),
                "suggestions_y": int(viewport_h),
                "suggestions_height": int(sug_h),
                "suggestions_width": int(viewport_w),
                "gutter_left": int(gutter_left),
                "gutter_right": int(gutter_right),
                "scrollbar_x": int(scrollbar_x),
                "bottom_rows": bottom_rows,
                "bottom_rows_count": int(len(bottom_rows)),
            }
        )
        return out

    def _viewport_rows_model_from_parts(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
        gutter: dict[str, Any],
    ) -> dict[str, Any]:
        """Return the shared visible edit-surface rows from existing model parts.

        This keeps the composed viewport rows deterministic and inspectable
        without forcing callers to zip together edit-window rows and gutter
        rows by hand. Styling still belongs to the renderer; the shared editor
        core owns the boring visible text/position contract.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        viewport_y = int(layout.get("viewport_y", 0) or 0)
        viewport_x = int(layout.get("viewport_x", 0) or 0)
        viewport_h = int(layout.get("viewport_height", 0) or 0)
        viewport_w = int(layout.get("viewport_width", 0) or 0)
        left_w = int(layout.get("gutter_left", 0) or 0)
        right_w = int(layout.get("gutter_right", 0) or 0)
        right_x = int(layout.get("scrollbar_x", viewport_x + viewport_w) or (viewport_x + viewport_w))

        out: dict[str, Any] = {
            "active": 0,
            "lines": h,
            "cols": w,
            "y": int(viewport_y),
            "x": int(viewport_x),
            "width": int(viewport_w),
            "height": int(viewport_h),
            "left_width": int(left_w),
            "right_width": int(right_w),
            "rows": [],
            "row_count": 0,
        }
        if viewport_h <= 0 or viewport_w <= 0:
            return out

        rows_by_screen_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(window.get("rows") or [])
            if isinstance(row, dict)
        }
        line_numbers_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(gutter.get("line_numbers") or [])
            if isinstance(row, dict)
        }
        scrollbar_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(gutter.get("scrollbar_rows") or [])
            if isinstance(row, dict)
        }
        cursor = dict(window.get("cursor") or {})
        cursor_visible = bool(int(cursor.get("visible", 0) or 0))
        cursor_y = int(cursor.get("screen_y", -1) or -1)
        cursor_x = int(cursor.get("screen_x", -1) or -1)

        out_rows: list[dict[str, Any]] = []
        for view_y in range(int(viewport_h)):
            screen_y = int(viewport_y + view_y)
            row_model = dict(rows_by_screen_y.get(screen_y, {}))
            left_model = dict(line_numbers_by_y.get(screen_y, {}))
            right_model = dict(scrollbar_by_y.get(screen_y, {}))
            frag = str(row_model.get("text", "") or "")
            if viewport_w > 0:
                frag = frag[: int(viewport_w)]
            left_text = str(left_model.get("text", "") or "") if left_w > 0 else ""
            if left_w > 0 and not left_text:
                left_text = " " * int(left_w)
            right_text = str(right_model.get("text", "") or "") if right_w > 0 else ""
            right_fill = right_text if right_text else ((" " * int(right_w)) if right_w > 0 else "")
            combined = (left_text + frag.ljust(max(0, int(viewport_w))) + right_fill).rstrip()
            cursor_here = 1 if cursor_visible and int(screen_y) == int(cursor_y) else 0
            out_rows.append(
                {
                    "view_y": int(view_y),
                    "screen_y": int(screen_y),
                    "line": int(row_model["line"]) if "line" in row_model else -1,
                    "has_line": 1 if row_model else 0,
                    "start_col": int(row_model.get("start_col", 0) or 0),
                    "text": frag,
                    "text_x": int(viewport_x),
                    "text_width": int(viewport_w),
                    "continuation": int(row_model.get("continuation", 0) or 0),
                    "left_x": 0,
                    "left_text": left_text,
                    "left_width": int(left_w),
                    "current": int(left_model.get("current", 0) or 0),
                    "right_x": int(right_x),
                    "right_text": right_text,
                    "right_width": int(right_w),
                    "combined_text": combined,
                    "cursor_here": int(cursor_here),
                    "cursor_x": int(cursor_x) if cursor_here else -1,
                    "empty": 0 if row_model else 1,
                }
            )

        out.update(
            {
                "active": 1 if out_rows else 0,
                "rows": out_rows,
                "row_count": int(len(out_rows)),
            }
        )
        return out

    def viewport_rows_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible viewport-row model for one screen size.

        This zips together the edit-window rows and visible gutters into one
        inspectable row-ordered snapshot, so future UIs, tests, scripts, and
        LLM handoffs can answer the practical question "what visible edit rows
        exist right now?" without rejoining line numbers, text fragments, and
        scrollbar rows by screen position.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        gutter = dict(self.gutter_model(lines=h, cols=w))
        return self._viewport_rows_model_from_parts(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
            gutter=gutter,
        )

    def _search_rows_model_from_window(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
    ) -> dict[str, Any]:
        """Return visible search-match spans aligned with one live edit window.

        The contract deliberately stays viewport-local and text-first: expose
        the exact visible row fragments, their best-effort search-match spans,
        and which visible match currently owns the primary cursor without
        promoting search highlighting into a larger whole-buffer style system.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        viewport_h = int(layout.get("viewport_height", 0) or 0)
        viewport_w = int(layout.get("viewport_width", 0) or 0)
        eb = self.cur()
        enabled = bool(self.options.get("hlsearch", local=eb.local_options))
        query = str(self.search.query or "")
        literal = bool(self.search.literal)
        case_sensitive = bool(self.search.case_sensitive)
        if query and not self._can_read_search_state():
            query = ""
        out: dict[str, Any] = {
            "active": 1 if query else 0,
            "enabled": 1 if enabled else 0,
            "lines": h,
            "cols": w,
            "y": int(layout.get("viewport_y", 0) or 0),
            "x": int(layout.get("viewport_x", 0) or 0),
            "width": int(max(0, viewport_w)),
            "height": int(max(0, viewport_h)),
            "query": str(query),
            "literal": 1 if literal else 0,
            "case_sensitive": 1 if case_sensitive else 0,
            "rows": [],
            "row_count": 0,
            "match_rows": 0,
        }
        if viewport_h <= 0 or viewport_w <= 0:
            return out

        cursor = dict(window.get("cursor") or {})
        cursor_visible = bool(int(cursor.get("visible", 0) or 0))
        cursor_view_y = int(cursor["view_y"]) if "view_y" in cursor else -1
        cursor_view_x = int(cursor["view_x"]) if "view_x" in cursor else -1
        rows_by_view_y = {
            int(row.get("view_y", -1)): dict(row)
            for row in list(window.get("rows") or [])
            if isinstance(row, dict)
        }

        out_rows: list[dict[str, Any]] = []
        match_rows = 0
        for view_y in range(int(viewport_h)):
            row = dict(rows_by_view_y.get(int(view_y), {}))
            text = str(row.get("text", "") or "")
            spans = search_match_spans(
                text,
                query,
                literal=literal,
                case_sensitive=case_sensitive,
            ) if enabled and query else []
            current_spans = [
                (int(a), int(b))
                for a, b in spans
                if cursor_visible and int(view_y) == int(cursor_view_y) and int(a) <= int(cursor_view_x) < int(b)
            ]
            if spans:
                match_rows += 1
            out_rows.append(
                {
                    "view_y": int(view_y),
                    "screen_y": int(row["screen_y"]) if "screen_y" in row else int(layout.get("viewport_y", 0) or 0) + int(view_y),
                    "line": int(row["line"]) if "line" in row else -1,
                    "start_col": int(row["start_col"]) if "start_col" in row else 0,
                    "text": text,
                    "spans": [[int(a), int(b)] for a, b in spans],
                    "current_spans": [[int(a), int(b)] for a, b in current_spans],
                    "match_count": int(len(spans)),
                    "current_match_count": int(len(current_spans)),
                }
            )

        out.update(
            {
                "rows": out_rows,
                "row_count": int(len(out_rows)),
                "match_rows": int(match_rows),
            }
        )
        return out

    def search_rows_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible search-cue model for one screen size.

        This reports viewport-local search-match spans for the active whole-
        buffer search, aligned with the same live edit-window rows the minimal
        curses TUI paints. It stays smaller than a general style API: just the
        visible row fragments, their spans, and the cursor-owned current match.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        return self._search_rows_model_from_window(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
        )

    def _showchars_rows_model_from_window(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
    ) -> dict[str, Any]:
        """Return visible ``showchars`` replacements aligned with one edit window.

        The contract stays viewport-local and text-first: expose the exact raw
        row fragments, their visible replacement text, and the replacement spans
        produced by the current tiny ``showchars`` policy without promoting that
        cue into a larger whole-buffer style system.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        viewport_h = int(layout.get("viewport_height", 0) or 0)
        viewport_w = int(layout.get("viewport_width", 0) or 0)
        eb = self.cur()
        raw_spec = str(self.options.get("showchars", local=eb.local_options) or "")
        spec = parse_showchars_option(raw_spec)
        out: dict[str, Any] = {
            "active": 1 if spec else 0,
            "enabled": 1 if spec else 0,
            "lines": h,
            "cols": w,
            "y": int(layout.get("viewport_y", 0) or 0),
            "x": int(layout.get("viewport_x", 0) or 0),
            "width": int(max(0, viewport_w)),
            "height": int(max(0, viewport_h)),
            "spec": str(raw_spec),
            "rows": [],
            "row_count": 0,
            "changed_rows": 0,
        }
        if viewport_h <= 0 or viewport_w <= 0:
            return out

        rows_by_view_y = {
            int(row.get("view_y", -1)): dict(row)
            for row in list(window.get("rows") or [])
            if isinstance(row, dict)
        }

        out_rows: list[dict[str, Any]] = []
        changed_rows = 0
        for view_y in range(int(viewport_h)):
            row = dict(rows_by_view_y.get(int(view_y), {}))
            text = str(row.get("text", "") or "")
            line_index = int(row["line"]) if "line" in row else -1
            start_col = int(row["start_col"]) if "start_col" in row else 0
            line_text = str(eb.buf.lines[line_index]) if 0 <= int(line_index) < len(eb.buf.lines) else text
            display_text, spans = render_showchars_fragment(
                line_text,
                frag_start=int(start_col),
                frag_text=text,
                spec=spec,
            )
            if spans:
                changed_rows += 1
            out_rows.append(
                {
                    "view_y": int(view_y),
                    "screen_y": int(row["screen_y"]) if "screen_y" in row else int(layout.get("viewport_y", 0) or 0) + int(view_y),
                    "line": int(line_index),
                    "start_col": int(start_col),
                    "text": text,
                    "display_text": str(display_text),
                    "spans": [[int(a), int(b)] for a, b in spans],
                    "replacement_count": int(len(spans)),
                }
            )

        out.update(
            {
                "rows": out_rows,
                "row_count": int(len(out_rows)),
                "changed_rows": int(changed_rows),
            }
        )
        return out

    def showchars_rows_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible ``showchars`` row model for one screen size.

        Future UIs, tests, scripts, and LLM handoffs can inspect the exact
        visible replacements and their spans without re-parsing the option or
        recomputing fragment-local indentation rules in renderer code.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        return self._showchars_rows_model_from_window(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
        )

    def _viewport_cues_model_from_parts(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
        search_rows: dict[str, Any],
        showchars_rows: dict[str, Any],
    ) -> dict[str, Any]:
        """Return shared visible cue spans aligned with one live edit window.

        This keeps the contract deliberately viewport-local and span-first:
        expose the tiny non-text cues that the reference TUI overlays on edit
        rows (current row, search/current match, showchars replacements,
        trailing whitespace, tab errors, colorcolumn, and brace pairs) without
        promoting them into a broader theme or attribute system.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        viewport_h = int(layout.get("viewport_height", 0) or 0)
        viewport_w = int(layout.get("viewport_width", 0) or 0)
        eb = self.cur()
        raw_showchars = str(self.options.get("showchars", local=eb.local_options) or "")
        showchars_enabled = bool(parse_showchars_option(raw_showchars))
        cursorline_enabled = bool(self.options.get("cursorline", local=eb.local_options))
        hlsearch_enabled = bool(self.options.get("hlsearch", local=eb.local_options))
        hltrailingws_enabled = bool(self.options.get("hltrailingws", local=eb.local_options))
        hltaberrors_enabled = bool(self.options.get("hltaberrors", local=eb.local_options))
        colorcolumn = int(self.options.get("colorcolumn", local=eb.local_options) or 0)
        tabstospaces = bool(self.options.get("tabstospaces", local=eb.local_options))
        softwrap_enabled = bool(self.options.get("softwrap", local=eb.local_options))
        matchbrace_enabled = bool(self.options.get("matchbrace", local=eb.local_options))
        matchbraceleft_enabled = bool(self.options.get("matchbraceleft", local=eb.local_options))

        out: dict[str, Any] = {
            "active": 1 if viewport_h > 0 and viewport_w > 0 else 0,
            "enabled": 1 if any(
                [
                    cursorline_enabled,
                    hlsearch_enabled,
                    showchars_enabled,
                    hltrailingws_enabled,
                    hltaberrors_enabled,
                    int(colorcolumn) > 0,
                    matchbrace_enabled,
                ]
            ) else 0,
            "lines": h,
            "cols": w,
            "y": int(layout.get("viewport_y", 0) or 0),
            "x": int(layout.get("viewport_x", 0) or 0),
            "width": int(max(0, viewport_w)),
            "height": int(max(0, viewport_h)),
            "cursorline_enabled": 1 if cursorline_enabled else 0,
            "hlsearch_enabled": 1 if hlsearch_enabled else 0,
            "showchars_enabled": 1 if showchars_enabled else 0,
            "hltrailingws_enabled": 1 if hltrailingws_enabled else 0,
            "hltaberrors_enabled": 1 if hltaberrors_enabled else 0,
            "tabstospaces": 1 if tabstospaces else 0,
            "colorcolumn": int(colorcolumn),
            "matchbrace_enabled": 1 if matchbrace_enabled else 0,
            "matchbraceleft_enabled": 1 if matchbraceleft_enabled else 0,
            "rows": [],
            "row_count": 0,
            "cue_rows": 0,
        }
        if viewport_h <= 0 or viewport_w <= 0:
            return out

        cursor = dict(window.get("cursor") or {})
        cursor_visible = bool(int(cursor.get("visible", 0) or 0))
        cursor_view_y = int(cursor["view_y"]) if "view_y" in cursor else -1
        rows_by_view_y = {
            int(row.get("view_y", -1)): dict(row)
            for row in list(window.get("rows") or [])
            if isinstance(row, dict)
        }
        search_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(search_rows.get("rows") or [])
            if isinstance(row, dict)
        }
        showchars_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(showchars_rows.get("rows") or [])
            if isinstance(row, dict)
        }
        brace_positions = matching_brace_positions(
            eb.buf.lines,
            line=int(eb.cursors[eb.primary].line),
            col=int(eb.cursors[eb.primary].col),
            match_left=matchbraceleft_enabled,
        ) if matchbrace_enabled else []

        out_rows: list[dict[str, Any]] = []
        cue_rows = 0
        for view_y in range(int(viewport_h)):
            row = dict(rows_by_view_y.get(int(view_y), {}))
            screen_y = int(row["screen_y"]) if "screen_y" in row else int(layout.get("viewport_y", 0) or 0) + int(view_y)
            text = str(row.get("text", "") or "")
            line_index = int(row["line"]) if "line" in row else -1
            start_col = int(row.get("start_col", 0) or 0)
            line_text = str(eb.buf.lines[line_index]) if 0 <= int(line_index) < len(eb.buf.lines) else text

            search_row = dict(search_by_y.get(int(screen_y), {}))
            search_spans = [
                [int(a), int(b)] for a, b in [tuple(int(x) for x in span[:2]) for span in list(search_row.get("spans") or [])]
            ]
            current_search_spans = [
                [int(a), int(b)] for a, b in [tuple(int(x) for x in span[:2]) for span in list(search_row.get("current_spans") or [])]
            ]
            showchars_row = dict(showchars_by_y.get(int(screen_y), {}))
            showchar_spans = [
                [int(a), int(b)] for a, b in [tuple(int(x) for x in span[:2]) for span in list(showchars_row.get("spans") or [])]
            ]
            trailing_spans_ = trailing_whitespace_spans(
                line_text,
                frag_start=int(start_col),
                frag_text=text,
            ) if hltrailingws_enabled else []
            tab_error_spans_ = tab_error_spans(
                line_text,
                tabstospaces=tabstospaces,
                frag_start=int(start_col),
                frag_text=text,
            ) if hltaberrors_enabled else []
            color_x = colorcolumn_screen_x(
                colorcolumn=int(colorcolumn),
                frag_start=int(start_col),
                view_width=int(viewport_w),
                softwrap=softwrap_enabled,
            )
            colorcolumn_spans = [] if color_x is None or int(color_x) >= len(text) else [(int(color_x), int(color_x) + 1)]
            brace_spans_ = brace_match_spans(
                line_index=int(line_index),
                frag_start=int(start_col),
                frag_text=text,
                brace_positions=brace_positions,
            ) if matchbrace_enabled else []
            cursorline = 1 if cursor_visible and cursorline_enabled and int(view_y) == int(cursor_view_y) else 0
            row_has_any = bool(cursorline or search_spans or current_search_spans or showchar_spans or trailing_spans_ or tab_error_spans_ or colorcolumn_spans or brace_spans_)
            if row_has_any:
                cue_rows += 1
            out_rows.append(
                {
                    "view_y": int(view_y),
                    "screen_y": int(screen_y),
                    "line": int(line_index),
                    "start_col": int(start_col),
                    "text": text,
                    "cursorline": int(cursorline),
                    "search_spans": search_spans,
                    "current_search_spans": current_search_spans,
                    "showchar_spans": showchar_spans,
                    "trailing_spans": [[int(a), int(b)] for a, b in trailing_spans_],
                    "tab_error_spans": [[int(a), int(b)] for a, b in tab_error_spans_],
                    "colorcolumn_x": int(color_x) if color_x is not None else -1,
                    "colorcolumn_blank": 1 if color_x is not None and int(color_x) >= len(text) else 0,
                    "colorcolumn_spans": [[int(a), int(b)] for a, b in colorcolumn_spans],
                    "brace_spans": [[int(a), int(b)] for a, b in brace_spans_],
                    "cue_count": int(
                        int(cursorline)
                        + len(search_spans)
                        + len(current_search_spans)
                        + len(showchar_spans)
                        + len(trailing_spans_)
                        + len(tab_error_spans_)
                        + len(colorcolumn_spans)
                        + len(brace_spans_)
                    ),
                }
            )

        out.update(
            {
                "rows": out_rows,
                "row_count": int(len(out_rows)),
                "cue_rows": int(cue_rows),
            }
        )
        return out

    def viewport_cues_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible cue-span model for one screen snapshot.

        Future UIs, tests, scripts, and LLM handoffs can inspect the tiny
        visible non-text edit-window cues the reference TUI paints — current
        row, search/current match, showchars replacements, trailing whitespace,
        tab errors, colorcolumn, and brace pairs — without scraping curses
        attributes or recomputing those spans from raw buffer state.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        search_rows = dict(
            self._search_rows_model_from_window(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        showchars_rows = dict(
            self._showchars_rows_model_from_window(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        return self._viewport_cues_model_from_parts(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
            search_rows=search_rows,
            showchars_rows=showchars_rows,
        )

    def _docs_cues_model_from_parts(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
    ) -> dict[str, Any]:
        """Return shared visible docs/help scanability spans for one edit window."""

        from .docs_cues import docs_cues_model_from_parts

        return docs_cues_model_from_parts(
            self,
            lines=lines,
            cols=cols,
            layout=layout,
            window=window,
        )

    def docs_cues_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return shared visible docs/help scanability spans for one screen.

        Future UIs, tests, scripts, and LLM handoffs can inspect the same tiny
        markdown-ish heading/link/list/blockquote/table cues the reference TUI
        paints for docs/help buffers without scraping curses attributes or
        re-parsing those visible row fragments themselves.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        return self._docs_cues_model_from_parts(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
        )

    def prompt_panel_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared visible picker-panel model for one screen size.

        This lifts the remaining reference-TUI prompt-panel truth into one
        inspectable editor-side snapshot: if a picker-style prompt currently has
        visible suggestion rows, the model reports the reserved panel geometry
        plus the rendered visible entries with stable screen positions.

        Future UIs, scripts, tests, and LLMs can inspect the same picker panel
        the curses TUI paints without recomputing suggestion height, sticky
        headers, more markers, or row placement from several smaller helpers.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        sug_h = int(layout.get("suggestions_height", 0) or 0)
        sug_y = int(layout.get("suggestions_y", 0) or 0)
        sug_w = int(layout.get("suggestions_width", 0) or 0)
        prompt = self.prompt
        kind = "" if prompt is None else str(prompt.kind or "")
        out: dict[str, Any] = {
            "active": 0,
            "kind": kind,
            "lines": h,
            "cols": w,
            "y": int(sug_y),
            "x": 0,
            "width": int(max(0, sug_w)),
            "screen_width": int(w),
            "height": int(max(0, sug_h)),
            "entries": [],
            "row_count": 0,
        }
        if (
            prompt is None
            or not self._can_read_prompt_state(prompt)
            or kind in ("command", "find")
            or sug_h <= 0
            or sug_w <= 0
        ):
            return out
        if not prompt.suggestion_rows:
            return out

        entries: list[dict[str, Any]] = []
        for idx, row in enumerate(self.prompt_display_model(max_lines=sug_h, width=sug_w)):
            if not isinstance(row, dict):
                continue
            ent = dict(row)
            ent.setdefault("text", "")
            ent["screen_y"] = int(sug_y + idx)
            ent["screen_x"] = 0
            entries.append(ent)

        out.update(
            {
                "active": 1 if entries else 0,
                "entries": entries,
                "row_count": int(len(entries)),
            }
        )
        return out

    def edit_window_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared reference edit-window model for a given screen.

        This lifts the remaining tiny curses-specific viewing truth into one
        inspectable editor-side snapshot: given a screen size, it applies the
        same reference layout reservation policy as the minimal TUI, syncs the
        viewport size/follow-cursor behavior, and reports the visible edit
        window rows plus the primary cursor's position within that window.

        Unlike `screen_layout_model(...)`, this is intentionally a *live view*
        snapshot: it may update the stored viewport size/origin the same way a
        real renderer would before painting.
        """

        layout = dict(self.screen_layout_model(lines=lines, cols=cols))
        view_h = int(layout.get("viewport_height", 0) or 0)
        view_w = int(layout.get("viewport_width", 0) or 0)
        out: dict[str, Any] = dict(layout)
        out.update(
            {
                "rows": [],
                "row_count": 0,
                "viewport": self.viewport_model(),
                "cursor": {
                    "view_y": 0,
                    "view_x": 0,
                    "screen_y": int(layout.get("viewport_y", 0) or 0),
                    "screen_x": int(layout.get("viewport_x", 0) or 0),
                    "visible": 0,
                },
                "softwrap": 0,
            }
        )
        if view_h <= 0 or view_w <= 0:
            return out

        self.set_viewport(height=view_h, width=view_w, follow_cursor=True)
        vp = self.viewport_model()
        eb = self.cur()
        softwrap = bool(self.options.get("softwrap", local=eb.local_options))
        rows = self.view_rows(height=view_h, width=view_w)
        row_models: list[dict[str, Any]] = []
        base_y = int(layout.get("viewport_y", 0) or 0)
        base_x = int(layout.get("viewport_x", 0) or 0)
        for view_y, (li, start_col, frag) in enumerate(rows):
            row_models.append(
                {
                    "view_y": int(view_y),
                    "screen_y": int(base_y + view_y),
                    "screen_x": int(base_x),
                    "line": int(li),
                    "start_col": int(start_col),
                    "text": str(frag),
                    "continuation": 1 if softwrap and int(start_col) > 0 else 0,
                }
            )

        cy, cx = self.cursor_view_pos(height=view_h, width=view_w)
        cursor_visible = 1 if 0 <= int(cy) < len(row_models) and 0 <= int(cx) < view_w else 0
        out.update(
            {
                "rows": row_models,
                "row_count": int(len(row_models)),
                "viewport": vp,
                "cursor": {
                    "view_y": int(cy),
                    "view_x": int(cx),
                    "screen_y": int(base_y + cy),
                    "screen_x": int(base_x + cx),
                    "visible": int(cursor_visible),
                },
                "softwrap": 1 if softwrap else 0,
            }
        )
        return out


    def _display_rows_model_from_parts(
        self,
        *,
        lines: int,
        cols: int,
        layout: dict[str, Any],
        window: dict[str, Any],
        prompt_panel: dict[str, Any],
        showchars_rows: dict[str, Any],
        viewport_rows: dict[str, Any],
    ) -> dict[str, Any]:
        """Return shared display-text screen rows from already-synced model parts."""

        h = max(0, int(lines))
        w = max(0, int(cols))
        out: dict[str, Any] = {
            "active": 0,
            "lines": h,
            "cols": w,
            "rows": [],
            "row_count": 0,
        }
        if h <= 0 or w <= 0:
            return out

        eb = self.cur()
        layout_rows = list(layout.get("bottom_rows", []) or [])
        bottom_rows_text = list(self.bottom_rows_model(w)) if w > 0 else []
        bottom_rows: list[dict[str, Any]] = []
        for idx, row in enumerate(bottom_rows_text):
            entry = dict(row)
            if idx < len(layout_rows):
                entry["y"] = int(layout_rows[idx].get("y", -1) or -1)
            else:
                entry["y"] = -1
            bottom_rows.append(entry)

        cursor = dict(window.get("cursor") or {})
        cursor.setdefault("visible", 0)
        cursor["mode"] = "edit"
        prompt_y = int(layout.get("prompt_y", -1) or -1)
        if prompt_y >= 0 and self.prompt is not None:
            prompt_cursor = max(0, int(self.status_model().get("prompt_cursor", 0) or 0))
            cursor = {
                "mode": "prompt",
                "screen_y": int(prompt_y),
                "screen_x": max(0, min(max(0, w - 1), 1 + prompt_cursor)),
                "visible": 1 if w > 0 and h > 0 else 0,
            }
        cursor_visible = bool(int(cursor.get("visible", 0) or 0))
        cursor_y = int(cursor.get("screen_y", -1) or -1)
        cursor_x = int(cursor.get("screen_x", -1) or -1)

        softwrap_enabled = bool(self.options.get("softwrap", local=eb.local_options))
        overflow_enabled = bool(self.options.get("overflowmarkers", local=eb.local_options))
        showchars_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(showchars_rows.get("rows") or [])
            if isinstance(row, dict)
        }
        viewport_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(viewport_rows.get("rows") or [])
            if isinstance(row, dict)
        }
        panel_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(prompt_panel.get("entries") or [])
            if isinstance(row, dict)
        }
        bottom_by_y = {
            int(row.get("y", -1)): dict(row)
            for row in list(bottom_rows or [])
            if isinstance(row, dict)
        }

        rows: list[dict[str, Any]] = []
        for y in range(int(h)):
            text = ""
            entry: dict[str, Any] = {
                "screen_y": int(y),
                "screen_x": 0,
                "width": int(w),
                "kind": "blank",
                "text": text,
                "raw_text": text,
                "display_changed": 0,
                "empty": 1,
                "cursor_here": 1 if cursor_visible and int(y) == int(cursor_y) else 0,
                "cursor_x": int(cursor_x) if cursor_visible and int(y) == int(cursor_y) else -1,
            }
            vp = viewport_by_y.get(int(y))
            if vp is not None:
                frag = str(vp.get("text", "") or "")
                line_index = int(vp["line"]) if "line" in vp else -1
                start_col = int(vp.get("start_col", 0) or 0)
                view_w = int(vp.get("text_width", layout.get("viewport_width", 0) or 0) or 0)
                left_text = str(vp.get("left_text", "") or "")
                right_text = str(vp.get("right_text", "") or "")
                right_w = int(vp.get("right_width", 0) or 0)
                right_fill = right_text if right_text else ((" " * int(right_w)) if right_w > 0 else "")
                raw_text = str(vp.get("combined_text", "") or "")[: int(w)]
                showchars_model = dict(showchars_by_y.get(int(y), {}))
                display_frag0 = str(showchars_model.get("display_text", frag) or frag)
                line_text = str(eb.buf.lines[line_index]) if 0 <= int(line_index) < len(eb.buf.lines) else str(frag)
                display_frag, overflow_cells = render_overflow_fragment(
                    line_text,
                    frag_start=int(start_col),
                    frag_text=display_frag0,
                    view_width=int(view_w),
                    softwrap=softwrap_enabled or not overflow_enabled,
                )
                display_area = str(display_frag).ljust(max(0, int(view_w)))
                text = (left_text + display_area + right_fill).rstrip()[: int(w)]
                entry.update(
                    {
                        "kind": "viewport",
                        "text": text,
                        "raw_text": raw_text,
                        "display_changed": 1 if text != raw_text else 0,
                        "empty": 0 if vp and text else 1,
                        "view_y": int(vp.get("view_y", 0) or 0),
                        "line": int(line_index),
                        "has_line": int(vp.get("has_line", 0) or 0),
                        "start_col": int(start_col),
                        "continuation": int(vp.get("continuation", 0) or 0),
                        "viewport_text": frag,
                        "viewport_display_text": str(display_frag),
                        "overflow_cells": [[int(pos), str(ch)] for pos, ch in overflow_cells],
                        "overflow_count": int(len(overflow_cells)),
                        "overflow_left": 1 if any(int(pos) == 0 and str(ch) == '<' for pos, ch in overflow_cells) else 0,
                        "overflow_right": 1 if any(str(ch) == '>' for _, ch in overflow_cells) else 0,
                    }
                )
            panel = panel_by_y.get(int(y))
            if panel is not None:
                text = str(panel.get("text", "") or "")[: int(w)]
                entry.update(
                    {
                        "kind": "prompt-panel",
                        "text": text,
                        "raw_text": text,
                        "display_changed": 0,
                        "empty": 0 if text else 1,
                        "type": str(panel.get("type", "") or ""),
                        "row_kind": str(panel.get("row_kind", "") or ""),
                        "selected": int(panel.get("selected", 0) or 0),
                    }
                )
            bottom = bottom_by_y.get(int(y))
            if bottom is not None:
                text = str(bottom.get("text", "") or "")[: int(w)]
                entry.update(
                    {
                        "kind": str(bottom.get("kind", "bottom") or "bottom"),
                        "slot": str(bottom.get("slot", "") or ""),
                        "text": text,
                        "raw_text": text,
                        "display_changed": 0,
                        "empty": 0 if text else 1,
                    }
                )
            rows.append(entry)

        out.update(
            {
                "active": 1 if rows else 0,
                "rows": rows,
                "row_count": int(len(rows)),
            }
        )
        return out

    def display_rows_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared display-text screen rows for one visible snapshot.

        This is the painted-text sibling of ``screen_rows_model(...)``: future
        UIs, tests, scripts, and LLM handoffs can inspect the same plain row
        text the reference curses TUI draws after tiny ``showchars`` and
        overflow-marker policy are applied, without scraping curses output or
        redoing row-overlay logic by hand.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        if h <= 0 or w <= 0:
            return {"active": 0, "lines": h, "cols": w, "rows": [], "row_count": 0}

        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        prompt_panel = dict(self.prompt_panel_model(lines=h, cols=w))
        gutter = dict(self.gutter_model(lines=h, cols=w))
        showchars_rows = dict(
            self._showchars_rows_model_from_window(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        viewport_rows = dict(
            self._viewport_rows_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
                gutter=gutter,
            )
        )
        return self._display_rows_model_from_parts(
            lines=h,
            cols=w,
            layout=layout,
            window=window,
            prompt_panel=prompt_panel,
            showchars_rows=showchars_rows,
            viewport_rows=viewport_rows,
        )

    def screen_rows_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return the shared plain-text screen rows for one visible snapshot.

        This flattens the composed visible screen into ordered row maps so
        future UIs, tests, scripts, and LLM handoffs can ask the boring but
        practical question "what plain text is on screen right now?" without
        scraping curses output or manually overlaying viewport rows, picker
        rows, and bottom chrome by hand.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        out: dict[str, Any] = {
            "active": 0,
            "lines": h,
            "cols": w,
            "rows": [],
            "row_count": 0,
        }
        if h <= 0 or w <= 0:
            return out

        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)
        prompt_panel = dict(self.prompt_panel_model(lines=h, cols=w))
        gutter = dict(self.gutter_model(lines=h, cols=w))
        viewport_rows = dict(
            self._viewport_rows_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
                gutter=gutter,
            )
        )
        layout_rows = list(layout.get("bottom_rows", []) or [])
        bottom_rows_text = list(self.bottom_rows_model(w)) if w > 0 else []
        bottom_rows: list[dict[str, Any]] = []
        for idx, row in enumerate(bottom_rows_text):
            entry = dict(row)
            if idx < len(layout_rows):
                entry["y"] = int(layout_rows[idx].get("y", -1) or -1)
            else:
                entry["y"] = -1
            bottom_rows.append(entry)

        cursor = dict(window.get("cursor") or {})
        cursor.setdefault("visible", 0)
        cursor["mode"] = "edit"
        prompt_y = int(layout.get("prompt_y", -1) or -1)
        if prompt_y >= 0 and self.prompt is not None:
            prompt_cursor = max(0, int(self.status_model().get("prompt_cursor", 0) or 0))
            cursor = {
                "mode": "prompt",
                "screen_y": int(prompt_y),
                "screen_x": max(0, min(max(0, w - 1), 1 + prompt_cursor)),
                "visible": 1 if w > 0 and h > 0 else 0,
            }
        cursor_visible = bool(int(cursor.get("visible", 0) or 0))
        cursor_y = int(cursor.get("screen_y", -1) or -1)
        cursor_x = int(cursor.get("screen_x", -1) or -1)

        viewport_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(viewport_rows.get("rows") or [])
            if isinstance(row, dict)
        }
        panel_by_y = {
            int(row.get("screen_y", -1)): dict(row)
            for row in list(prompt_panel.get("entries") or [])
            if isinstance(row, dict)
        }
        bottom_by_y = {
            int(row.get("y", -1)): dict(row)
            for row in list(bottom_rows or [])
            if isinstance(row, dict)
        }

        rows: list[dict[str, Any]] = []
        for y in range(int(h)):
            text = ""
            kind = "blank"
            entry: dict[str, Any] = {
                "screen_y": int(y),
                "screen_x": 0,
                "width": int(w),
                "kind": kind,
                "text": text,
                "empty": 1,
                "cursor_here": 1 if cursor_visible and int(y) == int(cursor_y) else 0,
                "cursor_x": int(cursor_x) if cursor_visible and int(y) == int(cursor_y) else -1,
            }
            vp = viewport_by_y.get(int(y))
            if vp is not None:
                text = str(vp.get("combined_text", "") or "")[: int(w)]
                entry.update(
                    {
                        "kind": "viewport",
                        "text": text,
                        "empty": 0 if vp and text else 1,
                        "view_y": int(vp.get("view_y", 0) or 0),
                        "line": int(vp["line"]) if "line" in vp else -1,
                        "has_line": int(vp.get("has_line", 0) or 0),
                        "start_col": int(vp.get("start_col", 0) or 0),
                        "continuation": int(vp.get("continuation", 0) or 0),
                    }
                )
            panel = panel_by_y.get(int(y))
            if panel is not None:
                text = str(panel.get("text", "") or "")[: int(w)]
                entry.update(
                    {
                        "kind": "prompt-panel",
                        "text": text,
                        "empty": 0 if text else 1,
                        "type": str(panel.get("type", "") or ""),
                        "row_kind": str(panel.get("row_kind", "") or ""),
                        "selected": int(panel.get("selected", 0) or 0),
                    }
                )
            bottom = bottom_by_y.get(int(y))
            if bottom is not None:
                text = str(bottom.get("text", "") or "")[: int(w)]
                entry.update(
                    {
                        "kind": str(bottom.get("kind", "bottom") or "bottom"),
                        "slot": str(bottom.get("slot", "") or ""),
                        "text": text,
                        "empty": 0 if text else 1,
                    }
                )
            rows.append(entry)

        out.update(
            {
                "active": 1 if rows else 0,
                "rows": rows,
                "row_count": int(len(rows)),
            }
        )
        return out

    def screen_model(self, lines: int, cols: int) -> dict[str, Any]:
        """Return one shared visible-screen snapshot for the reference TUI.

        This is a tiny composition helper layered on top of the existing shared
        layout/edit-window/prompt-panel/bottom-row models. It gives future UIs,
        tests, scripts, and LLMs one inspectable map for "what is on screen
        now?" without forcing them to stitch together geometry, visible edit
        rows, prompt suggestions, bottom-row text, and active cursor placement
        by hand.
        """

        h = max(0, int(lines))
        w = max(0, int(cols))
        layout = dict(self.screen_layout_model(lines=h, cols=w))
        window = dict(self.edit_window_model(lines=h, cols=w))
        layout = dict(window)
        layout.setdefault("lines", h)
        layout.setdefault("cols", w)

        prompt_panel = dict(self.prompt_panel_model(lines=h, cols=w))
        gutter = dict(self.gutter_model(lines=h, cols=w))
        search_rows = dict(
            self._search_rows_model_from_window(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        showchars_rows = dict(
            self._showchars_rows_model_from_window(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        viewport_rows = dict(
            self._viewport_rows_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
                gutter=gutter,
            )
        )
        viewport_cues = dict(
            self._viewport_cues_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
                search_rows=search_rows,
                showchars_rows=showchars_rows,
            )
        )
        docs_cues = dict(
            self._docs_cues_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
            )
        )
        display_rows = dict(
            self._display_rows_model_from_parts(
                lines=h,
                cols=w,
                layout=layout,
                window=window,
                prompt_panel=prompt_panel,
                showchars_rows=showchars_rows,
                viewport_rows=viewport_rows,
            )
        )
        layout_rows = list(layout.get("bottom_rows", []) or [])
        bottom_rows_text = list(self.bottom_rows_model(w)) if w > 0 else []
        bottom_rows: list[dict[str, Any]] = []
        for idx, row in enumerate(bottom_rows_text):
            entry = dict(row)
            if idx < len(layout_rows):
                entry["y"] = int(layout_rows[idx].get("y", -1) or -1)
            else:
                entry["y"] = -1
            bottom_rows.append(entry)

        cursor = dict(window.get("cursor") or {})
        cursor.setdefault("visible", 0)
        cursor["mode"] = "edit"
        prompt_y = int(layout.get("prompt_y", -1) or -1)
        if prompt_y >= 0 and self.prompt is not None:
            prompt_cursor = max(0, int(self.status_model().get("prompt_cursor", 0) or 0))
            cursor = {
                "mode": "prompt",
                "screen_y": int(prompt_y),
                "screen_x": max(0, min(max(0, w - 1), 1 + prompt_cursor)),
                "visible": 1 if w > 0 and h > 0 else 0,
            }

        out = {
            "lines": h,
            "cols": w,
            "layout": layout,
            "gutter": gutter,
            "search_rows": search_rows,
            "showchars_rows": showchars_rows,
            "viewport_rows": viewport_rows,
            "viewport_cues": viewport_cues,
            "docs_cues": docs_cues,
            "display_rows": display_rows,
            "edit_window": window,
            "prompt_panel": prompt_panel,
            "bottom_rows": bottom_rows,
            "bottom_rows_count": int(len(bottom_rows)),
            "cursor": cursor,
        }
        out["screen_rows"] = self.screen_rows_model(lines=h, cols=w)
        return out

    def bottom_rows_model(self, width: int) -> list[dict[str, Any]]:
        """Return the currently visible bottom-row chrome as ordered row maps.

        The list is ordered top-to-bottom exactly as the minimal curses TUI will
        paint the visible bottom rows. This keeps the editor-side contract tiny
        but useful for future renderers, scripts, tests, and LLM handoffs: they
        can inspect the active keymenu/interaction/infobar/statusline stack
        directly instead of rebuilding it from scattered options and renderer
        helpers.
        """

        w = max(0, int(width))
        if w <= 0:
            return []

        eb = self.cur()
        rows: list[dict[str, Any]] = []
        keymenu = self.keymenu_model(w)
        if int(keymenu.get("active", 0) or 0):
            rows.append(
                {
                    "kind": "keymenu",
                    "slot": "help",
                    "text": str(keymenu.get("text", "") or ""),
                }
            )

        interaction = self.interaction_model(w)
        if int(interaction.get("active", 0) or 0):
            rows.append(
                {
                    "kind": "interaction",
                    "slot": "prompt",
                    "text": str(interaction.get("text", "") or ""),
                }
            )
        else:
            infobar = self.infobar_model(w)
            if int(infobar.get("active", 0) or 0):
                rows.append(
                    {
                        "kind": "infobar",
                        "slot": "prompt",
                        "text": str(infobar.get("text", "") or ""),
                    }
                )

        if bool(self.options.get("statusline", local=eb.local_options)):
            rows.append(
                {
                    "kind": "statusline",
                    "slot": "status",
                    "text": self.statusline_text(w),
                }
            )
        return rows

    def display_file_name(self, eb: EditorBuffer | None = None) -> str:
        """Return the effective filename/status label for the active buffer.

        When `basename` is off, path-backed buffers prefer the full path so
        statusline/infobar-style views can mirror micro-esque behavior. Buffers
        without a path keep their ordinary buffer name.
        """

        eb = self.cur() if eb is None else eb
        path = str(eb.buf.path or "")
        if not path:
            return str(eb.name)
        if bool(self.options.get("basename", local=eb.local_options)):
            return str(Path(path).name or eb.name)
        return path

    def status_model(self) -> dict[str, Any]:
        """Return a small, portable statusline/infobar model.

        The goal is to let future UI layers render shared editor state without
        inventing semantics. Values are chosen to be easy for micromax scripts,
        tests, and future tooling to inspect directly.
        """

        eb = self.cur()
        self._normalize_cursor_lists(eb)
        c = eb.cursors[eb.primary]

        path = str(eb.buf.path or "")
        buffer_visible = self._buffer_read_allowed(str(eb.name))
        raw_file_name = Path(path).name if path else str(eb.name)
        display_name = self.display_file_name(eb)
        if not buffer_visible:
            raw_file_name = ""
            display_name = ""
        filetype = self.filetype()

        protected = bool(self.options.get("readonly", local=eb.local_options))

        # OS-level read-only status (file permissions). This is distinct from
        # "protected" buffers: you can still edit an unwritable file and then
        # `saveas` elsewhere, but protected buffers should reject edits.
        try:
            readonly_file = bool(path) and Path(path).exists() and (not Path(path).is_dir()) and (not os.access(Path(path), os.W_OK))
        except OSError:
            readonly_file = False
        readonly = bool(protected) or bool(readonly_file)

        selection_count = 0
        for i in range(len(eb.cursors)):
            sel = self.selection(i)
            if sel is not None and not sel.is_empty():
                selection_count += 1

        primary_sel = self.selection(None)
        primary_sel_chars = 0
        if primary_sel is not None and not primary_sel.is_empty():
            primary_sel_chars = len(self.selection_text(None))

        prompt_visible = self.prompt is not None and self._can_read_prompt_state(self.prompt)
        prompt_kind = self.prompt.kind if self.prompt is not None and prompt_visible else ""
        prompt_text = self.prompt.text if self.prompt is not None and prompt_visible else ""
        capture = self.capture_status_model()
        interaction = self.interaction_status_model()
        prompt_current_row = self.prompt_current_row() if prompt_visible else []
        prompt_current_insert = prompt_current_row[0] if prompt_current_row else ""
        prompt_current_kind = prompt_current_row[1] if prompt_current_row else ""
        prompt_current_menu = prompt_current_row[2] if prompt_current_row else ""
        prompt_current_info = prompt_current_row[3] if prompt_current_row else ""
        prompt_pos = self.prompt_current_position() if prompt_visible else prompt_position_model([], 0, labeler=lambda _row: "")
        search_pos = self.search_position_model()
        buffer_names = self.visible_buffer_names()
        try:
            buffer_index = int(buffer_names.index(str(self.active or ""))) + 1 if buffer_names and buffer_visible else 0
        except ValueError:
            buffer_index = 0
        buffer_count = int(len(buffer_names))
        buffer_summary = f"{buffer_index}/{buffer_count}" if buffer_count > 0 else ""
        disk_state = self.buffer_disk_state(eb)
        visible_keymode_rows = self.visible_active_key_mode_rows()
        status_keymode = str(visible_keymode_rows[0][0]) if visible_keymode_rows else ""
        status_keymode_once = bool(visible_keymode_rows and int(visible_keymode_rows[0][1] or 0))
        raw_capture_mode = self.current_capture_key_mode()
        status_keymode_capture = bool(status_keymode and raw_capture_mode == status_keymode)

        out: dict[str, Any] = {
            "mode": self.editor_mode(),
            "keymode": status_keymode,
            "keymode_once": 1 if status_keymode_once else 0,
            "keymode_capture": 1 if status_keymode_capture else 0,
            "buffer_name": str(eb.name) if buffer_visible else "",
            "file_name": str(raw_file_name),
            "display_name": str(display_name),
            "buffer_index": int(buffer_index),
            "buffer_count": int(buffer_count),
            "buffer_summary": str(buffer_summary),
            "filetype": str(filetype),
            "encoding": str(self.options.get("encoding", local=eb.local_options) or "utf-8"),
            "fileformat": str(self.options.get("fileformat", local=eb.local_options) or "unix"),
            "path": path if buffer_visible else "",
            "cwd": str(Path.cwd()),
            "dirty": 1 if eb.buf.dirty else 0,
            "readonly": 1 if readonly else 0,
            "protected": 1 if protected else 0,
            "disk_state": str(disk_state.get("disk_state", "") or ""),
            "disk_summary": str(disk_state.get("disk_summary", "") or ""),
            "disk_changed": int(disk_state.get("disk_changed", 0) or 0),
            "disk_missing": int(disk_state.get("disk_missing", 0) or 0),
            "disk_known": int(disk_state.get("disk_known", 0) or 0),
            "disk_warning": int(disk_state.get("disk_warning", 0) or 0),
            "disk_error": str(disk_state.get("disk_error", "") or ""),
            "line": int(c.line),
            "col": int(c.col),
            "display_line": int(c.line) + 1,
            "display_col": int(c.col) + 1,
            "position": f"{int(c.line) + 1}:{int(c.col) + 1}",
            "line_count": int(len(eb.buf.lines)),
            "percentage": int((int(c.line) / max(1, int(len(eb.buf.lines)) - 1)) * 100),
            "cursor_count": int(len(eb.cursors)),
            "primary_cursor_index": int(eb.primary),
            "cursor_summary": f"{int(eb.primary) + 1}/{int(len(eb.cursors))}",
            "selection_count": int(selection_count),
            "selection_summary": str(int(selection_count)),
            "primary_selection_chars": int(primary_sel_chars),
            "prompt_kind": str(prompt_kind),
            "prompt_text": str(prompt_text),
            "prompt_cursor": int(self.prompt.cursor) if self.prompt is not None and prompt_visible else 0,

            "viewport_top_line": int(self.viewport_top_line),
            "viewport_left_col": int(self.viewport_left_col),
            "viewport_height": int(self.viewport_height),
            "viewport_width": int(self.viewport_width),
            "display_viewport_top_line": int(self.viewport_top_line) + 1,
            "display_viewport_left_col": int(self.viewport_left_col) + 1,
            "prompt_current_insert": str(prompt_current_insert),
            "prompt_current_kind": str(prompt_current_kind),
            "prompt_current_menu": str(prompt_current_menu),
            "prompt_current_info": str(prompt_current_info),
            "prompt_current_section": self.prompt_current_section(),
            "prompt_current_preview": self.prompt_current_preview(),
            "prompt_index": int(prompt_pos.get("index", 0) or 0),
            "prompt_count": int(prompt_pos.get("count", 0) or 0),
            "prompt_section_index": int(prompt_pos.get("section_index", 0) or 0),
            "prompt_section_count": int(prompt_pos.get("section_count", 0) or 0),
            "prompt_position_summary": str(prompt_pos.get("summary", "") or ""),
            "search_query": str(search_pos.get("query", "") or ""),
            "search_literal": int(search_pos.get("literal", 0) or 0),
            "search_case_sensitive": int(search_pos.get("case_sensitive", 0) or 0),
            "search_match_index": int(search_pos.get("index", 0) or 0),
            "search_match_count": int(search_pos.get("count", 0) or 0),
            "search_summary": str(search_pos.get("summary", "") or ""),
            "last_message": self.last_visible_message(),
            "macro_recording": 1 if self.macro_recording else 0,
            "macro_playing": 1 if self._macro_playing else 0,
            "macro_name": str(self._macro_target) if self.macro_recording else str(self._macro_play_name),
        }
        out.update(self.help_navigation_model())
        out.update(self.jump_navigation_model())
        out.update(capture)
        out.update(interaction)
        return out

    def status_summary(self, *, include_prompt: bool = True) -> str:
        """Return a compact, deterministic status summary string.

        This is mainly for the headless REPL and `showstatus` command. UI layers
        should prefer `status_model()`. Command-bar preview paths can pass
        ``include_prompt=False`` so the summary stays close to the eventual
        command output instead of echoing the transient prompt itself.
        """

        st = self.status_model()
        mode = str(st['mode'])
        if not include_prompt and st.get('prompt_kind'):
            mode = 'normal'
        parts = [
            f"mode={mode}",
            f"buffer={str(st.get('display_name', st['file_name']))!r}",
            f"dirty={st['dirty']}",
            f"readonly={st['readonly']}",
            f"pos={st['position']}",
            f"cursors={int(st['primary_cursor_index']) + 1}/{st['cursor_count']}",
            f"sels={st['selection_count']}",
            f"selchars={st['primary_selection_chars']}",
        ]
        if st['keymode'] and not (not include_prompt and str(st.get('keymode') or '') == 'prompt'):
            suffix = '!' if st.get('keymode_once') else ''
            parts.append(f"keymode={st['keymode']!r}{suffix}")
        if include_prompt and st['prompt_kind']:
            parts.append(f"prompt={st['prompt_kind']!r}")
        if int(st.get('buffer_count', 0) or 0) > 1 and st.get('buffer_summary'):
            parts.append(f"buf_pos={st['buffer_summary']!r}")
        if st.get('search_query') and st.get('search_summary'):
            parts.append(f"search_pos={st['search_summary']!r}")
        if include_prompt and st['prompt_kind'] not in ('', 'command', 'find') and st.get('prompt_position_summary'):
            parts.append(f"prompt_pos={st['prompt_position_summary']!r}")
        if include_prompt and st['prompt_kind'] not in ('', 'command', 'find') and st.get('prompt_current_preview'):
            parts.append(f"prompt_item={st['prompt_current_preview']!r}")
        if include_prompt and st.get('interaction_kind') and not st.get('capture_kind'):
            parts.append(f"interaction={st['interaction_kind']!r}")
            if st.get('interaction_position'):
                parts.append(f"interaction_pos={st['interaction_position']!r}")
            if st.get('interaction_detail'):
                parts.append(f"interaction_item={st['interaction_detail']!r}")
        if include_prompt and st.get('capture_kind'):
            parts.append(f"capture={st['capture_kind']!r}")
        if include_prompt and st.get('capture_progress'):
            parts.append(f"capture_pos={st['capture_progress']!r}")
        if include_prompt and st.get('capture_detail'):
            parts.append(f"capture_item={st['capture_detail']!r}")
        if st.get('help_navigation_summary'):
            parts.append(f"help_nav={st['help_navigation_summary']!r}")
        if st.get('help_navigation_action_summary'):
            parts.append(f"help_actions={st['help_navigation_action_summary']!r}")
        if st.get('help_navigation_warning_summary'):
            parts.append(f"help_warn={st['help_navigation_warning_summary']!r}")
        if st.get('jump_navigation_summary'):
            parts.append(f"jump_nav={st['jump_navigation_summary']!r}")
        if st.get('jump_navigation_action_summary'):
            parts.append(f"jump_actions={st['jump_navigation_action_summary']!r}")
        if st['macro_recording']:
            parts.append(f"macro=rec:{st['macro_name']!r}")
        if st['macro_playing']:
            parts.append("macro=play")
        return " ".join(parts)

    def statusline_model(self, width: int) -> dict[str, Any]:
        """Return a tiny shared layout model for the visible statusline row.

        The model intentionally stays text-first and inspectable: future
        UIs/scripts/LLMs can see the rendered left/right segments, truncation
        policy, and final padding without having to reverse-engineer the final
        one-line status string.
        """

        w = max(0, int(width))
        out: dict[str, Any] = {
            "active": 0,
            "width": w,
            "left_raw": "",
            "right_raw": "",
            "left": "",
            "right": "",
            "padding": "",
            "padding_width": 0,
            "truncated_left": 0,
            "truncated_right": 0,
            "text": "",
        }
        if w <= 0:
            return out

        if not bool(self.options.get("statusline", local=self.cur().local_options)):
            return out

        st = self.status_model()
        fmt_l = str(self.options.get("statusformatl", local=self.cur().local_options) or "")
        fmt_r = str(self.options.get("statusformatr", local=self.cur().local_options) or "")
        left_raw = render_status_template(fmt_l, ed=self, status=st)
        right_raw = render_status_template(fmt_r, ed=self, status=st).strip()
        left = left_raw
        right = right_raw
        truncated_left = 0
        truncated_right = 0

        # If the right side alone is too long, show the end (keeps mode/key hints).
        if len(right) >= w:
            right = right[-w:]
            truncated_right = 1 if right != right_raw else 0
            out.update(
                {
                    "active": 1,
                    "left_raw": left_raw,
                    "right_raw": right_raw,
                    "right": right,
                    "truncated_left": 1 if left_raw else 0,
                    "truncated_right": truncated_right,
                    "text": right,
                }
            )
            return out

        # Fit left + right into width, truncating left if needed.
        avail_left = w - len(right)
        if len(left) > avail_left:
            truncated_left = 1
            # Reserve at least one char if possible; add an ellipsis when truncating.
            if avail_left <= 0:
                left = ""
            elif avail_left == 1:
                left = left[:1]
            else:
                left = left[: max(0, avail_left - 1)] + "…"

        padding = " " * max(0, w - len(left) - len(right))
        text = (left + padding + right)[:w]
        out.update(
            {
                "active": 1,
                "left_raw": left_raw,
                "right_raw": right_raw,
                "left": left,
                "right": right,
                "padding": padding,
                "padding_width": len(padding),
                "truncated_left": truncated_left,
                "truncated_right": truncated_right,
                "text": text,
            }
        )
        return out

    def statusline_text(self, width: int) -> str:
        """Return a micro-esque single-line statusline string for the current viewport width.

        UI layers should generally prefer `status_model()` / `statusline_model()` for richer
        structure, but having a deterministic reference formatter is useful for the minimal TUI,
        REPL output, and tests.
        """
        return str(self.statusline_model(width).get("text", "") or "")

    # ----- prompt (command bar / find bar) -----
    def _stamp_prompt_script_origin(self, prompt: Prompt | None = None) -> None:
        """Make the active prompt remember lower-authority script provenance.

        Prompts are deferred execution objects: script code can open a command
        prompt, alter its text, or move a picker selection, then return to the
        UI loop.  A later Enter key should submit the prompt with the authority
        of the code that prepared it, not with fresh ambient editor/user
        authority.
        """

        target = prompt if prompt is not None else self.prompt
        if target is None:
            return
        origin = self.script_callback_origin_kwargs()
        if not bool(origin.get("script_context", False)):
            return
        target.script_context = True
        target.plugin_load_root = (
            str(origin.get("plugin_load_root")) if origin.get("plugin_load_root") else None
        )
        gen = origin.get("plugin_generation")
        target.plugin_generation = int(gen) if gen not in (None, "") else None
        sid = origin.get("script_origin_id")
        target.script_origin_id = str(sid) if sid else None
        raw_group = getattr(self.vm, "current_editor_group", None)
        target.group = str(raw_group) if raw_group not in (0, None, "") else None

    def _prompt_runs_under_captured_origin(self, prompt: Prompt | None = None) -> bool:
        """Return True when a deferred prompt should re-enter script authority."""

        target = prompt if prompt is not None else self.prompt
        if target is None:
            return False
        if not bool(getattr(target, "script_context", False)):
            return False
        if bool(getattr(self, "_prompt_origin_action_active", False)):
            return False
        try:
            if self.in_script_context():
                return False
        except Exception:
            pass
        return True

    def _run_prompt_origin_callback(self, fn, *, rollback_on_false: bool = False) -> object:
        """Run a delayed prompt operation under the prompt's captured authority.

        ``submit_prompt`` already treated prompts as delayed execution objects,
        but non-submit prompt actions are delayed authority objects too: Tab can
        inspect paths, picker navigation can refresh rows, and copy-selected can
        write to the clipboard.  When a script/plugin prepared the prompt, these
        later actions should not borrow ambient user/editor authority merely
        because they are triggered by a later keypress.
        """

        prompt = self.prompt
        if prompt is None or not bool(getattr(prompt, "script_context", False)):
            return fn()
        authority = self._prompt_runtime_authority(prompt)
        stale_reason = self._stale_plugin_authority_reason(authority, label="prompt")
        if stale_reason:
            self.message(stale_reason)
            self._drop_stale_plugin_interaction(authority)
            return False
        old = bool(getattr(self, "_prompt_origin_action_active", False))
        self._prompt_origin_action_active = True
        try:
            return self.run_script_origin_callback(
                fn,
                plugin_load_root=getattr(prompt, "plugin_load_root", None),
                group=getattr(prompt, "group", None),
                plugin_generation=getattr(prompt, "plugin_generation", None),
                script_origin_id=getattr(prompt, "script_origin_id", None),
                rollback_on_false=rollback_on_false,
            )
        finally:
            self._prompt_origin_action_active = old

    def _prompt_runtime_authority(self, prompt: Prompt | None = None) -> RuntimeRegistrationAuthority:
        """Return the authority that owns the active prompt state."""

        target = self.prompt if prompt is None else prompt
        if target is None or not bool(getattr(target, "script_context", False)):
            return RuntimeRegistrationAuthority(script_context=False)
        gen = getattr(target, "plugin_generation", None)
        return RuntimeRegistrationAuthority(
            script_context=True,
            plugin_load_root=(str(getattr(target, "plugin_load_root", "") or "") or None),
            plugin_generation=(int(gen) if gen not in (None, "") else None),
            script_origin_id=(str(getattr(target, "script_origin_id", "") or "") or None),
            group=(str(getattr(target, "group", "") or "") or None),
        )

    def _script_prompt_read_capability_enabled(self) -> bool:
        try:
            return bool(self.in_script_context()) and bool(self.options.get("cap.prompt-read"))
        except Exception:
            return False

    def _script_prompt_write_capability_enabled(self) -> bool:
        try:
            return bool(self.in_script_context()) and bool(self.options.get("cap.prompt-write"))
        except Exception:
            return False

    def _prompt_read_decision(self, prompt: Prompt | None = None):
        target = self.prompt if prompt is None else prompt
        if target is None:
            return prompt_read_policy(
                self._current_runtime_authority(kind="editor"),
                RuntimeRegistrationAuthority(script_context=False),
                capability_enabled=self._script_prompt_read_capability_enabled(),
            )
        return prompt_read_policy(
            self._current_runtime_authority(kind="editor"),
            self._prompt_runtime_authority(target),
            capability_enabled=self._script_prompt_read_capability_enabled(),
        )

    def _can_read_prompt_state(self, prompt: Prompt | None = None) -> bool:
        return bool(self._prompt_read_decision(prompt).allowed)

    def _prompt_write_decision(self, prompt: Prompt | None = None):
        target = self.prompt if prompt is None else prompt
        if target is None:
            return prompt_read_policy(
                self._current_runtime_authority(kind="editor"),
                RuntimeRegistrationAuthority(script_context=False),
                capability_enabled=self._script_prompt_write_capability_enabled(),
            )
        return prompt_read_policy(
            self._current_runtime_authority(kind="editor"),
            self._prompt_runtime_authority(target),
            capability_enabled=self._script_prompt_write_capability_enabled(),
        )

    def _can_write_prompt_state(self, prompt: Prompt | None = None) -> bool:
        return bool(self._prompt_write_decision(prompt).allowed)

    def _guard_prompt_read(self, op: str, prompt: Prompt | None = None) -> None:
        decision = self._prompt_read_decision(prompt)
        if bool(decision.allowed):
            return
        reason = str(decision.reason or "prompt read denied")
        raise PermissionError(
            f"script context cannot read active prompt: {str(op or 'prompt')} ({reason}; cap.prompt-read)"
        )

    def _guard_prompt_write(self, op: str, prompt: Prompt | None = None) -> None:
        decision = self._prompt_write_decision(prompt)
        if bool(decision.allowed):
            return
        reason = str(decision.reason or "prompt write denied")
        raise PermissionError(
            f"script context cannot modify active prompt: {str(op or 'prompt')} ({reason}; cap.prompt-write)"
        )

    def _check_prompt_write(self, op: str, prompt: Prompt | None = None) -> bool:
        try:
            self._guard_prompt_write(op, prompt)
        except PermissionError as e:
            self.message(str(e))
            return False
        return True

    def _interaction_read_allowed(
        self,
        authority: RuntimeRegistrationAuthority | None,
        *,
        kind: str = "interaction",
    ) -> bool:
        if not bool(self.in_script_context()):
            return True
        if self._script_prompt_read_capability_enabled():
            return True
        decision = interaction_response_policy(self._current_runtime_authority(kind="editor"), authority)
        return bool(decision.allowed)

    def enter_prompt(self, kind: str, *, prefill: str = "") -> None:
        self.prompt = Prompt(kind=kind)
        self._stamp_prompt_script_origin(self.prompt)
        self.prompt.prefill(prefill)
        self._push_prompt_keymode()

